	public static readonly string Html = "\n\n\n\n<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>Newfies Server Essentials Suite</title>\n<link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\">\n<link rel=\"apple-touch-icon\" href=\"data:image/png;base64,\">\n<style>\n:root{\n  color-scheme:dark;\n  --bg:#0a0f14;\n  --panel:#111821;\n  --panel2:#17212b;\n  --panel3:#1d2935;\n  --line:#293746;\n  --text:#eef5fb;\n  --muted:#8ea0b0;\n  --accent:#69aefa;\n  --good:#8fda72;\n  --warn:#ffd166;\n  --bad:#ff7474;\n  --orange:#ffad66;\n  --purple:#c69cff;\n  --shadow:0 14px 38px rgba(0,0,0,.30);\n  --panel-glow:rgba(105,174,250,.055);\n  --line-soft:rgba(86,109,130,.34);\n  --surface-hover:rgba(105,174,250,.055);\n  --ui-scale:.75;\n  --header-height:62px;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{margin:0;background:radial-gradient(circle at 78% -10%,rgba(62,121,181,.11),transparent 32%),radial-gradient(circle at 12% 0%,rgba(104,80,160,.06),transparent 26%),var(--bg);color:var(--text);font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background-attachment:fixed}\nbutton,input,select{font:inherit}\nbutton{\n  background:#283440;color:var(--text);border:1px solid #40505f;border-radius:7px;\n  padding:8px 12px;cursor:pointer;transition:.15s background,.15s border-color,.15s transform\n}\nbutton:hover{background:#344352;border-color:#536678}\nbutton:active{transform:translateY(1px)}\n#app button.primary,.overlay button.primary{background:#245b94;border-color:#3679ba}\n#app button.danger,.overlay button.danger{background:#713434;border-color:#a84e4e}\nbutton.active{background:#2d4f70;border-color:#5382ae}\nbutton:disabled{opacity:.45;cursor:not-allowed;transform:none}\nbutton:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\nbutton.miniClear{min-height: