position:relative}.passwordWrap input{padding-right:74px}.passwordToggle{position:absolute;right:8px;top:8px;height:34px;padding:0 10px;background:transparent;border:0;color:var(--muted);font-size:11px;border-radius:10px}.passwordToggle:hover{color:#dce7f2;background:rgba(255,255,255,.05)}\n.loginSubmit{width:100%;padding:13px 16px;margin-top:3px;font-weight:800;border-radius:14px;position:relative;overflow:hidden;background:linear-gradient(180deg,#4e94dd,#2f6eae);box-shadow:inset 0 1px 0 rgba(255,255,255,.10),0 12px 26px rgba(40,100,160,.24),0 0 22px rgba(74,145,218,.12)}\n.loginSubmit.loading{pointer-events:none}.loginSubmit.loading::after{content:\"\";position:absolute;right:14px;top:50%;width:15px;height:15px;margin-top:-7.5px;border-radius:50%;border:2px solid rgba(255,255,255,.25);border-top-color:#fff;animation:loginSpin .8s linear infinite}\n.loginSecurity{display:flex;gap:8px;align-items:flex-start;margin:18px 0 0;padding-top:16px;border-top:1px solid rgba(60,78,97,.50);line-height:1.45}\n#loginError{color:var(--bad);min-height:22px;margin:4px 0 8px;font-size:12px}.loginErrorActive{padding:10px 12px;border:1px solid rgba(216,88,88,.35);background:rgba(216,88,88,.08);border-radius:12px}\n#loginView.isSubmitting{box-shadow:0 28px 90px rgba(0,0,0,.50),0 0 0 1px rgba(116,180,243,.15),0 0 42px rgba(116,180,243,.08)}\n#loginView.loginSuccess{box-shadow:0 30px 96px rgba(0,0,0,.52),0 0 0 1px rgba(143,218,114,.20),0 0 44px rgba(143,218,114,.08)}\n#loginView.loginSuccess::after{content:\"\";position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(143,218,114,.15),transparent);animation:loginSweep .65s ease-out 1;pointer-events:none}\n.headerBrand{display:flex;align-items:center;gap:10px;margin-right:14px;min-width:0;flex:0 1 auto}\n.headerBrand img{width:34px;height:34px;object-fit:contain;display:block;filter:drop-shadow(0 4px 10px rgba(0,0,0,.22))}\n.headerBrandTitle{display:flex;flex-direction:column;min-width:0}.headerBrandTitle strong{font-siz