:8px;white-space:normal}.compareGrid .label{color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase}\n.savedViews{display:flex;align-items:end;gap:6px;flex-wrap:wrap;margin-top:10px;padding-top:10px;border-top:1px solid var(--line)}\n.helpGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}.helpTerm{border-left:3px solid #49677e}\n.kbd{display:inline-block;background:#0c1217;border:1px solid #40505e;border-bottom-width:2px;border-radius:4px;padding:1px 5px;font-size:11px;color:#c5d2dc}\n.emptyAction{padding:18px;text-align:center;border:1px dashed #40505e;border-radius:8px;color:var(--muted)}.emptyAction b{color:var(--text)}\n.tooltipHelp{display:inline-flex;width:16px;height:16px;border-radius:50%;border:1px solid #4a5c6b;align-items:center;justify-content:center;font-size:10px;color:#9aacba;cursor:help;margin-left:4px}\n\n.announcementGrid{display:grid;grid-template-columns:minmax(320px,.9fr) minmax(420px,1.4fr);gap:12px;align-items:start}\n.announcementEditor{display:grid;grid-template-columns:150px minmax(0,1fr);gap:9px 12px;align-items:center}\n.announcementEditor textarea{min-height:100px;resize:vertical}\n.consoleShell{background:#070b0e;border:1px solid #36434d;border-radius:8px;overflow:hidden}\n.consoleToolbar{display:flex;gap:8px;align-items:center;padding:9px 10px;background:#10171d;border-bottom:1px solid #303c45;flex-wrap:wrap}\n.consoleOutput{height:min(58vh,620px);min-height:320px;overflow:auto;margin:0;padding:12px;background:#070b0e;color:#c7d2da;font:12px/1.5 Consolas,Monaco,monospace;white-space:pre-wrap;overflow-wrap:anywhere}\n.consoleLine{display:block;min-height:1.5em;padding:0 4px;border-left:2px solid transparent}\n.consoleLine.error,.consoleLine.fatal{color:#ff9b94;background:rgba(130,28,28,.12);border-left-color:#d75b54}\n.consoleLine.warning{color:#ffd58a;background:rgba(128,88,16,.10);border-left-color:#c99737}\n.consoleLine.chat{color:#8fd8ff;border-left-color:#4b9cc9}\n.consoleLine.command{color:#d8b4ff;border-left-color:#8a5ab7}\n.consoleLine.debug{color:#8394a1}\n.consoleLine.event{color:#9ed6aa}\n.consoleLine.info{color:#c7d2da}\n.consoleInputRow{display:flex;gap:7px;padding:9px 10px;background:#0d1419;border-top:1px solid #303c45}.consoleInputRow input{flex:1;font-family:Consolas,Monaco,monospace}.consoleInputRow select{min-width:110px}\n.consoleInputOff{opacity:.55}\n.consoleAlertStrip{display:grid;gap:8px;margin-bottom:10px}\n.consoleAlertStrip:empty{display:none}\n.consoleSpamAlert{border:1px solid #8f3f3f;background:rgba(120,24,24,.18);border-radius:8px;padding:10px 12px}\n.consoleSpamAlert .alertHead{display:flex;gap:10px;align-items:flex-start;flex-wrap:wrap}\n.consoleSpamAlert .alertTitle{font-weight:700;color:#ffaaa2}\n.consoleSpamAlert .alertMeta{font-size:12px;color:#c7d2da}\n.consoleSpamAlert .alertError{margin-top:7px;font-family:Consolas,Monaco,monospace;font-size:12px;overflow-wrap:anywhere}\n.webMapFrameShell{position:relative;min-height:540px;border:1px solid #36434d;border-radius:8px;background:#070b0e;overflow:hidden}\n.webMapFrame{width:100%;height:68vh;min-height:540px;border:0;background:#070b0e}\n.webMapPlaceholder{display:flex;align-items:center;justify-content:center;min-height:540px;padding:30px;text-align:center;color:#93a5b0}\n.webMapSettings{display:grid;grid-template-columns:minmax(160px,1fr) minmax(260px,3fr);gap:8px 10px;align-items:center}\n.webMapSettings input[type=text]{width:100%}\n.terrainProgressBox{display:none;margin:0 0 12px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:#0d141a}.terrainProgressBox.active{display:block}.terrainProgressHead{display:flex;align-items:center;gap:10px;margin-bottom:7px}.terrainProgressTitle{font-weight:800}.terrainProgressPct{margin-left:auto;font-variant-numeric:tabular-nums;font-weight:850}.terrainProgressTrack{height:14px;border-radius:999px;background:#202c35;border:1px solid #3b4a56;overflow:hidden}.terrainProgressFill{height:100%;width:0%;background:linear-gradient(90deg,#3b82f6,#22c55e);transition:width .35s ease}.terrainProgressMeta{display:flex;gap:10px;flex-wrap:wrap;margin-top:7px;color:var(--muted);font-size:11px;font-variant-numeric:tabular-nums}\n.animalRuleGrid{display:grid;grid-template-columns:minmax(310px,.8fr) minmax(480px,1.5fr);gap:12px;align-items:start;margin-top:12px}\n.animalRuleEditor{display:grid;grid-template-columns:130px minmax(0,1fr);gap:9px 12px;align-items:center}\n.animalRecommendationNote{margin:8px 0 10px}\n@media(max-width:1180px){.animalRuleGrid{grid-template-columns:1fr}}\n.updateBadge{display:inline-flex;align-items:center;border-radius:999px;padding:2px 7px;font-size:10px;font-weight:800;border:1px solid #40515f;white-space:nowrap}\n.updateBadge.update{color:#ffe7a3;border-color:#866d2d;background:#332b14}.updateBadge.current{color:#bdebb1;border-color:#476842;background:#162718}.updateBadge.unknown{color:#aab8c3;background:#151d23}\n@media(max-width:1180px){.announcementGrid{grid-template-columns:1fr}}\n\n@media(max-width:1450px) and (min-width:881px){\n  header{padding-left:12px;padding-right:12px}\n  header h1{max-width:250px;font-size:16px;margin-right:6px}\n  #lastUpdate{display:none}\n  .headerSearch{min-width:130px;max-width:230px;flex-basis:170px}\n  .languagePicker label,.scalePicker label,.motionPicker label{display:none}\n  .languagePicker select{min-width:96px;max-width:112px}\n  .scalePicker select{min-width:68px}\n  .motionPicker select{min-width:78px}\n  .headerDivider{margin:0 5px}\n  header .user{margin:0 5px;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n}\n@media(max-width:1120px) and (min-width:881px){\n  .headerSearch{display:none}\n  header h1{max-width:220px}\n  .connection{min-width:105px}\n}\n\n@media(max-width:1180px){\n  .chartGrid{grid-template-columns:repeat(2,minmax(260px,1fr))}\n  .playerAnalyticsGrid,.serverStatusGrid,.reportLayout{grid-template-columns:1fr}\n  .reportDetailScroll{position:static;max-height:none}\n  .diagnosis{grid-template-columns:repeat(3,1fr)}\n  .diagnosisMain{grid-column:1/-1}\n}\n@media(max-width:880px){\n  header{position:static;height:auto;min-height:62px;flex-wrap:wrap;gap:7px;padding:10px 12px}\n  header .spacer{display:none}\n  #globalStatusBar,#offlineBanner{margin-left:0;position:static}\n  .connection{min-width:0;flex:1}\n  nav{position:static;width:auto;display:flex;overflow:auto;border-right:0;border-bottom:1px solid var(--line);padding:7px}\n  nav .navLabel{display:none}\n  nav button{width:auto;white-space:nowrap}\n  main{margin-left:0;padding:14px}\n  .chartGrid{grid-template-columns:1fr}\n  .diagnosis{grid-template-columns:repeat(2,1fr)}\n  .diagnosisMain{grid-column:1/-1}\n}\n\n@media(max-width:700px){\n  .headerSearch{display:none}\n  #globalStatusBar,#offlineBanner{margin-left:0}\n  .customizeList{grid-template-columns:1fr}\n  .expandPanel{grid-template-columns:1fr}\n  table.mobileTable thead{display:none}\n  table.mobileTable,table.mobileTable tbody,table.mobileTable tr,table.mobileTable td{display:block;width:100%}\n  table.mobileTable tr{border-bottom:1px solid #384653;padding:6px 0}\n  table.mobileTable td{border:0!important;white-space:normal;padding:5px 9px 5px 42%;position:relative;min-height:28px}\n  table.mobileTable td::before{content:attr(data-label);position:absolute;left:9px;top:5px;width:38%;color:var(--muted);font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.04em}\n  .compareGrid{grid-template-columns:110px repeat(2,minmax(160px,1fr));overflow:auto}\n}\n\n\n/* v1.5.19 bad block-entity tracker UI; manual blacklist fingerprints retained from v1.5.18 */\n:root{--suite-sidebar-width:232px;--nav-width:var(--suite-sidebar-width)}\nnav{width:var(--nav-width)}\nmain,#globalStatusBar,#offlineBanner{margin-left:var(--nav-width)}\nmain{padding-top:18px}\n.pageTitle{padding-bottom:12px;border-bottom:1px solid rgba(45,57,70,.72);margin-bottom:14px}\n.pageTitle h2{font-size:23px;letter-spacing:-.015em}\n.card{border-radius:10px}\n.toolbar{padding:8px 0}\n.navGroup{margin-bottom:5px}\n.navGroupToggle{display:flex!important;align-items:center;gap:8px;width:100%;padding:9px 10px 7px!important;margin:7px 0 3px!important;color:#a9b7c3!important;background:#141d25!important;border:1px solid #24313d!important;border-left:4px solid #4f6578!important;border-radius:7px!important;font-size:12px!important;line-height:1.2;font-weight:850!important;text-transform:uppercase;letter-spacing:.07em}\n.navGroupToggle:hover{filter:brightness(1.12);color:#f2f7fb!important}\n.navGroup[data-nav-group=\"overview\"]>.navGroupToggle{color:#82bdf5!important;background:#142435!important;border-color:#244565!important;border-left-color:#4da3ff!important}\n.navGroup[data-nav-group=\"performance\"]>.navGroupToggle{color:#f0c778!important;background:#2a2317!important;border-color:#51401f!important;border-left-color:#e3a940!important}\n.navGroup[data-nav-group=\"utilities\"]>.navGroupToggle{color:#74d6c4!important;background:#142824!important;border-color:#285148!important;border-left-color:#43bda7!important}\n.navGroup[data-nav-group=\"moderation\"]>.navGroupToggle{color:#d5a4f1!important;background:#251c2d!important;border-color:#4a3559!important;border-left-color:#ae72d2!important}\n.navGroup[data-nav-group=\"administration\"]>.navGroupToggle{color:#a8b9dc!important;background:#1b2230!important;border-color:#35425a!important;border-left-color:#748fc8!important}\n.navGroupToggle .navChevron{margin-left:auto;font-size:10px;transition:transform .15s ease}\n.navGroup.collapsed .navChevron{transform:rotate(-90deg)}\n.navGroupBody{display:block}\n.navGroup.collapsed .navGroupBody{display:none}\nnav .navGroupBody>button{position:relative;padding-left:13px;display:flex;align-items:center;gap:7px;min-height:36px}\nnav .navGroupBody>button.active{box-shadow:inset 3px 0 0 var(--accent);background:#203040;border-color:#32495d}\n.navPageLabel{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.navPageMeta{margin-left:auto;display:inline-flex;align-items:center;gap:6px;flex:0 0 auto;min-height:18px}\n.navStatusDot{display:none;width:8px;height:8px;border-radius:50%;background:#64727e;box-shadow:0 0 0 3px rgba(255,255,255,.025)}\n.navStatusDot.visible{display:inline-block}\n.navStatusDot.good{background:var(--good);box-shadow:0 0 0 3px rgba(143,218,114,.08)}\n.navStatusDot.warn{background:var(--warn);box-shadow:0 0 0 3px rgba(255,209,102,.08)}\n.navStatusDot.bad{background:var(--bad);box-shadow:0 0 0 3px rgba(255,116,116,.08)}\n.navStatusDot.neutral{background:#64727e}\n.navPageBadge{display:none;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:999px;background:#4e6070;color:#fff;font-size:10px;font-weight:850;line-height:18px;font-variant-numeric:tabular-nums}\n.navPageBadge.visible{display:inline-flex}\n.navPageBadge.attention{background:#8a6822;color:#fff1bd}\n.navPageBadge.critical{background:#8c3434;color:#fff}\n.navPageBadge.info{background:#315f8d;color:#d9ebff}\n.navInlineState{margin-left:auto;padding:2px 6px;border-radius:999px;font-size:9px;font-weight:850;letter-spacing:.05em;background:#394957;color:#dbe7f1}\n.navInlineState.good{background:#24472c;color:#bff0c8}\n.navInlineState.neutral{background:#4a4141;color:#d6c7c7}\n.tickDebugMetricStrip{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:12px}\n.tickDebugMetricStrip .metric{min-width:0}\n.endpointSafetyScroll{max-height:340px;overflow:auto}\n.endpointSafetyScroll thead{position:sticky;top:0;z-index:2;background:var(--panel2)}\n@media(max-width:1200px){.tickDebugMetricStrip{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media(max-width:700px){.tickDebugMetricStrip{grid-template-columns:repeat(2,minmax(0,1fr))}}\nnav .navGroupBody>button.active .navPageBadge.attention{background:#a37b26}\n.readOnlyNotice{display:none;margin:0 0 12px;padding:9px 12px;border:1px solid #6c5a2d;background:#272317;color:#ffe39a;border-radius:8px;font-size:12px}\n.readOnlyNotice.visible{display:flex;gap:8px;align-items:center}\n.sectionTabs{display:flex;gap:5px;align-items:center;overflow:auto;padding:4px;background:#0e141a;border:1px solid var(--line);border-radius:9px;margin:0 0 12px;scrollbar-width:thin}\n.sectionTabs button{flex:0 0 auto;border:0;background:transparent;padding:8px 11px;color:#9cabb8}\n.sectionTabs button.active{background:#26394a;color:#fff;box-shadow:inset 0 0 0 1px #3b566e}\n.tabPanel{display:none}\n.tabPanel.active{display:block}\n.summaryHero{display:flex;gap:14px;align-items:center;padding:16px;border:1px solid var(--line);border-radius:10px;background:linear-gradient(135deg,#151e27,#121820);margin-bottom:12px}\n.summaryHero .heroIcon{width:58px;height:58px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex:none;border:4px solid #506172;font-size:22px;font-weight:850}\n.summaryHero.good .heroIcon{border-color:var(--good);color:var(--good)}\n.summaryHero.warn .heroIcon{border-color:var(--warn);color:var(--warn)}\n.summaryHero.bad .heroIcon{border-color:var(--bad);color:var(--bad)}\n.summaryHero .heroTitle{font-size:20px;font-weight:820}\n.summaryHero .heroText{color:var(--muted);font-size:12px;margin-top:3px;line-height:1.45}\n.summaryHero .heroMeta{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}\n.stateChip{display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border:1px solid #41515f;border-radius:999px;background:#11181e;color:#b8c5cf;font-size:11px;font-weight:720}\n.stateChip.good{border-color:#42653c;color:#b8e7ad}.stateChip.warn{border-color:#755f2c;color:#ffe39a}.stateChip.bad{border-color:#7c3c3c;color:#ffb0b0}\n.acPlayerOverview{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:9px;margin-bottom:10px}.acInfoTile{border:1px solid var(--line);border-radius:9px;background:linear-gradient(180deg,#18212a,#131a21);padding:11px;min-width:0}.acInfoTile .k{font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);font-weight:800}.acInfoTile .v{font-size:17px;font-weight:850;margin-top:3px;overflow-wrap:anywhere}.acInfoTile .sub{font-size:11px;color:var(--muted);line-height:1.4;margin-top:4px}.acFullSpan{grid-column:1/-1}.acHash{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:10px;word-break:break-all}.acEvidenceActions{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.acEvidenceStored{border-left:3px solid var(--good)}\n.helpDisclosure{border:1px solid var(--line);border-radius:8px;background:#10171d;margin:8px 0 12px}\n.helpDisclosure summary{cursor:pointer;padding:9px 11px;color:#b7c4ce;font-size:12px;font-weight:750}\n.helpDisclosure>div{padding:0 11px 11px;color:var(--muted);font-size:12px;line-height:1.5}\n.policyPresetBar{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0 10px}\n.policyPresetBar button{font-size:11px;padding:6px 8px}\n.compactNote{font-size:11px;color:var(--muted);line-height:1.45}\n.acPlayerName{display:flex;align-items:center;gap:7px}\n.acRisk{font-variant-numeric:tabular-nums}\n@media(max-width:880px){\n  :root{--nav-width:0px}\n  nav .navGroup{display:contents}\n  nav .navGroupToggle{display:none!important}\n  nav .navGroupBody{display:contents!important}\n  main,#globalStatusBar,#offlineBanner{margin-left:0}\n  .summaryHero{align-items:flex-start}\n}\n\n\n/* v1.5.46 dashboard polish: preserve the existing layout while improving density,\n   hierarchy, long-page navigation, mobile ergonomics, and interaction feedback. */\n:root{\n  --panel-soft:#121920;\n  --panel-hover:#18212a;\n  --line-soft:rgba(84,103,120,.42);\n  --focus-ring:0 0 0 3px rgba(125,182,255,.13);\n}\nbody{\n  background:\n    radial-gradient(1100px 520px at 75% -140px,rgba(64,103,142,.09),transparent 62%),\n    var(--bg);\n  -webkit-font-smoothing:antialiased;\n  text-rendering:optimizeLegibility;\n}\nheader{box-shadow:0 8px 26px rgba(0,0,0,.13)}\nheader h1{font-weight:790;letter-spacing:-.015em}\nnav{scrollbar-width:thin;scrollbar-color:#344655 transparent}\nnav::-webkit-scrollbar,.tableWrap::-webkit-scrollbar,.dataScroll::-webkit-scrollbar,.dataScrollTall::-webkit-scrollbar{width:9px;height:9px}\nnav::-webkit-scrollbar-thumb,.tableWrap::-webkit-scrollbar-thumb,.dataScroll::-webkit-scrollbar-thumb,.dataScrollTall::-webkit-scrollbar-thumb{background:#344655;border-radius:999px;border:2px solid transparent;background-clip:padding-box}\nnav .navGroupBody>button{border-radius:8px;color:#aab8c4}\nnav .navGroupBody>button:hover{background:#19242d;border-color:#253847;color:#eef5fb}\nnav .navGroupBody>button.active{font-weight:760;color:#fff}\nmain{width:min(calc(100% - var(--nav-width)),2000px);min-height:calc(100vh - 98px)}\nsection.active{animation:pageIn .14s ease-out}\n@keyframes pageIn{from{opacity:.72;transform:translateY(3px)}to{opacity:1;transform:none}}\n.pageTitle{align-items:center;min-height:52px}\n.pageTitle h2{font-weight:810}\n.pageTitle .subtitle{max-width:920px;line-height:1.5}\n.card{\n  background:linear-gradient(180deg,rgba(24,32,40,.98),rgba(19,26,33,.98));\n  border-color:var(--line-soft);\n  box-shadow:0 1px 0 rgba(255,255,255,.018),0 6px 18px rgba(0,0,0,.08);\n}\n.cardHeader{min-height:30px;margin-bottom:12px}\n.cardHeader h3{font-size:15px;font-weight:790;letter-spacing:-.008em}\n.metric{position:relative;overflow:hidden}\n.metric::after{content:'';position:absolute;left:0;right:0;bottom:0;height:2px;background:linear-gradient(90deg,rgba(125,182,255,.28),transparent 72%)}\nbutton{min-height:34px;font-weight:650}\nbutton.primary{box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 2px 8px rgba(26,91,153,.15)}\nbutton.danger{box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}\ntextarea{font:inherit;background:#0d1217;color:var(--text);border:1px solid #394857;border-radius:6px;padding:8px}\ninput,select,textarea{transition:border-color .14s ease,box-shadow .14s ease,background .14s ease}\n#app input:hover,#app select:hover,#app textarea:hover,.overlay input:hover,.overlay select:hover,.overlay textarea:hover{border-color:#4a5d6e}\n#app input:focus,#app select:focus,#app textarea:focus,.overlay input:focus,.overlay select:focus,.overlay textarea:focus{border-color:#5e8db8;box-shadow:var(--focus-ring)}\n.toolbar{border-bottom:1px solid rgba(45,57,70,.45);padding-bottom:11px;margin-bottom:14px}\n.quickActions{margin:12px 0 14px;padding:10px;border:1px solid rgba(45,57,70,.5);border-radius:9px;background:#10171d}\n.tableWrap{background:#10161c;border-color:var(--line-soft)}\nth{font-size:11px;text-transform:uppercase;letter-spacing:.045em;font-weight:780;background:#1d2730}\nth,td{padding:9px 10px}\ntbody tr:last-child td{border-bottom:0}\ntr:hover td{background:#1b2731}\n.badge,.stateChip,.updateBadge,.recBadge,.safetyBadge{box-shadow:inset 0 1px 0 rgba(255,255,255,.035)}\n.empty,.emptyAction{line-height:1.55}\n.emptyAction{background:rgba(14,20,26,.55)}\n#globalStatusBar{box-shadow:0 5px 16px rgba(0,0,0,.08)}\n.statusPill{padding:3px 7px;border-radius:999px;background:rgba(24,34,43,.72);border:1px solid rgba(63,80,95,.45)}\n.toast{animation:toastIn .18s ease-out;backdrop-filter:blur(8px)}\n@keyframes toastIn{from{opacity:0;transform:translateY(8px) scale(.985)}to{opacity:1;transform:none}}\n#backToTop{\n  position:fixed;right:18px;bottom:78px;z-index:95;width:40px;height:40px;padding:0;\n  border-radius:999px;background:#1a2630;border-color:#405566;box-shadow:var(--shadow);\n  opacity:0;pointer-events:none;transform:translateY(6px);transition:.16s opacity,.16s transform,.16s background\n}\n#backToTop.visible{opacity:.94;pointer-events:auto;transform:none}\n#backToTop:hover{background:#263746}\n#backToTop::before{content:'↑';font-size:19px;line-height:1}\n@media(max-width:880px){\n  nav{position:sticky;top:0;z-index:29;display:flex;gap:3px;padding:7px 8px;scroll-snap-type:x proximity;box-shadow:0 6px 16px rgba(0,0,0,.13)}\n  nav .navGroupBody>button{scroll-snap-align:start;padding:8px 10px}\n  main{width:100%;padding:14px 12px 28px}\n  .pageTitle{min-height:0;padding-bottom:10px}\n  .pageTitle h2{font-size:21px}\n  .grid{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}\n  .quickActions{padding:8px}\n}\n@media(max-width:560px){\n  header h1{font-size:16px;width:100%;margin-right:0}\n  header .connection{order:2}\n  .metric .value,.metricValue{font-size:22px}\n  .card{padding:12px}\n  .toolbar{gap:6px}\n  .toolbar button,.quickActions button{flex:1 1 auto}\n  #toastHost{left:10px;right:10px;bottom:10px}\n  .toast{min-width:0;max-width:none;width:100%}\n  #backToTop{right:12px;bottom:72px}\n}\n@media(max-width:700px){.languagePicker label{display:none}.languagePicker select{min-width:92px;max-width:110px;padding:5px 6px}.motionPicker label,.scalePicker label{display:none}.motionPicker select{min-width:78px;max-width:96px;padding:5px 6px}}\n\n/* 1.2.22 dashboard motion system: short, GPU-friendly UI feedback only. */\n:root{--motion-fast:120ms;--motion-normal:170ms;--motion-slow:240ms;--motion-ease:cubic-bezier(.2,.75,.25,1)}\nhtml[data-motion=\"full\"] #loginView{animation:loginPanelIn var(--motion-slow) var(--motion-ease) both}\nhtml[data-motion=\"full\"] section.sectionEntering{animation:pageIn var(--motion-normal) var(--motion-ease) both}\nhtml[data-motion=\"full\"] section.sectionEntering .card{animation:cardIn var(--motion-normal) var(--motion-ease) both}\nhtml[data-motion=\"full\"] section.sectionEntering .card:nth-child(2){animation-delay:18ms}\nhtml[data-motion=\"full\"] section.sectionEntering .card:nth-child(3){animation-delay:32ms}\nhtml[data-motion=\"full\"] section.sectionEntering .card:nth-child(4){animation-delay:44ms}\nhtml[data-motion=\"full\"] .overlay.open{animation:overlayIn var(--motion-fast) ease-out both}\nhtml[data-motion=\"full\"] .overlay.open .modal{animation:modalIn var(--motion-normal) var(--motion-ease) both}\nhtml[data-motion=\"full\"] #notificationPanel.open{animation:panelIn var(--motion-normal) var(--motion-ease) both}\nhtml[data-motion=\"full\"] details[open]>:not(summary){animation:detailIn var(--motion-normal) ease-out both}\nhtml[data-motion=\"full\"] button:not(:disabled):hover{transform:translateY(-1px)}\nhtml[data-motion=\"full\"] button:not(:disabled):active{transform:translateY(1px) scale(.99)}\nhtml[data-motion=\"full\"] .summaryStatus,html[data-motion=\"full\"] .statusPill,html[data-motion=\"full\"] .badge,html[data-motion=\"full\"] .stateChip{transition:background var(--motion-fast),border-color var(--motion-fast),color var(--motion-fast),transform var(--motion-fast)}\nhtml[data-motion=\"full\"] .summaryStatus:hover{transform:translateY(-1px)}\nhtml[data-motion=\"full\"] .terrainProgressFill,html[data-motion=\"full\"] progress{transition:width 320ms var(--motion-ease),value 320ms var(--motion-ease)}\nhtml[data-motion=\"full\"] .toast.leaving{animation:toastOut var(--motion-normal) ease-in both}\nhtml[data-motion=\"full\"] nav .navGroupBody>button{transition:background var(--motion-fast),border-color var(--motion-fast),color var(--motion-fast),transform var(--motion-fast)}\nhtml[data-motion=\"full\"] nav .navGroupBody>button:hover{transform:translateX(2px)}\nhtml[data-motion=\"full\"] .navChevron{transition:transform var(--motion-normal) var(--motion-ease)}\n\nhtml[data-motion=\"reduced\"]{--motion-fast:70ms;--motion-normal:95ms;--motion-slow:120ms}\nhtml[data-motion=\"reduced\"] section.sectionEntering{animation:reducedFade var(--motion-normal) ease-out both}\nhtml[data-motion=\"reduced\"] .overlay.open .modal,html[data-motion=\"reduced\"] #notificationPanel.open{animation:reducedFade var(--motion-normal) ease-out both}\nhtml[data-motion=\"reduced\"] .toast{animation:reducedFade var(--motion-normal) ease-out both}\nhtml[data-motion=\"reduced\"] .toast.leaving{animation:reducedFadeOut var(--motion-normal) ease-in both}\nhtml[data-motion=\"reduced\"] body.loginMode::before{animation:loginGridDrift 90s linear infinite}\nhtml[data-motion=\"reduced\"] body.loginMode::after{animation:loginOrbFloat 32s ease-in-out infinite alternate}\n\nhtml[data-motion=\"off\"]{scroll-behavior:auto}\nhtml[data-motion=\"off\"] *,html[data-motion=\"off\"] *::before,html[data-motion=\"off\"] *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}\n\n@keyframes loginPanelIn{from{opacity:0;transform:translateY(8px) scale(.992)}to{opacity:1;transform:none}}\n@keyframes cardIn{from{opacity:.55;transform:translateY(5px)}to{opacity:1;transform:none}}\n@keyframes overlayIn{from{background:rgba(3,6,9,0)}to{background:rgba(3,6,9,.76)}}\n@keyframes modalIn{from{opacity:0;transform:translateY(8px) scale(.985)}to{opacity:1;transform:none}}\n@keyframes panelIn{from{opacity:0;transform:translateY(-6px) scale(.99)}to{opacity:1;transform:none}}\n@keyframes detailIn{from{opacity:.45;transform:translateY(-2px)}to{opacity:1;transform:none}}\n@keyframes toastOut{from{opacity:1;transform:none}to{opacity:0;transform:translateY(7px) scale(.985)}}\n@keyframes reducedFade{from{opacity:.55}to{opacity:1}}\n@keyframes reducedFadeOut{from{opacity:1}to{opacity:0}}\n\n@media(prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}\n}\n\n\n/* 1.2.22 theme refinement + Anti-Cheat investigation UI */\nheader{background:rgba(14,20,27,.94);backdrop-filter:blur(14px);box-shadow:0 5px 20px rgba(0,0,0,.16)}\nnav{background:linear-gradient(180deg,#0f161d 0%,#0c1218 100%)}\nnav button{position:relative;border-radius:8px;color:#a7b5c1;transition:.14s background,.14s color,.14s border-color}\nnav button:hover{background:rgba(105,174,250,.055);color:#dfeaf3}\nnav button.active{background:linear-gradient(90deg,rgba(66,127,184,.24),rgba(43,70,94,.50));border-color:rgba(82,132,176,.38);color:#fff;box-shadow:inset 3px 0 0 var(--accent)}\n.card{background:linear-gradient(180deg,rgba(18,26,35,.97),rgba(14,21,28,.97));border-color:var(--line-soft);box-shadow:0 8px 22px rgba(0,0,0,.13),inset 0 1px 0 rgba(255,255,255,.018);transition:border-color .16s,box-shadow .16s}\n.card:hover{border-color:rgba(78,105,130,.52)}\n.cardHeader{padding-bottom:8px;border-bottom:1px solid rgba(76,96,115,.20)}\n.cardHeader h3{font-size:14px;letter-spacing:.005em}\nbutton{background:linear-gradient(180deg,#263542,#202c37);border-color:#3a4d5e;box-shadow:inset 0 1px 0 rgba(255,255,255,.035)}\nbutton:hover{background:linear-gradient(180deg,#304352,#273744);border-color:#536b80}\n#app button.primary,.overlay button.primary{background:linear-gradient(180deg,#2867a2,#205381);border-color:#3d7db6}\n#app button.danger,.overlay button.danger{background:linear-gradient(180deg,#70383a,#5d2e31);border-color:#9b5054}\ninput,select{background:#0b1117;border-color:#334655;box-shadow:inset 0 1px 2px rgba(0,0,0,.18)}\n.tableWrap{border-color:rgba(74,96,116,.40);background:rgba(8,13,18,.22)}\nth{background:#17222c;color:#bdcad5;border-bottom-color:#334555}\ntd{border-bottom-color:#22313d}\ntr:nth-child(even) td{background:rgba(17,25,33,.55)}\ntr:hover td{background:rgba(54,91,122,.18)}\n.sectionTabs{background:#0b1117;border-color:#2a3a48;padding:4px;box-shadow:inset 0 1px 2px rgba(0,0,0,.22)}\n.sectionTabs button{border-radius:7px}\n.sectionTabs button.active{background:linear-gradient(180deg,#29445b,#20374b);box-shadow:inset 0 0 0 1px rgba(99,154,200,.34),0 3px 10px rgba(0,0,0,.16)}\n.summaryHero{background:radial-gradient(circle at 0% 0%,rgba(105,174,250,.085),transparent 34%),linear-gradient(135deg,#131d26,#0f161d);border-color:rgba(75,99,120,.48);box-shadow:0 12px 30px rgba(0,0,0,.13)}\n.stateChip{border-color:rgba(84,107,128,.42);background:rgba(20,30,39,.82)}\n.badge{border:1px solid rgba(255,255,255,.075);box-shadow:inset 0 1px 0 rgba(255,255,255,.025)}\n/* Normalize semantic badge colors: low/clean = green, medium/review = amber, high/suspicious = red. */\n.badge.low{background:rgba(79,145,73,.28);color:#a9e89c;border-color:rgba(143,218,114,.24)}\n.badge.medium{background:rgba(151,119,36,.30);color:#ffe08a;border-color:rgba(255,209,102,.25)}\n.badge.moderate{background:rgba(156,94,39,.30);color:#ffc18a;border-color:rgba(255,173,102,.25)}\n.badge.high{background:rgba(153,61,65,.32);color:#ffaaaa;border-color:rgba(255,116,116,.27)}\n::-webkit-scrollbar{width:10px;height:10px}::-webkit-scrollbar-track{background:#0a0f14}::-webkit-scrollbar-thumb{background:#304252;border:2px solid #0a0f14;border-radius:999px}::-webkit-scrollbar-thumb:hover{background:#41586b}\n\n#acDetail{border-color:rgba(105,174,250,.26);box-shadow:0 18px 45px rgba(0,0,0,.22)}\n.acPlayerOverview{grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px}\n.acInfoTile{position:relative;overflow:hidden;background:linear-gradient(180deg,rgba(25,36,47,.94),rgba(15,23,31,.94));border-color:rgba(68,94,116,.48);padding:12px 13px}\n.acInfoTile:before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:2px;background:#445d72}\n.acInfoTile.good:before{background:var(--good)}.acInfoTile.warn:before{background:var(--warn)}.acInfoTile.bad:before{background:var(--bad)}.acInfoTile.accent:before{background:var(--accent)}\n.acInfoTile .v{font-size:18px;letter-spacing:-.015em}\n.acRiskMeter{margin-top:8px}.acRiskTrack{height:8px;background:linear-gradient(90deg,rgba(143,218,114,.25) 0 10%,rgba(255,209,102,.28) 10% 50%,rgba(255,116,116,.30) 50% 100%);border:1px solid rgba(85,105,121,.45);border-radius:999px;position:relative;overflow:visible}.acRiskFill{height:100%;border-radius:999px;background:linear-gradient(90deg,var(--good),var(--warn) 45%,var(--bad));width:0;transition:width .25s ease}.acRiskMarker{position:absolute;top:50%;width:12px;height:12px;border-radius:50%;background:#f5f9fc;border:2px solid #16212b;box-shadow:0 0 0 2px rgba(105,174,250,.30);transform:translate(-50%,-50%);left:0}.acRiskScale{display:flex;justify-content:space-between;font-size:9px;color:#718391;margin-top:4px;text-transform:uppercase;letter-spacing:.055em}\n.acInvestigationPanel{display:grid;grid-template-columns:minmax(280px,1.1fr) minmax(300px,1fr);gap:10px;margin:10px 0 12px}.acInvestigationCard{border:1px solid rgba(72,96,117,.46);border-radius:10px;padding:12px;background:linear-gradient(180deg,rgba(15,24,32,.90),rgba(11,18,24,.90))}.acInvestigationCard h4{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:#9fb0be;margin-bottom:8px}.acEvidenceGrid{display:grid;grid-template-columns:repeat(3,minmax(110px,1fr));gap:7px}.acEvidenceStat{padding:8px 9px;border:1px solid rgba(68,91,111,.40);border-radius:8px;background:rgba(22,31,40,.56)}.acEvidenceStat b{display:block;font-size:17px}.acEvidenceStat span{font-size:10px;color:var(--muted)}.acEvidenceStat.strong{border-color:rgba(255,116,116,.30)}.acEvidenceStat.server{border-color:rgba(105,174,250,.32)}\n.acReasonList{display:grid;gap:6px}.acReason{padding:7px 9px;border-left:3px solid #49657d;border-radius:5px;background:rgba(25,35,44,.62);font-size:11px;line-height:1.42}.acReason.high{border-left-color:var(--bad)}.acReason.medium{border-left-color:var(--warn)}.acReason .meta{color:var(--muted);margin-top:2px}\n.acPlayerFilterBar{display:flex;gap:8px;align-items:end;flex-wrap:wrap;margin:0 0 10px}.acPlayerFilterBar .field{min-width:150px}.acPlayerFilterBar input{min-width:220px}.acPlayerCount{margin-left:auto;color:var(--muted);font-size:11px;padding-bottom:8px}.acSortHead{all:unset;display:inline-flex;align-items:center;gap:5px;cursor:pointer;color:inherit;font:inherit;font-weight:800}.acSortHead:hover{color:var(--accent)}.acSortArrow{font-size:9px;color:var(--muted);min-width:8px}.acSortHead.active .acSortArrow{color:var(--accent)}\n.acDomainBadge{display:inline-flex;align-items:center;gap:5px;padding:2px 6px;border-radius:999px;border:1px solid rgba(83,106,126,.42);background:rgba(23,33,42,.72);font-size:10px;font-weight:750;color:#afbeca}.acDomainBadge.server{color:#9dcbff;border-color:rgba(105,174,250,.34);background:rgba(44,91,133,.14)}.acDomainBadge.integrity{color:#d9c0ff;border-color:rgba(198,156,255,.28);background:rgba(99,69,133,.14)}\n.acFresh{color:var(--good)}.acStale{color:var(--warn)}.acExpired{color:var(--bad)}\n.acFindingSummary{min-width:300px;max-width:650px;white-space:normal}.acFindingSummary b{display:block;margin-bottom:3px}.acFindingSummary .why{color:#8ea0b0;line-height:1.4}.acFindingSummary .next{margin-top:5px;color:#aebbc6}\n@media(max-width:1050px){.acInvestigationPanel{grid-template-columns:1fr}.acEvidenceGrid{grid-template-columns:repeat(2,minmax(110px,1fr))}}\n@media(max-width:700px){.acPlayerFilterBar input{min-width:150px;width:100%}.acPlayerCount{width:100%;margin-left:0}.acEvidenceGrid{grid-template-columns:1fr 1fr}}\n\n\n/* 1.2.28 web panel refinement pass */\n:root{\n  --radius-sm:7px;--radius-md:10px;--radius-lg:14px;\n  --surface-0:#0a1016;--surface-1:#101820;--surface-2:#151f29;--surface-3:#1a2631;\n  --border-subtle:rgba(107,132,153,.22);--border-strong:rgba(107,132,153,.38);\n  --shadow-card:0 8px 24px rgba(0,0,0,.18);--shadow-float:0 18px 48px rgba(0,0,0,.34);\n}\nbody{font-size:13px;line-height:1.45;letter-spacing:.001em}\nheader{background:rgba(14,21,28,.94);backdrop-filter:blur(14px);border-bottom-color:var(--border-subtle);box-shadow:0 1px 0 rgba(255,255,255,.018)}\nheader h1{font-size:17px;font-weight:780;letter-spacing:-.018em}\nheader .headerIcon,#liveBtn,#logoutBtn{min-height:33px}\n.headerSearch button{background:rgba(10,16,22,.72);border-color:var(--border-subtle)}\n.headerSearch button:hover{border-color:rgba(105,174,250,.42);background:rgba(18,31,42,.9)}\nnav{background:linear-gradient(180deg,rgba(15,22,29,.98),rgba(12,19,25,.98));border-right-color:var(--border-subtle);padding:14px 9px}\nnav .navLabel{padding:12px 10px 6px;color:#738698;letter-spacing:.095em}\nnav button{position:relative;border-radius:8px;padding:8px 10px;color:#b6c2cc;font-weight:620}\nnav button:hover{background:rgba(105,174,250,.055);color:#eaf3fb}\nnav button.active{background:linear-gradient(90deg,rgba(64,116,165,.22),rgba(44,67,88,.36));border-color:rgba(93,132,169,.28);color:#fff;box-shadow:inset 2px 0 0 var(--accent)}\nmain{padding:20px 22px 34px}\n.pageTitle{margin-bottom:18px;padding-bottom:12px;border-bottom:1px solid rgba(91,114,133,.18)}\n.pageTitle h2{font-size:22px;font-weight:790;letter-spacing:-.025em}\n.pageTitle .subtitle{font-size:12px;max-width:900px;line-height:1.5}\nh2{letter-spacing:-.02em} h3{font-size:14px;letter-spacing:-.01em} h4{font-size:12px}\n.card{background:linear-gradient(180deg,rgba(18,27,36,.96),rgba(14,22,29,.96));border-color:var(--border-subtle);border-radius:var(--radius-md);padding:13px 14px;box-shadow:var(--shadow-card)}\n.cardHeader{min-height:28px;margin-bottom:11px;padding-bottom:8px;border-bottom:1px solid rgba(100,124,145,.14)}\n.cardHeader h3,.cardHeader h4{font-weight:760}\n.grid{gap:10px}\n.metric{min-height:88px}\n.metric .value,.metricValue{font-variant-numeric:tabular-nums;letter-spacing:-.025em}\n.metric .detail{line-height:1.35}\n.toolbar{padding:8px 9px;background:rgba(11,18,24,.48);border:1px solid rgba(89,113,133,.18);border-radius:9px;margin-bottom:10px}\nbutton{border-radius:7px;border-color:rgba(98,120,139,.42);background:linear-gradient(180deg,#2b3946,#24313c);font-weight:650;box-shadow:0 1px 0 rgba(255,255,255,.025)}\nbutton:hover{background:linear-gradient(180deg,#354756,#2b3b48);border-color:rgba(117,145,169,.58)}\n#app button.primary,.overlay button.primary{background:linear-gradient(180deg,#2c6aa6,#24598b);border-color:#3e7fbb}\nbutton.primary:hover{background:linear-gradient(180deg,#3377b7,#29679f)}\n#app button.danger,.overlay button.danger{background:linear-gradient(180deg,#773b3b,#613030);border-color:#9a4a4a}\ninput,select,textarea{background:#0b1218;border-color:rgba(91,115,136,.42);border-radius:7px;min-height:34px}\n#app input:hover,#app select:hover,#app textarea:hover,.overlay input:hover,.overlay select:hover,.overlay textarea:hover{border-color:rgba(111,139,162,.56)}\n#app input:focus,#app select:focus,#app textarea:focus,.overlay input:focus,.overlay select:focus,.overlay textarea:focus{border-color:rgba(105,174,250,.68);box-shadow:0 0 0 3px rgba(105,174,250,.09);outline:none}\n.segmented{background:rgba(8,13,18,.72);border-color:var(--border-subtle)}\n.segmented button.active{background:rgba(62,103,140,.46);box-shadow:none}\n.tableWrap{border-color:var(--border-subtle);border-radius:9px;background:rgba(8,14,19,.28)}\ntable{font-variant-numeric:tabular-nums}\nth{font-size:10px;letter-spacing:.055em;text-transform:uppercase;color:#90a2b1;background:#121d26!important;border-bottom-color:rgba(90,113,133,.3)!important}\ntd{line-height:1.38}\ntbody tr{transition:background .12s ease}\ntbody tr:hover{background:rgba(105,174,250,.035)}\n.warning,.infoBox,.errorBox{border-radius:9px;box-shadow:inset 3px 0 0 currentColor}\n.warning{background:rgba(74,57,21,.48)} .infoBox{background:rgba(20,45,67,.5)} .errorBox{background:rgba(72,29,29,.5)}\ndetails{border-radius:9px} details>summary{cursor:pointer;font-weight:680}\n.pageStatusIndicator{box-shadow:inset 0 1px 0 rgba(255,255,255,.025)}\n#globalStatusBar{background:rgba(10,16,22,.93);backdrop-filter:blur(10px);border-bottom-color:var(--border-subtle)}\n.statusPill,.summaryStatus{border-color:rgba(93,116,136,.23)!important;background:rgba(18,27,35,.72)!important}\n.statusPill b{font-variant-numeric:tabular-nums}\n.emptyState{padding:28px 20px;text-align:center;border:1px dashed rgba(103,127,147,.3);border-radius:10px;background:rgba(11,18,24,.42);color:var(--muted)}\n.emptyState b{display:block;color:var(--text);margin-bottom:4px}\n.kbd{border-color:rgba(106,130,151,.34)!important;background:rgba(8,14,19,.72)!important}\n.acInfoTile,.acInvestigationCard,.dbStorageDatabase{box-shadow:0 5px 18px rgba(0,0,0,.13)}\n.acFindingSummary .why{color:#9aaab7}\n@media(max-width:1100px){main{padding:17px 16px 28px}.pageTitle h2{font-size:20px}}\n@media(max-width:700px){main{padding:14px 11px 24px}.card{padding:11px}.toolbar{padding:7px}.pageTitle{margin-bottom:13px}}\n\n\n/* 1.2.28 visual investigation pass: drawers, timelines, visual diffs, clusters and switches */\n/* Checkbox baseline: keep selection checkboxes native. Boolean settings are upgraded to switches by JS. */\ninput[type=\"checkbox\"]{accent-color:#4f8fc8;cursor:pointer}\ninput[type=\"checkbox\"]:disabled{cursor:not-allowed;opacity:.48}\nlabel.switchToggle{display:inline-flex!important;align-items:center;gap:9px;min-height:30px;padding:3px 1px;border:0;background:transparent;cursor:pointer;line-height:1.25;transition:color .15s}\nlabel.switchToggle:hover{color:#c6d4df!important}\nlabel.switchToggle.switchBlock{display:flex!important;width:100%;white-space:normal}\nlabel.linkedSwitchLabel{cursor:pointer}\n.suiteSwitchInput{position:absolute!important;opacity:0!important;width:1px!important;height:1px!important;min-width:1px!important;margin:0!important;pointer-events:none!important}\n.suiteSwitchTrack{position:relative;display:inline-flex;flex:0 0 auto;width:50px;height:24px;border:1px solid #384955;border-radius:999px;background:#121a21;box-shadow:inset 0 1px 3px rgba(0,0,0,.52);vertical-align:middle;transition:background .15s,border-color .15s,box-shadow .15s}\n.suiteSwitchTrack::before{content:\"OFF\";position:absolute;right:5px;top:50%;transform:translateY(-50%);font-size:8px;line-height:1;font-weight:800;letter-spacing:.035em;color:#7f909e;pointer-events:none;transition:color .15s}\n.suiteSwitchTrack::after{content:\"\";position:absolute;left:3px;top:3px;width:16px;height:16px;border-radius:50%;background:#8495a2;box-shadow:0 1px 3px rgba(0,0,0,.58);transition:transform .16s ease,background .16s ease}\n.suiteSwitchTrack.isOn,.suiteSwitchInput:checked + .suiteSwitchTrack{background:#0d4f7b;border-color:#337eaf;box-shadow:inset 0 1px 3px rgba(0,0,0,.26),0 0 0 1px rgba(74,156,216,.08)}\n.suiteSwitchTrack.isOn::before,.suiteSwitchInput:checked + .suiteSwitchTrack::before{content:\"ON\";left:7px;right:auto;color:#dff3ff}\n.suiteSwitchTrack.isOn::after,.suiteSwitchInput:checked + .suiteSwitchTrack::after{transform:translateX(26px);background:#f4f8fb}\n.switchToggle.switchOn,.linkedSwitchLabel.switchOn{color:#c8dfef!important}\n.suiteSwitchInput:focus-visible + .suiteSwitchTrack{outline:2px solid rgba(76,157,216,.48);outline-offset:2px}\n.suiteSwitchInput:disabled + .suiteSwitchTrack{opacity:.42;cursor:not-allowed;filter:saturate(.55)}\n.switchToggle .suiteSwitchTrack{order:-1}\n.switchCell{white-space:nowrap}.switchCell .suiteSwitchTrack{margin:0 auto}\n\n.acDrawerBackdrop{display:none;position:fixed;inset:0;z-index:220;background:rgba(2,7,11,.66);backdrop-filter:blur(3px)}\n.acDrawerBackdrop.open{display:block;animation:acFadeIn .16s ease-out}\n#acDetail.acPlayerDrawer{position:fixed;z-index:230;right:0;top:0;bottom:0;width:min(1120px,86vw);max-width:none!important;margin:0!important;border-radius:16px 0 0 16px;border:1px solid rgba(105,174,250,.32);background:linear-gradient(180deg,#111a23,#0c1319);box-shadow:-28px 0 70px rgba(0,0,0,.48);padding:14px 16px 24px;overflow-y:auto;overscroll-behavior:contain;animation:acDrawerIn .20s ease-out}\n#acDetail.acPlayerDrawer .acDrawerHeader{position:sticky;top:-14px;z-index:6;margin:-14px -16px 12px;padding:14px 16px 11px;background:rgba(14,22,29,.96);backdrop-filter:blur(9px);border-bottom:1px solid rgba(78,104,125,.38)}\nbody.acDrawerOpen{overflow:hidden}\n@keyframes acDrawerIn{from{transform:translateX(45px);opacity:.25}to{transform:translateX(0);opacity:1}}\n@keyframes acFadeIn{from{opacity:0}to{opacity:1}}\n@media(max-width:900px){#acDetail.acPlayerDrawer{width:96vw;border-radius:13px 0 0 13px}}\n@media(max-width:640px){#acDetail.acPlayerDrawer{width:100vw;border-radius:0;padding-left:10px;padding-right:10px}#acDetail.acPlayerDrawer .acDrawerHeader{margin-left:-10px;margin-right:-10px;padding-left:10px;padding-right:10px}}\n\n/* Lag-spike investigation drawer: shares the player-card visual language but is optimized for incident evidence. */\n#lagIncidentBackdrop{display:none;position:fixed;inset:0;z-index:240;background:rgba(2,7,11,.66);backdrop-filter:blur(3px)}\n#lagIncidentBackdrop.open{display:block;animation:acFadeIn .16s ease-out}\n#lagIncidentDrawer{display:none;position:fixed;z-index:250;right:0;top:0;bottom:0;width:min(1120px,88vw);max-width:none;margin:0;border-radius:16px 0 0 16px;border:1px solid rgba(255,173,102,.34);background:linear-gradient(180deg,#111a23,#0c1319);box-shadow:-28px 0 70px rgba(0,0,0,.5);padding:14px 16px 28px;overflow-y:auto;overscroll-behavior:contain;animation:acDrawerIn .20s ease-out}\n#lagIncidentDrawer.open{display:block}\n#lagIncidentDrawer .lagDrawerHeader{position:sticky;top:-14px;z-index:6;margin:-14px -16px 12px;padding:14px 16px 11px;background:rgba(14,22,29,.97);backdrop-filter:blur(9px);border-bottom:1px solid rgba(255,173,102,.24)}\nbody.lagIncidentDrawerOpen{overflow:hidden}\n.lagDrawerHero{display:grid;grid-template-columns:auto 1fr;gap:13px;align-items:start;margin-bottom:12px;padding:12px;border:1px solid rgba(83,108,128,.4);border-radius:11px;background:linear-gradient(135deg,rgba(26,39,51,.94),rgba(13,20,27,.94))}\n.lagDrawerScore{min-width:92px;padding:11px 10px;border-radius:10px;text-align:center;background:#151f28;border:1px solid rgba(255,173,102,.34)}\n.lagDrawerScore .value{font-size:28px;line-height:1;font-weight:900;font-variant-numeric:tabular-nums}.lagDrawerScore .label{margin-top:5px;font-size:9px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}\n.lagDrawerScore.critical{border-color:rgba(255,116,116,.5);box-shadow:inset 3px 0 0 rgba(255,116,116,.72)}\n.lagDrawerScore.high,.lagDrawerScore.watch{box-shadow:inset 3px 0 0 rgba(255,173,102,.68)}\n.lagDrawerMetricGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;margin:10px 0}\n.lagDrawerMetric{padding:9px 10px;border:1px solid rgba(78,103,124,.34);border-radius:9px;background:rgba(10,17,23,.56)}\n.lagDrawerMetric .label{font-size:9px;text-transform:uppercase;letter-spacing:.065em;color:var(--muted)}.lagDrawerMetric .value{margin-top:3px;font-size:16px;font-weight:820;font-variant-numeric:tabular-nums}.lagDrawerMetric .sub{margin-top:2px;font-size:10px;color:var(--muted)}\n.lagPhaseGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.lagPhaseCard{padding:10px;border:1px solid rgba(74,98,118,.36);border-radius:9px;background:rgba(10,17,23,.5)}.lagPhaseCard h4{margin:0 0 6px}.lagPhaseRow{display:flex;justify-content:space-between;gap:10px;padding:3px 0;border-bottom:1px solid rgba(72,92,108,.18);font-size:10px}.lagPhaseRow:last-child{border-bottom:0}.lagPhaseRow span:first-child{color:var(--muted)}\n.lagCauseGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:7px}.lagCauseCard{padding:9px 10px;border:1px solid rgba(74,98,118,.34);border-left:3px solid #6e8496;border-radius:8px;background:rgba(10,17,23,.5)}.lagCauseCard.watch{border-left-color:var(--warn)}.lagCauseCard.high{border-left-color:var(--orange)}.lagCauseCard.critical{border-left-color:var(--bad)}\n.lagRawTable{max-height:340px;overflow:auto}.lagClickableHint{color:#aebdca;font-size:10px;margin-top:4px}.lagIncidentMarkerHover{cursor:pointer!important}\n@media(max-width:900px){#lagIncidentDrawer{width:96vw}.lagPhaseGrid{grid-template-columns:1fr}}\n@media(max-width:640px){#lagIncidentDrawer{width:100vw;border-radius:0;padding-left:10px;padding-right:10px}#lagIncidentDrawer .lagDrawerHeader{margin-left:-10px;margin-right:-10px;padding-left:10px;padding-right:10px}.lagDrawerHero{grid-template-columns:1fr}.lagDrawerScore{max-width:140px}}\n\n.acTimeline{position:relative;display:grid;gap:0;padding:4px 2px 4px 5px}\n.acTimeline:before{content:\"\";position:absolute;left:14px;top:12px;bottom:12px;width:2px;background:linear-gradient(180deg,rgba(105,174,250,.46),rgba(105,174,250,.06))}\n.acTimelineItem{position:relative;display:grid;grid-template-columns:22px minmax(120px,150px) 1fr;gap:8px;padding:7px 7px 7px 0;align-items:start;border-radius:8px}\n.acTimelineItem:hover{background:rgba(105,174,250,.045)}\n.acTimelineDot{z-index:1;width:11px;height:11px;margin:4px 0 0 4px;border-radius:50%;background:#708494;border:2px solid #101820;box-shadow:0 0 0 2px rgba(112,132,148,.18)}\n.acTimelineItem.good .acTimelineDot{background:var(--good);box-shadow:0 0 0 2px rgba(143,218,114,.15)}\n.acTimelineItem.warn .acTimelineDot{background:var(--warn);box-shadow:0 0 0 2px rgba(255,209,102,.15)}\n.acTimelineItem.bad .acTimelineDot{background:var(--bad);box-shadow:0 0 0 2px rgba(255,116,116,.16)}\n.acTimelineItem.accent .acTimelineDot{background:var(--accent);box-shadow:0 0 0 2px rgba(105,174,250,.17)}\n.acTimelineWhen{font-size:10px;color:var(--muted);line-height:1.35;padding-top:1px}.acTimelineWhen b{display:block;color:#becbd5;font-size:11px}\n.acTimelineBody{min-width:0;font-size:11px;line-height:1.42}.acTimelineBody .title{font-size:12px;font-weight:790;color:#e6eef5}.acTimelineBody .meta{color:var(--muted);margin-top:2px;overflow-wrap:anywhere}.acTimelineCompact{max-height:340px;overflow:auto;padding-right:4px}\n@media(max-width:620px){.acTimelineItem{grid-template-columns:22px 1fr}.acTimelineWhen{grid-column:2}.acTimelineBody{grid-column:2}}\n\n.acDiffPanel{display:grid;gap:7px;min-width:300px;max-width:620px}.acDiffHeader{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.acDiffStats{display:flex;gap:5px;flex-wrap:wrap}.acDiffStat{padding:3px 7px;border:1px solid rgba(88,111,130,.38);border-radius:999px;background:rgba(23,33,42,.70);font-size:10px;font-weight:750}.acDiffStat.modified{color:#ffc27d;border-color:rgba(255,173,102,.34)}.acDiffStat.added{color:#ff9a9a;border-color:rgba(255,116,116,.30)}.acDiffStat.removed{color:#d9bdff;border-color:rgba(198,156,255,.28)}.acDiffStat.matched{color:#afe8a4;border-color:rgba(143,218,114,.28)}\n.acDiffList{display:grid;gap:3px;margin-top:4px}.acDiffPath{display:grid;grid-template-columns:72px 1fr;gap:6px;padding:4px 6px;border-radius:6px;background:rgba(8,13,18,.36);border-left:3px solid #5b7184;font-size:10px}.acDiffPath.modified{border-left-color:var(--orange)}.acDiffPath.added{border-left-color:var(--bad)}.acDiffPath.removed{border-left-color:var(--purple)}.acDiffPath .kind{text-transform:uppercase;letter-spacing:.05em;font-weight:850}.acDiffPath code{white-space:normal;overflow-wrap:anywhere}.acDiffMore summary{cursor:pointer;color:#b7c6d1;font-size:10px}\n\n.acClusterBoard{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:9px;margin-top:10px}.acClusterCard{border:1px solid rgba(76,101,122,.44);border-radius:11px;background:linear-gradient(180deg,rgba(19,29,38,.94),rgba(11,18,24,.94));overflow:hidden}.acClusterCard.multi{border-color:rgba(255,209,102,.44);box-shadow:inset 3px 0 0 rgba(255,209,102,.55)}.acClusterHead{display:flex;gap:8px;align-items:center;padding:10px 11px;border-bottom:1px solid rgba(75,97,115,.28)}.acClusterHead .grow{min-width:0}.acClusterHead .modName{font-weight:850;overflow-wrap:anywhere}.acClusterVariants{display:grid}.acClusterVariant{padding:8px 10px;border-top:1px solid rgba(58,78,95,.22)}.acClusterVariant:first-child{border-top:0}.acClusterVariantHead{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.acClusterVariant .fingerprint{font-size:10px;color:#9db0bf;overflow-wrap:anywhere}.acClusterBar{height:5px;margin:6px 0;background:#0a1117;border-radius:999px;overflow:hidden;border:1px solid rgba(64,85,103,.32)}.acClusterBar span{display:block;height:100%;background:linear-gradient(90deg,#4d83b1,#69aefa);border-radius:999px}.acClusterPlayers{display:flex;gap:4px;flex-wrap:wrap}.acClusterPlayer{padding:2px 6px;font-size:10px;border-radius:999px!important;background:#182630!important}.acClusterFlag{font-size:9px;font-weight:850;text-transform:uppercase;letter-spacing:.05em}.acClusterFlag.outlier{color:#ffca77}.acClusterFlag.dominant{color:#9fd7ff}\n\n\n.acCompareGrid{display:grid;gap:4px;margin-top:6px;min-width:210px}.acCompareRow{display:grid;grid-template-columns:72px 78px 1fr;gap:5px;align-items:center;padding:4px 6px;border-radius:6px;background:rgba(8,13,18,.32);font-size:10px;border-left:3px solid #52697b}.acCompareRow.match{border-left-color:var(--good)}.acCompareRow.mismatch{border-left-color:var(--bad)}.acCompareRow.diagnostic{border-left-color:var(--warn)}.acCompareGroup{margin-top:7px;padding:7px;border:1px solid rgba(73,97,117,.26);border-radius:8px;background:rgba(8,13,18,.20)}.acCompareGroupHead{display:flex;align-items:center;gap:7px;margin-bottom:3px}.acCompareGroupHead b{font-size:10px;text-transform:uppercase;letter-spacing:.055em;color:#b7c7d3}.acCompareGroupHead .badge{margin-left:auto}\n.acCompareRow.unavailable{opacity:.68}.acCompareKey{text-transform:uppercase;letter-spacing:.05em;color:#9eb0be;font-weight:800}.acCompareValue{font-weight:850}.acCompareRow.match .acCompareValue{color:#a8e69c}.acCompareRow.mismatch .acCompareValue{color:#ff9d9d}.acCompareRow.diagnostic .acCompareValue{color:#ffe08a}.acCompareNote{color:var(--muted);overflow-wrap:anywhere}\n\n\n/* 1.2.28 player drawer + ModDB startup baseline polish */\n#acDetail.acPlayerDrawer .acDrawerHeader{display:block!important}\n.acDrawerHeaderLine{display:flex;align-items:flex-start;gap:8px;flex-wrap:wrap}\n.acDrawerPosture{margin-top:9px;padding:9px 10px;border:1px solid rgba(76,102,124,.38);border-radius:11px;background:linear-gradient(180deg,rgba(19,31,41,.88),rgba(12,20,27,.86));box-shadow:0 6px 18px rgba(0,0,0,.12)}\n.acDrawerPostureLabel{font-size:9px;text-transform:uppercase;letter-spacing:.09em;font-weight:850;color:#8ea4b6;margin-bottom:6px}\n.acDrawerQuickBar{display:flex;gap:6px;flex-wrap:wrap}\n.acDrawerQuickBar .stateChip{font-size:10px}\n.acDrawerTabs{display:flex;gap:5px;align-items:center;overflow-x:auto;margin:9px -3px -11px;padding:0 3px 10px;border-top:1px solid rgba(74,98,118,.28);padding-top:9px;scrollbar-width:thin}\n.acDrawerTab{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;padding:7px 10px;font-size:10px;font-weight:780;border-radius:9px 9px 5px 5px;background:rgba(18,29,38,.72);border-color:rgba(68,91,111,.40);color:#afbeca;position:relative}\n.acDrawerTab:hover{border-color:rgba(105,174,250,.55);background:rgba(34,55,72,.86);color:#e5f1fa}\n.acDrawerTab.active{background:linear-gradient(180deg,rgba(50,91,126,.82),rgba(27,53,75,.82));border-color:rgba(105,174,250,.68);color:#f2f8fd;box-shadow:0 5px 14px rgba(28,83,126,.14)}\n.acDrawerTab.active:after{content:\"\";position:absolute;left:9px;right:9px;bottom:-10px;height:2px;border-radius:2px;background:var(--accent);box-shadow:0 0 9px rgba(105,174,250,.35)}\n.acDrawerTabCount{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:999px;background:rgba(0,0,0,.28);color:#c6d5e0;font-size:9px;font-weight:850}\n.acDrawerTabCount.warn{background:rgba(255,209,102,.14);color:#ffe08a}.acDrawerTabCount.bad{background:rgba(255,116,116,.14);color:#ffabab}.acDrawerTabCount.good{background:rgba(143,218,114,.13);color:#b7eba9}\n.acDrawerTabPanel{display:none;animation:acTabIn .13s ease-out}.acDrawerTabPanel.active{display:block}.acDrawerTabPanel>.grid,.acDrawerTabGrid{margin-top:0}\n@keyframes acTabIn{from{opacity:.45;transform:translateY(3px)}to{opacity:1;transform:translateY(0)}}\n.acDrawerTabIntro{display:flex;align-items:flex-start;gap:10px;margin-bottom:10px;padding:9px 11px;border:1px solid rgba(69,93,113,.30);border-radius:9px;background:rgba(12,20,27,.48)}\n.acDrawerTabIntro b{display:block;font-size:11px}.acDrawerTabIntro span{font-size:10px;color:var(--muted);line-height:1.4}\n.acConnectionSummary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px;margin-bottom:10px}\n.acConnectionStat{border:1px solid rgba(69,93,113,.36);border-radius:9px;padding:9px 10px;background:rgba(15,24,32,.68)}.acConnectionStat .k{font-size:9px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);font-weight:800}.acConnectionStat .v{font-size:15px;font-weight:850;margin-top:3px;overflow-wrap:anywhere}.acConnectionStat .sub{font-size:10px;color:var(--muted);margin-top:3px;line-height:1.35}\n#acDetail [id^=\"acDrawer\"],#acPlayerOverview{scroll-margin-top:190px}\n.acDrawerSectionHint{font-size:10px;color:var(--muted);margin-top:3px}\n@media(max-width:640px){.acDrawerTabs{margin-left:-1px;margin-right:-1px}.acDrawerTab{padding:7px 9px}.acDrawerHeaderLine .spacer{display:none}.acDrawerPosture{padding:8px}.acConnectionSummary{grid-template-columns:1fr 1fr}}\n@media(max-width:430px){.acConnectionSummary{grid-template-columns:1fr}}\n\n\n\n/* 1.2.28 full WebPanel visual system pass */\n:root{\n  --suite-cyan:#67c7ef;\n  --suite-blue:#69aefa;\n  --suite-indigo:#7a8cff;\n  --suite-violet:#a083e8;\n  --suite-teal:#62bfc2;\n  --suite-panel:rgba(17,25,34,.94);\n  --suite-panel-strong:rgba(12,19,27,.97);\n  --suite-border:rgba(117,145,169,.22);\n  --suite-border-hover:rgba(119,165,206,.42);\n  --suite-glow:0 0 0 1px rgba(105,174,250,.025),0 12px 30px rgba(0,0,0,.18);\n  --suite-glow-strong:0 18px 55px rgba(0,0,0,.34),0 0 32px rgba(74,145,218,.055);\n  --suite-radius:14px;\n  --suite-radius-lg:18px;\n}\nbody:not(.loginMode){\n  background:\n    radial-gradient(780px 520px at 82% 5%,rgba(105,174,250,.055),transparent 67%),\n    radial-gradient(640px 500px at 18% 58%,rgba(98,191,194,.035),transparent 70%),\n    radial-gradient(720px 560px at 74% 92%,rgba(122,140,255,.038),transparent 72%),\n    linear-gradient(180deg,#091018 0%,#0a1118 45%,#081017 100%);\n  background-attachment:fixed;\n}\nbody:not(.loginMode)::before,\nbody:not(.loginMode)::after{\n  content:\"\";position:fixed;pointer-events:none;z-index:0;border-radius:50%;filter:blur(28px);opacity:.46\n}\nbody:not(.loginMode)::before{\n  width:36vw;height:36vw;min-width:340px;min-height:340px;right:-15vw;top:16vh;\n  background:radial-gradient(circle,rgba(103,199,239,.055),rgba(105,174,250,.022) 42%,transparent 70%);\n  animation:suiteAmbientA 22s ease-in-out infinite alternate\n}\nbody:not(.loginMode)::after{\n  width:32vw;height:32vw;min-width:300px;min-height:300px;left:10vw;bottom:-17vw;\n  background:radial-gradient(circle,rgba(160,131,232,.045),rgba(98,191,194,.018) 46%,transparent 72%);\n  animation:suiteAmbientB 27s ease-in-out infinite alternate\n}\n#app{position:relative;z-index:1}\n@keyframes suiteAmbientA{from{transform:translate3d(0,0,0) scale(1)}to{transform:translate3d(-26px,18px,0) scale(1.07)}}\n@keyframes suiteAmbientB{from{transform:translate3d(0,0,0) scale(1)}to{transform:translate3d(20px,-20px,0) scale(1.08)}}\n\n/* Header */\nheader{\n  min-height:68px;padding:9px 16px;\n  background:linear-gradient(180deg,rgba(13,21,29,.96),rgba(10,17,24,.93));\n  border-bottom:1px solid rgba(117,145,169,.18);\n  box-shadow:0 9px 30px rgba(0,0,0,.20);\n  backdrop-filter:blur(18px) saturate(1.08)\n}\n.headerBrand{gap:11px;margin-right:10px;padding-right:13px;border-right:1px solid rgba(117,145,169,.14)}\n.headerBrand img{width:38px;height:38px;filter:drop-shadow(0 6px 14px rgba(0,0,0,.30))}\n.headerBrandTitle strong{font-size:15px;letter-spacing:-.018em;color:#f1f7fc}\n.headerBrandTitle span{font-size:9px;letter-spacing:.15em;color:#7891a6;margin-top:2px}\n.connection{padding:7px 9px;border:1px solid rgba(111,137,159,.16);border-radius:999px;background:rgba(7,13,18,.34);min-width:auto}\n.connection .dot{width:7px;height:7px}\n.headerSearch{min-width:190px;max-width:360px;flex:1 1 240px}\n.headerSearch button{width:100%;height:36px;border-radius:11px!important;background:rgba(7,13,19,.58)!important;border-color:rgba(112,139,163,.22)!important;color:#8fa6b9!important;text-align:left;padding:0 11px!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.018)!important}\n.headerSearch button:hover{background:rgba(18,31,42,.76)!important;border-color:rgba(105,174,250,.35)!important;color:#c9d9e6!important}\n.languagePicker select,.scalePicker select,.motionPicker select{height:34px;border-radius:9px;background:rgba(8,14,20,.74)}\nheader .headerIcon,#liveBtn,#logoutBtn{height:34px;border-radius:9px;padding:0 10px}\n#notificationBtn{position:relative}\n#liveBtn.active{border-color:rgba(143,218,114,.36);background:rgba(69,117,64,.22);color:#c7efbd}\nheader .user{padding:7px 10px;margin:0 3px;border:1px solid rgba(111,137,159,.16);border-radius:999px;background:rgba(7,13,18,.30);color:#aabac8}\n#logoutBtn{background:rgba(89,38,38,.20);border-color:rgba(175,78,78,.28);color:#efc3c3}\n#logoutBtn:hover{background:rgba(120,48,48,.28);border-color:rgba(214,93,93,.40);color:#fff}\n.headerDivider{height:30px;background:rgba(117,145,169,.16)}\n\n/* Global status strip */\n#globalStatusBar{\n  min-height:42px;padding:6px 14px;gap:8px;\n  background:rgba(8,14,20,.88);border-bottom:1px solid rgba(117,145,169,.16);\n  backdrop-filter:blur(14px);box-shadow:0 7px 24px rgba(0,0,0,.13)\n}\n.statusPill,.summaryStatus{\n  min-height:27px;padding:4px 8px!important;border-radius:999px!important;\n  background:rgba(18,27,36,.62)!important;border-color:rgba(107,134,157,.20)!important;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.018)\n}\n.statusPill{display:inline-flex;align-items:center;gap:5px}\n.statusPill b{color:#e2edf5;font-weight:780}\n.statusSummaryGroup{gap:5px;padding-left:10px;border-left-color:rgba(110,136,157,.18)}\n.summaryStatus:hover{background:rgba(28,42,55,.76)!important;border-color:rgba(105,174,250,.32)!important;transform:translateY(-1px)}\n.summaryStatus.good{color:#b9ebb0!important;background:rgba(87,146,68,.13)!important;border-color:rgba(143,218,114,.34)!important}\n.summaryStatus.good .summaryStatusDot{background:var(--good)!important;box-shadow:0 0 0 3px rgba(143,218,114,.11),0 0 10px rgba(143,218,114,.32)!important}\n.summaryStatus.warn{color:#ffe39a!important;background:rgba(151,112,38,.12)!important;border-color:rgba(255,209,102,.32)!important}\n.summaryStatus.warn .summaryStatusDot{background:var(--warn)!important;box-shadow:0 0 0 3px rgba(255,209,102,.10),0 0 10px rgba(255,209,102,.24)!important}\n.summaryStatus.bad{color:#ffb1b1!important;background:rgba(151,57,57,.13)!important;border-color:rgba(255,116,116,.34)!important}\n.summaryStatus.bad .summaryStatusDot{background:var(--bad)!important;box-shadow:0 0 0 3px rgba(255,116,116,.10),0 0 10px rgba(255,116,116,.25)!important}\n.summaryStatus.neutral{color:#8ea0af!important;background:rgba(18,27,36,.62)!important;border-color:rgba(107,134,157,.20)!important}\n\n.globalOverallStatus,.globalPageContext{min-height:30px;border:1px solid rgba(107,134,157,.22);border-radius:10px;background:rgba(18,27,36,.68);color:#9aabba;display:inline-flex;align-items:center;gap:7px;padding:4px 9px;white-space:nowrap;box-shadow:inset 0 1px 0 rgba(255,255,255,.02)}\n.globalOverallStatus{cursor:pointer;font:inherit}.globalOverallStatus:hover{background:rgba(28,42,55,.82);border-color:rgba(105,174,250,.34)}\n.globalStatusKicker{font-size:8px;font-weight:900;letter-spacing:.12em;color:#667d90}.globalOverallStatus b,.globalPageContext b{font-size:11px;color:#e7f0f7}.globalStatusCount{display:none;min-width:17px;height:17px;padding:0 5px;border-radius:999px;align-items:center;justify-content:center;font-size:9px;font-weight:900;background:#6c5020;color:#ffe39a}.globalStatusCount.visible{display:inline-flex}\n.globalOverallStatus.good{border-color:rgba(143,218,114,.34);background:rgba(77,132,61,.13)}.globalOverallStatus.good .summaryStatusDot{background:var(--good);box-shadow:0 0 0 3px rgba(143,218,114,.10),0 0 10px rgba(143,218,114,.24)}\n.globalOverallStatus.warn{border-color:rgba(255,209,102,.36);background:rgba(151,112,38,.14)}.globalOverallStatus.warn b{color:#ffe39a}.globalOverallStatus.warn .summaryStatusDot{background:var(--warn);box-shadow:0 0 0 3px rgba(255,209,102,.10),0 0 10px rgba(255,209,102,.24)}\n.globalOverallStatus.bad{border-color:rgba(255,116,116,.38);background:rgba(151,57,57,.15)}.globalOverallStatus.bad b{color:#ffb1b1}.globalOverallStatus.bad .summaryStatusDot{background:var(--bad);box-shadow:0 0 0 3px rgba(255,116,116,.11),0 0 10px rgba(255,116,116,.28)}.globalOverallStatus.bad .globalStatusCount{background:#843636;color:#fff}\n.globalPageContext{gap:6px}.globalPageState{display:inline-flex;align-items:center;gap:5px;font-size:10px;color:#8799a8;padding-left:7px;border-left:1px solid rgba(107,134,157,.17)}.globalPageContext.good .globalPageState{color:#b9ebb0}.globalPageContext.good .summaryStatusDot{background:var(--good)}.globalPageContext.warn .globalPageState{color:#ffe39a}.globalPageContext.warn .summaryStatusDot{background:var(--warn)}.globalPageContext.bad .globalPageState{color:#ffb1b1}.globalPageContext.bad .summaryStatusDot{background:var(--bad)}\n.statusGroupLabel{font-size:8px;font-weight:900;letter-spacing:.12em;color:#607789;margin-right:1px}.statusSummaryGroup{flex:0 0 auto}.statusPill{flex:0 0 auto}\n@media(max-width:1500px){#globalStatusBar .statusTertiary{display:none}}\n@media(max-width:1320px){#globalStatusBar .statusSecondary{display:none}.globalStatusKicker{display:none}}\n@media(max-width:1120px){#globalStatusBar{gap:6px}.globalPageState{display:none}.statusGroupLabel{display:none}.summaryStatus{padding-left:7px!important;padding-right:7px!important}}\n@media(max-width:880px){.globalOverallStatus,.globalPageContext{min-height:28px}.statusSummaryGroup{max-width:none}.globalPageContext{display:none}}\n\n/* Sidebar */\nnav{\n  padding:14px 10px 22px;\n  background:linear-gradient(180deg,rgba(13,20,27,.985),rgba(10,16,22,.99));\n  border-right:1px solid rgba(116,144,166,.17);\n  box-shadow:9px 0 28px rgba(0,0,0,.10)\n}\n.navGroup{--group-accent:#6aaef8;margin-bottom:9px}\n.navGroup[data-nav-group=\"performance\"]{--group-accent:#d6aa61}\n.navGroup[data-nav-group=\"utilities\"]{--group-accent:#62bfc2}\n.navGroup[data-nav-group=\"moderation\"]{--group-accent:#a083e8}\n.navGroup[data-nav-group=\"administration\"]{--group-accent:#8297cf}\n.navGroupToggle{\n  min-height:32px!important;padding:7px 8px!important;margin:5px 0 3px!important;\n  color:#8398aa!important;background:transparent!important;border:0!important;border-radius:8px!important;\n  font-size:9px!important;letter-spacing:.12em!important;font-weight:820!important;box-shadow:none!important\n}\n.navGroupToggle::before{content:\"\";width:6px;height:6px;border-radius:2px;background:var(--group-accent);box-shadow:0 0 10px color-mix(in srgb,var(--group-accent) 48%,transparent);opacity:.82}\n.navGroupToggle:hover{background:rgba(255,255,255,.025)!important;color:#b9c8d4!important;filter:none!important}\n.navGroupToggle .navChevron{font-size:8px;opacity:.58}\nnav .navGroupBody>button{\n  min-height:38px;margin:2px 0;padding:8px 9px 8px 12px;border:1px solid transparent!important;border-radius:10px!important;\n  color:#9eafbd;font-weight:640;background:transparent!important;box-shadow:none!important\n}\nnav .navGroupBody>button::before{\n  content:\"\";width:5px;height:5px;border-radius:999px;background:#40515f;flex:0 0 auto;\n  transition:background .15s,box-shadow .15s,transform .15s\n}\nnav .navGroupBody>button:hover{background:rgba(105,174,250,.045)!important;border-color:rgba(105,174,250,.08)!important;color:#e0eaf2!important;transform:translateX(1px)}\nnav .navGroupBody>button:hover::before{background:color-mix(in srgb,var(--group-accent) 72%,#fff 0%)}\nnav .navGroupBody>button.active{\n  background:linear-gradient(90deg,color-mix(in srgb,var(--group-accent) 13%,transparent),rgba(25,37,48,.50))!important;\n  border-color:color-mix(in srgb,var(--group-accent) 24%,transparent)!important;\n  color:#f2f7fb!important;box-shadow:inset 2px 0 0 var(--group-accent)!important\n}\nnav .navGroupBody>button.active::before{background:var(--group-accent);box-shadow:0 0 10px color-mix(in srgb,var(--group-accent) 55%,transparent);transform:scale(1.18)}\n.navPageBadge{box-shadow:inset 0 1px 0 rgba(255,255,255,.06)}\n\n/* Main content, breadcrumbs and page titles */\nmain{padding:22px 24px 38px}\n#breadcrumbBar{margin:0 0 12px;padding:0 3px;color:#667f93;font-size:10px;letter-spacing:.025em}\n.crumbCurrent{color:#9db1c1}\n.pageTitle{\n  position:relative;min-height:62px;margin-bottom:16px;padding:10px 4px 15px 15px;\n  border-bottom:1px solid rgba(115,142,165,.16);align-items:center\n}\n.pageTitle::before{\n  content:\"\";position:absolute;left:0;top:14px;bottom:17px;width:3px;border-radius:999px;\n  background:linear-gradient(180deg,var(--suite-cyan),var(--suite-indigo));\n  box-shadow:0 0 14px rgba(105,174,250,.17)\n}\n.pageTitle h2{font-size:24px;font-weight:800;letter-spacing:-.03em;color:#f0f6fb}\n.pageTitle .subtitle{font-size:12px;color:#8399ab;margin-top:4px;line-height:1.55}\n.pageStatusIndicator{padding:6px 10px;border-radius:999px;background:rgba(12,20,27,.72);backdrop-filter:blur(8px)}\n.readOnlyNotice{border-radius:12px;background:rgba(71,56,22,.46);border-color:rgba(205,165,70,.32);box-shadow:inset 3px 0 0 #d6aa61}\n\n/* Cards */\n.card{\n  position:relative;border-radius:var(--suite-radius)!important;padding:15px 16px;\n  background:linear-gradient(180deg,rgba(18,28,38,.92),rgba(13,21,29,.94));\n  border:1px solid var(--suite-border)!important;\n  box-shadow:var(--suite-glow)!important;\n  transition:border-color .16s ease,box-shadow .16s ease,transform .16s ease\n}\n.card::before{\n  content:\"\";position:absolute;left:16px;right:16px;top:0;height:1px;\n  background:linear-gradient(90deg,transparent,rgba(144,196,244,.13),transparent);pointer-events:none\n}\n.card:hover{border-color:rgba(117,151,180,.30)!important;box-shadow:0 12px 30px rgba(0,0,0,.19),0 0 0 1px rgba(105,174,250,.02)!important}\n.cardHeader{min-height:34px;margin-bottom:12px;padding-bottom:10px;border-bottom:1px solid rgba(110,137,159,.13)}\n.cardHeader h3{font-size:14px;font-weight:770;color:#e7eff6}\n.cardHeader .small{font-size:10px;color:#71879a}\n.grid{gap:12px}\n.metric{min-height:104px;padding-top:17px!important;overflow:hidden}\n.metric::after{height:2px;background:linear-gradient(90deg,var(--suite-blue),rgba(103,199,239,.25),transparent 75%);opacity:.55}\n.metric::before{left:auto;right:-38px;top:-42px;width:110px;height:110px;border-radius:50%;background:radial-gradient(circle,rgba(105,174,250,.07),transparent 68%);pointer-events:none}\n.metric .name{font-size:10px;letter-spacing:.09em;color:#8296a7}\n.metric .value,.metricValue{font-size:28px;font-weight:800;color:#f0f6fb}\n.metric .detail{font-size:10px;color:#6f8291;margin-top:8px}\n#dashboardMetrics .metric:hover{transform:translateY(-2px);border-color:rgba(105,174,250,.34)!important;box-shadow:0 15px 32px rgba(0,0,0,.19),0 0 22px rgba(105,174,250,.035)!important}\n\n/* Toolbars and actions */\n.toolbar,.quickActions{\n  padding:9px 10px!important;margin-bottom:13px!important;border:1px solid rgba(108,134,156,.17)!important;\n  border-radius:12px!important;background:rgba(8,14,20,.40)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.012)\n}\n.quickActions{gap:7px}\n#app button,#notificationPanel button,.overlay button,#backToTop{\n  min-height:35px;border-radius:9px!important;padding:7px 11px;\n  border:1px solid rgba(100,126,148,.31)!important;\n  background:linear-gradient(180deg,rgba(43,57,69,.95),rgba(34,47,58,.96))!important;\n  color:#d8e3eb;font-weight:660;box-shadow:inset 0 1px 0 rgba(255,255,255,.028),0 2px 8px rgba(0,0,0,.08)!important;\n  transition:background .14s,border-color .14s,color .14s,transform .14s,box-shadow .14s\n}\n#app button:hover:not(:disabled),#notificationPanel button:hover:not(:disabled),.overlay button:hover:not(:disabled),#backToTop:hover{background:linear-gradient(180deg,rgba(53,72,87,.98),rgba(42,58,71,.98))!important;border-color:rgba(118,153,181,.48)!important;color:#fff}\n#app button.primary,.overlay button.primary{background:linear-gradient(180deg,#347cc0,#28639b)!important;border-color:#4a91d0!important;color:#fff;box-shadow:inset 0 1px 0 rgba(255,255,255,.10),0 7px 18px rgba(30,92,150,.16)!important}\n#app button.primary:hover:not(:disabled),.overlay button.primary:hover:not(:disabled){background:linear-gradient(180deg,#3d8bd2,#2e70ad)!important;border-color:#65a6df!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 9px 24px rgba(30,92,150,.22)!important}\n#app button.danger,.overlay button.danger{background:linear-gradient(180deg,rgba(117,57,57,.95),rgba(91,43,43,.98))!important;border-color:rgba(174,78,78,.58)!important;color:#ffd6d6}\n#app button.danger:hover:not(:disabled),.overlay button.danger:hover:not(:disabled){background:linear-gradient(180deg,#884545,#6d3535)!important;border-color:#c15a5a!important;color:#fff}\n.iconBtn{border-radius:8px!important}\n.segmented{padding:3px;border-radius:10px;background:rgba(7,13,18,.72);border-color:rgba(107,133,154,.20)}\n.segmented button{min-height:29px!important;border:0!important;box-shadow:none!important;background:transparent!important}\n.segmented button.active{background:rgba(67,108,145,.42)!important;color:#fff;box-shadow:inset 0 0 0 1px rgba(105,174,250,.16)!important}\n\n/* Forms */\n#app input,#app select,#app textarea,.overlay input,.overlay select,.overlay textarea{\n  min-height:36px;border-radius:10px!important;background:rgba(7,13,19,.73)!important;\n  border:1px solid rgba(102,129,152,.30)!important;color:#e3edf5;\n  box-shadow:inset 0 1px 3px rgba(0,0,0,.18)\n}\n#app input:hover,#app select:hover,#app textarea:hover,.overlay input:hover,.overlay select:hover,.overlay textarea:hover{border-color:rgba(121,153,179,.46)!important;background:rgba(9,16,23,.86)!important}\n#app input:focus,#app select:focus,#app textarea:focus,.overlay input:focus,.overlay select:focus,.overlay textarea:focus{border-color:rgba(105,174,250,.62)!important;box-shadow:0 0 0 3px rgba(105,174,250,.10),inset 0 1px 3px rgba(0,0,0,.20)!important}\n#app label,.overlay label{color:#8fa2b2;letter-spacing:.07em}\n.field .small,.compactNote{color:#748a9d}\n\n/* Tabs */\n.sectionTabs{\n  gap:4px;padding:4px;margin-bottom:14px;border-radius:12px;\n  background:rgba(8,14,20,.55);border-color:rgba(108,134,156,.18);box-shadow:inset 0 1px 0 rgba(255,255,255,.012)\n}\n.sectionTabs button{min-height:34px!important;border:0!important;background:transparent!important;color:#879bac!important;box-shadow:none!important}\n.sectionTabs button:hover{background:rgba(105,174,250,.045)!important;color:#c9d8e4!important}\n.sectionTabs button.active{background:linear-gradient(180deg,rgba(56,96,132,.55),rgba(35,66,91,.55))!important;color:#f0f6fb!important;box-shadow:inset 0 0 0 1px rgba(105,174,250,.20),0 4px 12px rgba(0,0,0,.10)!important}\n\n/* Tables */\n.tableWrap{border-radius:12px!important;background:rgba(7,13,18,.34)!important;border-color:rgba(107,133,154,.20)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.01)}\n.tableWrap thead th,.dataScroll thead th,.dataScrollTall thead th,.adminHistoryScroll thead th{position:sticky;top:0;z-index:3}\nth{\n  height:38px;padding:9px 11px!important;background:rgba(19,29,38,.97)!important;color:#8499aa!important;\n  border-bottom:1px solid rgba(115,141,162,.20)!important;font-size:9px!important;letter-spacing:.09em!important;font-weight:800!important\n}\ntd{padding:9px 11px!important;border-bottom-color:rgba(88,109,126,.12)!important;color:#c8d5df}\ntbody tr:nth-child(even) td{background:rgba(255,255,255,.008)}\ntbody tr:hover td{background:rgba(105,174,250,.040)!important}\nth.sortable:hover{background:rgba(31,48,62,.98)!important;color:#b8c9d6!important}\n.rowActions{gap:4px}.rowActions button{min-height:28px!important;padding:4px 7px!important;border-radius:7px!important}\n.tableTools{padding:7px 8px;border:1px solid rgba(104,131,153,.14);border-radius:9px;background:rgba(7,13,18,.28);margin-bottom:8px}\n\n/* Status / badges */\n.badge,.stateChip,.updateBadge,.recBadge,.safetyBadge,.acDomainBadge{\n  border-radius:999px!important;padding:3px 8px!important;font-size:9px!important;font-weight:800!important;letter-spacing:.03em;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.028)\n}\n.badge{background:rgba(72,87,101,.42)}\n.stateChip{background:rgba(13,21,28,.64);border-color:rgba(101,127,149,.28)}\n.stateChip.good{background:rgba(62,108,56,.16);border-color:rgba(143,218,114,.26);color:#b8e9ad}\n.stateChip.warn{background:rgba(117,88,32,.16);border-color:rgba(255,209,102,.26);color:#ffe39a}\n.stateChip.bad{background:rgba(117,50,50,.16);border-color:rgba(255,116,116,.26);color:#ffb1b1}\n.warning,.infoBox,.errorBox{border-radius:12px!important;padding:12px 14px;box-shadow:inset 3px 0 0 currentColor,0 6px 16px rgba(0,0,0,.06)}\n.warning{background:rgba(75,59,24,.34)!important;border-color:rgba(195,156,64,.28)!important}\n.infoBox{background:rgba(24,55,80,.34)!important;border-color:rgba(82,144,198,.28)!important}\n.errorBox{background:rgba(78,31,31,.34)!important;border-color:rgba(184,78,78,.30)!important}\n\n/* Empty and loading states */\n.empty,.emptyAction,.emptyState{border-radius:12px;color:#74899a}\n.emptyAction,.emptyState{padding:24px 18px;background:rgba(8,14,19,.30)!important;border:1px dashed rgba(112,139,161,.25)!important}\n.emptyAction b,.emptyState b{color:#b9c8d3}\n.status{border-radius:11px!important;background:rgba(6,11,16,.66)!important;border-color:rgba(102,129,151,.20)!important}\npre.status{box-shadow:inset 0 1px 8px rgba(0,0,0,.18)}\n\n/* Notifications, command palette and modal surfaces */\n#notificationPanel{\n  right:18px;top:calc(var(--header-height,68px) + 7px);width:min(440px,calc(100vw - 26px));max-height:76vh;\n  padding:13px;border-radius:16px;background:linear-gradient(180deg,rgba(17,26,35,.97),rgba(11,18,25,.98));\n  border:1px solid rgba(119,151,177,.28);box-shadow:0 28px 80px rgba(0,0,0,.46),0 0 28px rgba(105,174,250,.045);backdrop-filter:blur(18px)\n}\n#notificationPanel .cardHeader{margin-bottom:7px}\n.notificationItem{margin:6px 0;padding:10px 11px;border-radius:10px;border-color:rgba(103,130,152,.18);background:rgba(8,14,20,.30)}\n.notificationItem:hover{background:rgba(32,48,61,.58);border-color:rgba(105,174,250,.25)}\n.overlay{background:rgba(2,6,10,.74);backdrop-filter:blur(8px)}\n.modal{\n  border-radius:18px;padding:16px;background:linear-gradient(180deg,rgba(18,27,36,.98),rgba(11,18,25,.99));\n  border:1px solid rgba(119,151,177,.28);box-shadow:0 30px 90px rgba(0,0,0,.52),0 0 34px rgba(105,174,250,.045)\n}\n.modalHeader{padding-bottom:11px;border-bottom:1px solid rgba(105,133,156,.14);margin-bottom:13px}\n.commandInput{height:44px!important;border-radius:12px!important;font-size:14px}\n.commandResults{gap:5px}.commandItem{border-radius:10px;padding:10px 11px}.commandItem:hover,.commandItem.selected{background:rgba(34,51,65,.70);border-color:rgba(105,174,250,.24)}\n\n/* Drawers */\n.acDrawerBackdrop{background:rgba(2,7,11,.70);backdrop-filter:blur(7px)}\n#acDetail.acPlayerDrawer{\n  width:min(1160px,87vw);border-radius:20px 0 0 20px;\n  border-color:rgba(105,174,250,.27);background:linear-gradient(180deg,rgba(15,24,32,.99),rgba(9,16,22,.99));\n  box-shadow:-34px 0 90px rgba(0,0,0,.52),-4px 0 32px rgba(105,174,250,.045)\n}\n#acDetail.acPlayerDrawer .acDrawerHeader{background:rgba(12,20,27,.965);border-bottom-color:rgba(102,130,153,.20);box-shadow:0 8px 24px rgba(0,0,0,.16)}\n.acDrawerPosture{border-radius:13px;background:linear-gradient(180deg,rgba(19,31,41,.82),rgba(11,19,26,.82));border-color:rgba(105,174,250,.20)}\n.acDrawerTabs{gap:4px}\n.acDrawerTab{border-radius:9px!important;background:transparent!important;border-color:transparent!important;box-shadow:none!important}\n.acDrawerTab:hover{background:rgba(105,174,250,.05)!important;border-color:rgba(105,174,250,.10)!important}\n.acDrawerTab.active{background:rgba(48,87,120,.33)!important;border-color:rgba(105,174,250,.20)!important;box-shadow:inset 0 0 0 1px rgba(105,174,250,.08)!important}\n\n/* Charts / visual data */\ncanvas.healthChart,canvas.playerChart{border-radius:11px!important;background:rgba(6,11,16,.68)!important;border-color:rgba(102,128,150,.20)!important}\n.chartCard{border-radius:var(--suite-radius)}\n.chartTip{border-radius:10px;background:rgba(8,14,20,.96);border-color:rgba(119,151,177,.30);box-shadow:0 18px 48px rgba(0,0,0,.36)}\n.terrainProgressTrack{height:10px;border-color:rgba(100,127,149,.28);background:rgba(6,11,16,.65)}\n.terrainProgressFill{background:linear-gradient(90deg,var(--suite-blue),var(--suite-teal))}\n\n/* Details and disclosure */\ndetails,.helpDisclosure{border-radius:12px!important;background:rgba(8,14,20,.30)!important;border-color:rgba(105,132,154,.18)!important}\ndetails>summary,.helpDisclosure summary{padding:10px 12px;color:#aebfcb}\ndetails[open]>summary,.helpDisclosure[open]>summary{color:#e2edf4}\n\n/* Inventory and specialist workspaces get the same glass treatment without changing layout */\n.inventoryWorkbench,.acInventoryLayout,.acInventoryPanel,.dbStorageDatabase,.acInvestigationCard,.acInfoTile{\n  border-color:rgba(105,133,155,.20)!important;box-shadow:0 7px 20px rgba(0,0,0,.10)\n}\n.acInfoTile{border-radius:11px;background:linear-gradient(180deg,rgba(20,31,41,.76),rgba(13,21,28,.78))}\n.acInfoTile .k{color:#7890a3}.acInfoTile .v{color:#e9f1f7}\n\n/* Back to top and toasts */\n#backToTop{width:42px;height:42px;border-radius:13px!important;background:rgba(20,32,42,.92)!important;border-color:rgba(105,139,167,.28)!important;box-shadow:0 14px 32px rgba(0,0,0,.28)!important;backdrop-filter:blur(12px)}\n#backToTop:hover{background:rgba(34,52,66,.96)!important;border-color:rgba(105,174,250,.38)!important}\n.toast{border-radius:12px!important;background:rgba(17,26,34,.92)!important;border-color:rgba(108,136,158,.28)!important;box-shadow:0 20px 48px rgba(0,0,0,.36)!important;backdrop-filter:blur(14px)}\n\n/* Motion: richer but restrained */\nhtml[data-motion=\"full\"] .card:hover{transform:translateY(-1px)}\nhtml[data-motion=\"full\"] #dashboardMetrics .metric:hover{transform:translateY(-2px)}\nhtml[data-motion=\"full\"] .pageStatusIndicator{transition:border-color var(--motion-fast),background var(--motion-fast),color var(--motion-fast),transform var(--motion-fast)}\nhtml[data-motion=\"full\"] .pageStatusIndicator:hover{transform:translateY(-1px)}\nhtml[data-motion=\"reduced\"] body:not(.loginMode)::before{animation:suiteAmbientA 55s ease-in-out infinite alternate}\nhtml[data-motion=\"reduced\"] body:not(.loginMode)::after{animation:suiteAmbientB 65s ease-in-out infinite alternate}\n\n/* Responsive refinements */\n@media(max-width:1450px) and (min-width:881px){\n  .headerBrandTitle span{display:none}\n  .headerBrand{padding-right:8px;margin-right:5px}\n}\n@media(max-width:1120px) and (min-width:881px){\n  .headerBrandTitle strong{max-width:170px;overflow:hidden;text-overflow:ellipsis}\n}\n@media(max-width:880px){\n  header{padding:9px 10px;gap:6px}\n  .headerBrand{border-right:0;padding-right:0;margin-right:5px}\n  nav{background:rgba(11,18,24,.96);border-bottom-color:rgba(113,140,162,.18);box-shadow:0 8px 22px rgba(0,0,0,.16)}\n  nav .navGroupBody>button{min-height:35px;padding:7px 10px}\n  nav .navGroupBody>button::before{display:none}\n  main{padding:16px 12px 30px}\n  .pageTitle{padding-left:12px}\n  .pageTitle h2{font-size:21px}\n  #globalStatusBar{padding:6px 9px}\n}\n@media(max-width:600px){\n  .headerBrandTitle strong{font-size:14px}.headerBrand img{width:34px;height:34px}\n  .connection{order:3}\n  .pageTitle{align-items:flex-start;padding-top:8px}.pageStatusIndicator{margin-left:0;margin-top:6px}\n  .metric .value,.metricValue{font-size:24px}\n  .card{border-radius:12px!important;padding:12px 13px}\n  .modal{border-radius:15px;padding:13px}\n  #notificationPanel{right:8px;width:calc(100vw - 16px);border-radius:14px}\n}\n\n\n\n/* 1.2.28 WebPanel refinement pass: flatter data surfaces, darker drawer actions,\n   simpler navigation, repaired switches, and cleaner charts. */\nbody:not(.loginMode){background:#091018}\nbody:not(.loginMode)::before,body:not(.loginMode)::after{display:none!important}\n\n/* Data surfaces: remove decorative corner/edge gradients from admin data windows. */\n.card,.acInfoTile,.acInvestigationCard,.dbStorageDatabase,.acClusterCard,.acDrawerPosture,.summaryHero{\n  background:#111a22!important;\n  box-shadow:0 5px 16px rgba(0,0,0,.13)!important;\n}\n.card::before,.metric::before,.metric::after{display:none!important}\n.card:hover{box-shadow:0 7px 19px rgba(0,0,0,.16)!important}\n#dashboardMetrics .metric:hover{transform:translateY(-1px);box-shadow:0 8px 20px rgba(0,0,0,.17)!important}\n.acInfoTile,.acInvestigationCard,.dbStorageDatabase,.acClusterCard{border-color:rgba(105,133,155,.20)!important}\n\n/* Sidebar: one calm navigation language instead of per-group color management. */\nnav{background:#0d151c;box-shadow:none}\n.navGroup{--group-accent:#6c879d;margin-bottom:7px!important}\n.navGroup[data-nav-group=\"performance\"],.navGroup[data-nav-group=\"utilities\"],.navGroup[data-nav-group=\"moderation\"],.navGroup[data-nav-group=\"administration\"]{--group-accent:#6c879d}\n.navGroupToggle{\n  min-height:27px!important;padding:7px 8px 5px!important;margin:7px 0 2px!important;\n  color:#708696!important;background:transparent!important;border:0!important;border-bottom:1px solid rgba(92,113,130,.18)!important;\n  border-radius:0!important;font-size:9px!important;letter-spacing:.11em!important;font-weight:780!important\n}\n.navGroupToggle::before{display:none!important}\n.navGroupToggle:hover{background:transparent!important;color:#9fb1bf!important}\n.navGroupToggle .navChevron{opacity:.44}\nnav .navGroupBody>button{min-height:36px;margin:1px 0;padding:8px 10px!important;border-radius:7px!important;color:#9babb8!important;background:transparent!important;border:1px solid transparent!important}\nnav .navGroupBody>button::before{display:none!important}\nnav .navGroupBody>button:hover{transform:none!important;background:#151f28!important;border-color:#202f3b!important;color:#e2ebf2!important}\nnav .navGroupBody>button.active{background:#1a2732!important;border-color:#2a3c4b!important;color:#f2f7fb!important;box-shadow:inset 3px 0 0 #5d9bd0!important;font-weight:750}\n\n/* Side/player drawer: deliberately darker controls and tabs. */\n#acDetail.acPlayerDrawer{background:#0c141b!important;border-color:#2a3b49!important;box-shadow:-26px 0 72px rgba(0,0,0,.54)!important}\n#acDetail.acPlayerDrawer .acDrawerHeader{background:#0d161e!important;border-bottom-color:#24323e!important}\n#acDetail button:not(.danger){background:#16212a!important;border-color:#2b3a47!important;color:#c2d0da!important;box-shadow:none!important}\n#acDetail button:not(.danger):hover:not(:disabled){background:#1b2a35!important;border-color:#3b5265!important;color:#f2f7fb!important}\n#acDetail button.primary{background:#214d70!important;border-color:#376f9a!important;color:#f4f8fb!important}\n#acDetail button.primary:hover:not(:disabled){background:#285b83!important;border-color:#4b84ae!important}\n#acDetail .acDrawerTab{background:#101920!important;border:1px solid transparent!important;color:#8397a7!important}\n#acDetail .acDrawerTab:hover{background:#16222b!important;border-color:#263a49!important;color:#c7d4de!important}\n#acDetail .acDrawerTab.active{background:#1b2d3b!important;border-color:#31536d!important;color:#f1f6fa!important;box-shadow:inset 0 -2px 0 #5d9bd0!important}\n\n/* Charts: crisp dark plots, slightly taller profiler charts, no decorative card gradients. */\n.chartWrap{height:235px}\ncanvas.healthChart,canvas.playerChart,canvas.memoryChart,canvas.performanceTimeline{\n  background:#0b1218!important;border-color:#263744!important;border-radius:9px!important;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.012)\n}\n.chartMeta{gap:14px;color:#728697}.chartMeta b{color:#dbe6ee}\n.chartLegend{color:#8194a4}\n.chartTip{background:#0e171e!important;border-color:#344b5d!important;box-shadow:0 12px 34px rgba(0,0,0,.42)!important}\n\n@media(max-width:880px){nav{background:#0d151c}.navGroupToggle{display:none!important}}\n\n/* 1.2.28 sidebar hierarchy restoration: prominent category headers with quiet child actions. */\n.navGroup{margin-bottom:10px!important;--group-accent:#5ba8ee;--group-head:#13283a;--group-border:#28506f;--group-text:#92c8f6;--group-glow:rgba(75,157,226,.16)}\n.navGroup[data-nav-group=\"performance\"]{--group-accent:#d8a447;--group-head:#292217;--group-border:#51411f;--group-text:#edc36f;--group-glow:rgba(216,164,71,.14)}\n.navGroup[data-nav-group=\"utilities\"]{--group-accent:#48bca8;--group-head:#142824;--group-border:#285047;--group-text:#79d3c3;--group-glow:rgba(72,188,168,.14)}\n.navGroup[data-nav-group=\"moderation\"]{--group-accent:#a875d2;--group-head:#241b2d;--group-border:#49345a;--group-text:#d0a3ef;--group-glow:rgba(168,117,210,.14)}\n.navGroup[data-nav-group=\"administration\"]{--group-accent:#7896cf;--group-head:#1a2230;--group-border:#34425a;--group-text:#adc0e5;--group-glow:rgba(120,150,207,.14)}\n\n.navGroupToggle{\n  display:flex!important;align-items:center!important;gap:9px!important;width:100%!important;\n  min-height:42px!important;padding:10px 12px!important;margin:8px 0 5px!important;\n  color:var(--group-text)!important;background:var(--group-head)!important;\n  border:1px solid var(--group-border)!important;border-left:4px solid var(--group-accent)!important;\n  border-radius:9px!important;font-size:11px!important;line-height:1.15!important;font-weight:850!important;\n  letter-spacing:.085em!important;text-transform:uppercase!important;\n  box-shadow:0 5px 15px rgba(0,0,0,.16),0 0 18px var(--group-glow),inset 0 1px 0 rgba(255,255,255,.028)!important;\n  transition:background .16s ease,border-color .16s ease,box-shadow .16s ease,color .16s ease,transform .16s ease!important;\n}\n.navGroupToggle::before{\n  content:\"\"!important;display:block!important;width:7px!important;height:7px!important;flex:0 0 7px!important;\n  border-radius:2px!important;background:var(--group-accent)!important;\n  box-shadow:0 0 10px var(--group-accent)!important;opacity:.95!important;\n}\n.navGroupToggle:hover{\n  color:#f5f9fc!important;filter:none!important;transform:translateY(-1px)!important;\n  border-color:var(--group-accent)!important;box-shadow:0 7px 18px rgba(0,0,0,.20),0 0 24px var(--group-glow),inset 0 1px 0 rgba(255,255,255,.04)!important;\n}\n.navGroupToggle .navChevron{margin-left:auto!important;font-size:9px!important;opacity:.72!important;color:currentColor!important;transition:transform .15s ease,opacity .15s ease!important}\n.navGroup.collapsed .navChevron{transform:rotate(-90deg)!important}\n\nnav .navGroupBody{padding:1px 0 2px!important}\nnav .navGroupBody>button{\n  position:relative!important;display:flex!important;align-items:center!important;gap:7px!important;\n  min-height:36px!important;margin:2px 0!important;padding:8px 10px 8px 13px!important;\n  border-radius:7px!important;color:#9aaab7!important;background:#101820!important;\n  border:1px solid #18242e!important;box-shadow:none!important;font-weight:620!important;\n  transition:background .14s ease,border-color .14s ease,color .14s ease,transform .14s ease,box-shadow .14s ease!important;\n}\nnav .navGroupBody>button::before{display:none!important}\nnav .navGroupBody>button:hover{\n  transform:translateX(2px)!important;background:#17232c!important;border-color:#2a3b48!important;\n  color:#e6eef4!important;box-shadow:none!important;\n}\nnav .navGroupBody>button.active{\n  background:#1b2a35!important;border-color:#304555!important;color:#f5f9fc!important;font-weight:760!important;\n  box-shadow:inset 3px 0 0 var(--group-accent),0 3px 10px rgba(0,0,0,.12)!important;\n}\nnav .navGroupBody>button.active:hover{background:#1d2e3a!important;border-color:#3b5365!important}\n\n@media(max-width:880px){\n  .navGroupToggle{display:none!important}\n  nav .navGroupBody>button{background:#111b23!important;border-color:#1c2a35!important}\n  nav .navGroupBody>button.active{box-shadow:inset 0 -2px 0 var(--accent)!important}\n}\n\n\n/* v1.2.28 player client-only mod section + mobile layout refinement */\n.mobileNavToggle,.mobileNavHead,.mobileNavBackdrop,.mobileCellLabel{display:none}\n.acClientOnlyModsCard{border-color:#2d5268;background:#0d171f}\n.acClientOnlyModsCard>.cardHeader{border-bottom-color:#254556}\n.acClientOnlyModsCard h3{color:#b9dcf5}\n#acClientOnlyModsCount,#acAllModsCount{font-variant-numeric:tabular-nums}\n\n@media(max-width:880px){\n  html,body{max-width:100%;overflow-x:hidden}\n  body.mobileNavOpen{overflow:hidden}\n  header{position:sticky!important;top:0;z-index:1250;min-height:58px;height:auto!important;display:flex!important;align-items:center;flex-wrap:wrap;gap:7px;padding:8px 10px!important;background:rgba(10,15,20,.97);backdrop-filter:blur(14px);border-bottom:1px solid #263542}\n  .mobileNavToggle{display:inline-grid;place-items:center;flex:0 0 42px;width:42px;height:42px;padding:0;border-radius:9px;border:1px solid #334554;background:#121c24;color:#e9f1f8;font-size:21px;line-height:1}\n  .mobileNavToggle:active{transform:translateY(1px)}\n  .headerBrand{flex:1 1 180px;min-width:0;max-width:none}\n  .headerBrand img{width:34px;height:34px}\n  .headerBrandTitle{min-width:0}\n  .headerBrandTitle strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  header>h1,#lastUpdate,.headerSearch,.scalePicker,.motionPicker,#quickReportBtn,.headerDivider,header .user{display:none!important}\n  .connection{flex:0 0 auto;min-width:0;max-width:145px;padding:6px 8px;font-size:11px}\n  #notificationBtn{flex:0 0 40px;width:40px;height:38px;padding:0}\n  #liveBtn,.languagePicker,#logoutBtn{order:20}\n  #liveBtn{flex:1 1 120px;min-height:36px}\n  .languagePicker{flex:0 1 118px}\n  .languagePicker select{width:100%;min-width:0!important;max-width:none!important}\n  #logoutBtn{flex:0 0 auto;min-height:36px}\n\n  #globalStatusBar{position:static!important;z-index:1180;margin-left:0!important;display:flex!important;flex-wrap:nowrap!important;gap:6px;overflow-x:auto;overscroll-behavior-x:contain;scroll-snap-type:x proximity;padding:6px 8px!important;background:#0a1117;border-bottom:1px solid #22313d;scrollbar-width:none}\n  #globalStatusBar::-webkit-scrollbar{display:none}\n  #globalStatusBar>*{flex:0 0 auto;scroll-snap-align:start}\n  #globalStatusBar .statusPill{min-height:31px;padding:5px 8px}\n  #globalStatusBar .statusSummaryGroup{display:flex;gap:6px;flex:0 0 auto}\n  #offlineBanner{margin-left:0!important;position:relative!important;top:auto!important;padding:8px 10px;gap:7px;flex-wrap:wrap}\n\n  nav#nav{display:block!important;position:fixed!important;inset:0 auto 0 0!important;width:min(86vw,320px)!important;max-width:320px;height:100dvh;transform:translateX(-105%);transition:transform .2s ease;z-index:1500;overflow-y:auto;overscroll-behavior:contain;padding:10px 9px 28px!important;border-right:1px solid #344654!important;border-bottom:0!important;background:#0b1218!important;box-shadow:20px 0 55px rgba(0,0,0,.48)}\n  body.mobileNavOpen nav#nav{transform:translateX(0)}\n  .mobileNavHead{display:flex;position:sticky;top:-10px;z-index:3;align-items:center;gap:10px;justify-content:space-between;margin:-1px -1px 9px;padding:11px 10px 10px;background:#0b1218;border-bottom:1px solid #263641}\n  .mobileNavHead>div{display:flex;flex-direction:column;line-height:1.15}.mobileNavHead span{font-size:10px;color:var(--muted);margin-top:3px;text-transform:uppercase;letter-spacing:.08em}\n  #mobileNavClose{width:38px;height:38px;padding:0;border-radius:9px;font-size:24px;line-height:1;background:#121d25;border-color:#344856}\n  nav#nav .navGroupToggle{display:flex!important;width:100%!important;min-height:42px!important;margin-top:8px!important}\n  nav#nav .navGroupBody{display:block}\n  nav#nav .navGroup.collapsed .navGroupBody{display:none}\n  nav#nav .navGroupBody>button{display:flex!important;width:100%!important;min-height:41px;padding:8px 11px 8px 14px!important;margin:2px 0!important;white-space:normal!important;text-align:left}\n  nav#nav .navPageLabel{white-space:normal;line-height:1.25}\n  .mobileNavBackdrop{display:block;position:fixed;inset:0;z-index:1450;background:rgba(0,0,0,.58);opacity:0;pointer-events:none;transition:opacity .2s ease}\n  body.mobileNavOpen .mobileNavBackdrop{opacity:1;pointer-events:auto}\n\n  main{margin-left:0!important;width:100%;max-width:100%;padding:12px 10px 26px!important;overflow:visible}\n  #breadcrumbBar{margin-bottom:9px;overflow-x:auto;white-space:nowrap;scrollbar-width:none}\n  #breadcrumbBar::-webkit-scrollbar{display:none}\n  .pageTitle{align-items:flex-start;gap:8px;padding-bottom:10px;margin-bottom:11px;flex-wrap:wrap}\n  .pageTitle>div:first-child{min-width:0;flex:1 1 220px}.pageTitle h2{font-size:20px!important;line-height:1.15}.pageTitle .subtitle{font-size:11px;line-height:1.4}\n  .pageStatusIndicator{margin-left:0}\n  .card{min-width:0;padding:10px!important;border-radius:9px}\n  .cardHeader{display:flex;align-items:flex-start;flex-wrap:wrap;gap:6px 8px}.cardHeader>.spacer{display:none}.cardHeader h3{line-height:1.22}\n  .grid,.acDrawerTabGrid,.reportLayout,.playerAnalyticsGrid,.serverStatusGrid{grid-template-columns:1fr!important}\n  .toolbar,.quickActions{gap:6px;align-items:stretch;flex-wrap:wrap}\n  .toolbar>button,.quickActions>button{flex:1 1 145px;min-height:38px}\n  .toolbar input,.toolbar select,.field input,.field select,.field textarea{max-width:100%;min-width:0}\n  .tableWrap{max-width:100%;overflow-x:auto!important;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain}\n  .tableWrap table:not(.mobileStackTable){min-width:680px}\n  .chartGrid{grid-template-columns:1fr!important}.chartCard canvas,.chartShell canvas{max-height:260px}\n  .modal,.dialog,.commandPalette{max-width:calc(100vw - 18px)!important;max-height:calc(100dvh - 24px)!important}\n  #notificationPanel{width:min(94vw,420px)!important;max-width:94vw!important}\n\n  #acDetail.acPlayerDrawer{inset:0 0 0 auto!important;width:100vw!important;max-width:none!important;height:100dvh!important;max-height:100dvh!important;border-radius:0!important;padding:0 10px 24px!important;overflow-y:auto!important;overscroll-behavior:contain}\n  #acDetail.acPlayerDrawer .acDrawerHeader{position:sticky;top:0;z-index:10;margin:0 -10px 10px!important;padding:9px 10px 7px!important;background:rgba(11,18,24,.98);border-bottom:1px solid #2a3b48;backdrop-filter:blur(12px)}\n  .acDrawerHeaderLine{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px!important;align-items:stretch!important}\n  .acDrawerHeaderLine>div:first-child{grid-column:1/-1;min-width:0}.acDrawerHeaderLine>.spacer{display:none!important}.acDrawerHeaderLine button{width:100%;min-height:38px;padding:7px 8px!important}\n  .acDrawerPosture{padding:7px 0 3px!important}.acDrawerPostureLabel{font-size:10px}.acDrawerQuickBar{display:flex!important;flex-wrap:nowrap!important;overflow-x:auto;gap:5px;padding-bottom:3px;scrollbar-width:none}.acDrawerQuickBar::-webkit-scrollbar{display:none}.acDrawerQuickBar .stateChip{flex:0 0 auto}\n  .acDrawerTabs{display:flex!important;flex-wrap:nowrap!important;overflow-x:auto;overscroll-behavior-x:contain;scroll-snap-type:x proximity;margin:6px -10px -7px!important;padding:0 10px 7px!important;gap:4px;scrollbar-width:none}.acDrawerTabs::-webkit-scrollbar{display:none}\n  .acDrawerTab{flex:0 0 auto;min-height:39px;padding:7px 10px!important;scroll-snap-align:start}\n  .acDrawerTabPanel{padding-top:2px}.acDrawerTabIntro{margin-bottom:9px;padding:9px 10px}.acDrawerTabIntro span{line-height:1.4}\n  .acPlayerOverview,.acEvidenceGrid,.acConnectionSummary{grid-template-columns:1fr!important}\n  .acInventoryLayout{grid-template-columns:1fr!important}.acInventoryToolbar{align-items:stretch}.acInventoryToolbar>*{max-width:100%}.acInventoryToolbar input[type=search]{width:100%!important;min-width:0!important;flex:1 1 100%}.acInventoryGameGrid{overflow:visible}.acInventoryGridPane{overflow-x:auto;-webkit-overflow-scrolling:touch}\n}\n\n@media(max-width:700px){\n  header{gap:6px;padding:7px 8px!important}.headerBrand{flex-basis:145px}.headerBrandTitle span{display:none}.connection{max-width:125px}.connection span:last-child{max-width:96px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  main{padding:10px 8px 24px!important}.card{padding:9px!important}.pageTitle h2{font-size:19px!important}\n  .toolbar,.quickActions{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));width:100%}.toolbar>*:not(button),.quickActions>*:not(button){grid-column:1/-1}.toolbar>button,.quickActions>button{width:100%;min-width:0}\n\n  table.mobileStackTable,table.mobileStackTable tbody,table.mobileStackTable tr,table.mobileStackTable td{display:block;width:100%}\n  table.mobileStackTable{min-width:0!important;border-collapse:separate;border-spacing:0 8px}\n  table.mobileStackTable thead{display:none}\n  table.mobileStackTable tbody{display:grid;gap:8px}\n  table.mobileStackTable tr{border:1px solid #2b3d49;border-radius:9px;background:#0b1319;overflow:hidden;padding:5px 0}\n  table.mobileStackTable td{display:grid!important;grid-template-columns:104px minmax(0,1fr);gap:9px;align-items:start;border:0!important;border-bottom:1px solid #1d2b35!important;white-space:normal!important;overflow-wrap:anywhere;padding:7px 9px!important;min-height:34px}\n  table.mobileStackTable td:last-child{border-bottom:0!important}\n  table.mobileStackTable td[colspan]{display:block!important;padding:10px!important}\n  table.mobileStackTable .mobileCellLabel{display:block;color:#8297a8;font-size:9px;font-weight:850;text-transform:uppercase;letter-spacing:.055em;line-height:1.25;padding-top:2px}\n  table.mobileStackTable .mobileCellValue{min-width:0;overflow-wrap:anywhere}\n  table.mobileStackTable .acCompareGroup{margin-top:6px}\n  table.mobileStackTable button{max-width:100%}\n  .acClientOnlyModsCard>.cardHeader{align-items:center}\n  .acClientOnlyModsCard .badge,#acAllModsCount{margin-left:auto}\n}\n\n@media(max-width:500px){\n  .mobileNavToggle{width:40px;height:40px;flex-basis:40px}.headerBrand img{width:31px;height:31px}.headerBrandTitle strong{font-size:11px}.connection{font-size:10px;padding:5px 7px}\n  #liveBtn{flex:1 1 100px;font-size:10px}.languagePicker{flex-basis:96px}.languagePicker label{display:none}#logoutBtn{font-size:10px;padding-left:9px;padding-right:9px}\n  .toolbar,.quickActions{grid-template-columns:1fr!important}\n  .acDrawerHeaderLine{grid-template-columns:1fr!important}.acDrawerHeaderLine>div:first-child{grid-column:1}.acDrawerHeaderLine button{min-height:36px}\n  .acDrawerTabs{padding-right:24px!important}\n  table.mobileStackTable td{grid-template-columns:88px minmax(0,1fr)}\n  .statusPill{font-size:10px}.summaryStatus{font-size:10px}\n}\n\n\n/* Suite customization + Community MOTD companion */\nbody.suiteHideStatus #globalStatusBar{display:none!important}\nbody.suiteHideModuleStatus #globalStatusBar .statusSummaryGroup{display:none!important}\nbody.suiteHideHeaderLogo .headerBrand img{display:none!important}\n#suiteSidebarFooter{padding:10px 12px 6px;color:#607789;font-size:10px;line-height:1.35;border-top:1px solid rgba(100,124,145,.12);margin-top:10px}\nbody.suiteCompact main{padding-top:14px;padding-bottom:24px}\nbody.suiteCompact .card{padding:10px 12px}\nbody.suiteCompact .cardHeader{margin-bottom:8px;padding-bottom:7px;min-height:28px}\nbody.suiteCompact .pageTitle{min-height:50px;margin-bottom:12px;padding-top:6px;padding-bottom:10px}\nbody.suiteCompact .metric{min-height:72px}\nbody.suiteCompact .toolbar{padding:6px 7px}\n.motdStatusGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}\n.motdEditorGrid{display:grid;grid-template-columns:minmax(260px,.85fr) minmax(360px,1.4fr);gap:12px}\n.motdToggleGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:7px 12px}\n.motdContentTabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px}\n.motdContentTabs button.active{background:linear-gradient(180deg,#2c6aa6,#24598b);border-color:#3e7fbb}\n#patchGeneratorCard [hidden]{display:none!important}\n#patchGeneratorCard .formGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:12px 0 18px}\n#patchGeneratorCard .field{min-width:0;display:flex;flex-direction:column;gap:5px}\n#patchGeneratorCard input,#patchGeneratorCard select,#patchGeneratorCard textarea{width:100%;max-width:100%;min-width:0;box-sizing:border-box}\n#patchGeneratorCard #pgValueWrap{grid-column:1/-1}\n@media(max-width:760px){#patchGeneratorCard .formGrid{grid-template-columns:1fr}}\n#patchAdvancedRuntime>summary,#patchAdvancedJson>summary{cursor:pointer;padding:14px;border:1px solid var(--border);border-radius:8px;margin-bottom:12px}\n#communityMotdEditor{min-height:330px;width:100%;resize:vertical;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;line-height:1.55;tab-size:2}\n.motdComposeWorkspace{display:grid;grid-template-columns:minmax(0,1fr);gap:12px}\n.motdFormatTools{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:10px 0}\n.motdFormatTools button{padding:6px 10px}.motdFormatTools input[type=color]{width:36px;height:30px;padding:2px}\n.motdDraftBar{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap;margin:8px 0}.motdDraftBar .dirty{color:var(--warn)}\n.motdContentTabs button.modified::after{content:' •';color:var(--warn)}\n.motdPreview{border:1px solid var(--line);border-top:3px solid var(--motd-accent,#ffc857);border-radius:10px;background:var(--panel);padding:18px;min-width:0;overflow:hidden}\n.motdPreviewTitle{font-size:22px;font-weight:800;overflow-wrap:anywhere}.motdPreviewSubtitle{color:var(--muted);margin:5px 0 14px;overflow-wrap:anywhere}\n.motdPreviewBody{white-space:pre-wrap;overflow-wrap:anywhere;max-height:440px;overflow:auto;line-height:1.6;min-height:150px}.motdPreviewFooter{border-top:1px solid var(--line);padding-top:10px;margin-top:14px;color:var(--muted);overflow-wrap:anywhere}\n#communityMotd.motdWriting .motdEditorGrid{grid-template-columns:minmax(0,1fr)}\n#communityMotd.motdWriting .motdEditorGrid>div:first-child,#communityMotd.motdWriting .motdFeedsCard{display:none}\n#communityMotd.motdWriting .motdComposeWorkspace{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n#communityMotd.motdWriting #communityMotdEditor{min-height:440px}\n@media(max-width:850px){#communityMotd.motdWriting .motdComposeWorkspace{grid-template-columns:minmax(0,1fr)}}\n@media(max-width:950px){.motdEditorGrid{grid-template-columns:1fr}}\n\n\n/* Top-bar community leaderboard */\n.headerLeaderboardBtn{display:inline-flex;align-items:center;gap:6px;white-space:nowrap}\n.headerLeaderboardBtn .headerLeaderboardLabel{font-size:11px;font-weight:800;letter-spacing:.02em}\n.leaderboardPanelModal{width:min(1120px,96vw);max-height:86vh;padding:0;overflow:hidden}\n.panelLbHeader{padding:14px 16px;margin:0;border-bottom:1px solid rgba(105,133,156,.18);background:linear-gradient(135deg,rgba(34,48,61,.96),rgba(14,22,29,.98))}\n.panelLbTitle{display:flex;align-items:center;gap:9px}.panelLbTitle h3{margin:0}.panelLbTitleIcon{font-size:22px}\n.panelLbTabs{display:flex;gap:7px;padding:10px 14px;border-bottom:1px solid rgba(105,133,156,.14);background:rgba(8,14,20,.72);overflow:auto}\n.panelLbTab{padding:7px 12px;border-radius:999px;white-space:nowrap}.panelLbTab.active{background:#2d4f70!important;border-color:#5382ae!important;color:#fff!important}\n.panelLbStatus{display:flex;gap:7px;flex-wrap:wrap;padding:12px 14px 0}\n.panelLbChip{display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border:1px solid #334958;border-radius:999px;background:#0d161d;color:#aebdca;font-size:10px;font-weight:800}\n.panelLbChip.good{border-color:#356844;color:#9de6af;background:#102018}.panelLbChip.gold{border-color:#6d5931;color:#f0d08b;background:#211b10}\n.panelLbBody{padding:14px;overflow:auto;max-height:calc(86vh - 145px)}\n.panelLbGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:11px}\n.panelLbCard{border:1px solid #314453;border-radius:12px;background:linear-gradient(180deg,#121c24,#0c141b);overflow:hidden}\n.panelLbCardHead{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid #283a47;font-weight:900}.panelLbCardHead span:first-child{font-size:17px}\n.panelLbRows{display:grid}.panelLbRow{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:8px;align-items:center;padding:8px 11px;border-top:1px solid rgba(69,91,108,.24)}.panelLbRow:first-child{border-top:0}\n.panelLbRank{font-weight:950;color:#8194a3}.panelLbRank.r1{color:#ffd86b}.panelLbRank.r2{color:#cdd7df}.panelLbRank.r3{color:#d6a06c}\n.panelLbPlayer{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:800;cursor:pointer}.panelLbPlayer:hover{color:#9dcbff}.panelLbValue{color:#b9c6d1;font-size:11px;font-weight:800;text-align:right}\n.panelLbOnline{display:inline-block;width:7px;height:7px;border-radius:50%;background:#75da83;box-shadow:0 0 8px rgba(117,218,131,.45);margin-right:6px}\n.panelLbEmpty{padding:22px;text-align:center;color:#8295a2;font-size:12px}.panelLbNotice{margin:10px 14px 0;padding:8px 10px;border:1px solid #344a59;border-radius:9px;background:#101922;color:#94a8b7;font-size:11px}\n.panelLbSkills{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:11px}.panelLbSkill{border:1px solid #314453;border-left:3px solid var(--skillAccent,#60a5fa);border-radius:11px;background:#0d161d;overflow:hidden}.panelLbSkillHead{display:flex;align-items:center;gap:9px;padding:10px 12px;border-bottom:1px solid #283a47}.panelLbSkillIcon{font-size:20px}.panelLbSkillName{font-weight:900}.panelLbSkillSub{font-size:10px;color:#8295a2;margin-top:2px}\n.panelLbProfileHero{padding:16px;border:1px solid #496071;border-top:3px solid #c99a48;border-radius:12px;background:linear-gradient(135deg,#16232b,#0c141a)}.panelLbProfileName{font-size:25px;font-weight:950;color:#f3d494}.panelLbProfileStats{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:8px;margin-top:12px}.panelLbStat{padding:10px;border:1px solid #314452;border-radius:9px;background:#