-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:6px;max-height:260px;overflow:auto;margin:12px 0}.rolePolicies{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.rolePolicies>div{padding:12px;border:1px solid var(--line);border-radius:var(--radius-md)}.rolePlayers>div{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid var(--line)}.rolePlayers>div>span{flex:1;min-width:180px}.roleWorkspace input,.roleWorkspace textarea,.roleWorkspace select{max-width:100%;min-width:0;width:100%}.roleWorkspace input[type=checkbox]{width:auto}.roleWorkspace form{min-width:0}.rolePrivileges [hidden]{display:none!important}@media(max-width:880px){.roleWorkspace{grid-template-columns:1fr}.roleList{max-height:230px}.roleWorkspace .row{flex-wrap:wrap}.roleWorkspace .field{min-width:0}}\nbody.suiteThemed,body.suiteThemed #app,body.suiteThemed main{background:var(--suite-bg)!important;color:var(--suite-text)!important}body.suiteThemed nav,body.suiteThemed header,body.suiteThemed .card,body.suiteThemed .loginCard,body.suiteThemed .infoBox,body.suiteThemed .overlayContent{background:var(--suite-panel)!important;color:var(--suite-text)!important;border-color:color-mix(in srgb,var(--suite-text) 20%,transparent)!important}body.suiteThemed #app input,body.suiteThemed #app select,body.suiteThemed #app textarea{background:var(--suite-bg)!important;color:var(--suite-text)!important}body.suiteThemed .small,body.suiteThemed .subtitle,body.suiteThemed label,body.suiteThemed h2,body.suiteThemed h3{color:var(--suite-text)!important}body #app button.primary,body .overlay button.primary{background:color-mix(in srgb,var(--accent) 55%,#101820)!important;border-color:var(--accent)!important;color:#fff!important}body.suiteThemed nav .navGroupBody>button{color:var(--suite-text)!important}body.suiteThemed nav .navGroupBody>button.active{background:color-mix(in srgb,var(--accent) 22%,var(--suite-panel))!important}body #app .card{border-radius:var(--radius-md)!important}body.suiteReducedMotion *,body.suiteReducedMotion *::before,body.suiteReducedMotion *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}\n#customization .field textarea{width:100%}#customization label.field{display:flex;flex-direction:column;gap:6px}#roleEditor>.row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}\n@media(max-width:880px){html,body:not(.loginMode){overflow-x:clip!important;overflow-y:visible}body:not(.loginMode){height:auto;min-height:100svh}body.loginMode{overflow-x:clip!important;overflow-y:visible!important}}\n#roles label.toggleLine{display:flex!important;align-items:start;white-space:normal;gap:8px;line-height:1.5;min-width:0}#roles label.toggleLine>span:not(.suiteSwitchTrack){flex:1;min-width:0;overflow-wrap:anywhere}#roles .suiteSwitchTrack{flex:0 0 50px!important;max-width:50px}\n#roles label.toggleLine[hidden]{display:none!important}\n\n/* Chat formatting controls remain usable on narrow webpanel screens. */\n#chatDisplay .webMapSettings>div{min-width:0;overflow-wrap:anywhere}\n#chatDisplay .webMapSettings input[type=text],#chatDisplay textarea{max-width:100%;min-width:0;box-sizing:border-box}\n#chatDisplay .webMapSettings>div>label{display:flex;align-items:center;gap:8px;white-space:normal;line-height:1.5}\n#chatDisplay .suiteSwitchTrack{flex:0 0 50px}\n#chatDisplay .tableWrap code{white-space:normal;overflow-wrap:anywhere}\n@media(max-width:700px){\n  #chatDisplay .webMapSettings{grid-template-columns:minmax(0,1fr);gap:6px}\n  #chatDisplay .webMapSettings>label{margin-top:10px}\n  #chatDisplay .cardHeader{flex-wrap:wrap}\n  #chatDisplay .tableWrap table{min-width:0!important;width:100%}\n}\n__NSS_INTERFACE_STYLE__\n</style>\n</head>\n<body>\n\n<div class=\"loginBackdrop\" aria-hidden=\"true\"></div>\n<div class=\"loginAuraA\" aria-hidden=\"true\"></div>\n<div class=\"loginAuraB\" aria-hidden=\"true\"></div>\n<div class=\"loginArc\" aria-hidden=\"true\"></div>\n<div class=\"loginGrid\" aria-hidden=\"true\"></div>\n<div class=\"loginShell\">\n  <div class=\"loginStack\">\n    <div class=\"loginBrandLockup\">\n      <img class=\"loginBrandImage\" src=\"data:image/png;base64,\" alt=\"Newfie's Server Suite\">\n      <div id=\"suiteLoginKicker\" class=\"loginBrandSub\" data-login-kicker>Secure Administration Console</div>\n    </div>\n    <div class=\"loginCardWrap\">\n      <div class=\"loginCardGlow\" aria-hidden=\"true\"></div>\n      <div id=\"loginView\">\n        <div class=\"loginHero\">\n          <h1>Sign in</h1>\n          <p class=\"loginSubtitle\" data-login-subtitle>Remote server administration. Fresh installs on 127.0.0.1 enter automatically without a login.</p>\n        </div>\n        <div class=\"loginBody\">\n          <form id=\"loginForm\">\n            <label>Username</label>\n            <input id=\"loginUser\" autocomplete=\"username\" value=\"admin\" spellcheck=\"false\">\n            <label>Password</label>\n            <div class=\"passwordWrap\"><input id=\"loginPass\" type=\"password\" autocomplete=\"current-password\"><button id=\"loginPassToggle\" class=\"passwordToggle\" type=\"button\">Show</button></div>\n            <div id=\"loginError\" role=\"alert\" aria-live=\"polite\"></div>\n            <button class=\"primary loginSubmit\" type=\"submit\">Sign in</button>\n          </form>\n          <p class=\"small loginSecurity\" data-login-https><span aria-hidden=\"true\">◆</span><span>For Internet access, use HTTPS through a trusted reverse proxy/tunnel.</span></p>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div id=\"app\">\n<header>\n  <button id=\"mobileNavToggle\" class=\"mobileNavToggle\" type=\"button\" aria-controls=\"nav\" aria-expanded=\"false\" aria-label=\"Open navigation\">☰</button>\n  <div class=\"headerBrand\"><img src=\"data:image/png;base64,\" alt=\"Newfie's Server Suite\"><div class=\"headerBrandTitle\"><strong id=\"suiteBrandName\">Newfie's Server Suite</strong><span id=\"suiteHeaderSubtitle\">WebPanel</span></div></div>\n  <h1 id=\"suiteHeaderTitle\">Newfies Server Essentials Suite</h1>\n  <div class=\"connection\"><span id=\"connectionDot\" class=\"dot\"></span><span id=\"connectionText\">Connecting…</span></div>\n  <span id=\"lastUpdate\" class=\"small\"></span>\n  <div class=\"headerSearch\">\n    <button id=\"commandOpen\" title=\"Search pages, actions, alerts, mods and watchlist (Ctrl+K)\">⌕ Search Server Essentials Suite… <span class=\"kbd\" style=\"float:right\">Ctrl K</span></button>\n  </div>\n  <div class=\"spacer\"></div>\n  <div class=\"languagePicker\"><label for=\"languageSelect\" id=\"languageLabel\">Language</label><select id=\"languageSelect\" aria-label=\"Language\"><option value=\"en\">English</option><option value=\"ru\">Русский</option><option value=\"fr\">Français</option><option value=\"de\">Deutsch</option><option value=\"es\">Español</option><option value=\"pt\">Português</option><option value=\"pl\">Polski</option></select></div>\n  <div class=\"scalePicker\"><label for=\"uiScaleSelect\" id=\"uiScaleLabel\">Scale</label><select id=\"uiScaleSelect\" aria-label=\"Interface scale\"><option value=\"0.70\">70%</option><option value=\"0.75\">75%</option><option value=\"0.80\">80%</option><option value=\"0.90\">90%</option><option value=\"1.00\">100%</option></select></div>\n  <div class=\"motionPicker\"><label for=\"motionSelect\" id=\"motionLabel\">Motion</label><select id=\"motionSelect\" aria-label=\"Animation level\"><option value=\"full\">Full</option><option value=\"reduced\">Reduced</option><option value=\"off\">Off</option></select></div>\n  <button id=\"leaderboardTopBtn\" class=\"headerIcon headerLeaderboardBtn\" title=\"Server leaderboards\"><span aria-hidden=\"true\">\ud83c\udfc6</span><span class=\"headerLeaderboardLabel\">Leaderboard</span></button>\n  <button id=\"quickReportBtn\" class=\"headerIcon\" title=\"Copy a compact troubleshooting report\">Report</button>\n  <button id=\"notificationBtn\" class=\"headerIcon\" title=\"Active alerts\">\ud83d\udd14<span id=\"notificationBadge\" class=\"notifyBadge\"></span></button>\n  <button id=\"liveBtn\">Live Updates: OFF</button>\n  <div class=\"headerDivider\"></div>\n  <span id=\"headerUser\" class=\"user\"></span>\n  <button id=\"logoutBtn\">Logout</button>\n</header>\n\n<div id=\"globalStatusBar\">\n  <button id=\"globalOverallStatus\" class=\"globalOverallStatus neutral\" type=\"button\" title=\"Waiting for Suite health\"><span class=\"summaryStatusDot\"></span><span class=\"globalStatusKicker\">SUITE</span><b id=\"globalOverallText\">Waiting</b><span id=\"globalOverallCount\" class=\"globalStatusCount\"></span></button>\n  <div id=\"globalPageContext\" class=\"globalPageContext neutral\" title=\"Current page status\"><span class=\"globalStatusKicker\">PAGE</span><b id=\"globalPageName\">Dashboard</b><span class=\"globalPageState\"><span class=\"summaryStatusDot\"></span><span id=\"globalPageStateText\">Idle</span></span></div>\n  <span class=\"statusPill statusPrimary\"><span id=\"globalLivePulse\" class=\"livePulse\"></span><b id=\"globalLiveText\">MANUAL</b></span>\n  <span class=\"statusPill statusPrimary\">Health <b id=\"globalHealth\">—</b></span>\n  <span class=\"statusPill statusSecondary\">CPU <b id=\"globalCpu\">—</b></span>\n  <span class=\"statusPill statusPrimary\">Delay <b id=\"globalDelay\">—</b></span>\n  <span class=\"statusPill statusPrimary\">Players <b id=\"globalPlayers\">—</b></span>\n  <span class=\"statusPill statusSecondary\">Entities <b id=\"globalEntities\">—</b></span>\n  <span class=\"statusPill statusPrimary\">Alerts <b id=\"globalAlerts\">—</b></span>\n  <span class=\"statusPill statusSecondary\">BL Queue <b id=\"globalQueue\">—</b></span>\n  <span class=\"statusPill statusTertiary\">Updated <b id=\"globalUpdated\">—</b></span>\n  <span class=\"statusSummaryGroup\" aria-label=\"Module status summary\">\n    <span class=\"statusGroupLabel\">MODULES</span>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"server\" data-summary-section=\"serverStatus\" title=\"Waiting for server status\"><span class=\"summaryStatusDot\"></span><span>Server</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"anticheat\" data-summary-section=\"anticheat\" title=\"Waiting for Anti-Cheat status\"><span class=\"summaryStatusDot\"></span><span>Anti-Cheat</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"packetguard\" data-summary-section=\"anticheat\" title=\"Waiting for PacketGuard status\"><span class=\"summaryStatusDot\"></span><span>PacketGuard</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"memory\" data-summary-section=\"memory\" title=\"Waiting for Memory / GC status\"><span class=\"summaryStatusDot\"></span><span>Memory / GC</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"webmap\" data-summary-section=\"webmap\" title=\"Waiting for Web Map status\"><span class=\"summaryStatusDot\"></span><span>Web Map</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"blocklogger\" data-summary-section=\"blocklogger\" title=\"Waiting for BlockLogger status\"><span class=\"summaryStatusDot\"></span><span>BlockLogger</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"chatguard\" data-summary-section=\"chatguard\" title=\"Waiting for ChatGuard status\"><span class=\"summaryStatusDot\"></span><span>ChatGuard</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"discord\" data-summary-section=\"discord\" title=\"Waiting for Discord status\"><span class=\"summaryStatusDot\"></span><span>Discord</span></button>\n    <button class=\"summaryStatus neutral\" data-summary-status=\"loginprotection\" data-summary-section=\"loginProtection\" title=\"Waiting for Login Protection status\"><span class=\"summaryStatusDot\"></span><span>Login Protection</span></button>\n  </span>\n</div>\n\n<div id=\"offlineBanner\">\n  <b>DASHBOARD CONNECTION ISSUE</b>\n  <span id=\"offlineDetail\">Displaying the last successful data.</span>\n  <div class=\"spacer\"></div>\n  <button id=\"retryConnectionBtn\">Retry Now</button>\n</div>\n\n<nav id=\"nav\">\n  <div class=\"mobileNavHead\"><div><b>Navigation</b><span>Server Suite</span></div><button id=\"mobileNavClose\" type=\"button\" aria-label=\"Close navigation\">×</button></div>\n  <div class=\"workspaceNavSearch\"><input id=\"workspaceNavSearch\" type=\"search\" placeholder=\"Find a page…\" aria-label=\"Find an administration page\" autocomplete=\"off\"><button id=\"workspaceNavClear\" type=\"button\" aria-label=\"Clear page search\">×</button></div>\n  <div id=\"workspaceNavEmpty\" role=\"status\" hidden>No pages match. Try a player, inventory, packet, or server tool.</div>\n  <div class=\"navGroup\" data-nav-group=\"overview\">\n    <button class=\"navGroupToggle\" type=\"button\"><span>Overview</span><span class=\"navChevron\">▼</span></button>\n    <div class=\"navGroupBody\">\n      <button data-section=\"dashboard\" class=\"active\">Dashboard</button>\n      <button data-section=\"serverStatus\">Server Status</button>\n      <button data-section=\"actionCenter\">Action Center</button>\n      <button data-section=\"logIntelligence\">Log Intelligence</button>\n    </div>\n  </div>\n  <div class=\"navGroup\" data-nav-group=\"performance\">\n    <button class=\"navGroupToggle\" type=\"button\"><span>Performance</span><span class=\"navChevron\">▼</span></button>\n    <div class=\"navGroupBody\">\n      <button data-section=\"performance\">Performance Center</button>\n      <button data-section=\"tickDebug\"><span>Tick Debugging</span><span id=\"tickDebugNavState\" class=\"navInlineState\">ON</span></button>\n      <button data-section=\"profiler\">Profiler &amp; Lag</button>\n      <button data-section=\"memory\">Memory &amp; GC</button>\n      <button data-section=\"optimizations\">Optimizations</button>\n      <button data-section=\"health\">Suite Health</button>\n    </div>\n  </div>\n  <div class=\"navGroup\" data-nav-group=\"utilities\">\n    <button class=\"navGroupToggle\" type=\"button\"><span>Server Tools</span><span class=\"navChevron\">▼</span></button>\n    <div class=\"navGroupBody\">\n      <button data-section=\"blocklogger\">Block Logging</button>\n      <button data-section=\"animals\">Animal Limiter</button>\n      <button data-section=\"announcements\">Announcements</button>\n      <button data-section=\"restarts\">Automated Restarts</button>\n      <button data-section=\"chatDisplay\">Chat Display</button>\n      <button data-section=\"console\">Web Console</button>\n      <button data-section=\"webmap\">Web Map</button>\n      <button data-section=\"communityMotd\">Community MOTD</button>\n      <button data-section=\"mods\">Mod Management</button>\n      <button data-section=\"customPatches\">Patch Generator</button>\n      <button data-section=\"compatibility\">Compatibility</button>\n      <button data-section=\"loginProtection\">Login Protection</button>\n    </div>\n  </div>\n  <div class=\"navGroup\" data-nav-group=\"moderation\">\n    <button class=\"navGroupToggle\" type=\"button\"><span>Players &amp; Moderation</span><span class=\"navChevron\">▼</span></button>\n    <div class=\"navGroupBody\">\n      <button data-section=\"playerlist\">Player List</button>\n      <button data-section=\"playercommands\">Player Commands</button>\n      <button data-section=\"roles\">Role Config</button>\n      <button data-section=\"warps\">Warp Management</button>\n      <button data-section=\"anticheat\">Anti-Cheat</button>\n      <button data-section=\"chatguard\">ChatGuard</button>\n      <button data-section=\"reports\">Reports &amp; Tickets</button>\n      <button data-section=\"admin\">Player Administration</button>\n    </div>\n  </div>\n  <div class=\"navGroup\" data-nav-group=\"administration\">\n    <button class=\"navGroupToggle\" type=\"button\"><span>Administration</span><span class=\"navChevron\">▼</span></button>\n    <div class=\"navGroupBody\">\n      <button data-section=\"operations\">Operations &amp; Audit</button>\n      <button data-section=\"customization\">Suite Customization</button>\n      <button data-section=\"databaseStorage\">Database Storage</button>\n      <button data-section=\"discord\">Discord</button>\n      <button data-section=\"web\">Web Server</button>\n      <button data-section=\"help\">Help &amp; About</button>\n    </div>\n  </div>\n  <div id=\"suiteSidebarFooter\">Newfie's Server Suite · Server Administration</div>\n</nav>\n<div id=\"mobileNavBackdrop\" class=\"mobileNavBackdrop\" aria-hidden=\"true\"></div>\n\n<main>\n<div class=\"workspaceToolbar\" aria-label=\"Page workspace tools\">\n  <div id=\"breadcrumbBar\"><span>Server Essentials Suite</span><span>›</span><span id=\"breadcrumbCurrent\" class=\"crumbCurrent\">Dashboard</span></div>\n  <div class=\"workspaceTools\"><select id=\"workspaceJump\" aria-label=\"Jump to a panel on this page\"><option value=\"\">On this page</option></select><button id=\"workspaceDensity\" type=\"button\" aria-pressed=\"false\">Compact</button><button id=\"workspaceFocus\" type=\"button\" aria-pressed=\"false\">Focus page</button><button id=\"workspaceRefresh\" type=\"button\">Refresh page</button></div>\n</div>\n<div id=\"readOnlyNotice\" class=\"readOnlyNotice\"><b>Read-only session</b><span>You can inspect server data, but changes and disruptive actions are disabled for this account.</span></div>\n<section id=\"dashboard\" class=\"active\">\n  <div class=\"pageTitle\">\n    <div><h2 id=\"suiteDashboardTitle\">Server Dashboard</h2><div id=\"suiteDashboardSubtitle\" class=\"subtitle\">Actionable server and Suite overview: what needs attention, current operations state, health evidence, and recent lag.</div></div>\n  </div>\n  <div id=\"dashboardWarning\"></div>\n  <div class=\"workspaceLaunchGrid\" aria-label=\"Common administration tasks\">\n    <button type=\"button\" data-workspace-go=\"anticheat\"><span class=\"workspaceShortcutIcon\" aria-hidden=\"true\">⌕</span><span><b>Investigate a player</b><small>Review client evidence, packet findings, and incident history.</small></span></button>\n    <button type=\"button\" data-workspace-go=\"admin\"><span class=\"workspaceShortcutIcon\" aria-hidden=\"true\">▦</span><span><b>Inspect player inventories</b><small>Find online players or inspect saved offline inventories.</small></span></button>\n    <button type=\"button\" data-workspace-go=\"performance\"><span class=\"workspaceShortcutIcon\" aria-hidden=\"true\">↗</span><span><b>Review server load</b><small>Check tick health, recent lag, and performance evidence.</small></span></button>\n  </div>\n  <div class=\"grid2\" style=\"margin-bottom:12px\">\n    <div class=\"card\" id=\"dashboardAttentionCard\">\n      <div class=\"cardHeader\"><h3>Needs Attention</h3><div class=\"spacer\"></div><span id=\"dashboardAttentionMeta\" class=\"small\">Checking…</span></div>\n      <div id=\"dashboardAttention\"><div class=\"empty\">Checking current server and Suite signals…</div></div>\n    </div>\n    <div class=\"card\" id=\"dashboardOperationsCard\">\n      <div class=\"cardHeader\"><h3>Operations Snapshot</h3><div class=\"spacer\"></div><span class=\"small\">Live actionable state</span></div>\n      <div id=\"dashboardOpsSummary\"><div class=\"empty\">Loading operations state…</div></div>\n    </div>\n  </div>\n  <div id=\"dashboardSmart\" class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"empty\">Smart diagnosis is waiting for profiler diagnostics.</div>\n  </div>\n  <div class=\"grid\" id=\"dashboardMetrics\"></div>\n  <div class=\"quickActions\">\n    <button id=\"dashRefresh\">Refresh Now</button>\n    <button id=\"dashCustomize\">Customize Dashboard</button>\n    <button id=\"dashServerStatus\">Server Status</button>\n    <button id=\"dashActionCenter\">Open Action Center</button>\n    <button id=\"dashProfiler\" class=\"primary\">Open Profiler & Lag</button>\n  </div>\n  <div class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\"><h3>Watchlist / Pinned Items</h3><div class=\"spacer\"></div><span id=\"watchCount\" class=\"small\"></span></div>\n    <div id=\"dashboardWatchlist\" class=\"watchList\"><div class=\"emptyAction\"><b>No pinned items yet.</b><br>Pin an entity, chunk, mod, or page while investigating and it will appear here.</div></div>\n  </div>\n  <div class=\"card\">\n    <div class=\"cardHeader\"><h3>Recent Lag Evidence</h3><div class=\"spacer\"></div><span class=\"small\">Newest correlated events from lightweight diagnostics</span></div>\n    <div id=\"dashboardIncidents\" class=\"empty\">Profiler diagnostics are disabled or no lag evidence has been recorded.</div>\n  </div>\n</section>\n\n<section id=\"serverStatus\">\n  <div class=\"pageTitle\">\n    <div><h2>Server Status</h2><div class=\"subtitle\">Live server runtime, player population, network totals, maintenance state, and historical player-count analytics in one place.</div></div>\n  </div>\n  <div class=\"toolbar\">\n    <button id=\"serverStatusRefresh\">Refresh</button>\n    <div class=\"segmented\" id=\"playerAnalyticsRange\">\n      <button data-player-days=\"7\">7 days</button>\n      <button data-player-days=\"30\" class=\"active\">30 days</button>\n      <button data-player-days=\"90\">90 days</button>\n    </div>\n    <button id=\"serverStatusCopy\">Copy Status</button>\n    <div class=\"spacer\"></div><span id=\"serverStatusState\" class=\"small\">Not loaded.</span>\n  </div>\n  <div class=\"quickActions\">\n    <button id=\"serverStatusReports\">Open Reports</button>\n    <button id=\"serverStatusPlayers\">Player Administration</button>\n    <button id=\"serverStatusOperations\">Operations & Audit</button>\n    <button id=\"serverStatusProfiler\">Profiler & Lag</button>\n  </div>\n  <div id=\"serverStatusMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"serverStatusGrid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Operations State</h3><div class=\"spacer\"></div><span id=\"serverStatusOpsMeta\" class=\"small\"></span></div>\n      <div id=\"serverStatusOps\" class=\"small\">Loading…</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Current Players</h3><div class=\"spacer\"></div><span id=\"serverStatusOnlineMeta\" class=\"small\"></span></div>\n      <div class=\"tableWrap serverStatusOnlineScroll\"><table><thead><tr><th>Player</th><th>Ping</th><th>State</th><th>Session</th><th>Role</th></tr></thead><tbody id=\"serverStatusOnlineRows\"><tr><td colspan=\"5\" class=\"muted\">Loading players…</td></tr></tbody></table></div>\n    </div>\n  </div>\n  <div class=\"cardHeader\" style=\"margin:16px 0 10px\"><h3>Player Growth &amp; Analytics</h3><div class=\"spacer\"></div><span id=\"playerAnalyticsState\" class=\"small\"></span></div>\n  <div id=\"playerAnalyticsMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"playerAnalyticsGrid perfSection\">\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>Daily Peak / Average Player Count</h3><div class=\"spacer\"></div><span id=\"playerDailyMeta\" class=\"small\"></span></div>\n      <div class=\"playerLegend\"><span><i></i>Daily high</span><span><i class=\"lowMark\"></i>Daily average</span></div>\n      <div class=\"playerChartWrap\"><canvas id=\"playerDailyChart\" class=\"playerChart\"></canvas></div>\n    </div>\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>Rolling Player Count — Last 24 Hours</h3><div class=\"spacer\"></div><span id=\"playerHourlyMeta\" class=\"small\"></span></div>\n      <div class=\"playerLegend\"><span><i></i>Time-weighted average</span><span><i class=\"rangeMark\"></i>Observed low/high range</span></div>\n      <div class=\"playerChartWrap\"><canvas id=\"playerHourlyChart\" class=\"playerChart\"></canvas></div>\n    </div>\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>New Players — Last 30 Days</h3><div class=\"spacer\"></div><span id=\"playerNewMeta\" class=\"small\"></span></div>\n      <div class=\"playerLegend\"><span><i></i>First-time joins per day</span></div>\n      <div class=\"playerChartWrap\"><canvas id=\"playerNewChart\" class=\"playerChart\"></canvas></div>\n    </div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Collection Notes</h3><div class=\"spacer\"></div><span id=\"playerAnalyticsTimezone\" class=\"small\"></span></div>\n    <p class=\"small\">Player-count collection is profiler-independent. Population changes are recorded on player lifecycle events and reconciled once per minute. Hourly averages are time-weighted. Growth metrics use Player Administration first-seen/last-seen records, so new-player counts remain available across restarts.</p>\n  </div>\n</section>\n\n<section id=\"logIntelligence\">\n  <div class=\"pageTitle\">\n    <div><h2>Log Intelligence</h2><div class=\"subtitle\">Grouped server-log diagnosis, likely mod ownership, health correlation, startup preflight, and mod-change regression evidence.</div></div>\n  </div>\n  <div class=\"toolbar\">\n    <button id=\"logRefresh\">Refresh</button>\n    <button id=\"logScanCurrent\" class=\"primary\">Scan Current Log</button>\n    <button id=\"logScanArchived\">Scan Archived Logs</button>\n    <button id=\"logRunPreflight\">Re-run Preflight</button>\n    <div class=\"spacer\"></div><span id=\"logState\" class=\"small\">Not loaded.</span>\n  </div>\n  <div id=\"logHero\" class=\"card perfSection\"><div class=\"empty\">Open this page to load log health.</div></div>\n  <div id=\"logMetrics\" class=\"grid perfSection\"></div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Bad Block Entity Tracker</h3><div class=\"spacer\"></div><span id=\"badBeState\" class=\"small\">No tracker data loaded.</span><button id=\"badBeClearAll\" class=\"danger\">Remove All Tracker Entries</button></div>\n    <p class=\"small\">Tracks Vintage Story's standard <code>BlockEntity ... threw an error when ticked</code> log entries by exact coordinate. It reuses the existing incremental log tail: no world scan, per-tick scanner, or extra Harmony patch is added. Destructive world controls are audited and require confirmation. <b>Remove All Tracker Entries</b> only clears saved tracker records; it never removes world blocks or block entities.</p>\n    <div class=\"tableWrap logScroll\">\n      <table>\n        <thead><tr><th>Status</th><th>Position</th><th>Block / Entity</th><th>Errors</th><th>First / Last seen</th><th>Last exception</th><th>Controls</th></tr></thead>\n        <tbody id=\"badBeRows\"><tr><td colspan=\"6\" class=\"muted\">No bad block entities tracked yet.</td></tr></tbody>\n      </table>\n    </div>\n    <div id=\"badBeDetail\" class=\"card logDetailScroll\" style=\"display:none;margin-top:12px;background:#10171d\"></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Issue Categories</h3><div class=\"spacer\"></div><span class=\"small\">Repeated lines are grouped into normalized signatures.</span></div>\n    <div class=\"tableWrap logScroll logCategoryScroll\"><table><thead><tr><th>Category</th><th>Occurrences</th><th>Unique issues</th><th>Impact</th></tr></thead><tbody id=\"logCategoryRows\"><tr><td colspan=\"4\" class=\"muted\">No scan loaded.</td></tr></tbody></table></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Issue Signatures</h3><div class=\"spacer\"></div><span class=\"small\">Click an issue for context, diagnosis, correlation, and recommended action.</span><button id=\"logIssueClearAll\" class=\"danger\">Clear All</button></div>\n    <div class=\"tableWrap logScroll logIssueScroll\"><table><thead><tr><th>Impact</th><th>Category</th><th>Issue</th><th>Count</th><th>Likely mod</th><th>Confidence</th><th>Last seen</th></tr></thead><tbody id=\"logIssueRows\"><tr><td colspan=\"6\" class=\"muted\">No issues loaded.</td></tr></tbody></table></div>\n    <div id=\"logIssueDetail\" class=\"card logDetailScroll\" style=\"display:none;margin-top:12px;background:#10171d\"></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Startup Preflight</h3><div class=\"spacer\"></div><span id=\"preflightState\" class=\"small\"></span></div>\n    <div id=\"preflightMetrics\" class=\"grid\" style=\"margin-bottom:12px\"></div>\n    <div class=\"tableWrap logScroll logPreflightScroll\"><table><thead><tr><th>State</th><th>Category</th><th>Check</th><th>Detail</th><th>Recommended action</th></tr></thead><tbody id=\"preflightRows\"><tr><td colspan=\"5\" class=\"muted\">No preflight data loaded.</td></tr></tbody></table></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Changes Since Previous Recorded Boot</h3><div class=\"spacer\"></div><span class=\"small\">Loaded-mod manifest regression tracker</span></div>\n    <div id=\"logModChanges\" class=\"small\">No manifest comparison loaded.</div>\n  </div>\n</section>\n\n<section id=\"actionCenter\">\n  <div class=\"pageTitle\">\n    <div>\n      <h2>Action Center</h2>\n      <div class=\"subtitle\">One queue for active performance alerts, recommended next steps, and observed player-load behavior.</div>\n    </div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"actionRefresh\">Refresh</button>\n    <button id=\"actionEnableDiagnostics\" class=\"primary\">Enable Diagnostics</button>\n    <div class=\"spacer\"></div>\n    <span id=\"actionState\" class=\"small\"></span>\n  </div>\n\n  <div id=\"actionMetrics\" class=\"grid perfSection\"></div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Server Performance Scorecard</h3><div class=\"spacer\"></div><span class=\"small\">Click a category to investigate</span></div>\n    <div id=\"scorecardRows\" class=\"smartGrid\"><div class=\"empty\">Waiting for diagnostics.</div></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Recommended Actions</h3><div class=\"spacer\"></div><span id=\"actionCount\" class=\"small\"></span><button id=\"actionClearAll\" type=\"button\">Clear all actions</button></div>\n    <p class=\"small\">Recommendations combine active alerts and Smart Diagnosis. Clear dismisses the current recommendation until its condition disappears and occurs again. It does not fix the reported condition.</p>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Priority</th><th>Category</th><th>Action</th><th>Reason</th><th>Status</th><th>Controls</th></tr></thead>\n        <tbody id=\"actionRows\"><tr><td colspan=\"6\" class=\"muted\">Waiting for diagnostics.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Alerts</h3><div class=\"spacer\"></div><span id=\"alertCount\" class=\"small\"></span><button id=\"alertClearAll\" type=\"button\">Clear all alerts</button></div>\n    <p class=\"small\">Clear removes retained alert history. Ongoing conditions can create new alerts; monitoring stays enabled.</p>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Severity</th><th>Category</th><th>Alert</th><th>Evidence</th><th>Occurrences</th><th>Last seen</th><th>Status</th><th>Controls</th></tr></thead>\n        <tbody id=\"alertRows\"><tr><td colspan=\"8\" class=\"muted\">No alerts loaded.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Observed Player Load</h3><div class=\"spacer\"></div><span id=\"playerLoadComfort\" class=\"small\"></span></div>\n    <p class=\"small\">Historical one-minute samples grouped by online player count. This is an observed workload model, not a hard player limit.</p>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Players</th><th>Samples</th><th>Avg delay</th><th>Worst delay</th><th>Avg CPU</th><th>Max CPU</th><th>Stall samples</th><th>Stall %</th></tr></thead>\n        <tbody id=\"playerLoadRows\"><tr><td colspan=\"8\" class=\"muted\">Collecting player-load history.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>World Save Performance</h3><div class=\"spacer\"></div><span id=\"worldSaveState\" class=\"small\"></span></div>\n      <p class=\"small\">Measured from the official GameWorldSave event until the server main thread services a post-save callback. This is an observed main-thread save window, not pure disk-write time.</p>\n      <div class=\"tableWrap\">\n        <table>\n          <thead><tr><th>Time</th><th>Observed window</th><th>Players</th><th>Delay at start</th><th>Severity</th></tr></thead>\n          <tbody id=\"worldSaveRows\"><tr><td colspan=\"5\" class=\"muted\">Waiting for the next world save.</td></tr></tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Server Network</h3><div class=\"spacer\"></div><span id=\"networkState\" class=\"small\"></span></div>\n      <p class=\"small\">Real server-wide sent/received byte counters. Per-mod/per-packet attribution is not claimed.</p>\n      <div class=\"tableWrap\">\n        <table>\n          <thead><tr><th>Time</th><th>Outbound</th><th>Inbound</th><th>Players</th></tr></thead>\n          <tbody id=\"networkRows\"><tr><td colspan=\"4\" class=\"muted\">Collecting network history.</td></tr></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Deep Instrumentation Status</h3></div>\n    <div id=\"instrumentationCards\" class=\"smartGrid\"></div>\n  </div>\n</section>\n\n<section id=\"performance\">\n  <div class=\"pageTitle\">\n    <div>\n      <h2>Performance Center</h2>\n      <div class=\"subtitle\">Automatic lag incidents, entity/chunk pressure, BlockLogger activity hotspots, optimization providers, and Harmony patch-overlap inspection.</div>\n    </div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"perfRefresh\">Refresh Overview</button>\n    <select id=\"perfWindow\" title=\"Analysis window\">\n      <option value=\"300\">5 min</option>\n      <option value=\"900\">15 min</option>\n      <option value=\"1800\" selected>30 min</option>\n    </select>\n    <button id=\"perfEnableDiagnostics\" class=\"primary\">Enable Diagnostics</button>\n    <button id=\"perfEntityScan\">Scan Entity / Chunk Hotspots</button>\n    <button id=\"perfActivityRefresh\">Refresh Block Activity</button>\n    <button id=\"perfConflictRefresh\">Inspect Harmony Patches</button>\n    <button id=\"perfDownloadBundle\">Download Diagnostic Bundle v2</button>\n    <div class=\"spacer\"></div>\n    <span id=\"perfLastScan\" class=\"small\"></span>\n  </div>\n\n  <div id=\"perfNotice\"></div>\n  <div id=\"perfMetrics\" class=\"grid perfSection\"></div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Current Bottleneck Summary</h3><div class=\"spacer\"></div><span class=\"small\">Fast triage from existing lightweight diagnostics</span></div>\n    <div id=\"perfQuickRead\" class=\"smartGrid\"><div class=\"empty\">Waiting for diagnostics.</div></div>\n    <div id=\"perfWindowSummary\" class=\"grid\" style=\"margin-top:10px\"></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Suite Timing Hotspots</h3><div class=\"spacer\"></div><span class=\"small\">Rolling in-memory timings; recorded Suite wall time, not whole-server CPU attribution</span></div>\n    <div class=\"tableWrap\"><table><thead><tr><th>Subsystem</th><th>Calls / min</th><th>Time / min</th><th>Last</th><th>Average</th><th>P95</th><th>Max</th><th>Recent samples</th></tr></thead><tbody id=\"perfSuiteTimings\"><tr><td colspan=\"8\" class=\"muted\">No suite timing samples yet.</td></tr></tbody></table></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\">\n      <h3>Unified Performance Timeline</h3>\n      <div class=\"spacer\"></div>\n      <span id=\"perfTimelineState\" class=\"small\">30-minute rolling view</span>\n    </div>\n    <p class=\"small\">Aligned scheduler delay, CPU, loaded entities, and managed heap. Vertical markers show archived lag incidents, mod-environment changes, and manual entity scans.</p>\n    <div class=\"timelineWrap\"><canvas id=\"perfTimelineCanvas\" class=\"performanceTimeline\"></canvas></div>\n  </div>\n\n  <div id=\"perfIncidentDetailCard\" class=\"card perfSection\" style=\"display:none\">\n    <div class=\"cardHeader\">\n      <h3>Incident Drill-Down / Black Box</h3>\n      <div class=\"spacer\"></div>\n      <button id=\"perfIncidentProfiler\">Open in Profiler</button>\n      <button id=\"perfIncidentClose\">Close</button>\n    </div>\n    <div id=\"perfIncidentDetail\"></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\">\n      <h3>Automatic Lag Incident Center</h3>\n      <div class=\"spacer\"></div>\n      <button id=\"perfCompareBtn\" disabled>Compare Selected (0/2)</button>\n      <span id=\"perfIncidentCount\" class=\"small\"></span>\n      <button id=\"perfClearLagHistory\" class=\"miniClear\" title=\"Clear retained Performance/Profiler lag incident history\">Clear</button>\n    </div>\n    <p class=\"small\">Built from the lightweight rolling diagnostics. Archived incidents retain approximately 30 seconds before, the incident itself, and 15 seconds after. Click a row for drill-down or select two incidents to compare recurring patterns.</p>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Compare</th><th>Start</th><th>Duration</th><th>Severity</th><th>Likely area</th><th>Likely mod</th><th>Confidence</th><th>Worst delay</th><th>CPU</th><th>Evidence</th><th>Next action</th></tr></thead>\n        <tbody id=\"perfIncidents\"><tr><td colspan=\"11\" class=\"muted\">Waiting for diagnostics.</td></tr></tbody>\n      </table>\n    </div>\n    <div id=\"perfIncidentCompare\" class=\"card\" style=\"display:none;margin-top:10px\"></div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Entity Type Hotspots</h3><div class=\"spacer\"></div><span id=\"perfEntityCount\" class=\"small\"></span></div>\n      <p class=\"small\">Manual scan of currently loaded entities. Counts/population are pressure evidence, not per-entity CPU timing.</p>\n      <div class=\"tableWrap\">\n        <table>\n          <thead><tr><th>Entity type</th><th>Runtime type</th><th>Count</th><th>Chunks</th><th>Actions</th></tr></thead>\n          <tbody id=\"perfEntityTypes\"><tr><td colspan=\"5\" class=\"muted\">Run Scan Entity / Chunk Hotspots.</td></tr></tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Chunk Pressure Heatmap</h3><div class=\"spacer\"></div><span class=\"small\">7×7 around hottest scanned chunk</span></div>\n      <p class=\"small\">Pressure combines loaded entities, unique entity types, and players. It is a triage score, not measured chunk CPU time.</p>\n      <div style=\"overflow:auto\"><div id=\"perfHeatmap\" class=\"perfHeatmap\"></div></div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Entity Growth / Runaway Watch</h3><div class=\"spacer\"></div><span id=\"perfGrowthState\" class=\"small\"></span></div>\n    <p class=\"small\">Type-level growth compares the last two manual entity scans. Large increases are investigation leads, not automatic proof of a broken spawn rule.</p>\n    <div id=\"perfGrowthSummary\" class=\"grid\" style=\"margin-top:10px\"></div>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Entity type</th><th>Before</th><th>After</th><th>Delta</th><th>Change %</th><th>Severity</th><th>Reason</th><th>Actions</th></tr></thead>\n        <tbody id=\"perfEntityGrowth\"><tr><td colspan=\"8\" class=\"muted\">Run at least two manual entity scans to build type-level growth history.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Highest-Pressure Chunks</h3><div class=\"spacer\"></div><span id=\"perfChunkCount\" class=\"small\"></span></div>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Chunk</th><th>Dimension</th><th>Pressure</th><th>Entities</th><th>Players</th><th>Unique types</th><th>Top entity types</th><th>Actions</th></tr></thead>\n        <tbody id=\"perfChunks\"><tr><td colspan=\"8\" class=\"muted\">Run the manual entity/chunk scan.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\">\n      <h3>Block / Container Activity Hotspots</h3>\n      <div class=\"spacer\"></div>\n      <select id=\"perfActivityWindow\">\n        <option value=\"10\">10 minutes</option>\n        <option value=\"30\" selected>30 minutes</option>\n        <option value=\"60\">1 hour</option>\n        <option value=\"360\">6 hours</option>\n      </select>\n      <span id=\"perfActivityCount\" class=\"small\"></span>\n    </div>\n    <div class=\"warning\"><b>Activity evidence only:</b> these rows count recent BlockLogger events by coordinate. They do not claim that a block entity consumed CPU time.</div>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Coordinate</th><th>Dimension</th><th>Block</th><th>Events</th><th>Action types</th><th>Last activity</th></tr></thead>\n        <tbody id=\"perfBlockActivity\"><tr><td colspan=\"6\" class=\"muted\">Loading activity hotspots…</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\">\n      <h3>Mod / Environment Regression History</h3>\n      <div class=\"spacer\"></div>\n      <button id=\"perfEnvironmentRefresh\">Refresh</button>\n      <span id=\"perfEnvironmentState\" class=\"small\"></span>\n    </div>\n    <p class=\"small\">The suite fingerprints the loaded mod/version environment. When it changes, it compares the previous environment's last known performance with the new one after enough diagnostics have collected.</p>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Detected</th><th>Changed mods</th><th>Result</th><th>Regression score</th><th>Confidence</th><th>Reason</th></tr></thead>\n        <tbody id=\"perfEnvironmentHistory\"><tr><td colspan=\"6\" class=\"muted\">No mod-environment change has been recorded yet.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Optimization Providers</h3><div class=\"spacer\"></div><button id=\"perfProvidersRefresh\">Refresh</button></div>\n      <div id=\"perfProviders\" class=\"smartGrid\"><div class=\"empty\">Loading providers…</div></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Instrumentation Coverage</h3></div>\n      <div class=\"small\">\n        <p><b>Automatic:</b> CPU, scheduler delay, GC, memory, entities/chunk counts, BlockLogger backpressure, Smart Diagnosis, grouped lag incidents.</p>\n        <p><b>Manual:</b> loaded entity/type/chunk hotspot scan and exact 10s/30s engine profiling.</p>\n        <p><b>Activity proxy:</b> block/container coordinates from BlockLogger history.</p>\n        <p><b>Not claimed yet:</b> exact per-block-entity CPU, packet bandwidth by mod, or world-save phase timing. Those need dedicated instrumentation before the dashboard should present them as measured cost.</p>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Harmony Patch / Compatibility Inspector</h3><div class=\"spacer\"></div><span id=\"perfConflictSummary\" class=\"small\"></span></div>\n    <p class=\"small\">Shows methods patched by more than one Harmony owner. Multiple owners can be completely compatible; this is a conflict-investigation lead, not automatic blame.</p>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Severity</th><th>Type</th><th>Method</th><th>Owners</th><th>Note</th></tr></thead>\n        <tbody id=\"perfConflicts\"><tr><td colspan=\"5\" class=\"muted\">Run Inspect Harmony Patches.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<section id=\"memory\">\n  <div class=\"pageTitle\">\n    <div>\n      <h2>Memory & GC</h2>\n      <div class=\"subtitle\">Heap direction, Gen0/1/2 pressure, and conservative retained-memory detection based on post-Gen2 behavior.</div>\n    </div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"memoryRefresh\">Refresh</button>\n    <button id=\"memoryEnableDiagnostics\" class=\"primary\">Enable Diagnostics</button>\n    <div class=\"spacer\"></div>\n    <span id=\"memoryState\" class=\"small\"></span>\n  </div>\n\n  <div id=\"memoryHero\" class=\"card perfSection\"><div class=\"empty\">Waiting for memory diagnostics.</div></div>\n  <div id=\"memoryMetrics\" class=\"grid perfSection\"></div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Managed Heap Timeline</h3><div class=\"spacer\"></div><span class=\"small\">30-minute rolling view</span></div>\n    <div class=\"memoryChartWrap\"><canvas id=\"memoryChart\" class=\"memoryChart\"></canvas></div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Interpretation</h3></div>\n      <div id=\"memoryFinding\" class=\"small\">Waiting for diagnostics.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>What the detector means</h3></div>\n      <div class=\"small\">\n        <p><b>Allocation pressure:</b> heap rises, Gen2 runs, then heap returns near its old baseline.</p>\n        <p><b>Possible retained growth:</b> the estimated post-Gen2 heap floor repeatedly settles higher.</p>\n        <p>The detector deliberately says <b>possible</b>; a rising heap floor is evidence, not proof of a memory leak in a particular mod.</p>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\">\n      <div>\n        <h3>MemLeakInspector</h3>\n        <div class=\"small\">Capture lightweight memory snapshots, compare growth over time, and inspect Suite-owned retained structures without continuously walking the whole managed heap.</div>\n      </div>\n      <div class=\"spacer\"></div>\n      <span id=\"memoryInspectorStatus\" class=\"badge neutral\">Ready</span>\n    </div>\n    <div class=\"compactNote\" style=\"margin-bottom:10px\">\n      MemLeakInspector presents evidence, not an automatic leak verdict. A true whole-heap object/type inventory requires a deep .NET heap capture and can pause a large server.\n    </div>\n    <div class=\"toolbar\">\n      <input id=\"memoryInspectorLabel\" maxlength=\"80\" placeholder=\"Snapshot label (optional)\" style=\"min-width:220px\">\n      <button id=\"memoryInspectorCapture\" class=\"primary\">Capture Snapshot</button>\n      <button id=\"memoryInspectorClear\" class=\"danger\">Clear Snapshots</button>\n    </div>\n    <div id=\"memoryInspectorSummary\" class=\"grid\" style=\"margin-top:10px\"></div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Snapshot Comparison</h3></div>\n      <div class=\"toolbar\">\n        <label class=\"small\">From <select id=\"memoryCompareA\"></select></label>\n        <label class=\"small\">To <select id=\"memoryCompareB\"></select></label>\n        <button id=\"memoryInspectorCompare\">Compare</button>\n      </div>\n      <div id=\"memoryInspectorComparison\" class=\"small\" style=\"margin-top:10px\">Capture at least one snapshot to compare memory state.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Deep Heap Capture Readiness</h3></div>\n      <div id=\"memoryDeepCapture\" class=\"small\">Checking runtime tooling…</div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Saved Memory Snapshots</h3><div class=\"spacer\"></div><span id=\"memorySnapshotCount\" class=\"small\"></span></div>\n    <div class=\"tableWrap dataScroll\">\n      <table>\n        <thead><tr><th>Time</th><th>Label</th><th>Heap</th><th>Private</th><th>Committed</th><th>Fragmented</th><th>Gen2</th><th>Players</th><th></th></tr></thead>\n        <tbody id=\"memoryInspectorSnapshots\"><tr><td colspan=\"9\" class=\"muted\">No snapshots captured.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Tracked Structures</h3><div class=\"spacer\"></div><span class=\"small\">Suite-owned structures and runtime context; not a whole-heap object inventory</span></div>\n    <div class=\"tableWrap dataScrollTall\">\n      <table>\n        <thead><tr><th>Category</th><th>Structure</th><th>Runtime type</th><th>Count</th><th>Note</th></tr></thead>\n        <tbody id=\"memoryInspectorStructures\"><tr><td colspan=\"5\" class=\"muted\">Waiting for memory data.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n__NSS_RETENTION_HTML__\n</section>\n\n<section id=\"optimizations\">\n  <div class=\"pageTitle\">\n    <div>\n      <h2>Optimizations</h2>\n      <div class=\"subtitle\">Measure and control supported external optimizers through their documented admin commands. Server Essentials provides recommendations, safety checks, and before/after measurement without copying optimizer code.</div>\n    </div>\n  </div>\n\n  <div id=\"tungstenBanner\" class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"empty\">Checking for Tungsten…</div>\n  </div>\n\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Smart Optimization Advisor</h3><div class=\"spacer\"></div><span id=\"tungstenAdvisorState\" class=\"small\"></span></div>\n      <div id=\"tungstenAdvisor\" class=\"small\">Waiting for server diagnostics.</div>\n      <div class=\"quickActions\">\n        <button id=\"tungstenEnableDiagnostics\">Enable Diagnostic Sampling</button>\n        <button id=\"tungstenOpenProfiler\">Open Profiler & Lag</button>\n      </div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Before / After Measurement</h3><div class=\"spacer\"></div><button id=\"optimizationEvaluate\">Evaluate Now</button></div>\n      <div id=\"optimizationExperiment\" class=\"small\">No measured optimization experiment is pending.</div>\n    </div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"tungstenRefresh\">Refresh</button>\n    <button id=\"tungstenStatus\">Run Status</button>\n    <button id=\"tungstenStats\">Stats</button>\n    <button id=\"tungstenHealth\">Health</button>\n    <button id=\"tungstenManifest\">Manifest</button>\n    <button id=\"tungstenReload\">Reload Config</button>\n    <div class=\"spacer\"></div>\n    <button id=\"tungstenAllOn\" class=\"primary\">All ON</button>\n    <button id=\"tungstenAllOff\" class=\"danger\">All OFF</button>\n  </div>\n\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Diagnostics</h3></div>\n      <div class=\"row\">\n        <div class=\"field grow\">\n          <label>Module</label>\n          <select id=\"tungstenDiagModule\" style=\"width:100%\"><option value=\"all\">All modules</option></select>\n        </div>\n        <button id=\"tungstenDiagOn\">Diag ON</button>\n        <button id=\"tungstenDiagOff\">Diag OFF</button>\n        <button id=\"tungstenDiagDump\">Dump</button>\n        <button id=\"tungstenDiagReset\">Reset</button>\n        <button id=\"tungstenStatsOn\">Detailed Stats ON</button>\n        <button id=\"tungstenStatsOff\">Detailed Stats OFF</button>\n      </div>\n      <p class=\"small\">Tungsten documents diagnostics as zero-overhead when disabled. Detailed dump output may be written to the Vintage Story server log.</p>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Benchmark & Slow Tick Tools</h3></div>\n      <div class=\"row\">\n        <button id=\"tungstenBenchmarkOn\">Benchmark ON</button>\n        <button id=\"tungstenBenchmarkOff\">Benchmark OFF</button>\n        <div class=\"field\">\n          <label>Slow tick threshold (ms)</label>\n          <input id=\"tungstenFrameThreshold\" type=\"number\" value=\"100\" min=\"10\" max=\"5000\" style=\"width:120px\">\n        </div>\n        <button id=\"tungstenFrameOn\">Frame Profiler ON</button>\n        <button id=\"tungstenFrameOff\">Frame Profiler OFF</button>\n      </div>\n      <p class=\"small\">These controls call Tungsten's benchmark harness and frame-profiler commands; they are separate from BlockLogger's own profiler.</p>\n    </div>\n  </div>\n\n  <div class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\">\n      <h3>Tungsten Optimizations</h3>\n      <div class=\"spacer\"></div>\n      <select id=\"tungstenCategory\"><option value=\"\">All categories</option></select>\n      <input id=\"tungstenFilter\" placeholder=\"Filter optimizations…\" style=\"min-width:220px\">\n      <span id=\"tungstenCount\" class=\"small\"></span>\n    </div>\n    <div class=\"warning\"><b>Restart note:</b> Tungsten documents that most optimization changes require a server restart. Buttons below send Tungsten's own <code>/tungsten &lt;name&gt; on|off</code> commands.</div>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Optimization</th><th>Recommendation</th><th>Category</th><th>What it targets</th><th>Available</th><th>Controls</th></tr></thead>\n        <tbody id=\"tungstenRows\"><tr><td colspan=\"6\" class=\"muted\">Waiting for Tungsten status…</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div style=\"height:1px;background:var(--line);margin:18px 0\"></div>\n\n  <div class=\"pageTitle\" style=\"margin-bottom:10px\">\n    <div>\n      <h2 style=\"font-size:21px\">Synergy</h2>\n      <div class=\"subtitle\">Coordinated server/client optimization integration through Synergy's public <code>/synergy</code> command interface.</div>\n    </div>\n  </div>\n\n  <div id=\"synergyBanner\" class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"empty\">Checking for Synergy…</div>\n  </div>\n\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Synergy Advisor</h3><div class=\"spacer\"></div><span id=\"synergyAdvisorState\" class=\"small\"></span></div>\n      <div id=\"synergyAdvisor\" class=\"small\">Waiting for server diagnostics.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Safety Notes</h3></div>\n      <div class=\"small\">\n        <div><b>Entity Activation Range:</b> test carefully with modded entities that must keep working far away from players.</div>\n        <div style=\"margin-top:6px\"><b>Distance Send Frequency:</b> if distant animals look choppy, this is the first Synergy option to test OFF.</div>\n        <div style=\"margin-top:6px\"><b>Delta Encoding:</b> bandwidth savings require Synergy on both server and client.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"synergyRefresh\">Refresh</button>\n    <button id=\"synergyStatus\">Run Status</button>\n    <button id=\"synergyStats\">Stats</button>\n    <button id=\"synergyReload\">Reload Config</button>\n    <button id=\"synergyDiagOn\">Diagnostics ON</button>\n    <button id=\"synergyDiagOff\">Diagnostics OFF</button>\n    <button id=\"synergyDiagDump\">Diagnostics Dump</button>\n    <button id=\"synergyDiagReset\">Diagnostics Reset</button>\n    <div class=\"spacer\"></div>\n    <button id=\"synergyAllOn\" class=\"primary\">All ON</button>\n    <button id=\"synergyAllOff\" class=\"danger\">All OFF</button>\n  </div>\n\n  <div class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\">\n      <h3>Synergy Optimizations</h3>\n      <div class=\"spacer\"></div>\n      <select id=\"synergyCategory\"><option value=\"\">All categories</option></select>\n      <input id=\"synergyFilter\" placeholder=\"Filter Synergy optimizations…\" style=\"min-width:240px\">\n      <span id=\"synergyCount\" class=\"small\"></span>\n    </div>\n    <div class=\"warning\"><b>Restart required:</b> Synergy's public controls save configuration; optimization changes are applied after a server restart. The Configured column is read from <code>/synergy</code> status output; a restart is still required before changed patches are applied. Runtime circuit-breaker health remains visible in full Synergy status output.</div>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Optimization</th><th>Configured</th><th>Recommendation</th><th>Scope</th><th>Category</th><th>What it targets</th><th>Caution</th><th>Controls</th></tr></thead>\n        <tbody id=\"synergyRows\"><tr><td colspan=\"8\" class=\"muted\">Waiting for Synergy status…</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\"><h3>Last Synergy Command</h3><div class=\"spacer\"></div><button id=\"synergyClearOutput\">Clear</button></div>\n    <pre id=\"synergyOutput\" class=\"status\">No Synergy command has been run from the web dashboard yet.</pre>\n  </div>\n\n  <div class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\"><h3>Optimization Test History</h3><div class=\"spacer\"></div><span class=\"small\">Persistent server-side before/after results</span></div>\n    <div class=\"tableWrap\"><table>\n      <thead><tr><th>Optimization</th><th>Target</th><th>Result</th><th>Score</th><th>Confidence</th><th>Reason</th></tr></thead>\n      <tbody id=\"optimizationHistory\"><tr><td colspan=\"6\" class=\"muted\">No completed measurements yet.</td></tr></tbody>\n    </table></div>\n  </div>\n\n  <div class=\"card\">\n    <div class=\"cardHeader\"><h3>Last Tungsten Command</h3><div class=\"spacer\"></div><button id=\"tungstenClearOutput\">Clear</button></div>\n    <pre id=\"tungstenOutput\" class=\"status\">No Tungsten command has been run from the web dashboard yet.</pre>\n  </div>\n</section>\n\n<section id=\"blocklogger\">\n  <div class=\"pageTitle\"><div><h2>BlockLogger</h2><div class=\"subtitle\">Search audit history and control how much database history/backups are retained on disk.</div></div></div>\n\n  <div class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\"><h3>Database Maintenance &amp; Disk Usage</h3><div class=\"spacer\"></div><button id=\"blMaintenanceRefresh\">Refresh</button></div>\n    <div id=\"blMaintenanceStatus\" class=\"small\">Loading BlockLogger database policy…</div>\n    <div class=\"row\" style=\"margin-top:12px\">\n      <div class=\"field\"><label>Automatic history retention (days)</label><input id=\"blRetentionDaysWeb\" type=\"number\" min=\"0\" max=\"3650\" value=\"180\"></div>\n      <div class=\"field\"><label>Automatic DB backup interval (hours)</label><input id=\"blBackupHours\" type=\"number\" min=\"0\" max=\"8760\" value=\"72\"></div>\n      <div class=\"field\"><label>Healthy backup files to keep</label><input id=\"blBackupCount\" type=\"number\" min=\"1\" max=\"20\" value=\"2\"></div>\n      <button id=\"blMaintenanceSave\" class=\"primary\">Save Storage Policy</button>\n    </div>\n    <div class=\"small\" style=\"margin-top:7px\"><b>Backup policy:</b> 0 hours disables automatic full-database backups; manual backups remain available under Suite Health. The suite now defaults to a maximum of 2 healthy BlockLogger backups instead of 7.</div>\n\n    <hr style=\"border:0;border-top:1px solid var(--line);margin:14px 0\">\n    <h3 style=\"margin-bottom:8px\">Manual database purge</h3>\n    <div class=\"row\">\n      <div class=\"field\"><label>Keep the most recent (days)</label><input id=\"blPurgeKeepDays\" type=\"number\" min=\"0\" max=\"3650\" value=\"30\"></div>\n      <label class=\"field\"><span>Data to purge</span><span><input id=\"blPurgeEvents\" type=\"checkbox\" checked> Block / interaction events</span></label>\n      <label class=\"field\"><span>&nbsp;</span><span><input id=\"blPurgeSnapshots\" type=\"checkbox\" checked> Container snapshots</span></label>\n      <label class=\"field\"><span>&nbsp;</span><span><input id=\"blPurgeEntity\" type=\"checkbox\" checked> Entity activity</span></label>\n      <label class=\"field\"><span>&nbsp;</span><span><input id=\"blPurgeCompact\" type=\"checkbox\"> Compact DB after purge</span></label>\n      <button id=\"blPurgeBtn\" class=\"danger\">Purge Selected Data</button>\n    </div>\n    <div class=\"warning\" style=\"margin-top:10px\"><b>Destructive:</b> purge permanently deletes matching BlockLogger history. <b>0 days deletes all rows in the selected categories.</b> Purges run in bounded batches so a very large database may require more than one pass. Compacting (VACUUM) physically shrinks the DB file but can be slow and needs substantial temporary free disk; use it during a quiet maintenance window.</div>\n    <div id=\"blPurgeResult\" class=\"small\" style=\"margin-top:8px\"></div>\n  </div>\n\n  <div class=\"card\">\n    <h3 style=\"margin-bottom:10px\">Nearby history</h3>\n    <div class=\"row\">\n      <div class=\"field\"><label>View</label><select id=\"blView\"><option value=\"blocks\">Blocks</option><option value=\"containers\">Containers</option><option value=\"entities\">Entities</option></select></div>\n      <div class=\"field\"><label>X</label><input id=\"blX\" type=\"number\" value=\"0\"></div>\n      <div class=\"field\"><label>Y</label><input id=\"blY\" type=\"number\" value=\"100\"></div>\n      <div class=\"field\"><label>Z</label><input id=\"blZ\" type=\"number\" value=\"0\"></div>\n      <div class=\"field\"><label>Dimension</label><input id=\"blDim\" type=\"number\" value=\"0\"></div>\n      <div class=\"field\"><label>Radius</label><input id=\"blRadius\" type=\"number\" value=\"5\" min=\"0\"></div>\n      <div class=\"field\"><label>Rows</label><input id=\"blLimit\" type=\"number\" value=\"50\" min=\"1\"></div>\n      <div class=\"field\"><label>Action</label><select id=\"blAction\"><option value=\"any\">Any</option><option value=\"break\">Break</option><option value=\"place\">Place</option><option value=\"interact\">Use/Interact</option><option value=\"open\">Open</option><option value=\"take\">Take</option><option value=\"put\">Put</option><option value=\"entityinteract\">Entity Interact</option><option value=\"entityspawn\">Spawn</option><option value=\"entitydeath\">Death</option><option value=\"entitydespawn\">Despawn</option></select></div>\n      <div class=\"field grow\"><label>Search</label><input id=\"blSearch\" style=\"width:100%\" placeholder=\"optional block/item/entity/player text\"></div>\n      <button id=\"blSearchBtn\" class=\"primary\">Search</button>\n    </div>\n    <div class=\"savedViews\">\n      <div class=\"field grow\"><label>Saved View</label><select id=\"blSavedView\" style=\"width:100%\"><option value=\"\">— Saved searches —</option></select></div>\n      <button id=\"blSavedApply\">Apply</button>\n      <button id=\"blSavedSave\">Save Current</button>\n      <button id=\"blSavedDelete\">Delete</button>\n      <span class=\"small\">Saved in this browser only.</span>\n    </div>\n  </div>\n\n  <div class=\"card\" style=\"margin-top:12px\">\n    <h3 style=\"margin-bottom:10px\">Player history</h3>\n    <div class=\"row\">\n      <div class=\"field grow\"><label>Player name or UID</label><input id=\"playerName\" style=\"width:100%\"></div>\n      <div class=\"field\"><label>Activity</label><select id=\"playerCategory\"><option value=\"any\">Any</option><option value=\"blocks\">Blocks</option><option value=\"containers\">Containers</option><option value=\"entities\">Entities</option></select></div>\n      <div class=\"field\"><label>Rows</label><input id=\"playerLimit\" type=\"number\" value=\"50\" min=\"1\"></div>\n      <button id=\"playerSearchBtn\" class=\"primary\">Search Player</button>\n    </div>\n  </div>\n\n  <div class=\"toolbar\" style=\"margin:12px 0\">\n    <span id=\"blResultInfo\" class=\"small\"></span>\n    <div class=\"spacer\"></div>\n    <button id=\"blPrev\" disabled>Previous</button>\n    <button id=\"blNext\" disabled>Next</button>\n  </div>\n  <div class=\"tableWrap\">\n    <table><thead><tr><th>Time</th><th>Player</th><th>Action</th><th>Detail</th><th>Coordinates</th><th>In-game date</th></tr></thead><tbody id=\"blRows\"></tbody></table>\n  </div>\n</section>\n\n<section id=\"animals\">\n  <div class=\"pageTitle\"><div><h2>Animal Limiter</h2><div class=\"subtitle\">Inspect population pressure, manage limiter rules, and generate conservative rule recommendations from a manual loaded-entity scan.</div></div></div>\n  <div class=\"toolbar\">\n    <button id=\"animalRefresh\">Refresh Status</button>\n    <button id=\"animalScan\" class=\"primary\">Scan Population</button>\n    <button id=\"animalRecommend\">Analyze &amp; Recommend</button>\n    <span id=\"animalRuleState\" class=\"small\">No population or recommendation scan runs automatically.</span>\n  </div>\n  <div class=\"grid\">\n    <div class=\"card\"><h3 style=\"margin-bottom:10px\">Status</h3><pre id=\"animalStatus\" class=\"status\">Not loaded.</pre></div>\n    <div class=\"card\"><h3 style=\"margin-bottom:10px\">Population Scan</h3><div id=\"animalPopulation\" class=\"small\">Press Scan Population.</div></div>\n  </div>\n\n  <div class=\"animalRuleGrid\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Rule Editor</h3><div class=\"spacer\"></div><button id=\"animalRuleClear\">New</button></div>\n      <div class=\"animalRuleEditor small\">\n        <label for=\"animalRulePattern\">Entity / wildcard</label><input id=\"animalRulePattern\" placeholder=\"game:hare-* or modid:entity\">\n        <label for=\"animalRuleLimit\">Limit per region</label><input id=\"animalRuleLimit\" type=\"number\" min=\"0\" max=\"1000000\" value=\"20\">\n        <label for=\"animalRuleRadius\">Radius (chunks)</label><input id=\"animalRuleRadius\" type=\"number\" min=\"0\" max=\"32\" value=\"3\">\n      </div>\n      <div class=\"quickActions\" style=\"margin-top:12px\"><button id=\"animalRuleSave\" class=\"primary\">Add / Update Rule</button></div>\n      <div class=\"small\" style=\"margin-top:10px\">Rules save immediately. Radius 0 means one chunk; radius 1 means a 3×3 chunk region. Exact entity codes are safest when applying a recommendation.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Current Rules</h3><div class=\"spacer\"></div><span id=\"animalRulesSummary\" class=\"small\">Not loaded.</span></div>\n      <div class=\"tableWrap dataScroll\"><table><thead><tr><th>Pattern</th><th>Limit</th><th>Radius</th><th>Registered matches</th><th>Actions</th></tr></thead><tbody id=\"animalRuleRows\"><tr><td colspan=\"5\" class=\"muted\">Open this page to load Animal Limiter rules.</td></tr></tbody></table></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><div><h3>Exclusions</h3><div class=\"small\">Entities matching an exclusion are never removed by Animal Limiter, including while universal limiting is enabled.</div></div><div class=\"spacer\"></div><span id=\"animalExclusionSummary\" class=\"small\">Not loaded.</span></div>\n      <div class=\"row\" style=\"align-items:end;margin-top:10px\">\n        <div class=\"field grow\"><label for=\"animalExclusionPattern\">Entity / wildcard</label><input id=\"animalExclusionPattern\" placeholder=\"game:chicken-* or modid:pet-*\"></div>\n        <button id=\"animalExclusionAdd\" class=\"primary\">Add Exclusion</button>\n      </div>\n      <div class=\"compactNote\" style=\"margin-top:10px\">Wildcards use <code>*</code>. <code>game:player</code> is permanently protected and cannot be removed here.</div>\n      <div class=\"tableWrap dataScroll\" style=\"margin-top:12px\"><table><thead><tr><th>Excluded pattern</th><th>Action</th></tr></thead><tbody id=\"animalExclusionRows\"><tr><td colspan=\"2\" class=\"muted\">Open this page to load exclusions.</td></tr></tbody></table></div>\n    </div>\n  </div>\n\n  <div class=\"card\" style=\"margin-top:12px\">\n    <div class=\"cardHeader\"><h3>Recommended Rules</h3><div class=\"spacer\"></div><span id=\"animalRecommendationState\" class=\"small\">Not analyzed.</span></div>\n    <div class=\"warning animalRecommendationNote\"><b>Recommendation safety:</b> NSE analyzes currently loaded non-player agents near online players. It does not auto-apply anything. Low-confidence single-hotspot suggestions should be reviewed carefully before using Apply.</div>\n    <div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>Entity</th><th>Observed</th><th>Suggested</th><th>Radius</th><th>Estimated effect now</th><th>Confidence</th><th>Why</th><th>Actions</th></tr></thead><tbody id=\"animalRecommendationRows\"><tr><td colspan=\"8\" class=\"muted\">Press Analyze &amp; Recommend to inspect loaded populations.</td></tr></tbody></table></div>\n  </div>\n</section>\n\n<section id=\"loginProtection\">\n  <div class=\"pageTitle\"><div><h2>Login Protection</h2><div class=\"subtitle\">Join/respawn protection, water-login recovery, and validated live configuration.</div></div></div>\n  <div class=\"toolbar\"><button id=\"loginProtRefresh\">Refresh</button><button id=\"loginProtSave\" class=\"primary\">Save Configuration</button><span id=\"loginProtConfigState\" class=\"small\"></span></div>\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\"><h3 style=\"margin-bottom:10px\">Runtime Status</h3><pre id=\"loginProtStatus\" class=\"status\">Not loaded.</pre></div>\n    <div class=\"card\">\n      <h3 style=\"margin-bottom:10px\">Configuration</h3>\n      <div class=\"small\" style=\"display:grid;grid-template-columns:minmax(180px,1fr) 1fr;gap:9px 14px;align-items:center\">\n        <label for=\"lpEnabled\">Enabled</label><input id=\"lpEnabled\" type=\"checkbox\">\n        <label for=\"lpSeconds\">Protection seconds</label><input id=\"lpSeconds\" type=\"number\" min=\"1\" max=\"3600\" value=\"60\">\n        <label for=\"lpJoin\">Protect on join</label><input id=\"lpJoin\" type=\"checkbox\">\n        <label for=\"lpRespawn\">Protect on respawn</label><input id=\"lpRespawn\" type=\"checkbox\">\n        <label for=\"lpAnnounceJoin\">Announce protection start</label><input id=\"lpAnnounceJoin\" type=\"checkbox\">\n        <label for=\"lpAnnounceEnd\">Announce protection end</label><input id=\"lpAnnounceEnd\" type=\"checkbox\">\n        <label for=\"lpBlockPvp\">Block PvP while protected</label><input id=\"lpBlockPvp\" type=\"checkbox\">\n        <label for=\"lpCancelAttack\">Cancel protection on attack</label><input id=\"lpCancelAttack\" type=\"checkbox\">\n        <label for=\"lpFall\">Protect fall damage</label><input id=\"lpFall\" type=\"checkbox\">\n        <label for=\"lpFire\">Extinguish fire while protected</label><input id=\"lpFire\" type=\"checkbox\">\n        <label for=\"lpSwim\">Recover swimming on login</label><input id=\"lpSwim\" type=\"checkbox\">\n      </div>\n      <div class=\"small\" style=\"margin-top:12px\">Changes are clamped/validated server-side and saved to <code>NewfiesServerEssentialsSuite/NewfiesLoginProtection.json</code>. Disabling protection immediately clears active shields.</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"announcements\">\n  <div class=\"pageTitle\"><div><h2>Automated Announcements</h2><div class=\"subtitle\">Schedule recurring server messages by interval or exact local times, with optional run limits.</div></div></div>\n  <div class=\"toolbar\">\n    <button id=\"annRefresh\">Refresh</button><button id=\"annSave\" class=\"primary\">Save Schedule</button>\n    <label class=\"small\"><input id=\"annGlobalEnabled\" type=\"checkbox\"> automation enabled</label>\n    <label class=\"small\">Prefix <input id=\"annPrefix\" style=\"width:150px\" value=\"[Server]\"></label>\n    <div class=\"spacer\"></div><span id=\"annState\" class=\"small\">Not loaded.</span>\n  </div>\n  <div id=\"annMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"announcementGrid\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Announcement Editor</h3><div class=\"spacer\"></div><button id=\"annClear\">New</button></div>\n      <div class=\"announcementEditor small\">\n        <label for=\"annName\">Name</label><input id=\"annName\" maxlength=\"80\" placeholder=\"Rules reminder\">\n        <label for=\"annMessage\">Message</label><textarea id=\"annMessage\" maxlength=\"1000\" placeholder=\"Remember to read /rules. Online now: {players}\"></textarea>\n        <label for=\"annEnabled\">Enabled</label><input id=\"annEnabled\" type=\"checkbox\" checked>\n        <label for=\"annMode\">Schedule mode</label><select id=\"annMode\"><option value=\"interval\">Interval</option><option value=\"daily\">Exact daily times</option></select>\n        <label for=\"annInterval\">Interval minutes</label><input id=\"annInterval\" type=\"number\" min=\"1\" max=\"10080\" value=\"60\">\n        <label for=\"annStartTime\">Interval anchor</label><input id=\"annStartTime\" type=\"time\"><span></span><span class=\"muted\">Optional. Example: every 60 min starting at 09:00.</span>\n        <label for=\"annDailyTimes\">Daily times</label><input id=\"annDailyTimes\" placeholder=\"09:00, 15:00, 21:00\"><span></span><span class=\"muted\">Server-local HH:mm values, comma separated.</span>\n        <label for=\"annMaxRuns\">Run limit</label><input id=\"annMaxRuns\" type=\"number\" min=\"0\" max=\"1000000\" value=\"0\"><span></span><span class=\"muted\">0 = unlimited. Automatic sends count toward this limit; Test does not.</span>\n      </div>\n      <div class=\"quickActions\" style=\"margin-top:12px\"><button id=\"annApplyEditor\" class=\"primary\">Add / Update Rule</button></div>\n      <p class=\"small\">Placeholders: <code>{players}</code>, <code>{time}</code>, <code>{date}</code>. Schedules use the server machine's local timezone.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Scheduled Messages</h3><div class=\"spacer\"></div><span class=\"small\">Stored in <code>NewfiesServerEssentialsSuite/NewfiesAnnouncements.json</code></span></div>\n      <div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>State</th><th>Name / message</th><th>Schedule</th><th>Runs</th><th>Next run</th><th>Actions</th></tr></thead><tbody id=\"annRows\"><tr><td colspan=\"6\" class=\"muted\">No schedule loaded.</td></tr></tbody></table></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"restarts\">\n  <div class=\"pageTitle\"><div><h2>Automated Restarts</h2><div class=\"subtitle\">Th3Essentials-style UTC restart scheduling with configurable warning announcements and clean server shutdown.</div></div></div>\n  <div class=\"toolbar\"><button id=\"restartRefresh\">Refresh</button><button id=\"restartSave\" class=\"primary\">Save Schedule</button><button id=\"restartReload\">Reload Config</button><button id=\"restartSkip\" class=\"warnButton\">Skip Next</button><div class=\"spacer\"></div><span id=\"restartState\" class=\"small\">Not loaded.</span></div>\n  <div id=\"restartMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Restart Schedule</h3><div class=\"spacer\"></div><span class=\"small\">Stored in <code>NewfiesServerEssentialsSuite/NewfiesAutomatedRestarts.json</code></span></div>\n    <div class=\"webMapSettings\">\n      <label for=\"restartEnabled\">Scheduler</label><div><label><input id=\"restartEnabled\" type=\"checkbox\"> Enable automated restarts</label><div class=\"small\">When enabled, NSE calculates the next configured UTC restart and gracefully shuts down the server at that time.</div></div>\n      <label for=\"restartPrimaryTime\">Single restart time UTC</label><div><input id=\"restartPrimaryTime\" type=\"text\" value=\"00:00:00\" placeholder=\"00:00:00\"><div class=\"small\">Used when the multiple-times field below is empty. Format: HH:mm or HH:mm:ss.</div></div>\n      <label for=\"restartTimes\">Multiple restart times UTC</label><div><input id=\"restartTimes\" type=\"text\" placeholder=\"00:00:00, 12:00:00\"><div class=\"small\">Comma-separated. When present, these times take priority over the single restart time.</div></div>\n      <label for=\"restartWarnings\">Warning minutes</label><div><input id=\"restartWarnings\" type=\"text\" value=\"1, 2, 3, 4, 5, 10, 20, 30\"><div class=\"small\">Comma-separated minute thresholds. Example: 1,2,3,4,5,10,20,30.</div></div>\n      <label for=\"restartReason\">Restart reason</label><input id=\"restartReason\" type=\"text\" maxlength=\"240\" value=\"Scheduled server restart\">\n      <label>Announcements</label><div><label><input id=\"restartGameAnnouncements\" type=\"checkbox\" checked> Announce countdown in game</label> &nbsp; <label><input id=\"restartDiscordAnnouncements\" type=\"checkbox\" checked> Announce countdown to Discord when the unified Discord module is connected</label></div>\n    </div>\n    <div id=\"restartNext\" class=\"compactNote\" style=\"margin-top:12px\">No automatic restart is currently scheduled.</div>\n    <div id=\"restartCompat\" style=\"margin-top:12px\"></div>\n    <div class=\"warning\" style=\"margin-top:12px\"><b>Restart behavior:</b> like Th3Essentials, NSE performs a graceful Vintage Story shutdown. Your hosting panel, service, container restart policy, or included wrapper script must relaunch the server process after it exits.</div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Custom / One-Off Restart</h3><div class=\"spacer\"></div><span id=\"restartCustomState\" class=\"small\">No one-off restart scheduled.</span></div>\n    <p class=\"small\">Schedule a one-time restart countdown without changing the recurring restart schedule. Example: restart in 10 minutes for maintenance.</p>\n    <div class=\"row\">\n      <div class=\"field\"><label for=\"restartCustomMinutes\">Delay (minutes)</label><input id=\"restartCustomMinutes\" type=\"number\" min=\"1\" max=\"1440\" value=\"10\"></div>\n      <div class=\"field grow\"><label for=\"restartCustomReason\">Reason</label><input id=\"restartCustomReason\" type=\"text\" maxlength=\"240\" value=\"Maintenance\" placeholder=\"Maintenance\"></div>\n      <div class=\"field\" style=\"justify-content:flex-end\"><label>&nbsp;</label><button id=\"restartCustomSchedule\" class=\"warnButton\">Schedule Restart</button></div>\n      <div class=\"field\" style=\"justify-content:flex-end\"><label>&nbsp;</label><button id=\"restartCustomCancel\">Cancel Pending</button></div>\n    </div>\n    <div id=\"restartCustomSummary\" class=\"compactNote\" style=\"margin-top:10px\">This one-off schedule is runtime-only and does not modify the recurring UTC schedule.</div>\n  </div>\n</section>\n\n<section id=\"chatDisplay\"><div class=\"infoBox\">Role name colors are shared with <button type=\"button\" onclick=\"setSection('roles')\">Role Config</button>.</div>\n  <div class=\"pageTitle\"><div><h2>Chat Display</h2><div class=\"subtitle\">Optional server-side chat decorations. General chat is the only formatted channel by default; modded/proximity chat is left untouched unless explicitly enabled.</div></div></div>\n  <div class=\"toolbar\"><button id=\"chatDisplayRefresh\">Refresh</button><button id=\"chatDisplaySave\" class=\"primary\">Save Settings</button><div class=\"spacer\"></div><span id=\"chatDisplayState\" class=\"small\">Not loaded.</span></div>\n  <div id=\"chatDisplayMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Message Formatting</h3><span class=\"small\">Server-side · stock Vintage Story clients</span></div>\n    <div class=\"webMapSettings\">\n      <label for=\"chatMarkdownEnabled\">Markdown</label><div><label><input id=\"chatMarkdownEnabled\" type=\"checkbox\"> Allow inline Markdown in player messages</label><div class=\"small\">Uses the chat scope below. Commands and sender names are never parsed as Markdown.</div></div>\n      <label for=\"chatMarkdownColors\">Text colors</label><div><label><input id=\"chatMarkdownColors\" type=\"checkbox\"> Allow six-digit hex colors</label><div class=\"small\">Off by default. Changes message text only, never the player name or role prefix.</div></div>\n      <label for=\"chatMarkdownLinks\">Clickable links</label><div><label><input id=\"chatMarkdownLinks\" type=\"checkbox\"> Allow HTTP/HTTPS Markdown links</label><div class=\"small\">Off by default. Link destinations and visible message text pass through ChatGuard when installed.</div></div>\n      <label for=\"chatMarkdownRoles\">Allowed role codes</label><div><input id=\"chatMarkdownRoles\" type=\"text\" maxlength=\"10400\" placeholder=\"All roles, or: admin, moderator\"><div class=\"small\">Leave blank for everyone. Otherwise enter exact Vintage Story role codes separated by commas. This restricts all message formatting styles.</div></div>\n    </div>\n    <div class=\"tableWrap\" style=\"margin-top:12px\"><table><thead><tr><th>Style</th><th>Type in chat</th></tr></thead><tbody>\n      <tr><td><strong>Bold</strong></td><td><code>**bold**</code> or <code>__bold__</code></td></tr>\n      <tr><td><i>Italic</i></td><td><code>*italic*</code> or <code>_italic_</code></td></tr>\n      <tr><td><strong><i>Bold italic</i></strong></td><td><code>***both***</code> or <code>___both___</code></td></tr>\n      <tr><td>Inline code (literal text)</td><td><code>`/home base`</code></td></tr>\n      <tr><td>Color (when allowed)</td><td><code>[color=#80C8FF]hello[/color]</code></td></tr>\n      <tr><td>Link (when allowed)</td><td><code>[Community](https://newfiescommunity.com)</code></td></tr>\n      <tr><td>Literal symbols</td><td>Put a backslash before a formatting symbol to keep it literal.</td></tr>\n    </tbody></table></div>\n    <div class=\"compactNote\" style=\"margin-top:10px\">Players can use <code>/chatformat</code> for a private guide showing the current settings. Nested styles are supported, for example <code>**bold with *italic***</code>; enabled colors can also be nested. Unclosed markers remain readable. Underline, strikethrough, images, headings and HTML/VTML input are not supported. No extra client mod is required.</div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><div><h3>Role Name Colors</h3><div class=\"small\">Shared player-name color overrides for Suite Chat Display and Newfie's Player List. Managed here because chat is where the colors are most visible.</div></div><div class=\"spacer\"></div><span class=\"badge low\">Shared presentation</span></div>\n    <div class=\"row\" style=\"align-items:flex-start;gap:16px\">\n      <div class=\"field\" style=\"min-width:240px\"><label class=\"toggleLine\"><input id=\"chatDisplayUseRoleColors\" type=\"checkbox\"> Enable role-based name colors</label><div class=\"small\" style=\"margin-top:6px\">Exact role name/code matches override the normal name color. Unmapped roles keep their Vintage Story color.</div></div>\n      <div class=\"field grow\"><label for=\"chatDisplayRoleColors\">Role colors — one per line as <code>Role=#RRGGBB</code></label><textarea id=\"chatDisplayRoleColors\" rows=\"5\" maxlength=\"4096\" placeholder=\"Supporter=#FEC500&#10;Admin=#EDC26B&#10;Moderator=#7DB8E6\"></textarea><div id=\"chatDisplayRoleColorPreview\" class=\"small\" style=\"margin-top:7px\">No custom role colors configured.</div></div>\n    </div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Player Chat Format</h3><div class=\"spacer\"></div><span class=\"small\">Stored in <code>NewfiesServerEssentialsSuite/NewfiesChatDisplay.json</code></span></div>\n    <div class=\"webMapSettings\">\n      <label for=\"chatDisplayLayout\">Chat layout</label><div><input id=\"chatDisplayLayout\" type=\"text\" maxlength=\"512\" style=\"width:100%\" value=\"{role} {name}: {timestamp} {message}\"><div class=\"small\">Use {role}, {name}, {timestamp}, {message}. Name and message are required once. Role includes brackets; timestamp includes brackets. Their toggles below control visibility. Other text is a literal prefix or suffix. Raw markup is displayed as text.</div>\n      <div class=\"toolbar\" style=\"margin-top:8px\"><button type=\"button\" id=\"chatLayoutDefault\">Classic</button><button type=\"button\" id=\"chatLayoutTimeFirst\">Time first</button><button type=\"button\" id=\"chatLayoutTimeAfterName\">Time after name</button></div><div id=\"chatLayoutError\" class=\"small\" role=\"status\"></div></div>\n      <label for=\"chatDisplayRole\">Role prefix</label><div><label><input id=\"chatDisplayRole\" type=\"checkbox\"> Include role tag in chat layout</label><div class=\"small\">Example: <code>[Admin] Newfie: Hello</code>. Uses the Vintage Story role name, falling back to its role code.</div></div>\n      <label for=\"chatDisplayBoldName\">Player name</label><div><label><input id=\"chatDisplayBoldName\" type=\"checkbox\"> Bold Vintage Story player names</label><div class=\"small\">Applies to normal in-game chat and mirrors the same bold player name into game → Discord chat.</div></div>\n      <label for=\"chatDisplayTimestamp\">Message timestamp</label><div><label><input id=\"chatDisplayTimestamp\" type=\"checkbox\"> Include timestamp in chat layout</label><div class=\"small\">Example: <code>Newfie: [21:35] Hello</code>.</div></div>\n      <label for=\"chatDisplayTimestampFormat\">Timestamp format</label><div><input id=\"chatDisplayTimestampFormat\" type=\"text\" value=\"HH:mm\" maxlength=\"40\"><div class=\"small\">.NET date/time format. Recommended: <code>HH:mm</code> or <code>HH:mm:ss</code>.</div></div>\n      <label for=\"chatDisplayUtc\">Timestamp timezone</label><div><label><input id=\"chatDisplayUtc\" type=\"checkbox\"> Use UTC instead of the server machine's local time</label></div>\n      <label for=\"chatDisplayGeneral\">Chat scope</label><div><label><input id=\"chatDisplayGeneral\" type=\"checkbox\" checked> Format General chat</label><div class=\"small\">Enabled by default. This is the safe compatibility mode for proximity/RP chat mods.</div></div>\n      <label for=\"chatDisplayOtherGroups\">Other chat groups</label><div><label><input id=\"chatDisplayOtherGroups\" type=\"checkbox\"> Format all non-General chat groups</label><div class=\"small\">Off by default. Enabling this can interfere with third-party chat windows that use their own groups.</div></div>\n      <label for=\"chatDisplayAdditionalGroups\">Specific extra groups</label><div><input id=\"chatDisplayAdditionalGroups\" type=\"text\" value=\"\" maxlength=\"240\" placeholder=\"Example: 3, 7\"><div class=\"small\">Optional comma-separated chat group IDs. These groups are formatted even when “all non-General” is off.</div></div>\n    </div>\n    <div id=\"chatDisplayPreview\" class=\"compactNote\" style=\"margin-top:12px\">ExamplePlayer: Hello world</div>\n    <div class=\"infoBox\" style=\"margin-top:12px\"><b>Compatibility default:</b> when formatting decorations are enabled, only General chat is rewritten. All other channels pass through exactly as supplied by Vintage Story or another chat mod unless you opt them in above.<br><br><b>Role name colors:</b> configure exact role → color mappings above. The same overrides are shared with Newfie's Player List; unmapped players keep their existing Vintage Story/mod-provided sender color.</div>\n  </div>\n</section>\n\n<section id=\"console\">\n  <div class=\"pageTitle\"><div><h2>Web Console</h2><div class=\"subtitle\">Color-coded Vintage Story server log mirror with guarded command execution and server-message broadcasting. This is not an operating-system shell.</div></div></div>\n  <div id=\"consoleMetrics\" class=\"grid perfSection\"></div>\n  <div id=\"consoleBlockAlerts\" class=\"consoleAlertStrip perfSection\"></div>\n  <div class=\"card perfSection\">\n    <div class=\"consoleShell\">\n      <div class=\"consoleToolbar\"><button id=\"consoleRefresh\">Refresh</button><button id=\"consoleLive\">Auto Refresh: OFF</button><label class=\"toggleLine\"><input id=\"consoleIncludeChat\" type=\"checkbox\"> Include public game chat</label><button id=\"consoleInputToggle\" class=\"warnButton\">Console Input: OFF</button><span class=\"small\" style=\"margin-left:6px\">Server:</span><button id=\"consoleStartServer\" class=\"primary\" disabled title=\"The dashboard is hosted inside the running server, so it cannot start a stopped process without an external supervisor integration.\">Start</button><button id=\"consoleRestartServer\" class=\"warnButton\" title=\"Gracefully restart the server. The process must be relaunched by Stratum or your external host/supervisor.\">Restart</button><button id=\"consoleStopServer\" class=\"danger\" title=\"Gracefully stop the Vintage Story server after a short safety delay.\">Stop</button><div class=\"spacer\"></div><span id=\"consoleState\" class=\"small\"></span></div>\n      <pre id=\"consoleOutput\" class=\"consoleOutput\">Open this page to load server-main.log.</pre>\n      <div id=\"consoleInputRow\" class=\"consoleInputRow consoleInputOff\"><select id=\"consoleInputMode\" disabled><option value=\"auto\">Auto</option><option value=\"command\">Command</option><option value=\"message\">Message</option></select><input id=\"consoleCommand\" placeholder=\"Auto: /command executes; plain text broadcasts to players\" disabled><button id=\"consoleSend\" class=\"primary\" disabled>Send</button></div>\n    </div>\n    <p class=\"small\" style=\"margin-top:10px\"><b>Server controls:</b> Stop and Restart use the suite's clean shutdown scheduler with a 5-second safety delay. Restart still depends on Stratum or your external host/service/container supervisor to relaunch the process. Start is shown for control-panel symmetry but is disabled while this in-process dashboard is online; once Vintage Story stops, this dashboard stops with it and cannot start the process itself.</p><p class=\"small\" style=\"margin-top:6px\"><b>Input modes:</b> Auto treats a leading <code>/</code> as a Vintage Story command and plain text as a server message. Command mode accepts commands with or without <code>/</code>. Message mode always broadcasts the text to online players. Input starts OFF and automatically expires after 15 minutes. No OS shell access is exposed.</p>\n  </div>\n</section>\n\n<section id=\"webmap\">\n  <div class=\"pageTitle\"><div><h2>Native Web Map</h2><div class=\"subtitle\">Optional public terrain map, live-player privacy controls, waypoints, terrain export controls, and cache status. The master feature can remain available while this map runtime stays fully off.</div></div></div>\n  <div class=\"toolbar\"><button id=\"webMapRefresh\">Refresh Status</button><button id=\"webMapOpen\" class=\"primary\">Open Public Map</button><span id=\"webMapState\" class=\"small\">Not loaded.</span></div>\n  <div id=\"webMapMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Map Host Settings</h3><div class=\"spacer\"></div><span class=\"small\">Stored in <code>NewfiesServerEssentialsSuite/NewfiesWebMap.json</code></span></div>\n    <div class=\"webMapSettings\">\n      <label for=\"webMapEnabled\">Map runtime</label><div><label><input id=\"webMapEnabled\" type=\"checkbox\"> Enable public Web Map</label><div class=\"small\">OFF by default. While off, no map listener, player/date tracking timer, terrain dirty-journal writes, or automatic export work runs. The master feature gate may stay ON so these controls and commands remain available.</div></div>\n      <label for=\"webMapBind\">Bind address</label><input id=\"webMapBind\" type=\"text\" placeholder=\"0.0.0.0\">\n      <label for=\"webMapPort\">Separate map port</label><input id=\"webMapPort\" type=\"number\" min=\"1024\" max=\"65535\" value=\"9466\">\n      <label for=\"webMapTitle\">Public map title</label><input id=\"webMapTitle\" type=\"text\" placeholder=\"Newfie's Server Map\">\n      <label for=\"webMapPublicUrl\">Public map URL (optional)</label><input id=\"webMapPublicUrl\" type=\"text\" placeholder=\"https://map.example.com/\">\n      <label for=\"webMapDashboardUrl\">Admin Panel URL (optional)</label><input id=\"webMapDashboardUrl\" type=\"text\" placeholder=\"https://admin.example.com/\">\n      <label>Public layers</label><div><label><input id=\"webMapShowActivity\" type=\"checkbox\"> BlockLogger activity</label> &nbsp; <label><input id=\"webMapShowPlayers\" type=\"checkbox\"> Players</label> &nbsp; <label><input id=\"webMapShowWaypoints\" type=\"checkbox\" checked> Waypoints</label> &nbsp; <label><input id=\"webMapShowBadBe\" type=\"checkbox\"> Bad block entities</label> &nbsp; <label><input id=\"webMapShowLeaderboards\" type=\"checkbox\" checked> Leaderboards</label><div class=\"small\">Activity and bad block-entity layers remain OFF by default. Enabling Players explicitly publishes live player coordinates. Leaderboards publish only community progression stats such as tracked playtime and optional XSkills levels/XP; they never expose UIDs, Anti-Cheat data, IPs, moderation notes, or private admin fields.</div></div>\n      <label>Player icon refresh</label><div><input id=\"webMapPlayerIconRefreshSeconds\" type=\"number\" min=\"1\" max=\"300\" step=\"1\" value=\"60\" style=\"max-width:100px\"> seconds<div class=\"small\">1–300 seconds. Lower values update positions more often and use more server/network resources. Default: 60 seconds. Applies when the Players layer is enabled.</div></div>\n      <label>Leaderboard settings</label><div class=\"rowActions\"><label><input id=\"webMapLeaderboardShowPlaytime\" type=\"checkbox\" checked> Playtime</label><label><input id=\"webMapLeaderboardShowXSkills\" type=\"checkbox\" checked> XSkills</label><label>Top <input id=\"webMapLeaderboardTopPlayers\" type=\"number\" min=\"3\" max=\"20\" value=\"5\" style=\"max-width:76px\"></label><label>Refresh <input id=\"webMapLeaderboardRefreshSeconds\" type=\"number\" min=\"30\" max=\"300\" step=\"15\" value=\"60\" style=\"max-width:86px\"> sec</label><div class=\"small\" style=\"flex-basis:100%\">XSkills is discovered dynamically through XLib. If it is not installed, the skill cards simply disappear and playtime leaderboards continue to work.</div></div>\n      <label>Player waypoint limits</label><div class=\"rowActions\"><label>Major <input id=\"webMapPlayerMajorWaypointLimit\" type=\"number\" min=\"0\" max=\"100\" value=\"5\" style=\"max-width:90px\"></label><label>Minor <input id=\"webMapPlayerMinorWaypointLimit\" type=\"number\" min=\"0\" max=\"100\" value=\"10\" style=\"max-width:90px\"></label><div class=\"small\" style=\"flex-basis:100%\">Separate per-player limits. 0 disables that waypoint class. Admin-created waypoints do not count.</div></div>\n      <label for=\"webMapMaximumZoomOutSpanBlocks\">Maximum zoom-out span</label><div><input id=\"webMapMaximumZoomOutSpanBlocks\" type=\"number\" min=\"2048\" max=\"100000\" step=\"256\" value=\"50000\" style=\"max-width:140px\"><div class=\"small\">Hard camera limit in blocks across the longer screen axis. Lower values prevent players from zooming out as far.</div></div>\n      <label for=\"webMapDefaultViewSpanBlocks\">Default opening span</label><div><input id=\"webMapDefaultViewSpanBlocks\" type=\"number\" min=\"512\" max=\"100000\" step=\"256\" value=\"8000\" style=\"max-width:140px\"><div class=\"small\">Approximate block span shown when the map first opens without a shared map-position link. This cannot exceed the maximum zoom-out span.</div></div>\n      <label>Startup export safety</label><div><label><input id=\"webMapLockDuringTerrainExport\" type=\"checkbox\" checked> Temporarily password-lock game server during a queued startup export</label><div class=\"small\">There are no automatic terrain exports while the server is running.</div></div>\n      <label>Terrain export layers</label><div><label><input id=\"webMapExportNormalTerrain\" type=\"checkbox\" checked> Normal color</label> &nbsp; <label><input id=\"webMapExportSepiaTerrain\" type=\"checkbox\" checked> Sepia / parchment</label> &nbsp; <label><input id=\"webMapExportTopographicTerrain\" type=\"checkbox\" checked> Topographic</label><div class=\"small\">Choose which terrain styles are actually generated and published. At least one layer must remain enabled. Disabled layers are removed from the published map cache after settings are saved.</div></div>\n      <label for=\"webMapTerrainTileSize\">Terrain tile size</label><input id=\"webMapTerrainTileSize\" type=\"number\" min=\"128\" max=\"512\" step=\"32\" value=\"256\">\n      <label for=\"webMapActivityWindow\">Activity window (minutes)</label><input id=\"webMapActivityWindow\" type=\"number\" min=\"5\" max=\"1440\" value=\"60\">\n      <label for=\"webMapActivityLimit\">Max activity markers</label><input id=\"webMapActivityLimit\" type=\"number\" min=\"25\" max=\"200\" value=\"150\">\n    </div>\n    <div class=\"quickActions\" style=\"margin-top:10px\"><button id=\"webMapSave\" class=\"primary\">Save Map Settings</button><button id=\"webMapTurnOff\" class=\"danger\">Turn Map OFF</button></div>\n    <p id=\"webMapNote\" class=\"small\" style=\"margin-top:8px\"></p>\n    <p class=\"small\">Listener settings and public layers apply immediately. Terrain tile-size changes apply on the next export. Version 1.5.33 requires one Full Rebuild Map to repaint terrain with the corrected v11 hillshade; the existing v10 raw patch sidecars are still used for fast dirty-chunk updates afterward.</p>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Export Schedule</h3><div class=\"spacer\"></div><span id=\"webMapExportScheduleState\" class=\"small\">Not loaded.</span></div>\n    <div class=\"webMapSettings\">\n      <label>Next startup</label><div><label><input id=\"webMapExportTerrainOnStart\" type=\"checkbox\"> Export terrain on next server start</label><div class=\"small\">One-shot startup request. Any successful terrain export automatically turns this back OFF. If a queued startup export fails, it remains queued so the following restart retries.</div></div>\n      <label>Automatic startup interval</label><div><label><input id=\"webMapAutomaticStartupExportEnabled\" type=\"checkbox\"> Automatically export on a server start when the interval is due</label><div class=\"rowActions\" style=\"margin-top:6px\"><span>Every</span><input id=\"webMapAutomaticStartupExportIntervalDays\" type=\"number\" min=\"1\" max=\"365\" value=\"7\" style=\"max-width:100px\"><span>day(s)</span></div><div class=\"small\">This is startup-only: <b>7 days = weekly</b>. If the server stays online past the due date, nothing exports until the next restart. Live updates remain manual.</div></div>\n      <label>Startup export mode</label><div><label><input id=\"webMapUseIncrementalTerrainExport\" type=\"checkbox\" checked> Use incremental exports when possible</label><div class=\"small\">ON patches dirty 32×32 chunks inside existing terrain tiles when the current v11 terrain cache and v10 raw sidecars are valid, and fully renders only new/missing tiles. OFF forces a full terrain rebuild whenever a queued startup export runs.</div></div>\n      <label>Runtime behavior</label><div><b>No automatic live exports.</b><div class=\"small\">Use <b>Update Changed Terrain</b> for routine live updates. <b>Full Rebuild Map</b> is reserved for renderer/cache changes or repair.</div></div>\n    </div>\n    <div class=\"quickActions\" style=\"margin-top:10px\"><button id=\"webMapSaveExportSchedule\" class=\"primary\">Save Export Schedule</button></div>\n    <p class=\"small\" style=\"margin-top:8px\">The one-shot checkbox is cleared after a successful export. Saving this card changes only export scheduling/mode settings and cannot toggle the public Web Map listener. When the map host is OFF, queued startup exports remain paused and live export controls are unavailable. Turning the map OFF also cancels an active live export after the current chunk load finishes.</p>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Terrain Export</h3><div class=\"spacer\"></div><span id=\"webMapTerrainState\" class=\"small\">Not loaded.</span></div>\n    <div id=\"webMapTerrainProgress\" class=\"terrainProgressBox\" aria-live=\"polite\">\n      <div class=\"terrainProgressHead\"><span id=\"webMapTerrainProgressTitle\" class=\"terrainProgressTitle\">Preparing export…</span><span id=\"webMapTerrainProgressPct\" class=\"terrainProgressPct\">0%</span></div>\n      <div class=\"terrainProgressTrack\"><div id=\"webMapTerrainProgressFill\" class=\"terrainProgressFill\"></div></div>\n      <div id=\"webMapTerrainProgressMeta\" class=\"terrainProgressMeta\"></div>\n    </div>\n    <div id=\"webMapTerrainMetrics\" class=\"grid\"></div>\n    <p id=\"webMapTerrainMessage\" class=\"small\" style=\"margin-top:8px\">No terrain status loaded.</p>\n    <div class=\"quickActions\" style=\"margin-top:10px\"><button id=\"webMapUpdateTerrain\" class=\"primary\">Update Changed Terrain</button><button id=\"webMapForceTerrainExport\" class=\"danger\">Full Rebuild Map</button></div>\n    <p class=\"small\"><b>Update Changed Terrain</b> uses the persistent dirty-chunk journal and renders only dirty/new/missing tiles when the cache is compatible. <b>Full Rebuild Map</b> recreates the entire explored terrain cache and should be used after renderer/tile-size changes or for repair. Full rebuilds prefer parallel read-only save-database terrain workers; changed live chunks and compatibility fallbacks use the safe runtime world-loader path.</p>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Admin Waypoints</h3><div class=\"spacer\"></div><span class=\"small\">Persistent per world · public marker data only</span></div>\n    <input id=\"webMapWaypointId\" type=\"hidden\">\n    <div class=\"webMapSettings\">\n      <label for=\"webMapWaypointName\">Name</label><input id=\"webMapWaypointName\" type=\"text\" maxlength=\"80\" placeholder=\"Town, mine, portal, landmark…\">\n      <label>HUD / map coordinates</label><div class=\"rowActions\"><input id=\"webMapWaypointX\" type=\"number\" step=\"any\" placeholder=\"X\" style=\"max-width:150px\"><input id=\"webMapWaypointY\" type=\"number\" step=\"any\" placeholder=\"Y\" style=\"max-width:150px\"><input id=\"webMapWaypointZ\" type=\"number\" step=\"any\" placeholder=\"Z\" style=\"max-width:150px\"><input id=\"webMapWaypointDimension\" type=\"number\" step=\"1\" value=\"0\" title=\"Dimension\" style=\"max-width:110px\"></div>\n      <label for=\"webMapWaypointType\">Waypoint type</label><select id=\"webMapWaypointType\"><option value=\"major\">Major — visible farther out</option><option value=\"minor\">Minor — appears when zoomed in</option></select>\n      <label for=\"webMapWaypointIcon\">Waypoint icon</label><select id=\"webMapWaypointIcon\"><option value=\"pin\">Pin</option><option value=\"base\">Base / home</option><option value=\"settlement\">Settlement</option><option value=\"shop\">Shop / market</option><option value=\"mine\">Mine / cave</option><option value=\"resource\">Resource</option><option value=\"danger\">Danger</option><option value=\"landmark\">Landmark</option><option value=\"road\">Road / route</option><option value=\"farm\">Farm</option></select>\n      <label for=\"webMapWaypointColor\">Marker color</label><input id=\"webMapWaypointColor\" type=\"color\" value=\"#38bdf8\" style=\"width:90px;min-height:38px\">\n      <label for=\"webMapWaypointDescription\">Description</label><input id=\"webMapWaypointDescription\" type=\"text\" maxlength=\"300\" placeholder=\"Optional public description\">\n    </div>\n    <div class=\"quickActions\" style=\"margin-top:10px\"><button id=\"webMapWaypointSave\" class=\"primary\">Add Waypoint</button><button id=\"webMapWaypointClear\">Clear Form</button></div>\n    <p class=\"small\" style=\"margin-top:8px\">Administrator/Owner accounts can create, edit and remove any marker. Players create markers only in-game at their current position with /webmap waypoint add major|minor [icon:&lt;type&gt;] &lt;name&gt; and remove their own with /webmap waypoint remove &lt;name&gt;. Major and minor limits are enforced separately. Major markers remain visible farther out; minor markers appear closer in. Players can use /webmap live off|on|status to control whether their live player data appears publicly. Enter the same relative X/Y/Z shown by the in-game coordinate HUD; the public map translates them to its internal terrain origin automatically.</p>\n    <div class=\"tableWrap dataScroll\" style=\"margin-top:10px\"><table><thead><tr><th>Waypoint</th><th>Position</th><th>Updated</th><th>Actions</th></tr></thead><tbody id=\"webMapWaypointRows\"><tr><td colspan=\"4\" class=\"muted\">No waypoints.</td></tr></tbody></table></div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Runtime Update Cadence</h3><div class=\"spacer\"></div><span class=\"small\">Idle when map runtime is OFF</span></div>\n    <p class=\"small\">When the map runtime is OFF, terrain dirty-journal writes, map listeners, player/date tracking and export hooks remain inactive. When enabled, terrain still has no continuous scanner: block place/break events only mark their 32×32 map chunk dirty in a deduplicated journal. Administrators can queue a one-shot startup export or enable a startup-only interval such as weekly; neither option renders terrain while the server is already running. The public browser feed remains <b>30 seconds</b>. Player coordinates remain at most <b>60 seconds</b>. BlockLogger activity remains at most one query per <b>60 seconds</b> while viewed.</p>\n  </div>\n  <div class=\"split perfSection\">\n    <div class=\"card\"><div class=\"cardHeader\"><h3>Cached Players</h3><div class=\"spacer\"></div><span class=\"small\">60-second snapshot</span></div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Player</th><th>Position</th><th>Dimension</th><th>Ping</th><th>Playtime</th></tr></thead><tbody id=\"webMapPlayerRows\"><tr><td colspan=\"5\" class=\"muted\">No map data loaded.</td></tr></tbody></table></div></div>\n    <div class=\"card\"><div class=\"cardHeader\"><h3>Bad Block-Entity Markers</h3><div class=\"spacer\"></div><span class=\"small\">Existing Log Intelligence cache</span></div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Position</th><th>Block</th><th>Errors</th><th>Actions</th></tr></thead><tbody id=\"webMapBadBeRows\"><tr><td colspan=\"4\" class=\"muted\">No map data loaded.</td></tr></tbody></table></div></div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>BlockLogger Activity Hotspots</h3><div class=\"spacer\"></div><span class=\"small\">Cached; at most one SQLite query/minute while viewed</span></div>\n    <div class=\"tableWrap dataScroll\"><table><thead><tr><th>Position</th><th>Block</th><th>Events</th><th>Actions</th></tr></thead><tbody id=\"webMapActivityRows\"><tr><td colspan=\"4\" class=\"muted\">No map data loaded.</td></tr></tbody></table></div>\n  </div>\n</section>\n\n\n\n<section id=\"communityMotd\">\n  <div class=\"pageTitle\"><div><h2>Community MOTD</h2><div class=\"subtitle\">Configure the optional Newfie's Community MOTD companion from the Suite. The MOTD remains an independent mod; this page uses its companion control bridge when installed.</div></div></div>\n  <div class=\"toolbar\"><button id=\"communityMotdRefresh\">Refresh</button><button id=\"communityMotdReload\">Reload from Disk</button><button id=\"communityMotdResetSeen\">Reset Seen State</button><div class=\"spacer\"></div><span id=\"communityMotdState\" class=\"small\">Checking companion…</span><button id=\"communityMotdWriting\" aria-pressed=\"false\">Writing Mode</button><button id=\"communityMotdDiscard\" disabled>Revert Draft</button><button id=\"communityMotdSave\" class=\"primary\">Save &amp; Apply</button></div>\n  <div id=\"communityMotdMissing\" class=\"warning\" style=\"display:none\"><b>Community MOTD companion is not connected.</b><br>Install the bundled Newfie's Community MOTD 2.1.2 companion on the server. Normal Suite operation is unaffected when it is absent.</div>\n  <div class=\"motdStatusGrid perfSection\" id=\"communityMotdStatus\"></div>\n  <div class=\"motdEditorGrid perfSection\">\n    <div>\n      <div class=\"card\">\n        <div class=\"cardHeader\"><h3>Presentation</h3></div>\n        <div class=\"field\"><label>Title</label><input id=\"communityMotdTitle\" maxlength=\"120\" style=\"width:100%\"></div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Subtitle</label><input id=\"communityMotdSubtitle\" maxlength=\"180\" style=\"width:100%\"></div>\n        <div class=\"row\" style=\"margin-top:8px\"><div class=\"field\"><label>Width</label><input id=\"communityMotdWidth\" type=\"number\" min=\"700\" max=\"1600\"></div><div class=\"field\"><label>Height</label><input id=\"communityMotdHeight\" type=\"number\" min=\"520\" max=\"1000\"></div></div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Accent</label><input id=\"communityMotdAccent\" type=\"color\" value=\"#ffc857\"></div>\n        <label class=\"toggleLine\"><input id=\"communityMotdLogoEnabled\" type=\"checkbox\"> Enable logo</label>\n        <div class=\"field\"><label>Logo source</label><select id=\"communityMotdLogoSource\" style=\"width:100%\"><option value=\"Asset\">Packaged Asset</option><option value=\"ServerFile\">Server-provided PNG</option></select></div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Logo asset</label><input id=\"communityMotdLogoAsset\" style=\"width:100%\"><div class=\"small\">Used when Logo source is Packaged Asset.</div></div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Server logo filename</label><input id=\"communityMotdServerLogoFile\" style=\"width:100%\" placeholder=\"branding/motd-logo.png\"><div class=\"small\">Place this PNG in the server data folder: NewfiesCommunityMOTD/branding/. Default: branding/motd-logo.png. Max 1 MB. It is sent to clients automatically when MOTD opens.</div></div>\n        <div class=\"row\" style=\"margin-top:8px\"><div class=\"field\"><label>Logo width (0 = Auto)</label><input id=\"communityMotdLogoWidth\" type=\"number\" min=\"0\" max=\"400\"></div><div class=\"field\"><label>Logo height (0 = Auto)</label><input id=\"communityMotdLogoHeight\" type=\"number\" min=\"0\" max=\"400\"></div></div>\n        <label class=\"toggleLine\"><input id=\"communityMotdLogoPreserveAspect\" type=\"checkbox\"> Preserve logo aspect ratio</label>\n        <div class=\"small\">Logo is rendered at up to 400 × 400. Set either dimension to 0 for automatic sizing.</div>\n        <label class=\"toggleLine\"><input id=\"communityMotdLinkEnabled\" type=\"checkbox\"> Show link button</label>\n        <div class=\"field\"><label>Link button text</label><input id=\"communityMotdLinkText\" style=\"width:100%\"></div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Link URL</label><input id=\"communityMotdLinkUrl\" style=\"width:100%\"></div>\n        <label class=\"toggleLine\"><input id=\"communityMotdWebMapEnabled\" type=\"checkbox\"> Show Web Map button</label>\n        <div class=\"field\"><label>Web Map button text</label><input id=\"communityMotdWebMapText\" style=\"width:100%\" placeholder=\"Web Map\"></div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Public Web Map URL</label><input id=\"communityMotdWebMapUrl\" style=\"width:100%\" placeholder=\"https://map.example.com\"></div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Footer text</label><input id=\"communityMotdFooter\" style=\"width:100%\"></div>\n      </div>\n      <div class=\"card perfSection\">\n        <div class=\"cardHeader\"><h3>Join Options</h3></div>\n        <div class=\"motdToggleGrid\">\n          <label class=\"toggleLine\"><input id=\"communityMotdEveryJoin\" type=\"checkbox\"> Open on every join</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdOnceSession\" type=\"checkbox\"> Once per session</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdOnceVersion\" type=\"checkbox\"> Once per version</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdDontShow\" type=\"checkbox\"> Allow “don't show again”</label>\n        </div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Version label</label><input id=\"communityMotdVersionLabel\" style=\"width:100%\"></div>\n      </div>\n    </div>\n    <div>\n      <div class=\"card\">\n        <div class=\"cardHeader\"><h3>Hub Tabs &amp; Content</h3><div class=\"spacer\"></div><select id=\"communityMotdFormat\"><option value=\"VTML\">VTML</option><option value=\"Markdown\">Markdown</option></select></div>\n        <div class=\"motdToggleGrid\" style=\"margin-bottom:10px\">\n          <label class=\"toggleLine\"><input id=\"communityMotdAnnouncementsTab\" type=\"checkbox\"> Announcements</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdUpdatesTab\" type=\"checkbox\"> Updates</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdEventsTab\" type=\"checkbox\"> Events</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdRulesTab\" type=\"checkbox\"> Rules</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdServerTab\" type=\"checkbox\"> Server Info</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdCommandsTab\" type=\"checkbox\"> Commands</label>\n        </div>\n        <div class=\"motdContentTabs\" id=\"communityMotdContentTabs\">\n          <button data-motd-content=\"main\" class=\"active\">Main</button><button data-motd-content=\"announcements\">Announcements</button><button data-motd-content=\"updates\">Updates</button><button data-motd-content=\"events\">Events</button><button data-motd-content=\"rules\">Rules</button><button data-motd-content=\"serverinfo\">Server Info</button><button data-motd-content=\"commands\">Commands</button>\n        </div>\n        <div class=\"motdFormatTools\" role=\"toolbar\" aria-label=\"MOTD formatting\">\n          <button data-motd-insert=\"bold\" title=\"Bold (Ctrl/Cmd+B)\"><b>Bold</b></button><button data-motd-insert=\"italic\" title=\"Italic (Ctrl/Cmd+I)\"><i>Italic</i></button><button data-motd-insert=\"heading\">Heading</button><button data-motd-insert=\"bullet\">Bullet</button><button data-motd-insert=\"code\">Code</button><input id=\"communityMotdTextColor\" type=\"color\" value=\"#ffc857\" aria-label=\"Text color\"><button data-motd-insert=\"color\">Color</button>\n          <span id=\"communityMotdEditorFormat\" class=\"small\">VTML</span>\n        </div>\n        <fieldset id=\"motdNewsBuilder\" class=\"uiFieldGroup\" hidden><legend>Write an announcement or update</legend>\n          <div class=\"grid2\"><label class=\"field\">Post title<input id=\"motdPostTitle\" maxlength=\"120\" placeholder=\"Title for this announcement or update\"></label><label class=\"field\">Date<input id=\"motdPostDate\" type=\"date\"></label></div>\n          <label class=\"field\">Post text<textarea id=\"motdPostBody\" rows=\"4\" maxlength=\"5000\" placeholder=\"What changed, who it affects, and anything players need to do.\"></textarea></label>\n          <div class=\"toolbar\"><label class=\"toggleLine\"><input id=\"motdPostImportant\" type=\"checkbox\"> Important</label><div class=\"spacer\"></div><button id=\"motdPostInsert\" type=\"button\">Add to draft</button></div>\n          <p class=\"small\">Adds a formatted post above existing local content. Text is escaped, so markup stays literal. Review the preview, then Save to publish. Discord posts are shown separately, newest first.</p>\n        </fieldset>\n        <div class=\"motdDraftBar\"><span id=\"communityMotdDraftState\" class=\"small\" role=\"status\" aria-live=\"polite\">No changes</span><span id=\"communityMotdEditorCount\" class=\"small\">0 characters · 1 line</span></div>\n        <div class=\"motdComposeWorkspace\">\n          <div><label for=\"communityMotdEditor\" class=\"small\">Content source</label><textarea id=\"communityMotdEditor\" spellcheck=\"false\" aria-label=\"MOTD content source\"></textarea><div class=\"small\" style=\"margin-top:7px\">Main uses the selected VTML/Markdown format. Other tabs always use VTML. Changing format does not convert existing text.</div></div>\n          <div><div class=\"small\" style=\"margin-bottom:6px\">Live preview · approximates game formatting</div><div class=\"motdPreview\" id=\"communityMotdPreview\"><div class=\"motdPreviewTitle\" id=\"communityMotdPreviewTitle\"></div><div class=\"motdPreviewSubtitle\" id=\"communityMotdPreviewSubtitle\"></div><div class=\"motdPreviewBody\" id=\"communityMotdPreviewBody\"></div><div class=\"motdPreviewFooter\" id=\"communityMotdPreviewFooter\"></div></div><div class=\"small\" style=\"margin-top:7px\">Logo assets and live companion feeds appear in game. Preview links do not navigate.</div></div>\n        </div>\n      </div>\n      <div class=\"card perfSection motdFeedsCard\">\n        <div class=\"cardHeader\"><h3>Companion Feeds</h3></div>\n        <div class=\"motdToggleGrid\">\n          <label class=\"toggleLine\"><input id=\"communityMotdDiscordAnnouncements\" type=\"checkbox\"> Discord announcements</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdDiscordUpdates\" type=\"checkbox\"> Discord updates</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdDiscordEvents\" type=\"checkbox\"> Discord events</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdMergeLocal\" type=\"checkbox\"> Merge local + companion feeds</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdSuiteStatus\" type=\"checkbox\"> Include Suite status</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdServerServerInfo\" type=\"checkbox\"> Server details</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdServerWorldInfo\" type=\"checkbox\"> World details</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdServerGameplay\" type=\"checkbox\"> Gameplay settings</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdServerProspecting\" type=\"checkbox\"> Prospecting &amp; resources</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdServerTemporal\" type=\"checkbox\"> Temporal settings</label>\n          <label class=\"toggleLine\"><input id=\"communityMotdServerMods\" type=\"checkbox\"> Installed mod list</label>\n        </div>\n        <div class=\"field\" style=\"margin-top:8px\"><label>Maximum Discord items per feed</label><input id=\"communityMotdDiscordMax\" type=\"number\" min=\"1\" max=\"50\"></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section id=\"customPatches\">\n  <div class=\"pageTitle\"><div><h2>Patch Generator</h2><div class=\"subtitle\">Find a loaded recipe, item or block, choose a change, preview the result and stage it for the next restart.</div></div></div>\n  <div class=\"toolbar\"><button id=\"patchRefresh\">Refresh</button><span id=\"patchStudioState\" class=\"small\">Not loaded.</span></div>\n  <div class=\"card perfSection\" id=\"patchGeneratorCard\">\n    <div class=\"cardHeader\"><h3>1. Choose an asset</h3><span id=\"pgCatalogState\" class=\"small\">Search the server’s loaded assets.</span></div>\n    <div class=\"formGrid\">\n      <div class=\"field\"><label for=\"pgKind\">Category</label><select id=\"pgKind\"><option value=\"recipe\">Recipes</option><option value=\"item\">Items</option><option value=\"block\">Blocks</option></select></div>\n      <div class=\"field grow\"><label for=\"pgSearch\">Search by mod, item or file name</label><input id=\"pgSearch\" maxlength=\"160\" placeholder=\"pickaxe, copper, food, modname…\"></div>\n      <div class=\"field grow\"><label for=\"pgAsset\">Loaded asset</label><select id=\"pgAsset\"><option value=\"\">Choose an asset…</option></select></div>\n      <div class=\"field grow\"><label for=\"pgRoot\">Definition in this file</label><select id=\"pgRoot\"><option value=\"\">Choose an asset first</option></select></div>\n    </div>\n    <h3>2. Set the change</h3>\n    <div class=\"formGrid\">\n      <div class=\"field grow\"><label for=\"pgName\">Patch name</label><input id=\"pgName\" maxlength=\"120\" placeholder=\"Example: cheaper copper pickaxes\"></div>\n      <div class=\"field\"><label for=\"pgPreset\">What to change</label><select id=\"pgPreset\"></select></div>\n      <div class=\"field grow\" id=\"pgFieldWrap\"><label for=\"pgField\">Property in this asset</label><select id=\"pgField\"></select></div>\n      <div class=\"field\" id=\"pgIngredientWrap\"><label for=\"pgIngredient\">Ingredient</label><select id=\"pgIngredient\"></select></div>\n      <div class=\"field\" id=\"pgQuantityWrap\"><label for=\"pgQuantity\">Quantity / stack size</label><input id=\"pgQuantity\" type=\"number\" min=\"1\" max=\"100000\" value=\"1\"></div>\n      <div class=\"field grow\" id=\"pgCodeWrap\"><label for=\"pgCode\">Item / block code</label><input id=\"pgCode\" maxlength=\"300\" placeholder=\"game:stick or mod:item-code\"></div>\n      <div class=\"field\" id=\"pgRecipeEnabledWrap\"><label for=\"pgRecipeEnabled\">Recipe state</label><select id=\"pgRecipeEnabled\"><option value=\"true\">Enabled</option><option value=\"false\">Disabled</option></select></div>\n      <div class=\"field\" id=\"pgOperationWrap\"><label for=\"pgOperation\">Change</label><select id=\"pgOperation\"><option value=\"replace\">Set existing value</option><option value=\"add\">Add / set value</option><option value=\"remove\">Remove property</option></select></div>\n      <div class=\"field grow\" id=\"pgScalarWrap\" hidden><label for=\"pgScalarNumber\">New value</label><input id=\"pgScalarNumber\" type=\"number\" step=\"any\"><input id=\"pgScalarText\" maxlength=\"8000\"><select id=\"pgScalarBoolean\"><option value=\"true\">True / enabled</option><option value=\"false\">False / disabled</option></select></div>\n      <div class=\"field grow\" id=\"pgValueWrap\"><label for=\"pgValue\">New value (JSON)</label><textarea id=\"pgValue\" rows=\"4\" spellcheck=\"false\">null</textarea></div>\n      <div class=\"field\"><label for=\"pgSide\">Apply to</label><select id=\"pgSide\"><option value=\"server\">Server</option><option value=\"\">Server and clients</option><option value=\"client\">Clients</option></select></div>\n      <div class=\"field grow\"><label for=\"pgNotes\">Reason / balance notes</label><input id=\"pgNotes\" maxlength=\"1200\" placeholder=\"What this change fixes\"></div>\n    </div>\n    <div class=\"quickActions\"><button id=\"pgPreview\" class=\"primary\">Generate &amp; Preview</button><button id=\"pgReset\">New Patch</button></div>\n    <div id=\"pgPreviewPanel\" hidden>\n      <h3>3. Review and apply</h3><div id=\"pgTarget\" class=\"small\"></div>\n      <div class=\"grid\"><div><b>Current value</b><pre id=\"pgBefore\" style=\"white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto\"></pre></div><div><b>After patch</b><pre id=\"pgAfter\" style=\"white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto\"></pre></div></div>\n      <p id=\"pgPreviewNote\" class=\"small\"></p>\n      <details><summary>Generated Vintage Story patch JSON</summary><pre id=\"pgJson\" style=\"white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto\"></pre></details>\n      <div class=\"quickActions\"><button id=\"pgSaveDraft\">Save Disabled Draft</button><button id=\"pgApply\" class=\"primary\">Stage for Next Restart</button><button id=\"pgDownload\">Download Patch JSON</button></div>\n    </div>\n    <p class=\"small\">Generated changes are checked against loaded assets. Recipes apply after a server restart. Client item/block changes also need the managed content mod on clients; this generator does not hot-reload game assets.</p>\n  </div>\n  <div class=\"card perfSection\"><div class=\"cardHeader\"><h3>Managed Content Patches</h3><span id=\"pgManagedState\" class=\"small\"></span></div>\n    <div class=\"quickActions\"><button id=\"pgExport\">Download Enabled Patch Pack</button></div>\n    <div class=\"tableWrap dataScroll\" style=\"margin-top:10px\"><table><thead><tr><th>Patch</th><th>Asset</th><th>Operation</th><th>State</th><th>Actions</th></tr></thead><tbody id=\"contentPatchRows\"><tr><td colspan=\"5\" class=\"muted\">Open Patch Studio to load JSON patch definitions.</td></tr></tbody></table></div>\n  </div>\n  <details class=\"perfSection\" id=\"patchAdvancedRuntime\"><summary>Advanced runtime patches and profiler investigations</summary>\n  <div id=\"patchStudioMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Patch Editor</h3><div class=\"spacer\"></div><span id=\"patchEditorState\" class=\"small\">New patch · disabled until you explicitly enable it.</span></div>\n    <input id=\"patchId\" type=\"hidden\">\n    <div class=\"formGrid\">\n      <div class=\"field\"><label for=\"patchName\">Patch name</label><input id=\"patchName\" maxlength=\"120\" placeholder=\"Example: Observe Slow Mod Tick\"></div>\n      <div class=\"field\"><label for=\"patchAssembly\">Assembly</label><input id=\"patchAssembly\" maxlength=\"180\" placeholder=\"ExampleMod\"></div>\n      <div class=\"field grow\"><label for=\"patchType\">Full type name</label><input id=\"patchType\" maxlength=\"300\" placeholder=\"ExampleMod.Server.SomeSystem\"></div>\n      <div class=\"field\"><label for=\"patchMethod\">Method</label><input id=\"patchMethod\" maxlength=\"160\" placeholder=\"OnGameTick\"></div>\n      <div class=\"field grow\"><label for=\"patchParameters\">Parameter types (optional, comma-separated)</label><input id=\"patchParameters\" maxlength=\"800\" placeholder=\"System.Single, Vintagestory.API.Server.IServerPlayer\"></div>\n      <div class=\"field\"><label for=\"patchMode\">Mode</label><select id=\"patchMode\"><option value=\"Observe\">Observe — measure only</option><option value=\"ThrottleVoid\">ThrottleVoid — rate limit a void method</option><option value=\"SkipVoid\">SkipVoid — suppress a void method</option></select></div>\n      <div class=\"field\"><label for=\"patchThrottle\">Throttle interval (ms)</label><input id=\"patchThrottle\" type=\"number\" min=\"50\" max=\"60000\" value=\"250\"></div>\n      <div class=\"field\"><label>Initial state</label><label style=\"text-transform:none;letter-spacing:0\"><input id=\"patchEnabled\" type=\"checkbox\"> Enable immediately when saved</label></div>\n      <div class=\"field grow\"><label for=\"patchNotes\">Notes</label><textarea id=\"patchNotes\" rows=\"3\" maxlength=\"1200\" placeholder=\"Why this patch exists, evidence, rollback notes…\"></textarea></div>\n    </div>\n    <div class=\"quickActions\"><button id=\"patchGenerate\">Generate Safe Template</button><button id=\"patchSave\" class=\"primary\">Save Patch</button><button id=\"patchClear\">Clear Form</button></div>\n    <p class=\"small\"><b>Recommended workflow:</b> start with <b>Observe</b>, confirm the exact method and measured cost, then consider throttling only non-critical <b>void</b> methods. <b>SkipVoid</b> is intentionally high-risk and should be a temporary compatibility workaround. Patch Studio refuses to patch Server Suite itself and refuses skip/throttle recipes for methods that return a value.</p>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Installed Patch Definitions</h3><div class=\"spacer\"></div><span class=\"small\">Runtime changes are reversible without editing mod files.</span></div>\n    <div class=\"tableWrap dataScroll\"><table><thead><tr><th>Patch</th><th>Target</th><th>Mode</th><th>Runtime</th><th>Telemetry</th><th>Actions</th></tr></thead><tbody id=\"patchRows\"><tr><td colspan=\"6\" class=\"muted\">Open Patch Studio to load definitions.</td></tr></tbody></table></div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Suggested Investigation Targets</h3><div class=\"spacer\"></div><span class=\"small\">Profiler evidence only · suggestions do not auto-apply patches.</span></div>\n    <div class=\"tableWrap dataScroll\"><table><thead><tr><th>Target</th><th>Evidence</th><th>Suggested next step</th></tr></thead><tbody id=\"patchSuggestions\"><tr><td colspan=\"3\" class=\"muted\">No profiler-backed suggestions loaded.</td></tr></tbody></table></div>\n  </div>\n  </details>\n  <details class=\"perfSection\" id=\"patchAdvancedJson\"><summary>Advanced JSON patch editor</summary>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>JSON &amp; Recipe Patches</h3><div class=\"spacer\"></div><span id=\"contentPatchState\" class=\"small\">Not loaded.</span></div>\n    <p class=\"small\">Build normal Vintage Story JSON patches for assets and recipes without editing files by hand. Enabled definitions are written to a managed <code>NewfiesSuiteContentPatches</code> content mod and apply on the <b>next server restart</b>.</p>\n    <input id=\"contentPatchId\" type=\"hidden\">\n    <div class=\"formGrid\">\n      <div class=\"field\"><label for=\"contentPatchName\">Patch name</label><input id=\"contentPatchName\" maxlength=\"120\" placeholder=\"Example: Increase bronze pick recipe output\"></div>\n      <div class=\"field\"><label for=\"contentPatchPreset\">Template</label><select id=\"contentPatchPreset\"><option value=\"generic\">Generic JSON patch</option><option value=\"recipe-output-quantity\">Recipe: output quantity</option><option value=\"recipe-ingredient-quantity\">Recipe: ingredient quantity</option><option value=\"recipe-ingredient-code\">Recipe: ingredient code</option><option value=\"recipe-enabled\">Recipe: enable / disable</option></select></div>\n      <div class=\"field grow\"><label for=\"contentPatchFile\">Target asset file</label><input id=\"contentPatchFile\" maxlength=\"400\" placeholder=\"game:recipes/grid/tool/axe.json\"></div>\n      <div class=\"field\"><label for=\"contentPatchOperation\">Operation</label><select id=\"contentPatchOperation\"><option>add</option><option>addMerge</option><option>addEach</option><option>remove</option><option>replace</option><option>move</option><option>copy</option></select></div>\n      <div class=\"field grow\"><label for=\"contentPatchPath\">JSON pointer path</label><input id=\"contentPatchPath\" maxlength=\"500\" placeholder=\"/output/quantity\"></div>\n      <div class=\"field\"><label for=\"contentPatchSide\">Side</label><select id=\"contentPatchSide\"><option value=\"server\">Server</option><option value=\"\">Both / unspecified</option><option value=\"client\">Client</option></select></div>\n      <div class=\"field grow\"><label for=\"contentPatchFromPath\">From path (move/copy only)</label><input id=\"contentPatchFromPath\" maxlength=\"500\" placeholder=\"/old/path\"></div>\n      <div class=\"field\"><label for=\"contentPatchDependsOn\">Only when mod is installed (optional)</label><input id=\"contentPatchDependsOn\" maxlength=\"128\" placeholder=\"someothermodid\"></div>\n      <div class=\"field\"><label>Dependency mode</label><label style=\"text-transform:none;letter-spacing:0\"><input id=\"contentPatchInvertDependency\" type=\"checkbox\"> Invert (apply when mod is absent)</label></div>\n      <div class=\"field grow\"><label for=\"contentPatchValue\">Value (valid JSON)</label><textarea id=\"contentPatchValue\" rows=\"5\" placeholder='1, true, \"game:item\", {\"key\":\"value\"}, or [ ... ]'>null</textarea></div>\n      <div class=\"field\"><label for=\"contentPatchIngredient\">Recipe ingredient key/index</label><input id=\"contentPatchIngredient\" maxlength=\"80\" value=\"A\" placeholder=\"A or 0\"></div>\n      <div class=\"field\"><label for=\"contentPatchQuantity\">Recipe quantity</label><input id=\"contentPatchQuantity\" type=\"number\" min=\"1\" max=\"100000\" value=\"1\"></div>\n      <div class=\"field grow\"><label for=\"contentPatchCode\">Recipe ingredient code</label><input id=\"contentPatchCode\" maxlength=\"300\" value=\"game:stick\" placeholder=\"game:stick\"></div>\n      <div class=\"field\"><label>Recipe enabled template</label><label style=\"text-transform:none;letter-spacing:0\"><input id=\"contentPatchRecipeEnabled\" type=\"checkbox\" checked> Enabled</label></div>\n      <div class=\"field\"><label>Patch state</label><label style=\"text-transform:none;letter-spacing:0\"><input id=\"contentPatchEnabled\" type=\"checkbox\"> Include in generated patch pack</label></div>\n      <div class=\"field grow\"><label for=\"contentPatchNotes\">Notes</label><textarea id=\"contentPatchNotes\" rows=\"3\" maxlength=\"1200\" placeholder=\"What this fixes, mod/version affected, rollback notes…\"></textarea></div>\n    </div>\n    <div class=\"quickActions\"><button id=\"contentPatchGenerate\">Generate Template</button><button id=\"contentPatchSave\" class=\"primary\">Save JSON Patch</button><button id=\"contentPatchClear\">Clear Form</button></div>\n    <p class=\"small\"><b>Recipe helper:</b> select a recipe template, enter the recipe asset path, and use Generate Template. The generic editor remains available for blocks, items, entities, worldgen, recipes, and other patchable JSON assets. Client-side asset changes may also require distributing the generated content mod to clients; server recipe fixes normally use the Server side.</p>\n\n  </div>\n  </details>\n</section>\n\n<section id=\"compatibility\">\n  <div class=\"pageTitle\"><div><h2>Compatibility Center</h2><div class=\"subtitle\">Known coexistence rules, command ownership, loaded-mod/version checks, and manual Harmony patch-overlap inspection.</div></div></div>\n  <div class=\"toolbar\">\n    <button id=\"compatRefresh\">Refresh</button>\n    <button id=\"compatDeep\" class=\"primary\">Run Deep Harmony Scan</button>\n    <label class=\"small\"><input id=\"compatShowIgnored\" type=\"checkbox\"> Show ignored</label>\n    <span id=\"compatState\" class=\"small\">Not loaded.</span>\n  </div>\n  <div id=\"compatMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Compatibility Checks</h3><div class=\"spacer\"></div><span class=\"small\">Evidence-based; warnings are not automatic blame.</span></div>\n    <div class=\"tableWrap dataScroll\"><table><thead><tr><th>State</th><th>Category</th><th>Check</th><th>Detail</th><th>Recommended action</th><th>Control</th></tr></thead><tbody id=\"compatChecks\"><tr><td colspan=\"6\" class=\"muted\">Open this page to run lightweight checks.</td></tr></tbody></table></div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Command Ownership</h3><div class=\"spacer\"></div><span class=\"small\">Prevents the Th3Essentials-style startup collision.</span></div>\n    <div class=\"tableWrap dataScroll\"><table><thead><tr><th>Command</th><th>Owner</th><th>Suite fallback</th><th>Status</th></tr></thead><tbody id=\"compatCommands\"></tbody></table></div>\n  </div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Harmony Patch Overlap</h3><div class=\"spacer\"></div><span id=\"compatHarmonyState\" class=\"small\">Manual deep scan not run.</span></div>\n    <p class=\"small\">Multiple Harmony owners on the same method is overlap evidence, not proof of an incompatibility. This scan is manual because reflection across every patched method is unnecessary during normal live updates.</p>\n    <div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>Severity</th><th>Method</th><th>Owners</th><th>Note</th></tr></thead><tbody id=\"compatHarmony\"><tr><td colspan=\"4\" class=\"muted\">Press Run Deep Harmony Scan when investigating compatibility.</td></tr></tbody></table></div>\n  </div>\n</section>\n\n<section id=\"mods\">\n  <div class=\"pageTitle\"><div><h2>Mod Management</h2><div class=\"subtitle\">Inventory, compatible updates, safe staged replacements, and measured performance evidence.</div></div></div>\n  <div id=\"modsTabs\" class=\"segmented\" style=\"margin-bottom:12px\">\n    <button data-mod-tab=\"installed\" class=\"active\">Installed Mods</button>\n    <button data-mod-tab=\"updates\">Updates <span id=\"modsUpdatesBadge\" class=\"badge medium\" style=\"display:none;margin-left:5px\">0</span></button>\n  </div>\n  <div class=\"toolbar\">\n    <input id=\"modsFilter\" class=\"modsSearch\" placeholder=\"Filter mod id, name, version, file, marker…\">\n    <button id=\"modsRefresh\">Refresh</button>\n    <button id=\"modsCheckUpdates\">Check Updates</button>\n    <button id=\"modsProfile10\" class=\"primary\">Profile 10s</button>\n    <button id=\"modsProfile30\" class=\"primary\">Profile 30s</button>\n    <button id=\"modsCopy\">Copy Mod List</button>\n    <label class=\"small\"><input id=\"modsThirdParty\" type=\"checkbox\"> third-party only</label>\n    <label class=\"small\"><input id=\"modsMeasuredOnly\" type=\"checkbox\"> measured only</label>\n    <span id=\"modsUpdateState\" class=\"small\"></span><span id=\"modsCount\" class=\"small\"></span>\n  </div>\n  <details class=\"helpDisclosure\"><summary>How updates and performance impact work</summary><div id=\"modsProfileState\">Update checks use the official Vintage Story Mod DB. <b>Update</b> stages a compatible ZIP release after validation and backs up the current package outside the Mods folder; a server restart is required. Folder/dev mods remain manual. Run a manual 10s or 30s profile during a slowdown to generate evidence-based performance rankings; mods without attributed evidence remain <b>Not measured</b>.</div></details>\n  <div id=\"modsInstalledPanel\" data-mod-panel=\"installed\">\n    <div class=\"tableWrap dataScrollTall\">\n      <table>\n        <thead><tr><th>#</th><th>Impact</th><th>Mod</th><th>Version</th><th>Update</th><th>Tick share</th><th>Max segment</th><th>≥10ms</th><th>Confidence</th><th>Top profiled part</th><th>Systems</th></tr></thead>\n        <tbody id=\"modsRows\"><tr><td colspan=\"11\" class=\"muted\">Open this page to load the mod inventory.</td></tr></tbody>\n      </table>\n    </div>\n    <div id=\"modPerformanceDetail\" class=\"card\" style=\"display:none;margin-top:12px\"></div>\n  </div>\n  <div id=\"modsUpdatesPanel\" data-mod-panel=\"updates\" style=\"display:none\">\n    <div class=\"card\" style=\"margin-bottom:12px\">\n      <div class=\"cardHeader\"><div><h3>Available Mod Updates</h3><div class=\"small\">Only loaded mods with a compatible newer version reported by the official Vintage Story Mod DB are shown here.</div></div><div class=\"spacer\"></div><span id=\"modsUpdatesSummary\" class=\"small\">Updates not checked yet.</span></div>\n    </div>\n    <div class=\"tableWrap dataScrollTall\">\n      <table>\n        <thead><tr><th>#</th><th>Mod</th><th>Installed</th><th>Available</th><th>Package</th><th>Details</th><th>Actions</th></tr></thead>\n        <tbody id=\"modsUpdateRows\"><tr><td colspan=\"6\" class=\"muted\">Run Check Updates to find compatible updates.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n\n<section id=\"tickDebug\">\n  <div class=\"pageTitle\">\n    <div><h2>Tick Debugging</h2><div class=\"subtitle\">Native Vintage Story tick diagnostics, kept manual and time-limited so troubleshooting does not become permanent server overhead.</div></div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"tickDebugRefresh\">Refresh</button>\n    <button id=\"tickDebugEnabledToggle\" class=\"primary\">Tick Debugging: ON</button>\n    <div class=\"spacer\"></div>\n    <span id=\"tickDebugStatus\" class=\"small\">Native diagnostics not loaded yet.</span>\n  </div>\n\n  <div id=\"tickDebugMetrics\" class=\"tickDebugMetricStrip\"></div>\n\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><div><h3>Native Slow-Tick Capture</h3><div class=\"small\">Uses Vintage Story's native <code>/debug logticks</code>. The Suite automatically switches it back off when the capture window ends.</div></div></div>\n      <div class=\"toolbar\" style=\"padding-left:0;padding-right:0\">\n        <label class=\"small\">Threshold <input id=\"tickDebugThreshold\" type=\"number\" min=\"20\" max=\"1000\" value=\"100\" style=\"width:90px\"> ms</label>\n        <label class=\"small\">Duration <input id=\"tickDebugDuration\" type=\"number\" min=\"5\" max=\"120\" value=\"30\" style=\"width:80px\"> s</label>\n      </div>\n      <div class=\"toolbar\" style=\"padding-left:0;padding-right:0\">\n        <button id=\"tickDebugStart\" class=\"primary\">Capture Slow Ticks</button>\n        <button id=\"tickDebugIncident\" class=\"primary\">Capture Incident + Profile</button>\n        <button id=\"tickDebugEnableDiagnostics\">Enable Lightweight Diagnostics</button>\n        <button id=\"tickDebugStop\">Stop Capture</button>\n      </div>\n      <div id=\"tickDebugState\" class=\"small\">No native slow-tick capture is running.</div>\n      <div id=\"tickDebugProfileState\" class=\"small\" style=\"margin-top:6px\">Engine profiler idle.</div>\n      <div class=\"infoBox\" style=\"margin-top:10px\">A normal troubleshooting starting point is <b>100ms</b>. Incident Capture runs the native slow-tick logger and the existing engine FrameProfiler together for the same bounded window.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><div><h3>Native Tick Handler Inspector</h3><div class=\"small\">Ask the game engine which block/entity tick handlers and delayed callbacks are registered.</div></div></div>\n      <div class=\"toolbar\" style=\"padding-left:0;padding-right:0\">\n        <button id=\"tickDebugHandlers\">Tick Handler Summary</button>\n        <button id=\"tickDebugMainThread\">Main Thread State</button>\n      </div>\n      <div class=\"toolbar\" style=\"padding-left:0;padding-right:0\">\n        <select id=\"tickDebugDumpType\">\n          <option value=\"dump-gtentity\">Game-tick entities</option>\n          <option value=\"dump-gtblock\">Game-tick blocks</option>\n          <option value=\"dump-dcentity\">Delayed entity callbacks</option>\n          <option value=\"dump-dcblock\">Delayed block callbacks</option>\n          <option value=\"dump-sdcblock\">Scheduled block callbacks</option>\n        </select>\n        <button id=\"tickDebugDump\">Dump Selected List</button>\n      </div>\n      <div class=\"small\">Detailed dumps are written by Vintage Story to its native debug log. Use them when the summary points to an unusually large handler family.</div>\n    </div>\n  </div>\n\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Last Native Debug Result</h3><div class=\"spacer\"></div><button id=\"tickDebugClearAction\" class=\"miniClear\" title=\"Clear the retained native debug command output\">Clear</button></div>\n      <pre id=\"tickDebugActionOutput\" style=\"white-space:pre-wrap;max-height:360px;overflow:auto\">No native debug command has been run from this page yet.</pre>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Last Slow-Tick Log Capture</h3><div class=\"spacer\"></div><button id=\"tickDebugClearSlow\" class=\"miniClear\" title=\"Clear the retained slow-tick excerpt and incident summary\">Clear</button></div>\n      <div id=\"tickDebugLogPath\" class=\"small\" style=\"margin-bottom:8px\">Current server log path will appear when a capture starts.</div>\n      <pre id=\"tickDebugSlowOutput\" style=\"white-space:pre-wrap;max-height:360px;overflow:auto\">No slow-tick capture has completed yet.</pre>\n    </div>\n  </div>\n\n  <div id=\"tickDebugModAttribution\" class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\"><div><h3>Likely Mod Attribution</h3><div class=\"small\">Based only on measured engine-profiler markers. This reports where tick time was attributed, not automatic proof of a mod defect.</div></div></div>\n    <div class=\"empty\">Run Incident Capture or wait for an automatic lag-attribution burst to collect mod timing evidence.</div>\n  </div>\n\n  <div class=\"infoBox\"><b>How this page is different from Performance Center:</b> Performance Center remains the always-on, low-overhead view. Tick Debugging is for short investigations using the game's native diagnostics. Native slow-tick logging remains time-limited; automatic mod-attribution profiling only uses short cooldown-limited bursts after major stalls.</div>\n</section>\n\n<div id=\"lagIncidentBackdrop\" aria-hidden=\"true\"></div>\n<aside id=\"lagIncidentDrawer\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"lagIncidentTitle\" aria-hidden=\"true\">\n  <div class=\"lagDrawerHeader\">\n    <div class=\"cardHeader\">\n      <div><h3 id=\"lagIncidentTitle\">Lag Spike Investigation</h3><div id=\"lagIncidentSubtitle\" class=\"small\">Click a yellow/orange or red lag marker to inspect the archived black-box evidence.</div></div>\n      <div class=\"spacer\"></div>\n      <button id=\"lagIncidentCopy\">Copy Summary</button>\n      <button id=\"lagIncidentOpenTick\">Tick Debugger</button>\n      <button id=\"lagIncidentClose\">Close</button>\n    </div>\n  </div>\n  <div id=\"lagIncidentDrawerBody\"><div class=\"empty\">No lag spike selected.</div></div>\n</aside>\n\n<section id=\"profiler\">\n  <div class=\"pageTitle\">\n    <div><h2>Profiler & Lag Diagnostics</h2><div class=\"subtitle\">Correlate slow-server evidence continuously, then use manual engine profiles for exact tick/mod attribution.</div></div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"profRefresh\">Refresh</button>\n    <button id=\"profEnable\">Enable Diagnostics</button>\n    <button id=\"profDisable\">Disable Diagnostics</button>\n    <button id=\"prof10\" class=\"primary\">Profile 10s</button>\n    <button id=\"prof30\" class=\"primary\">Profile 30s</button>\n    <button id=\"profCopy\">Copy Diagnosis</button>\n    <button id=\"profExport\">Export Snapshot</button>\n    <button id=\"profExportFull\">Export Full Report</button>\n    <button id=\"profSaveBaseline\">Save Baseline</button>\n    <button id=\"profClearBaseline\">Clear Baseline</button>\n    <div class=\"spacer\"></div>\n    <span class=\"small\">Graph range</span>\n    <div id=\"rangeButtons\" class=\"segmented\">\n      <button data-range=\"60\">1m</button>\n      <button data-range=\"300\" class=\"active\">5m</button>\n      <button data-range=\"900\">15m</button>\n      <button data-range=\"1800\">30m</button>\n    </div>\n  </div>\n\n  <div class=\"toolbar\">\n    <span id=\"profState\" class=\"small\">No profiler snapshot loaded.</span>\n    <div class=\"spacer\"></div>\n    <span class=\"small\">Hover any graph to inspect the same moment across all six charts. Red/orange markers on Main-thread delay are correlated Lag Events.</span>\n  </div>\n\n  <div id=\"profDiagnosis\" class=\"diagnosis\">\n    <div class=\"card diagnosisMain\"><div class=\"state muted\">Not loaded</div><div class=\"small\">No diagnostic summary loaded.</div></div>\n  </div>\n\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Smart Findings</h3><div class=\"spacer\"></div><span id=\"smartFindingCount\" class=\"small\"></span></div>\n      <div id=\"smartSignals\" class=\"smartGrid\"><div class=\"empty\">Waiting for diagnostics.</div></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Recommended Next Steps</h3></div>\n      <div id=\"smartRecommendations\" class=\"small\">No recommendations yet.</div>\n    </div>\n  </div>\n\n  <div class=\"grid\" style=\"margin-bottom:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Adaptive Server Baseline</h3><div class=\"spacer\"></div><span id=\"baselineSamples\" class=\"small\"></span></div>\n      <div id=\"adaptiveBaseline\" class=\"small\">Waiting for enough samples to learn the server baseline.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Trend / Leak Watch</h3><div class=\"spacer\"></div><span class=\"small\">10-minute direction</span></div>\n      <div id=\"smartTrends\" class=\"small\">No meaningful upward trend detected.</div>\n    </div>\n  </div>\n\n  <div id=\"baselineCompareCard\" class=\"card\" style=\"margin-bottom:12px\">\n    <div class=\"cardHeader\"><h3>Saved Baseline Comparison</h3><div class=\"spacer\"></div><span id=\"baselineSavedAt\" class=\"small\"></span></div>\n    <div id=\"baselineCompare\" class=\"small\">Press Save Baseline during a known-good period, then compare later lag captures against it.</div>\n  </div>\n\n  <div class=\"chartGrid\">\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>Main-thread delay</h3><div class=\"spacer\"></div><div class=\"chartLegend\"><span class=\"legendMark\"></span>scheduler lateness</div></div>\n      <div id=\"metaDelay\" class=\"chartMeta\"></div>\n      <div class=\"chartWrap\"><canvas class=\"healthChart\" id=\"chartDelay\"></canvas><div class=\"chartTip\" id=\"tipDelay\"></div></div>\n    </div>\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>CPU</h3></div>\n      <div id=\"metaCpu\" class=\"chartMeta\"></div>\n      <div class=\"chartWrap\"><canvas class=\"healthChart\" id=\"chartCpu\"></canvas><div class=\"chartTip\" id=\"tipCpu\"></div></div>\n    </div>\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>Managed heap</h3></div>\n      <div id=\"metaHeap\" class=\"chartMeta\"></div>\n      <div class=\"chartWrap\"><canvas class=\"healthChart\" id=\"chartHeap\"></canvas><div class=\"chartTip\" id=\"tipHeap\"></div></div>\n    </div>\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>Loaded entities</h3></div>\n      <div id=\"metaEntities\" class=\"chartMeta\"></div>\n      <div class=\"chartWrap\"><canvas class=\"healthChart\" id=\"chartEntities\"></canvas><div class=\"chartTip\" id=\"tipEntities\"></div></div>\n    </div>\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>BlockLogger queue</h3></div>\n      <div id=\"metaQueue\" class=\"chartMeta\"></div>\n      <div class=\"chartWrap\"><canvas class=\"healthChart\" id=\"chartQueue\"></canvas><div class=\"chartTip\" id=\"tipQueue\"></div></div>\n    </div>\n    <div class=\"card chartCard\">\n      <div class=\"cardHeader\"><h3>BlockLogger writer</h3></div>\n      <div id=\"metaWriter\" class=\"chartMeta\"></div>\n      <div class=\"chartWrap\"><canvas class=\"healthChart\" id=\"chartWriter\"></canvas><div class=\"chartTip\" id=\"tipWriter\"></div></div>\n    </div>\n  </div>\n\n  <div class=\"grid\" style=\"margin-top:12px\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Top Attributed Mods</h3><div class=\"spacer\"></div><span class=\"small\">last manual profile</span><button id=\"profClearMods\" class=\"miniClear\" title=\"Clear retained mod-attribution results from the latest profile\">Clear</button></div>\n      <div class=\"tableWrap\"><table><thead><tr><th>Mod</th><th>Total</th><th>Max</th><th>≥10ms</th><th>Share</th><th>Confidence</th></tr></thead><tbody id=\"profMods\"></tbody></table></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Worst Profiled Ticks</h3><div class=\"spacer\"></div><span class=\"small\">last manual profile</span><button id=\"profClearTicks\" class=\"miniClear\" title=\"Clear retained worst-tick summaries from the latest profile\">Clear</button></div>\n      <div class=\"tableWrap\"><table><thead><tr><th>Tick</th><th>Leading causes</th></tr></thead><tbody id=\"profTicks\"></tbody></table></div>\n    </div>\n  </div>\n\n  <div class=\"card\" style=\"margin-top:12px\">\n    <div class=\"cardHeader\"><h3>Grouped Lag Incidents</h3><div class=\"spacer\"></div><span id=\"incidentGroupCount\" class=\"small\"></span><button id=\"profClearLagGroups\" class=\"miniClear\" title=\"Clear retained Profiler/Performance lag history and archived lag markers\">Clear</button></div>\n    <p class=\"small\">Adjacent lag samples are grouped into one incident and classified by the strongest evidence. Click a row to open its archived black-box evidence; the synchronized graph crosshair follows the incident.</p>\n    <div class=\"tableWrap\"><table>\n      <thead><tr><th>Start</th><th>Duration</th><th>Severity</th><th>Likely area</th><th>Likely mod</th><th>Confidence</th><th>Worst delay</th><th>CPU</th><th>Gen2</th><th>Next action</th></tr></thead>\n      <tbody id=\"incidentGroups\"></tbody>\n    </table></div>\n  </div>\n\n  <div class=\"card\" style=\"margin-top:12px\">\n    <div class=\"cardHeader\"><h3>Correlated Lag Samples</h3><div class=\"spacer\"></div><span id=\"incidentCount\" class=\"small\"></span><button id=\"profClearLagSamples\" class=\"miniClear\" title=\"Clear retained Profiler/Performance lag history and archived lag markers\">Clear</button></div>\n    <p class=\"small\">Evidence correlations are not automatic blame. Use Profile 10s/30s when you need exact engine tick timing and mod ownership.</p>\n    <div class=\"tableWrap\"><table>\n      <thead><tr><th>Time</th><th>Severity</th><th>Delay</th><th>CPU</th><th>GC 0/1/2</th><th>BL queue/writer</th><th>Entities Δ</th><th>Chunks Δ</th><th>Evidence</th></tr></thead>\n      <tbody id=\"profIncidents\"></tbody>\n    </table></div>\n    <div id=\"profIncidentEvidence\" class=\"card\" style=\"display:none;margin-top:10px\"></div>\n  </div>\n</section>\n\n<section id=\"anticheat\">\n  <div class=\"pageTitle\"><div><h2>Anti-Cheat</h2><div class=\"subtitle\">Client integrity, mod policy, enforcement, and online player evidence in one place.</div></div></div>\n  <div class=\"toolbar\"><button id=\"acRefresh\">Refresh</button><div class=\"spacer\"></div><span id=\"acState\" class=\"small\">Not loaded.</span></div>\n  <div class=\"sectionTabs\" id=\"acTabs\" role=\"tablist\" aria-label=\"Anti-Cheat sections\">\n    <button data-ac-tab=\"overview\" class=\"active\">Overview</button>\n    <button data-ac-tab=\"players\">Players</button>\n    <button data-ac-tab=\"clientmods\">Client Mods</button>\n    <button data-ac-tab=\"oreshield\">Ore Shield</button>\n    <button data-ac-tab=\"packet\">Packet Protection</button>\n    <button data-ac-tab=\"history\">Reports / History</button>\n    <button data-ac-tab=\"policy\">Mod Policy</button>\n    <button data-ac-tab=\"enforcement\">Enforcement</button>\n    <button data-ac-tab=\"integrity\">Client Integrity</button>\n  </div>\n\n  <div class=\"tabPanel active\" data-ac-panel=\"overview\">\n    <div id=\"acHero\" class=\"summaryHero\"><div class=\"heroIcon\">AC</div><div><div class=\"heroTitle\">Loading protection state…</div><div class=\"heroText\">Anti-Cheat status will appear here.</div></div></div>\n    <div class=\"card perfSection\" id=\"acModuleCard\"><div class=\"cardHeader\"><h3>Anti-Cheat Module</h3><div class=\"spacer\"></div><span id=\"acModuleState\" class=\"small\">Loading…</span></div><div class=\"formRow\"><label class=\"toggleLine\"><input id=\"acModuleEnabled\" type=\"checkbox\"> Enable Anti-Cheat</label><button id=\"acModuleSave\" class=\"primary\">Save Module State</button></div><div class=\"compactNote\" style=\"margin-top:8px\"><b>Server-owner add-on:</b> when the AntiCheat companion is installed on the server, protection defaults on and the same companion is required on clients. This switch disables live Anti-Cheat enforcement/scanning only; the installed mod remains a required client dependency. Server Essentials and stored Anti-Cheat reports remain available.</div></div>\n    <div class=\"card perfSection\" id=\"acClientSettingsCard\">\n      <div class=\"cardHeader\"><div><h3>Client Scan & Timeout Settings</h3><div class=\"small\">Tune startup tolerance for slower PCs/connections without weakening exact client-mod verification.</div></div><div class=\"spacer\"></div><span id=\"acClientSettingsState\" class=\"small\">Loading policy…</span></div>\n      <div class=\"grid\" style=\"margin-top:10px\">\n        <div class=\"card\" style=\"background:#10171d\">\n          <div class=\"cardHeader\"><h3>Client Requirements</h3></div>\n          <label class=\"small\"><input id=\"acRequireClient\" type=\"checkbox\"> Require Client Integrity / Anti-Cheat companion</label><br>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acClientModDbVerification\" type=\"checkbox\"> Verify reported client mods against the official Vintage Story ModDB</label>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acStrictClientModDbEnforcement\" type=\"checkbox\"> Kick when any reported third-party mod lacks an exact trusted database match</label>\n          <div class=\"compactNote\" style=\"margin-top:8px\"><b>Strict database mode:</b> every reported third-party client mod must exactly match the server-loaded baseline, an administrator-approved custom fingerprint, or an official same-version ModDB fingerprint. Unknown, unavailable, or mismatched releases are rejected. Enabling strict mode forces ModDB verification on.</div>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acRequireCurrentClientRelease\" type=\"checkbox\"> Require clients to match the server-installed Client Integrity version</label>\n          <div id=\"acServerVersionRequirementNote\" class=\"compactNote\" style=\"margin-top:8px\"><b>Dynamic version match:</b> when enabled, every client must report the same semantic Client Integrity version that is installed on this server. Upgrading the server companion automatically changes the required client version; no Suite update is needed. Version mismatch is a compatibility failure, not cheat evidence.</div>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acRequireHardenedCapabilities\" type=\"checkbox\"> Require hardened report + heartbeat capabilities</label>\n          <div class=\"compactNote\" style=\"margin-top:8px\"><b>Transport hardening:</b> requires report-hash v2 and challenge-bound anti-replay heartbeats. This can be enforced independently from the exact client release requirement.</div>\n        </div>\n        <div class=\"card\" style=\"background:#10171d\">\n          <div class=\"cardHeader\"><h3>Connection / Heartbeat Tolerance</h3></div>\n          <div class=\"formGrid\">\n            <label>Client hello grace (seconds)<input id=\"acClientHelloGrace\" type=\"number\" min=\"15\" max=\"300\" step=\"1\"></label>\n            <label>Missing-client recovery delay (seconds)<input id=\"acClientHelloDisconnectDelay\" type=\"number\" min=\"10\" max=\"300\" step=\"1\"></label>\n            <label>Heartbeat timeout (seconds)<input id=\"acHeartbeatTimeout\" type=\"number\" min=\"30\" max=\"900\" step=\"1\"></label>\n            <label>Routine rescan timeout (seconds)<input id=\"acRoutineChallengeTimeout\" type=\"number\" min=\"10\" max=\"120\" step=\"1\"></label>\n          </div>\n          <div class=\"compactNote\" style=\"margin-top:8px\">The hello grace is how long a newly joined client has to establish the Anti-Cheat channel. The recovery delay gives a late client another chance before disconnect. Heartbeat timeout controls stale-client recovery after connection.</div>\n        </div>\n        <div class=\"card\" style=\"background:#10171d\">\n          <div class=\"cardHeader\"><h3>Startup Deep Scan</h3></div>\n          <div class=\"formGrid\">\n            <label>Initial startup scan window (seconds)<input id=\"acStartupChallengeTimeout\" type=\"number\" min=\"60\" max=\"900\" step=\"1\"></label>\n            <label>Heartbeat extension (seconds)<input id=\"acStartupHeartbeatExtension\" type=\"number\" min=\"30\" max=\"300\" step=\"1\"></label>\n            <label>Startup hard limit (seconds)<input id=\"acStartupHardLimit\" type=\"number\" min=\"60\" max=\"1800\" step=\"1\"></label>\n          </div>\n          <div class=\"compactNote\" style=\"margin-top:8px\">A responsive client that is still hashing mods can keep the same startup challenge alive with heartbeats, up to the hard limit. This avoids kicking slow disks/CPUs while still preventing a client from stalling forever.</div>\n        </div>\n        <div class=\"card\" style=\"background:#10171d\">\n          <div class=\"cardHeader\"><h3>Rescans</h3></div>\n          <div class=\"formGrid\"><label>Scheduled rescan interval (minutes)<input id=\"acRescanMinutes\" type=\"number\" min=\"1\" max=\"1440\" step=\"1\"></label><label>Runtime-change cooldown (seconds)<input id=\"acRuntimeChangeCooldown\" type=\"number\" min=\"10\" max=\"300\" step=\"1\"></label></div>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acRuntimeRescanOnChange\" type=\"checkbox\"> Rescan when the client runtime surface changes</label>\n        </div>\n        <div class=\"card\" style=\"background:#10171d\">\n          <div class=\"cardHeader\"><h3>Startup Integrity Gate / Quarantine</h3></div>\n          <label class=\"small\"><input id=\"acStartupGateEnabled\" type=\"checkbox\"> Enable startup integrity gate</label>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acStartupGateBlockInteractions\" type=\"checkbox\"> Block world interactions while startup verification is pending</label>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acStartupGateRequireClean\" type=\"checkbox\"> Require a clean startup verdict before release</label>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acStartupGateDisconnectFailure\" type=\"checkbox\"> Disconnect if startup verification fails or never completes</label>\n          <div class=\"formGrid\" style=\"margin-top:10px\"><label>Blocked-action notice cooldown (seconds)<input id=\"acStartupGateNoticeCooldown\" type=\"number\" min=\"2\" max=\"30\" step=\"1\"></label></div>\n          <div class=\"compactNote\" style=\"margin-top:8px\"><b>Quarantine behavior:</b> interaction blocking now defaults <b>OFF</b>. The integrity scan still runs normally, but joining players can immediately break, place, use blocks, and interact with entities. Enable this only if you intentionally want players quarantined until startup verification releases them.</div>\n        </div>\n      </div>\n      <div class=\"toolbar\" style=\"margin-top:10px\"><button id=\"acClientSettingsSave\" class=\"primary\">Save Client Scan Settings</button><div class=\"spacer\"></div><span class=\"small\">Defaults are intentionally more tolerant than the earlier timing profile: 90s hello + 60s recovery, 180s heartbeat, 300s startup window, 900s hard limit.</span></div>\n    </div>\n    <div id=\"acMetrics\" class=\"grid perfSection\"></div>\n    <div id=\"acCoverage\" class=\"card perfSection\"><div class=\"cardHeader\"><h3>Coverage & Freshness</h3><div class=\"spacer\"></div><span class=\"small\">Live quality of the evidence feeding the Anti-Cheat decisions.</span></div><div id=\"acCoverageGrid\" class=\"grid\"></div></div>\n    <div class=\"card perfSection\"><div class=\"cardHeader\"><div><h3>Anti-Cheat Connection Timeline</h3><div class=\"small\">Handshake, heartbeat and startup-scan stages remain visible after disconnects, with failures highlighted in sequence.</div></div><div class=\"spacer\"></div><span id=\"acConnectionDiagnosticsState\" class=\"small\">No diagnostics yet.</span></div><div id=\"acConnectionTimeline\" class=\"acTimeline acTimelineCompact\"><div class=\"muted\" style=\"padding:10px 30px\">No recent client connection diagnostics.</div></div><details class=\"helpDisclosure\"><summary>Detailed diagnostic table</summary><div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Time</th><th>Player</th><th>Stage</th><th>Event</th><th>Action</th><th>Detail</th></tr></thead><tbody id=\"acConnectionDiagnosticsRows\"><tr><td colspan=\"6\" class=\"muted\">No recent client connection diagnostics.</td></tr></tbody></table></div></div></details></div>\n    <div id=\"acServerCompanion\" class=\"card providerCard missing perfSection\"><div class=\"small\">Server AntiCheat add-on</div><div style=\"font-size:17px;font-weight:800\">Newfies AntiCheat Client</div><div><b>CHECKING INSTALLATION…</b></div><div class=\"small\" style=\"margin-top:5px\">The Suite owns the server Anti-Cheat backend. Installing this add-on on the server requires the same package on clients. The protection switch controls enforcement, not the client dependency.</div></div>\n    <div class=\"card perfSection\"><div class=\"cardHeader\"><h3>Attention Queue</h3><div class=\"spacer\"></div><span class=\"small\">Review/suspicious/missing clients first; click a player for evidence.</span></div><div class=\"tableWrap\"><table><thead><tr><th>Player</th><th>Status</th><th>Risk</th><th>Findings</th><th>Runtime changes</th><th>Client</th></tr></thead><tbody id=\"acAttentionRows\"><tr><td colspan=\"6\" class=\"muted\">No anti-cheat snapshot loaded.</td></tr></tbody></table></div></div>\n    <details class=\"helpDisclosure\"><summary>How the protection model works</summary><div><b>Server-owned verification</b> validates one-time challenges, client heartbeats, required/forbidden mod policy, scan timing, build fingerprints, runtime consistency, and cross-checks between reported mods and loaded assemblies. When Anti-Cheat enforcement is enabled, client telemetry is supporting evidence; PacketGuard independently validates server-observed movement, block reach, and connected mining behavior. When the module is disabled, both client scanning and PacketGuard enforcement stop.</div></details>\n    <div class=\"grid perfSection\">\n      <div class=\"card\"><div class=\"cardHeader\"><h3>Recommended workflow</h3></div><div class=\"compactNote\">1. Keep approved Client Integrity builds enrolled. 2. Resolve blacklist fingerprints. 3. Review suspicious players before enabling harsh automatic consequences. 4. Use exact fingerprint findings more aggressively than fuzzy similarity findings.</div><div class=\"quickActions\"><button data-ac-jump=\"players\">Review Players</button><button data-ac-jump=\"policy\">Mod Policy</button><button data-ac-jump=\"enforcement\">Enforcement</button></div></div>\n      <div class=\"card\"><div class=\"cardHeader\"><h3>Detection strength</h3></div><div class=\"compactNote\"><b>Strong:</b> exact forbidden mod/content/assembly fingerprints, unapproved client build, protocol/integrity failures.<br><b>Supporting:</b> structural similarity and other fuzzy evidence. Similarity should generally log/freeze for review rather than automatically long-ban by itself.</div></div>\n    </div>\n  </div>\n\n  <div class=\"tabPanel\" data-ac-panel=\"players\">\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Online Player State</h3><div class=\"spacer\"></div><span class=\"small\">Filter the live integrity posture, then open a player for an evidence-first investigation view.</span></div>\n      <div class=\"acPlayerFilterBar\"><div class=\"field\"><label>Search</label><input id=\"acPlayerSearch\" placeholder=\"Player, platform, client…\"></div><div class=\"field\"><label>Status</label><select id=\"acPlayerFilter\"><option value=\"all\">All players</option><option value=\"attention\">Needs attention</option><option value=\"suspicious\">Suspicious</option><option value=\"review\">Review</option><option value=\"pending\">Pending / missing</option><option value=\"clean\">Clean</option></select></div><div id=\"acPlayerCount\" class=\"acPlayerCount\">0 players</div></div>\n      <div class=\"tableWrap dataScrollTall\"><table><thead><tr><th><button class=\"acSortHead\" data-ac-sort=\"player\">Player <span class=\"acSortArrow\">↕</span></button></th><th>Status</th><th><button class=\"acSortHead active\" data-ac-sort=\"risk\">Risk <span class=\"acSortArrow\">↓</span></button></th><th>Startup</th><th>Client</th><th>Platform</th><th><button class=\"acSortHead\" data-ac-sort=\"mods\">Mods <span class=\"acSortArrow\">↕</span></button></th><th><button class=\"acSortHead\" data-ac-sort=\"evidence\" title=\"Sort by total evidence, then strong/server-authoritative findings\">Evidence <span class=\"acSortArrow\">↕</span></button></th><th><button class=\"acSortHead\" data-ac-sort=\"scan\">Last scan <span class=\"acSortArrow\">↕</span></button></th><th>Action</th></tr></thead><tbody id=\"acRows\"><tr><td colspan=\"10\" class=\"muted\">Open this page to load anti-cheat sessions.</td></tr></tbody></table></div>\n    </div>\n    <div id=\"acDetailBackdrop\" class=\"acDrawerBackdrop\" aria-hidden=\"true\"></div>\n    <div id=\"acDetail\" class=\"card acPlayerDrawer\" style=\"display:none\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"acDetailTitle\">\n      <div class=\"cardHeader acDrawerHeader\">\n        <div class=\"acDrawerHeaderLine\"><div><h3 id=\"acDetailTitle\">Player Detail</h3><div class=\"small\">Live investigation drawer · player-specific connection, integrity and mod evidence</div></div><div class=\"spacer\"></div><button id=\"acDetailCopyUid\">Copy UID</button><button id=\"acDetailRefresh\">Refresh</button><button id=\"acDetailHistory\">Full History</button><button id=\"acDetailRescan\" class=\"primary\">Rescan</button><button id=\"acDetailClose\">Close</button></div>\n        <div class=\"acDrawerPosture\"><div class=\"acDrawerPostureLabel\">Pinned player posture</div><div id=\"acDrawerQuickBar\" class=\"acDrawerQuickBar\"></div></div>\n        <div class=\"acDrawerTabs\" role=\"tablist\" aria-label=\"Player detail tabs\">\n          <button class=\"acDrawerTab active\" role=\"tab\" aria-selected=\"true\" aria-controls=\"acDrawerTabOverview\" data-ac-drawer-tab=\"overview\">Overview</button>\n          <button class=\"acDrawerTab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"acDrawerTabAntiCheat\" data-ac-drawer-tab=\"anticheat\">Anti-Cheat <span id=\"acTabAntiCheatCount\" class=\"acDrawerTabCount\">0</span></button>\n          <button class=\"acDrawerTab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"acDrawerTabMods\" data-ac-drawer-tab=\"mods\">Mods <span id=\"acTabModsCount\" class=\"acDrawerTabCount\">0</span></button>\n          <button class=\"acDrawerTab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"acDrawerTabInventory\" data-ac-drawer-tab=\"inventory\">Inventory <span id=\"acTabInventoryCount\" class=\"acDrawerTabCount\">—</span></button>\n          <button class=\"acDrawerTab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"acDrawerTabConnection\" data-ac-drawer-tab=\"connection\">Connection <span id=\"acTabConnectionCount\" class=\"acDrawerTabCount\">0</span></button>\n          <button class=\"acDrawerTab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"acDrawerTabHistory\" data-ac-drawer-tab=\"history\">History <span id=\"acTabHistoryCount\" class=\"acDrawerTabCount\">0</span></button>\n          <button class=\"acDrawerTab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"acDrawerTabEvidence\" data-ac-drawer-tab=\"evidence\">Evidence <span id=\"acTabEvidenceCount\" class=\"acDrawerTabCount\">0</span></button>\n        </div>\n      </div>\n\n      <section id=\"acDrawerTabOverview\" class=\"acDrawerTabPanel active\" data-ac-drawer-panel=\"overview\" role=\"tabpanel\">\n        <div class=\"acDrawerTabIntro\"><div><b>Player overview</b><span>High-level integrity posture, startup verdict, client identity, mod verification, connection health and the strongest current investigation drivers.</span></div></div>\n        <div id=\"acPlayerOverview\" class=\"acPlayerOverview\"></div>\n        <div id=\"acInvestigationSummary\" class=\"acInvestigationPanel\"></div>\n        <div id=\"acDetailSummary\" class=\"small\" style=\"margin-bottom:10px\"></div>\n      </section>\n\n      <section id=\"acDrawerTabAntiCheat\" class=\"acDrawerTabPanel\" data-ac-drawer-panel=\"anticheat\" role=\"tabpanel\" hidden>\n        <div class=\"acDrawerTabIntro\"><div><b>Anti-Cheat investigation</b><span>Active findings, runtime changes and scanner telemetry. Server-authoritative evidence remains visually distinct from client-reported integrity telemetry.</span></div></div>\n        <div class=\"grid acDrawerTabGrid\">\n          <div id=\"acDrawerFindings\" class=\"card acFullSpan\"><div class=\"cardHeader\"><h3>Evidence & Findings</h3><div class=\"spacer\"></div><span class=\"small\">Strongest evidence first</span></div><div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>Severity</th><th>Confidence</th><th>Evidence</th><th>Risk</th><th>Observed</th><th>Code / Subject</th><th>Investigation summary</th></tr></thead><tbody id=\"acFindingRows\"><tr><td colspan=\"7\" class=\"muted\">No findings loaded.</td></tr></tbody></table></div></div>\n          <div id=\"acDrawerRuntime\" class=\"card\"><div class=\"cardHeader\"><h3>Runtime Changes</h3></div><div class=\"compactNote\">New assemblies and post-baseline runtime changes reported after startup attestation.</div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Assembly</th><th>File</th><th>Context</th><th>Type</th><th>SHA-256 / MVID</th></tr></thead><tbody id=\"acRuntimeRows\"><tr><td colspan=\"5\" class=\"muted\">No post-baseline runtime changes reported.</td></tr></tbody></table></div></div>\n          <div id=\"acDrawerScanner\" class=\"card\"><div class=\"cardHeader\"><h3>Scanner Health</h3></div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Scanner</th><th>Status</th><th>Duration</th><th>Results</th><th>Hash cache</th></tr></thead><tbody id=\"acScannerRows\"><tr><td colspan=\"5\" class=\"muted\">No scanner telemetry loaded.</td></tr></tbody></table></div></div>\n        </div>\n      </section>\n\n      <section id=\"acDrawerTabMods\" class=\"acDrawerTabPanel\" data-ac-drawer-panel=\"mods\" role=\"tabpanel\" hidden>\n        <div class=\"acDrawerTabIntro\"><div><b>Client mod & assembly inventory</b><span>Separate true client-side additions from mods shared with the server, then review exact ModDB comparison, policy state, and loaded assemblies.</span></div></div>\n        <div class=\"grid acDrawerTabGrid\">\n          <div id=\"acDrawerClientOnlyMods\" class=\"card acFullSpan acClientOnlyModsCard\"><div class=\"cardHeader\"><div><h3>Client-only Mods</h3><div class=\"small\">Only mods reported by this player that are not present in the server-loaded mod baseline.</div></div><div class=\"spacer\"></div><span id=\"acClientOnlyModsCount\" class=\"badge\">0</span></div><div class=\"compactNote\">Use this section first when checking for cosmetic, utility, automation, or other client-side additions. The full inventory remains below for shared-mod integrity comparison.</div><div class=\"tableWrap dataScrollTall\"><table class=\"mobileStackTable acModInventoryTable\"><thead><tr><th>Mod</th><th>Version</th><th>Type</th><th>File</th><th>SHA-256</th><th>ModDB Verification</th><th>Policy</th></tr></thead><tbody id=\"acClientOnlyModRows\"><tr><td colspan=\"7\" class=\"muted\">No client-only mods reported.</td></tr></tbody></table></div></div>\n          <div id=\"acDrawerMods\" class=\"card acFullSpan\"><div class=\"cardHeader\"><div><h3>All Reported Mods</h3><div class=\"small\">Shared server/client mods and client-only mods together.</div></div><div class=\"spacer\"></div><span id=\"acAllModsCount\" class=\"badge\">0</span></div><div class=\"compactNote\">Shared mods are compared against the protected server baseline first. Client-only mods use policy and ModDB evidence where available.</div><div class=\"tableWrap dataScrollTall\"><table class=\"mobileStackTable acModInventoryTable\"><thead><tr><th>Mod</th><th>Version</th><th>Type</th><th>Scope</th><th>File</th><th>SHA-256</th><th>ModDB Verification</th><th>Policy</th></tr></thead><tbody id=\"acModRows\"><tr><td colspan=\"8\" class=\"muted\">No mod inventory loaded.</td></tr></tbody></table></div></div>\n          <div id=\"acDrawerAssemblies\" class=\"card acFullSpan\"><div class=\"cardHeader\"><h3>Loaded Assemblies</h3></div><div class=\"compactNote\">Classification is display context only; unknown future assemblies remain Unassociated / review and are not silently trusted.</div><div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>Assembly</th><th>Version</th><th>Class</th><th>Associated Mods</th><th>SHA-256</th><th>MVID</th></tr></thead><tbody id=\"acAssemblyRows\"><tr><td colspan=\"6\" class=\"muted\">No assembly inventory loaded.</td></tr></tbody></table></div></div>\n        </div>\n      </section>\n\n      <section id=\"acDrawerTabInventory\" class=\"acDrawerTabPanel\" data-ac-drawer-panel=\"inventory\" role=\"tabpanel\" hidden>\n        <div class=\"acDrawerTabIntro\"><div><b>Player inventory</b><span>Inspect live inventories and read-only saved inventories for offline investigations. Online slot edits create a rollback snapshot and check for conflicts.</span></div></div>\n        <div class=\"acInventoryShell\">\n          <div id=\"acInventoryHero\" class=\"acInventoryHero\"></div>\n          <div class=\"acInventoryToolbar\">\n            <input id=\"acInventoryFilter\" type=\"search\" placeholder=\"Find an item by name, code, inventory or section\">\n            <button id=\"acInventoryRefresh\">Refresh</button>\n            <button id=\"acInventorySnapshot\">Create Snapshot</button>\n            <button id=\"acInventoryClearSelection\">Clear Selection</button>\n            <div class=\"spacer\"></div><span id=\"acInventoryState\" class=\"small\">Open this tab to load inventory.</span>\n          </div>\n          <div class=\"acInventoryLayout\">\n            <div class=\"acInventoryGridPane\"><div id=\"acInventoryGrid\" class=\"acInventorySections\"><div class=\"acInventoryEmpty\">Inventory has not been loaded yet.</div></div></div>\n            <div class=\"acInventorySide\">\n              <div class=\"card\"><div class=\"cardHeader\"><h3>Selected Slot</h3><div class=\"spacer\"></div><span id=\"acInventorySelectedState\" class=\"small\">None</span></div><div id=\"acInventorySelectedDetail\" class=\"small\">Select a slot to inspect it.</div><div id=\"acInventorySelectedActions\" class=\"quickActions\"></div></div>\n              <div id=\"acInventoryEditWorkbench\" class=\"card\"><div class=\"cardHeader\"><h3>Give / Replace Item</h3><div class=\"spacer\"></div><span id=\"acInventoryCatalogSelected\" class=\"small\">No item selected</span></div><div class=\"inventoryToolbar\"><input id=\"acInventoryItemSearch\" type=\"search\" placeholder=\"Search item/block\"><button id=\"acInventoryItemSearchBtn\">Search</button><input id=\"acInventoryGiveQuantity\" type=\"number\" min=\"1\" value=\"1\" style=\"width:82px\" title=\"Quantity\"></div><div id=\"acInventoryItemSearchResults\" class=\"acInventorySearchResults\"><div class=\"small\" style=\"padding:7px\">Search for at least two characters.</div></div><div class=\"quickActions\"><button id=\"acInventoryGiveAuto\">Give to Free Slot</button><button id=\"acInventoryGiveSelected\">Give Here</button><button id=\"acInventoryReplaceSelected\" class=\"danger\">Replace Slot</button></div></div>\n            </div>\n          </div>\n          <div class=\"card\"><div class=\"cardHeader\"><h3>Inventory Snapshots</h3><div class=\"spacer\"></div><span id=\"acInventorySnapshotState\" class=\"small\">0 retained</span></div><div id=\"acInventorySnapshots\" class=\"acInventorySnapshotGrid\"><div class=\"muted\">No snapshots loaded.</div></div><div id=\"acInventoryCompare\" class=\"acInventoryCompare\" style=\"display:none\"><div class=\"cardHeader\"><h3>Snapshot Comparison</h3><div class=\"spacer\"></div><span id=\"acInventoryCompareState\" class=\"small\"></span></div><div class=\"tableWrap\"><table><thead><tr><th>Inventory</th><th>Slot</th><th>Snapshot</th><th>Current</th><th>Change</th></tr></thead><tbody id=\"acInventoryCompareRows\"></tbody></table></div></div></div>\n          <div class=\"card\"><div class=\"cardHeader\"><h3>Inventory Audit History</h3><div class=\"spacer\"></div><span class=\"small\">Recent inventory-only administration actions</span></div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Source</th><th>Detail</th></tr></thead><tbody id=\"acInventoryHistoryRows\"><tr><td colspan=\"5\" class=\"muted\">No inventory history loaded.</td></tr></tbody></table></div></div>\n        </div>\n      </section>\n\n      <section id=\"acDrawerTabConnection\" class=\"acDrawerTabPanel\" data-ac-drawer-panel=\"connection\" role=\"tabpanel\" hidden>\n        <div class=\"acDrawerTabIntro\"><div><b>Connection health</b><span>Hello, protocol, heartbeat, startup-scan and timeout stages for this player. Connection problems are compatibility/reliability diagnostics, not cheat evidence.</span></div></div>\n        <div id=\"acPlayerConnectionSummary\" class=\"acConnectionSummary\"></div>\n        <div class=\"card\"><div class=\"cardHeader\"><h3>Connection Diagnostics</h3><div class=\"spacer\"></div><span id=\"acPlayerConnectionState\" class=\"small\">No connection events loaded.</span></div><div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>Time</th><th>Stage</th><th>Event</th><th>Action</th><th>Client</th><th>Detail</th></tr></thead><tbody id=\"acPlayerConnectionRows\"><tr><td colspan=\"6\" class=\"muted\">No player-specific connection diagnostics loaded.</td></tr></tbody></table></div></div>\n      </section>\n\n      <section id=\"acDrawerTabHistory\" class=\"acDrawerTabPanel\" data-ac-drawer-panel=\"history\" role=\"tabpanel\" hidden>\n        <div class=\"acDrawerTabIntro\"><div><b>Investigation history</b><span>Combined chronological view of connection stages, scans, findings, captured evidence and consequences. Use Full History for the server-wide persistent history page.</span></div><div class=\"spacer\"></div><button id=\"acDrawerOpenFullHistory\">Open Full History</button></div>\n        <div id=\"acDrawerTimeline\" class=\"card acFullSpan\"><div class=\"cardHeader\"><div><h3>Anti-Cheat Timeline</h3><div class=\"small\">Newest events first.</div></div><div class=\"spacer\"></div><span id=\"acPlayerTimelineState\" class=\"small\">No events loaded.</span></div><div id=\"acPlayerTimeline\" class=\"acTimeline\"><div class=\"muted\" style=\"padding:10px 30px\">No timeline loaded.</div></div></div>\n      </section>\n\n      <section id=\"acDrawerTabEvidence\" class=\"acDrawerTabPanel\" data-ac-drawer-panel=\"evidence\" role=\"tabpanel\" hidden>\n        <div class=\"acDrawerTabIntro\"><div><b>Collected evidence</b><span>Player-authorized, bounded package transfer tied to current Anti-Cheat evidence, with server-side SHA-256 and visual ModDB file comparison.</span></div></div>\n        <div id=\"acDrawerEvidence\" class=\"card acFullSpan\"><div class=\"cardHeader\"><h3>Suspicious Package Evidence</h3><div class=\"spacer\"></div><span class=\"small\">Player authorization required · exact ModLoader package</span></div><div class=\"compactNote\">Only packages tied to current Anti-Cheat evidence are eligible. The player receives an in-game authorization popup before any package bytes are read or transferred. Existing ZIPs are sent byte-for-byte; folder/loose mods are wrapped into a ZIP. The server never requests an arbitrary client filesystem path. Declining or dismissing the request triggers the decline policy configured by server staff.</div><div class=\"tableWrap dataScroll\" style=\"margin-top:8px\"><table><thead><tr><th>Mod</th><th>Why suspicious</th><th>Reported package</th><th>Stored evidence</th><th>Action</th></tr></thead><tbody id=\"acEvidenceCandidateRows\"><tr><td colspan=\"5\" class=\"muted\">No suspicious package candidates loaded.</td></tr></tbody></table></div><div class=\"tableWrap dataScroll\" style=\"margin-top:10px\"><table><thead><tr><th>Collected</th><th>Mod</th><th>Saved ZIP</th><th>Size</th><th>SHA-256</th><th>Official file diff</th></tr></thead><tbody id=\"acCollectedEvidenceRows\"><tr><td colspan=\"6\" class=\"muted\">No stored transferred packages for this player.</td></tr></tbody></table></div></div>\n      </section>\n    </div>\n  </div>\n\n  <div class=\"tabPanel\" data-ac-panel=\"clientmods\">\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><div><h3>Client Mods</h3><div class=\"small\">All third-party mods reported by currently online Client Integrity sessions, including exact ModDB resolution, official fingerprints, and comparison state when ModDB verification is enabled. ModDB evidence is advisory by default.</div></div><div class=\"spacer\"></div><span id=\"acClientModsState\" class=\"small\">No inventory loaded.</span></div>\n      <div class=\"toolbar\">\n        <div class=\"field grow\"><label>Search</label><input id=\"acClientModsSearch\" style=\"width:100%\" placeholder=\"Player, ModID, version, filename…\"></div>\n        <div class=\"field\"><label>Verification</label><select id=\"acClientModsFilter\"><option value=\"all\">All states</option><option value=\"modified\">Modified</option><option value=\"diagnostic\">Diagnostic difference</option><option value=\"approved\">Approved custom</option><option value=\"official\">Verified / server match</option><option value=\"pending\">Pending / refreshing</option><option value=\"unavailable\">Unavailable / legacy</option><option value=\"notfound\">Not on ModDB</option><option value=\"unchecked\">Not checked</option></select></div>\n        <label class=\"small\" style=\"align-self:end;padding-bottom:8px\"><input id=\"acClientModsForceRefresh\" type=\"checkbox\"> Force refresh cached results</label>\n        <button id=\"acClientModsResolveAll\" class=\"primary\" style=\"align-self:end\">Resolve All DB Fingerprints</button>\n      </div>\n      <div id=\"acClientModsSummary\" class=\"grid\" style=\"margin:10px 0\"></div>\n      <div class=\"card\" style=\"margin:10px 0\"><div class=\"cardHeader\"><div><h3>ModDB Verification Health</h3><div class=\"small\">External ModDB availability is tracked separately from player integrity. An unavailable lookup is never labeled as a modified client mod.</div></div><div class=\"spacer\"></div><span id=\"acModDbHealthState\" class=\"small\">Not loaded.</span></div><div id=\"acModDbHealthGrid\" class=\"grid\"></div></div>\n      <div class=\"card\" style=\"margin:10px 0\">\n        <div class=\"cardHeader\"><div><h3>Approve Mod ZIP Fingerprint</h3><div class=\"small\">Upload a private or intentionally patched Vintage Story mod ZIP to approve its exact normalized fingerprint. The Suite reads root <code>modinfo.json</code> and hashes the package; it does not install, load, extract, or execute the uploaded mod.</div></div><div class=\"spacer\"></div><span id=\"acApprovalUploadState\" class=\"small\">Ready.</span></div>\n        <div class=\"row\" style=\"align-items:end;gap:12px;flex-wrap:wrap\">\n          <div class=\"field grow\" style=\"min-width:260px\"><label for=\"acApprovalZip\">Mod ZIP</label><input id=\"acApprovalZip\" type=\"file\" accept=\".zip,application/zip\"></div>\n          <div class=\"field grow\" style=\"min-width:220px\"><label for=\"acApprovalLabel\">Label <span class=\"small\">(optional)</span></label><input id=\"acApprovalLabel\" maxlength=\"160\" placeholder=\"Private build / compatibility patch\"></div>\n          <div class=\"field grow\" style=\"min-width:260px\"><label for=\"acApprovalNotes\">Notes <span class=\"small\">(optional)</span></label><input id=\"acApprovalNotes\" maxlength=\"1200\" placeholder=\"Why this exact build is approved\"></div>\n          <button id=\"acApprovalUploadButton\" class=\"primary\">Fingerprint &amp; Approve ZIP</button>\n        </div>\n        <div style=\"margin-top:10px;height:8px;border:1px solid var(--border);border-radius:999px;overflow:hidden;background:#0b1117\"><div id=\"acApprovalUploadBar\" style=\"width:0%;height:100%;background:linear-gradient(90deg,var(--accent),#72d5ff);transition:width .15s ease\"></div></div>\n        <div id=\"acApprovalUploadDetail\" class=\"small\" style=\"margin-top:7px\">Maximum upload: 96 MB. Upload is chunked so large mod ZIPs stay below the WebPanel request-size limit.</div>\n      </div>\n      <div class=\"card\" style=\"margin:10px 0\"><div class=\"cardHeader\"><div><h3>Approved Custom Fingerprints</h3><div class=\"small\">Exact exceptions for private or intentionally patched mods. Approval requires ModID + version + normalized content SHA-256; approving a ModID/version never trusts other builds.</div></div><div class=\"spacer\"></div><span id=\"acApprovedCustomState\" class=\"small\">No custom approvals.</span></div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Mod / Version</th><th>Label / Notes</th><th>Content fingerprint</th><th>Approved</th><th>Action</th></tr></thead><tbody id=\"acApprovedCustomRows\"><tr><td colspan=\"5\" class=\"muted\">No custom fingerprints approved.</td></tr></tbody></table></div></div>\n      <div class=\"card\" style=\"margin:10px 0\"><div class=\"cardHeader\"><div><h3>Fingerprint Clusters</h3><div class=\"small\">Each release is grouped visually by exact content fingerprint. Dominant fingerprints and one-player outliers are called out immediately.</div></div><div class=\"spacer\"></div><span id=\"acClientModClusterState\" class=\"small\">No clusters loaded.</span></div><div id=\"acClientModClusterBoard\" class=\"acClusterBoard\"><div class=\"muted\" style=\"padding:10px\">No fingerprint clusters loaded.</div></div></div>\n      <div class=\"compactNote\">Resolution is deduplicated by exact <b>ModID + version</b>, persisted server-side, and limited to two simultaneous downloads. Multiple players using the same release reuse the same official fingerprint. Missing or unavailable telemetry is shown as unavailable and is not treated as modified.</div>\n      <div class=\"tableWrap dataScrollTall\" style=\"margin-top:10px\"><table><thead><tr><th>Player</th><th>Mod / Version</th><th>Scope</th><th>Client Package</th><th>Official ModDB</th><th>Comparison</th><th>Checked</th></tr></thead><tbody id=\"acClientModsRows\"><tr><td colspan=\"7\" class=\"muted\">No client mod inventory loaded.</td></tr></tbody></table></div>\n    </div>\n  </div>\n\n  <div class=\"tabPanel\" data-ac-panel=\"oreshield\">\n    <div id=\"acOreShieldHero\" class=\"summaryHero\"><div class=\"heroIcon\">OS</div><div><div class=\"heroTitle\">Loading Ore Shield…</div><div class=\"heroText\">Server-authoritative ore concealment and performance status will appear here.</div></div></div>\n\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><div><h3>Ore Shield Control</h3><div class=\"small\">Tune concealment and cache behavior without editing the full Anti-Cheat JSON. Saving reloads only Ore Shield.</div></div><div class=\"spacer\"></div><span id=\"acOreShieldState\" class=\"small\">Loading policy…</span></div>\n      <div class=\"infoBox\"><b>OreShield · Beta</b> — Fully functioning, with bug fixes and performance polishing still in progress. Disabled by default on new configurations; enable it when you are ready to test it on your server.</div>\n      <div class=\"grid\" style=\"margin-top:10px\">\n        <div class=\"card\" style=\"background:#10171d\">\n          <div class=\"cardHeader\"><h3>Protection</h3></div>\n          <label class=\"small\"><input id=\"acOreShieldEnabled\" type=\"checkbox\"> Enable Ore Shield</label><br>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acOreShieldProtectModded\" type=\"checkbox\"> Protect compatible modded ores</label>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acOreShieldRevealUnknown\" type=\"checkbox\" disabled> Strict concealment when neighbor data is unavailable (forced)</label>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acOreShieldStrictMatching\" type=\"checkbox\"> Use strict ore / host-rock matching</label>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acOreShieldRevealVein\" type=\"checkbox\"> Reveal the loaded, connected mineral vein after mining protected ore (includes diagonals and mixed grades)</label>\n          <label style=\"display:block;margin-top:8px\">Maximum blocks revealed from one vein<input id=\"acOreShieldMaxVein\" type=\"number\" min=\"64\" max=\"8192\" step=\"64\"></label>\n          <div class=\"formGrid\" style=\"margin-top:8px\">\n            <label>LOS discovery range (blocks)<input id=\"acOreShieldDiscoveryRange\" type=\"number\" min=\"16\" max=\"192\" step=\"8\"></label>\n            <label>LOS scan interval (ms)<input id=\"acOreShieldLosInterval\" type=\"number\" min=\"100\" max=\"2000\" step=\"50\"></label>\n            <label>Max LOS checks / pass<input id=\"acOreShieldLosChecks\" type=\"number\" min=\"16\" max=\"512\" step=\"16\"></label>\n            <label>Server view cone (degrees)<input id=\"acOreShieldViewCone\" type=\"number\" min=\"90\" max=\"180\" step=\"5\"></label>\n            <label>Idle safety rescan (ms)<input id=\"acOreShieldIdleRescan\" type=\"number\" min=\"500\" max=\"15000\" step=\"250\"></label>\n          </div>\n          <label class=\"small\" style=\"display:block;margin-top:8px\"><input id=\"acOreShieldLeakAudit\" type=\"checkbox\"> Enable outbound leak invariant audit</label>\n          <div class=\"compactNote\" style=\"margin-top:8px\"><b>Ore Shield v3.2.9:</b> every protected natural ore is concealed by default, including cave-exposed ore. Geometry exposure only makes an ore eligible for a bounded server-side line-of-sight test from the player&apos;s real position. Authorized discoveries are remembered for that player for the lifetime of the current Ore Shield runtime, including chunk unload/reload and reconnect. Whole-vein reveal remains optional because it intentionally exposes buried connected vein geometry.</div>\n        </div>\n        <div class=\"card\" style=\"background:#10171d\">\n          <div class=\"cardHeader\"><h3>Revision Cache</h3></div>\n          <label class=\"small\"><input id=\"acOreShieldCacheEnabled\" type=\"checkbox\"> Cache virtualized chunks by world revision</label>\n          <div class=\"formGrid\" style=\"margin-top:8px\">\n            <label>Masked cache limit (MiB)<input id=\"acOreShieldCacheMiB\" type=\"number\" min=\"8\" max=\"1024\" step=\"8\"></label>\n            <label>Maximum cached chunks<input id=\"acOreShieldMaxChunks\" type=\"number\" min=\"256\" max=\"16384\" step=\"256\"></label>\n          </div>\n          <div id=\"acOreShieldCacheBudget\" class=\"compactNote\" style=\"margin-top:8px\">Waiting for live cache telemetry.</div>\n        </div>\n      </div>\n      <div class=\"toolbar\" style=\"margin-top:12px\"><button id=\"acOreShieldSave\" class=\"primary\">Save Ore Shield Settings</button><div class=\"spacer\"></div><span class=\"small\">Ore Shield never creates client-visible fake ore. Real world blocks and vanilla prospecting data are not rewritten.</span></div>\n    </div>\n\n    <div id=\"acOreShieldMetrics\" class=\"grid perfSection\"></div>\n\n    <div class=\"grid perfSection\">\n      <div class=\"card\">\n        <div class=\"cardHeader\"><div><h3>Runtime Efficiency</h3><div class=\"small\">Live counters since Ore Shield started or was reloaded.</div></div><div class=\"spacer\"></div><span id=\"acOreShieldEfficiencyState\" class=\"small\">Waiting for telemetry…</span></div>\n        <div id=\"acOreShieldEfficiency\" class=\"compactNote\">No telemetry loaded.</div>\n      </div>\n      <div class=\"card\">\n        <div class=\"cardHeader\"><div><h3>Concealment Health</h3><div class=\"small\">Recipient-aware chunk packets conceal every protected ore until that player passes a server-side line-of-sight discovery check. Break/place events accelerate nearby checks; periodic scans are bounded and candidate-indexed.</div></div><div class=\"spacer\"></div><span id=\"acOreShieldHealthState\" class=\"small\">Waiting for telemetry…</span></div>\n        <div id=\"acOreShieldHealth\" class=\"compactNote\">No telemetry loaded.</div>\n      </div>\n    </div>\n\n    <div class=\"grid perfSection\">\n      <div class=\"card\">\n        <div class=\"cardHeader\"><h3>Additional Ore Patterns</h3></div>\n        <textarea id=\"acOreShieldAdditionalPatterns\" rows=\"8\" spellcheck=\"false\" placeholder=\"examplemod:ore-*\"></textarea>\n        <div class=\"compactNote\" style=\"margin-top:8px\">One pattern per line. Strict geometry, light and exact host-rock checks still apply.</div>\n      </div>\n      <div class=\"card\">\n        <div class=\"cardHeader\"><h3>Excluded Block Patterns</h3></div>\n        <textarea id=\"acOreShieldExcludedPatterns\" rows=\"8\" spellcheck=\"false\" placeholder=\"examplemod:ore-special-*\"></textarea>\n        <div class=\"compactNote\" style=\"margin-top:8px\">Use exclusions for unusual ores or blocks that should always remain vanilla.</div>\n      </div>\n    </div>\n\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><div><h3>Coverage</h3><div class=\"small\">Aggregate operational information only. Ore coordinates are never exposed in the WebPanel.</div></div></div>\n      <div id=\"acOreShieldCoverage\" class=\"compactNote\">Loading coverage summary…</div>\n    </div>\n  </div>\n\n  <div class=\"tabPanel packetWorkspace\" data-ac-panel=\"packet\">\n<div class=\"card packetHero\">\n      <div class=\"cardHeader\"><h3>PacketGuard</h3><div class=\"spacer\"></div><span id=\"acPacketState\" class=\"small\">Loading policy…</span></div>\n      <div id=\"acIngressCoverage\" class=\"grid\" style=\"margin:10px 0\"></div>\n      <div id=\"acIngressStatus\" class=\"compactNote\">Waiting for raw packet protection coverage.</div>\n      <p id=\"acIngressHelp\" class=\"compactNote\">Ingress checks incoming vanilla packets before game handlers: packet size and rate limits, view distance caps and interaction validation. Requires PacketGuard enabled. Turning it off leaves the other enabled movement, reach and mining checks running. Save to apply immediately.</p>\n      <details class=\"helpDisclosure\"><summary>False-positive protections</summary><div>PacketGuard tracks trusted transitions independently of Movement enforcement so Reach-only configurations still recognize legitimate teleports and dimension changes. Trust is detector-scoped: mount/dismount reposition grace applies to Movement only, while engine teleports, /spawn, translocators, suite/admin teleports, dashboard teleports, TP Runes arrivals, and dimension changes can protect both Movement and Reach for a short bounded window.</div></details>\n      <div class=\"toolbar\" style=\"margin-top:10px\"><label><input id=\"acPacketEnabled\" type=\"checkbox\"> PacketGuard enabled</label><label><input id=\"acPacketIngressEnabled\" type=\"checkbox\" aria-describedby=\"acIngressHelp\"> PacketGuard ingress protection</label><button id=\"acPacketSave\" class=\"primary\">Save Packet Protection</button><button id=\"acPacketDiscard\" type=\"button\" hidden>Discard changes</button><span id=\"acPacketDraftState\" class=\"small\" aria-live=\"polite\">Settings saved</span><div class=\"spacer\"></div><span class=\"small\">Changes apply immediately; no client rescan is required.</span></div>\n    </div>\n<div class=\"packetNav\" role=\"tablist\" aria-label=\"PacketGuard settings\"><button type=\"button\" id=\"packetTab-movement\" role=\"tab\" aria-controls=\"packetSection-movement\" aria-selected=\"true\" tabindex=\"0\" data-packet-tab=\"movement\" class=\"active\">Movement</button><button type=\"button\" id=\"packetTab-mounts\" role=\"tab\" aria-controls=\"packetSection-mounts\" aria-selected=\"false\" tabindex=\"-1\" data-packet-tab=\"mounts\" class=\"\">Mounts & exemptions</button><button type=\"button\" id=\"packetTab-actions\" role=\"tab\" aria-controls=\"packetSection-actions\" aria-selected=\"false\" tabindex=\"-1\" data-packet-tab=\"actions\" class=\"\">Reach & mining</button><button type=\"button\" id=\"packetTab-policy\" role=\"tab\" aria-controls=\"packetSection-policy\" aria-selected=\"false\" tabindex=\"-1\" data-packet-tab=\"policy\" class=\"\">Policy & reports</button><button type=\"button\" id=\"packetTab-diagnostics\" role=\"tab\" aria-controls=\"packetSection-diagnostics\" aria-selected=\"false\" tabindex=\"-1\" data-packet-tab=\"diagnostics\" class=\"\">Diagnostics</button></div>\n<div id=\"packetSection-movement\" role=\"tabpanel\" aria-labelledby=\"packetTab-movement\" data-packet-section=\"movement\"><div class=\"packetSectionHeading\"><h3>Movement</h3><p>Speed limits, confirmation and collision checks.</p></div><div class=\"packetCards\"><div class=\"card packetSpeedCard\"><div class=\"cardHeader\"><h3>Unmounted speed limits</h3><span class=\"packetUnit\">blocks / second</span></div><p class=\"compactNote\">Set these above legitimate movement with XSkills or other server bonuses. Limits are server-wide and do not automatically scale with skills.</p><label class=\"packetToggle\"><input id=\"acPacketKickRepeatedConfirmedSpeed\" type=\"checkbox\"> Kick repeated confirmed speed violations at 100 risk</label><label>Risk added per repeated confirmed speed report<input id=\"acPacketConfirmedSpeedRepeatRisk\" type=\"number\" min=\"0\" max=\"50\" step=\"1\"></label><p class=\"compactNote\">Default risk: 50 → 75 → 100. Requires three Critical unmounted speed reports in one minute, at least 10 seconds apart. Mount, low-TPS and review-only observations do not qualify.</p><label class=\"packetToggle\"><input id=\"acPacketMovementModeLimitsEnabled\" type=\"checkbox\"> Use separate ground, swimming and airborne limits</label><div class=\"formGrid\"><label>Ground maximum<input id=\"acPacketGroundMaxHorizontalSpeed\" type=\"number\" min=\"6\" max=\"200\" step=\"any\"></label><label>Airborne maximum<input id=\"acPacketAirborneMaxHorizontalSpeed\" type=\"number\" min=\"6\" max=\"200\" step=\"any\"></label><label>Swimming maximum<input id=\"acPacketSwimmingMaxHorizontalSpeed\" type=\"number\" min=\"4\" max=\"120\" step=\"any\"></label><label>Fallback maximum<input id=\"acPacketMaxHorizontalSpeed\" type=\"number\" min=\"8\" max=\"200\" step=\"any\"></label></div><div class=\"compactNote\">The fallback is used when separate movement-mode limits are off. Hard move distance and acceleration checks still apply independently.</div></div><div class=\"card\"><div class=\"cardHeader\"><h3>Movement</h3></div>\n        <label class=\"small\"><input id=\"acPacketMovementEnabled\" type=\"checkbox\"> Enable movement validation</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Sample interval (ms)<input id=\"acPacketMovementSampleMs\" type=\"number\" min=\"75\" max=\"500\"></label><label>Hard move distance (blocks)<input id=\"acPacketHardMoveDistance\" type=\"number\" min=\"12\" max=\"96\" step=\"0.5\"></label><label>Confirm samples<input id=\"acPacketMovementConfirmSamples\" type=\"number\" min=\"1\" max=\"4\"></label><label>Confirm window (ms)<input id=\"acPacketMovementConfirmWindowMs\" type=\"number\" min=\"100\" max=\"2000\"></label><label>Extreme multiplier<input id=\"acPacketMovementExtremeMultiplier\" type=\"number\" min=\"1.5\" max=\"6\" step=\"0.05\"></label><label>Correction grace (ms)<input id=\"acPacketCorrectionGraceMs\" type=\"number\" min=\"250\" max=\"5000\"></label></div>\n        <label class=\"small\"><input id=\"acPacketRejectMovement\" type=\"checkbox\"> Roll back unauthorized movement instead of log-only</label>\n        <div class=\"compactNote\" style=\"margin-top:8px\">Borderline impossible jumps must persist across the configured confirmation samples. Extremely large jumps bypass confirmation and enforce immediately.</div>\n      </div><div class=\"card\"><div class=\"cardHeader\"><h3>Movement False-Positive Hardening</h3></div>\n        <div class=\"compactNote\">Advanced PacketGuard tuning added for modded movement. Block collision/noclip detection is OFF by default because complex vanilla and modded collision shapes (especially trapdoors/doors) can create legitimate overlap.</div>\n        <label class=\"small\" style=\"display:block;margin-top:10px\"><input id=\"acPacketNoclipEnabled\" type=\"checkbox\"> Enable block collision / noclip detection (advanced; default OFF)</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\">\n          <label>Acceleration sample minimum (ms)<input id=\"acPacketAccelerationSampleMinMs\" type=\"number\" min=\"100\" max=\"1000\" step=\"10\"></label>\n          <label>Acceleration smoothing factor<input id=\"acPacketAccelerationSmoothingFactor\" type=\"number\" min=\"0.05\" max=\"1\" step=\"0.05\"></label>\n          <label>Noclip path collision samples<input id=\"acPacketNoclipRequiredSamples\" type=\"number\" min=\"1\" max=\"6\" step=\"1\"></label>\n          <label>Noclip path penetration depth<input id=\"acPacketNoclipMinPenetration\" type=\"number\" min=\"0.03\" max=\"0.75\" step=\"0.01\"></label>\n          <label>Endpoint noclip minimum net movement<input id=\"acPacketNoclipEndpointMinMovement\" type=\"number\" min=\"0.10\" max=\"2\" step=\"0.05\"></label>\n          <label>Mount acceleration minimum speed ratio<input id=\"acPacketMountAccelerationMinSpeedRatio\" type=\"number\" min=\"0.50\" max=\"1.25\" step=\"0.05\"></label>\n        </div>\n        <div class=\"compactNote\" style=\"margin-top:8px\">Mount acceleration remains corroborating telemetry only; it cannot independently trigger rollback while mount speed, vertical speed, rider distance, and rider correlation remain legal.</div>\n      </div></div></div>\n<div id=\"packetSection-mounts\" role=\"tabpanel\" aria-labelledby=\"packetTab-mounts\" data-packet-section=\"mounts\" hidden><div class=\"packetSectionHeading\"><h3>Mounts & exemptions</h3><p>Tune Draconis and other mounts without weakening unmounted limits.</p></div><div class=\"packetCards\"><div class=\"card\"><div class=\"cardHeader\"><h3>Mount protection</h3></div><p class=\"compactNote\">Draconis / Jaunt, Shipwright and other mounts have separate speed envelopes. Unknown mounts remain telemetry-only unless enforcement is enabled.</p><label class=\"packetToggle\"><input id=\"acPacketMountProfilesEnabled\" type=\"checkbox\"> Use mount profiles</label><label class=\"packetToggle\"><input id=\"acPacketMountProfileEnforcementEnabled\" type=\"checkbox\"> Enforce mount profile limits</label><label class=\"packetToggle\"><input id=\"acPacketUnknownMountEnforcementEnabled\" type=\"checkbox\"> Enforce limits for unknown mounts</label><label class=\"packetToggle\"><input id=\"acPacketMountRiderCorrelationEnabled\" type=\"checkbox\"> Check rider position against the mount</label><div class=\"formGrid\"><label>Confirmation samples<input id=\"acPacketMountProfileConfirmSamples\" type=\"number\" min=\"1\" max=\"5\" step=\"1\"></label><label>Confirmation window (ms)<input id=\"acPacketMountProfileConfirmWindowMs\" type=\"number\" min=\"150\" max=\"3000\" step=\"50\"></label></div><div class=\"compactNote\">Mounted-player exemption controls generic player movement; enabled mount profiles are checked separately.</div></div><div class=\"card packetMountCard\"><div class=\"cardHeader\"><h3>Draconis / Jaunt</h3><span class=\"packetUnit\">mount profile</span></div><div class=\"formGrid\"><label>Horizontal speed (blocks/s)<input id=\"acPacketDraconisMaxHorizontalSpeed\" type=\"number\" min=\"20.0\" max=\"300.0\" step=\"any\"></label><label>Vertical speed (blocks/s)<input id=\"acPacketDraconisMaxVerticalSpeed\" type=\"number\" min=\"5.0\" max=\"150.0\" step=\"any\"></label><label>Acceleration (blocks/s²)<input id=\"acPacketDraconisMaxAcceleration\" type=\"number\" min=\"50.0\" max=\"3000.0\" step=\"any\"></label><label>Rider distance (blocks)<input id=\"acPacketDraconisMaxRiderDistance\" type=\"number\" min=\"4.0\" max=\"64.0\" step=\"any\"></label><label>Rider relative speed (blocks/s)<input id=\"acPacketDraconisMaxRiderRelativeSpeed\" type=\"number\" min=\"5.0\" max=\"150.0\" step=\"any\"></label></div></div><div class=\"card packetMountCard\"><div class=\"cardHeader\"><h3>Shipwright vessels</h3><span class=\"packetUnit\">mount profile</span></div><div class=\"formGrid\"><label>Horizontal speed (blocks/s)<input id=\"acPacketShipwrightMaxHorizontalSpeed\" type=\"number\" min=\"20.0\" max=\"300.0\" step=\"any\"></label><label>Vertical speed (blocks/s)<input id=\"acPacketShipwrightMaxVerticalSpeed\" type=\"number\" min=\"5.0\" max=\"150.0\" step=\"any\"></label><label>Acceleration (blocks/s²)<input id=\"acPacketShipwrightMaxAcceleration\" type=\"number\" min=\"50.0\" max=\"3000.0\" step=\"any\"></label><label>Rider distance (blocks)<input id=\"acPacketShipwrightMaxRiderDistance\" type=\"number\" min=\"4.0\" max=\"64.0\" step=\"any\"></label><label>Rider relative speed (blocks/s)<input id=\"acPacketShipwrightMaxRiderRelativeSpeed\" type=\"number\" min=\"5.0\" max=\"150.0\" step=\"any\"></label></div></div><div class=\"card packetMountCard\"><div class=\"cardHeader\"><h3>Other mounts</h3><span class=\"packetUnit\">mount profile</span></div><div class=\"formGrid\"><label>Horizontal speed (blocks/s)<input id=\"acPacketUnknownMountMaxHorizontalSpeed\" type=\"number\" min=\"20.0\" max=\"300.0\" step=\"any\"></label><label>Vertical speed (blocks/s)<input id=\"acPacketUnknownMountMaxVerticalSpeed\" type=\"number\" min=\"5.0\" max=\"150.0\" step=\"any\"></label><label>Acceleration (blocks/s²)<input id=\"acPacketUnknownMountMaxAcceleration\" type=\"number\" min=\"50.0\" max=\"3000.0\" step=\"any\"></label><label>Rider distance (blocks)<input id=\"acPacketUnknownMountMaxRiderDistance\" type=\"number\" min=\"4.0\" max=\"64.0\" step=\"any\"></label><label>Rider relative speed (blocks/s)<input id=\"acPacketUnknownMountMaxRiderRelativeSpeed\" type=\"number\" min=\"5.0\" max=\"150.0\" step=\"any\"></label></div></div><div class=\"card\"><div class=\"cardHeader\"><h3>Legitimate Movement Exemptions</h3></div>\n        <label class=\"small\"><input id=\"acPacketExemptAdmins\" type=\"checkbox\"> Exempt administrators (root/controlserver privileges)</label><br>\n        <label class=\"small\"><input id=\"acPacketExemptMounts\" type=\"checkbox\"> Exempt mounted players</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Mount/dismount grace (ms)<input id=\"acPacketMountGraceMs\" type=\"number\" min=\"250\" max=\"10000\"></label><label>Engine teleport grace (ms)<input id=\"acPacketEngineTeleportGraceMs\" type=\"number\" min=\"500\" max=\"15000\"></label></div>\n        <label class=\"small\"><input id=\"acPacketTPRunesCompatibility\" type=\"checkbox\"> TP Runes compatibility</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>TP Runes grace (ms)<input id=\"acPacketTPRunesGraceMs\" type=\"number\" min=\"1000\" max=\"20000\"></label></div>\n        <div id=\"acPacketTPRunesState\" class=\"compactNote\" style=\"margin-top:8px\"></div>\n        <label class=\"small\" style=\"margin-top:12px\"><input id=\"acPacketTh3SpawnCompatibility\" type=\"checkbox\"> Th3Essentials /spawn compatibility</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Th3Essentials /spawn grace (ms)<input id=\"acPacketTh3SpawnGraceMs\" type=\"number\" min=\"1000\" max=\"20000\"></label></div>\n        <div id=\"acPacketTh3SpawnState\" class=\"compactNote\" style=\"margin-top:8px\"></div>\n      </div></div></div>\n<div id=\"packetSection-actions\" role=\"tabpanel\" aria-labelledby=\"packetTab-actions\" data-packet-section=\"actions\" hidden><div class=\"packetSectionHeading\"><h3>Reach & mining</h3><p>Validate interactions using server-owned positions and tool timing.</p></div><div class=\"packetCards\"><div class=\"card\"><div class=\"cardHeader\"><h3>Reach</h3></div>\n        <label class=\"small\"><input id=\"acPacketReachEnabled\" type=\"checkbox\"> Enable server-side block reach validation</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Reach tolerance (blocks)<input id=\"acPacketReachTolerance\" type=\"number\" min=\"0.25\" max=\"3\" step=\"0.05\"></label><label>Max latency allowance (blocks)<input id=\"acPacketReachMaxLatency\" type=\"number\" min=\"0\" max=\"3\" step=\"0.05\"></label><label>Position history (ms)<input id=\"acPacketReachHistoryMs\" type=\"number\" min=\"100\" max=\"1500\" step=\"50\"></label><label>Max history rewind (ms)<input id=\"acPacketReachMaxRewindMs\" type=\"number\" min=\"100\" max=\"1500\" step=\"25\"></label><label>Use extra allowance<input id=\"acPacketReachUseExtra\" type=\"number\" min=\"0\" max=\"1.5\" step=\"0.05\"></label><label>Break extra allowance<input id=\"acPacketReachBreakExtra\" type=\"number\" min=\"0\" max=\"1.5\" step=\"0.05\"></label><label>Near-limit strikes<input id=\"acPacketReachStrikes\" type=\"number\" min=\"1\" max=\"8\"></label><label>Strike window (ms)<input id=\"acPacketReachWindowMs\" type=\"number\" min=\"500\" max=\"10000\"></label><label>Strike decay (ms)<input id=\"acPacketReachDecayMs\" type=\"number\" min=\"500\" max=\"10000\"></label><label>Immediate hard excess (blocks)<input id=\"acPacketReachHardExcess\" type=\"number\" min=\"0.5\" max=\"4\" step=\"0.1\"></label></div>\n        <label class=\"small\"><input id=\"acPacketReachLatency\" type=\"checkbox\"> Latency-aware reach compensation</label><br>\n        <label class=\"small\"><input id=\"acPacketReachHistory\" type=\"checkbox\"> Reconcile against recent server-authoritative eye positions</label><br>\n        <label class=\"small\"><input id=\"acPacketRejectReach\" type=\"checkbox\"> Reject confirmed out-of-range block actions</label>\n        <div class=\"compactNote\" style=\"margin-top:8px\">Reach now uses short server-side position history, action-specific allowances, and decaying near-limit strikes. Hard overages still trigger immediately.</div>\n      </div><div class=\"card\"><div class=\"cardHeader\"><h3>Mining Validation v2</h3></div>\n        <label class=\"small\"><input id=\"acPacketMiningEnabled\" type=\"checkbox\"> Enable server-side mining validation</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Connected-burst window (ms)<input id=\"acPacketVeinWindowMs\" type=\"number\" min=\"500\" max=\"5000\"></label><label>Connected break limit<input id=\"acPacketConnectedBreakLimit\" type=\"number\" min=\"8\" max=\"40\"></label><label>Duplicate target window (ms)<input id=\"acPacketMiningDuplicateTargetMs\" type=\"number\" min=\"100\" max=\"1500\"></label></div>\n        <label class=\"small\"><input id=\"acPacketMiningCadenceEnabled\" type=\"checkbox\"> Compare observed adjacent-break cadence with server-derived expected mining time</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Minimum expected time (ms)<input id=\"acPacketMiningMinExpectedMs\" type=\"number\" min=\"100\" max=\"10000\" step=\"25\"></label><label>Suspicious ratio<input id=\"acPacketMiningSuspiciousRatio\" type=\"number\" min=\"0.10\" max=\"0.85\" step=\"0.01\"></label><label>Confirmations<input id=\"acPacketMiningConfirmations\" type=\"number\" min=\"2\" max=\"8\"></label><label>Confirmation window (ms)<input id=\"acPacketMiningConfirmWindowMs\" type=\"number\" min=\"1000\" max=\"30000\" step=\"250\"></label></div>\n        <label class=\"small\"><input id=\"acPacketRejectMiningCadence\" type=\"checkbox\"> Reject confirmed impossible mining cadence</label><br>\n        <label class=\"small\"><input id=\"acPacketRejectMining\" type=\"checkbox\"> Reject connected mining bursts</label>\n        <div class=\"compactNote\" style=\"margin-top:8px\">Expected time uses server block resistance, required tier, block material, held tool/tier, material mining capability, item mining speed and block mining-speed modifiers. Confirmations use a true fixed window. Blocks or held items with custom break logic are retained as informational context only and cannot trigger cadence rejection or correlation risk; connected/vein-burst detection remains independent.</div>\n      </div></div></div>\n<div id=\"packetSection-policy\" role=\"tabpanel\" aria-labelledby=\"packetTab-policy\" data-packet-section=\"policy\" hidden><div class=\"packetSectionHeading\"><h3>Policy & reports</h3><p>Player feedback, lag allowances and independent risk families.</p></div><div class=\"packetCards\"><div class=\"card\"><div class=\"cardHeader\"><h3>Player Warnings</h3></div>\n        <label class=\"small\"><input id=\"acPacketPlayerWarningEnabled\" type=\"checkbox\"> Send a chat message to players when PacketGuard confirms a movement finding</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Warning cooldown (seconds)<input id=\"acPacketPlayerWarningCooldown\" type=\"number\" min=\"3\" max=\"300\" step=\"1\"></label></div>\n        <div class=\"compactNote\" style=\"margin-top:8px\">This is player-facing feedback only. It does not change detection, risk, rollback, kick, or consequence rules.</div>\n      </div><div class=\"card\"><div class=\"cardHeader\"><h3>TPS-Aware Timing</h3></div>\n        <label class=\"small\"><input id=\"acPacketTpsAware\" type=\"checkbox\"> Automatically relax timing-sensitive checks during measured server lag</label>\n        <div id=\"acPacketTpsState\" class=\"compactNote\" style=\"margin-top:8px\">TPS sampler has not reported yet.</div>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Degraded below (% target TPS)<input id=\"acPacketTpsDegradedPct\" type=\"number\" min=\"55\" max=\"99\" step=\"1\"></label><label>Critical below (% target TPS)<input id=\"acPacketTpsCriticalPct\" type=\"number\" min=\"25\" max=\"98\" step=\"1\"></label><label>Maximum timing multiplier<input id=\"acPacketTpsMaxMultiplier\" type=\"number\" min=\"1\" max=\"4\" step=\"0.05\"></label></div>\n        <label class=\"small\"><input id=\"acPacketTpsSuppressCriticalRejects\" type=\"checkbox\"> During critical TPS, observe timing-derived violations instead of rejecting them</label>\n        <div class=\"compactNote\" style=\"margin-top:8px\">Measured from actual main-thread tick cadence versus the server's configured TickTime. Movement soft distance/confirmation timing, Reach rewind/near-strike handling, mining cadence and connected-burst thresholds become more conservative as TPS falls. Extreme movement distance and hard Reach remain enforceable.</div>\n      </div><div class=\"card\"><div class=\"cardHeader\"><h3>Per-Family Live Risk</h3></div>\n        <label class=\"small\"><input id=\"acFamilyRiskEnabled\" type=\"checkbox\"> Keep Movement, Reach, Mining, Packet Abuse and Client Integrity risk isolated</label>\n        <div class=\"compactNote\" style=\"margin-top:8px\">Each family decays independently. Global live risk is the strongest current family instead of a sum across unrelated detectors, so one family cannot prime another for a kick.</div>\n        <div class=\"packetRiskRow\"><b>Movement</b><div class=\"formGrid\"><label>Decay (seconds)<input id=\"acMovementRiskDecay\" type=\"number\" min=\"30\" max=\"3600\"></label><label>Review threshold<input id=\"acMovementRiskReview\" type=\"number\" min=\"1\" max=\"100\"></label><label>Suspicious threshold<input id=\"acMovementRiskSuspicious\" type=\"number\" min=\"1\" max=\"100\"></label></div></div><div class=\"packetRiskRow\"><b>Reach</b><div class=\"formGrid\"><label>Decay (seconds)<input id=\"acReachRiskDecay\" type=\"number\" min=\"30\" max=\"7200\"></label><label>Review threshold<input id=\"acReachRiskReview\" type=\"number\" min=\"1\" max=\"100\"></label><label>Suspicious threshold<input id=\"acReachRiskSuspicious\" type=\"number\" min=\"1\" max=\"100\"></label></div></div><div class=\"packetRiskRow\"><b>Mining</b><div class=\"formGrid\"><label>Decay (seconds)<input id=\"acMiningRiskDecay\" type=\"number\" min=\"30\" max=\"7200\"></label><label>Review threshold<input id=\"acMiningRiskReview\" type=\"number\" min=\"1\" max=\"100\"></label><label>Suspicious threshold<input id=\"acMiningRiskSuspicious\" type=\"number\" min=\"1\" max=\"100\"></label></div></div><div class=\"packetRiskRow\"><b>Packet Abuse</b><div class=\"formGrid\"><label>Decay (seconds)<input id=\"acPacketAbuseRiskDecay\" type=\"number\" min=\"30\" max=\"14400\"></label><label>Review threshold<input id=\"acPacketAbuseRiskReview\" type=\"number\" min=\"1\" max=\"100\"></label><label>Suspicious threshold<input id=\"acPacketAbuseRiskSuspicious\" type=\"number\" min=\"1\" max=\"100\"></label></div></div><div class=\"packetRiskRow\"><b>Client Integrity</b><div class=\"formGrid\"><label>Decay (seconds)<input id=\"acClientIntegrityRiskDecay\" type=\"number\" min=\"60\" max=\"86400\"></label><label>Review threshold<input id=\"acClientIntegrityRiskReview\" type=\"number\" min=\"1\" max=\"100\"></label><label>Suspicious threshold<input id=\"acClientIntegrityRiskSuspicious\" type=\"number\" min=\"1\" max=\"100\"></label></div></div>\n      </div><div class=\"card\"><div class=\"cardHeader\"><h3>Incident Correlation</h3></div>\n        <label class=\"small\"><input id=\"acIncidentCorrelationEnabled\" type=\"checkbox\"> Correlate independent evidence units into one short-lived incident</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Correlation window (seconds)<input id=\"acIncidentCorrelationWindow\" type=\"number\" min=\"10\" max=\"600\"></label><label>Required evidence units<input id=\"acIncidentCorrelationCategories\" type=\"number\" min=\"2\" max=\"5\"></label><label>Legacy maximum risk bonus<input id=\"acIncidentCorrelationMaxBonus\" type=\"number\" min=\"0\" max=\"35\"></label></div>\n        <div class=\"compactNote\">With per-family risk enabled, correlation is supporting evidence only and does not add risk across unrelated families. The maximum bonus setting is retained only for legacy global-risk mode. Occurrences expire on their own timestamps inside the configured window.</div>\n      </div><div class=\"card\"><div class=\"cardHeader\"><h3>Persistent Reports</h3></div>\n        <label class=\"small\"><input id=\"acHistoryEnabled\" type=\"checkbox\"> Save server-behavior incidents to disk</label>\n        <div class=\"formGrid\" style=\"margin-top:10px\"><label>Retention (days)<input id=\"acHistoryRetentionDays\" type=\"number\" min=\"1\" max=\"3650\"></label><label>Maximum records<input id=\"acHistoryMaxRecords\" type=\"number\" min=\"100\" max=\"1000\"></label></div>\n        <div class=\"compactNote\">History is evidence for staff review. It survives disconnects/restarts but is not automatically re-added to a player's live risk score when they reconnect.</div>\n      </div></div></div>\n<div id=\"packetSection-diagnostics\" role=\"tabpanel\" aria-labelledby=\"packetTab-diagnostics\" data-packet-section=\"diagnostics\" hidden><div class=\"packetSectionHeading\"><h3>Diagnostics</h3><p>Trusted transitions and discarded unreliable samples.</p></div><div class=\"packetCards\"><div class=\"card\"><div class=\"cardHeader\"><h3>Diagnostic detail</h3></div><label class=\"packetToggle\"><input id=\"acPacketDiagnosticContextEnabled\" type=\"checkbox\"> Include decision context in reports</label><label class=\"packetToggle\"><input id=\"acPacketDiagnosticSuppressionEnabled\" type=\"checkbox\"> Record suppression reasons</label><div class=\"formGrid\"><label>Speed history samples<input id=\"acPacketDiagnosticSpeedHistorySamples\" type=\"number\" min=\"3\" max=\"16\" step=\"1\"></label></div><p class=\"compactNote\">Adds recent movement history and reasons for discarded samples to investigation evidence.</p></div><div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Trusted Teleport Sources</h3><div class=\"spacer\"></div><span id=\"acTrustedTeleportState\" class=\"small\">Waiting for PacketGuard telemetry…</span></div>\n      <div class=\"compactNote\">Live trust registry for legitimate server-side movement. Counts are deduplicated trust observations since this server process started; they are diagnostics, not Anti-Cheat findings. Expand any source to inspect recent player, from/to coordinates, exact trust path, verification method, and timestamp. Destination-specific integrations remain fail-closed and do not create a general teleport bypass.</div>\n      <div class=\"tableWrap dataScroll\" style=\"margin-top:10px\"><table><thead><tr><th>Source</th><th>Status</th><th>Scope</th><th>Observed</th><th>Last player</th><th>Last seen</th><th>Verification</th></tr></thead><tbody id=\"acTrustedTeleportRows\"><tr><td colspan=\"6\" class=\"muted\">No trusted teleport telemetry loaded.</td></tr></tbody></table></div>\n    </div><div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Packet Suppression Counters</h3><div class=\"spacer\"></div><span id=\"acPacketSuppressionState\" class=\"small\">Waiting for suppression telemetry…</span></div>\n      <div class=\"compactNote\">These counters show cases where PacketGuard deliberately discarded or re-baselined unreliable evidence before it could become a player finding. They are diagnostic-only and reset when the server process restarts.</div>\n      <div id=\"acPacketSuppressionGrid\" class=\"grid\" style=\"margin-top:10px\"><div class=\"card\"><div class=\"metricLabel\">Loading</div><div class=\"metricValue\">—</div><div class=\"small\">Waiting for PacketGuard telemetry.</div></div></div>\n    </div></div></div>\n  </div>\n\n  <div class=\"tabPanel\" data-ac-panel=\"history\">\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Persistent Anti-Cheat Reports</h3><div class=\"spacer\"></div><span id=\"acHistoryState\" class=\"small\">Not loaded.</span></div>\n      <div class=\"toolbar\"><input id=\"acHistoryPlayerFilter\" placeholder=\"Player name or UID\" style=\"min-width:260px\"><select id=\"acHistoryFindingFilter\" title=\"Filter reports by finding\"><option value=\"\">All findings</option></select><button id=\"acHistoryLoad\">Load Reports</button><button id=\"acHistoryClearFilter\">Clear Filters</button><button id=\"acHistoryClearAll\" class=\"danger\">Clear All Reports</button><div class=\"spacer\"></div><span class=\"small\">Stored server-behavior evidence survives disconnects and server restarts.</span></div>\n      <div id=\"acHistoryMetrics\" class=\"grid perfSection\"></div>\n      <div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>Time</th><th>Player</th><th>Severity</th><th>Confidence</th><th>Finding</th><th>Risk</th><th>Position</th><th>Evidence / guidance</th><th>Consequence</th></tr></thead><tbody id=\"acHistoryRows\"><tr><td colspan=\"9\" class=\"muted\">Open this tab or press Load Reports.</td></tr></tbody></table></div>\n    </div>\n  </div>\n\n  <div class=\"tabPanel\" data-ac-panel=\"policy\">\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Client Mod Blacklist</h3><div class=\"spacer\"></div><span id=\"acBlacklistState\" class=\"small\">Loading policy…</span></div>\n      <details class=\"helpDisclosure\"><summary>What fingerprint resolution does</summary><div>NSE downloads the configured number of recent official Mod DB releases in memory, validates the requested mod ID, and stores exact package/content/assembly fingerprints plus structural and identifier-independent IL behavior signatures. It does not install those mods. <b>Resolve Missing Fingerprints</b> only fills blacklist entries that do not yet have Mod DB release fingerprints. <b>Update All Fingerprints from DB</b> force-refreshes every active blacklist entry. The normalized content fingerprint excludes root <code>modinfo.json</code>, so changing only the declared mod ID does not bypass it. IL behavior signatures also ignore metadata-token operands and symbol names, improving detection of simple repacks/renames.</div></details>\n      <div class=\"toolbar\">\n        <select id=\"acBlacklistProfileSelect\" style=\"min-width:220px\" title=\"Saved blacklist profile\"><option value=\"\">No saved profile loaded</option></select>\n        <input id=\"acBlacklistProfileName\" maxlength=\"64\" placeholder=\"Profile name\" style=\"min-width:180px\">\n        <button id=\"acBlacklistProfileLoad\">Load</button>\n        <button id=\"acBlacklistProfileSave\" class=\"primary\">Save Current</button>\n        <button id=\"acBlacklistProfileSaveAs\">Save As New</button>\n        <button id=\"acBlacklistProfileDelete\">Delete</button>\n        <button id=\"acBlacklistLoadDefault\">Load Default Unfair Mods</button>\n      </div>\n      <div id=\"acBlacklistProfileState\" class=\"compactNote\" style=\"margin:8px 0 10px\">Profiles are snapshots. Load one to copy it into the active blacklist, edit the list freely, then use Save Current or Save As New when you want to persist those edits.</div>\n      <div class=\"toolbar\">\n        <input id=\"acBlacklistInput\" maxlength=\"64\" placeholder=\"mod ID, e.g. exampleclientmod\" style=\"min-width:280px\">\n        <button id=\"acBlacklistAdd\" class=\"danger\">Add to Blacklist</button>\n        <div class=\"field\" style=\"min-width:145px\"><label>Release history per mod</label><input id=\"acFingerprintReleaseDepth\" type=\"number\" min=\"1\" max=\"20\" step=\"1\" style=\"width:88px\"></div>\n        <button id=\"acFingerprintReleaseDepthSave\">Save depth</button>\n        <button id=\"acBlacklistResolveMissing\">Resolve Missing Fingerprints</button>\n        <button id=\"acBlacklistRefreshAll\" class=\"primary\">Update All Fingerprints from DB</button>\n        <div class=\"spacer\"></div><span id=\"acRequiredMods\" class=\"small\"></span>\n      </div>\n      <div id=\"acSimilarityState\" class=\"small\" style=\"margin:8px 0 10px\"></div>\n      <div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>Forbidden Mod ID</th><th>Fingerprint Sources</th><th>Package SHA-256</th><th>Normalized Content SHA-256</th><th style=\"width:330px\">Action</th></tr></thead><tbody id=\"acBlacklistRows\"><tr><td colspan=\"5\" class=\"muted\">No blacklist loaded yet.</td></tr></tbody></table></div>\n      <div id=\"acManualFingerprintEditor\" class=\"card\" style=\"display:none;margin-top:12px\">\n        <div class=\"cardHeader\"><h3>Manual Blacklist Fingerprints</h3><div class=\"spacer\"></div><span id=\"acManualFingerprintTarget\" class=\"small\"></span></div>\n        <div class=\"compactNote\">Use this for removed, private, locally archived, or otherwise unavailable client mods. Manual entries are stored separately from Mod DB fingerprints, so <b>Resolve / Refresh</b> will not overwrite them. Exact SHA-256/MVID/structure/IL-behavior matches are immediately included in server-side blacklist evaluation.</div>\n        <div class=\"toolbar\">\n          <div class=\"field grow\"><label>Label</label><input id=\"acManualLabel\" maxlength=\"80\" style=\"width:100%\" placeholder=\"e.g. Removed hack build 2026-08\"></div>\n          <div class=\"field\"><label>Version</label><input id=\"acManualVersion\" maxlength=\"64\" placeholder=\"optional\"></div>\n          <div class=\"field grow\"><label>File name</label><input id=\"acManualFileName\" maxlength=\"160\" style=\"width:100%\" placeholder=\"optional original ZIP/DLL name\"></div>\n        </div>\n        <div class=\"toolbar\">\n          <div class=\"field grow\"><label>Package SHA-256</label><input id=\"acManualPackageSha\" maxlength=\"64\" style=\"width:100%\" placeholder=\"64 hex characters (optional)\"></div>\n          <div class=\"field grow\"><label>Normalized content SHA-256</label><input id=\"acManualContentSha\" maxlength=\"64\" style=\"width:100%\" placeholder=\"64 hex characters (optional)\"></div>\n        </div>\n        <div class=\"toolbar\" style=\"align-items:flex-start\">\n          <div class=\"field grow\"><label>Assembly SHA-256 hashes</label><textarea id=\"acManualAssemblyHashes\" rows=\"4\" style=\"width:100%\" placeholder=\"One per line, comma, or space\"></textarea></div>\n          <div class=\"field grow\"><label>Assembly MVIDs</label><textarea id=\"acManualMvids\" rows=\"4\" style=\"width:100%\" placeholder=\"One GUID per line\"></textarea></div>\n          <div class=\"field grow\"><label>Assembly structure SHA-256 hashes</label><textarea id=\"acManualStructureHashes\" rows=\"4\" style=\"width:100%\" placeholder=\"One per line, comma, or space\"></textarea></div><div class=\"field grow\"><label>Assembly IL behavior SHA-256 hashes</label><textarea id=\"acManualBehaviorHashes\" rows=\"4\" style=\"width:100%\" placeholder=\"Optional; one per line, comma, or space\"></textarea></div>\n        </div>\n        <div class=\"field grow\"><label>Operator notes</label><textarea id=\"acManualNotes\" rows=\"2\" maxlength=\"300\" style=\"width:100%\" placeholder=\"Where the sample came from / why it is blacklisted (optional)\"></textarea></div>\n        <div class=\"toolbar\" style=\"margin-top:10px\"><button id=\"acManualSave\" class=\"danger\">Save Manual Fingerprint</button><button id=\"acManualNew\">New Entry</button><button id=\"acManualClose\">Close</button><div class=\"spacer\"></div><span id=\"acManualState\" class=\"small\"></span></div>\n        <div class=\"tableWrap\" style=\"margin-top:10px\"><table><thead><tr><th>Label</th><th>Version / file</th><th>Exact fingerprints</th><th>Updated</th><th style=\"width:170px\">Action</th></tr></thead><tbody id=\"acManualRows\"><tr><td colspan=\"5\" class=\"muted\">No manual fingerprint entries.</td></tr></tbody></table></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"tabPanel\" data-ac-panel=\"enforcement\">\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><div><h3>Quick Enforcement Setup</h3><div class=\"small\">Configure the common enforcement values here, then fine-tune the generated rules below only if needed.</div></div><div class=\"spacer\"></div><button id=\"acSimpleApply\" class=\"primary\">Apply to Rule Editor</button></div>\n      <div class=\"grid\" style=\"margin-top:10px\">\n        <div class=\"field\"><label>Forbidden fingerprint</label><select id=\"acSimpleForbiddenAction\"><option value=\"Log\">Log only</option><option value=\"Kick\" selected>Kick</option><option value=\"TempBan\">Temporary ban</option></select></div>\n        <div class=\"field\"><label>Missing required client</label><select id=\"acSimpleMissingAction\"><option value=\"Log\">Log only</option><option value=\"Kick\" selected>Kick</option></select></div>\n        <div class=\"field\"><label>Suspicious status</label><select id=\"acSimpleSuspiciousAction\"><option value=\"Log\">Log only</option><option value=\"Freeze\" selected>Freeze for review</option><option value=\"Kick\">Kick</option></select></div>\n        <div class=\"field\"><label>Kick at risk score</label><input id=\"acSimpleKickRisk\" type=\"number\" min=\"1\" max=\"100\" value=\"85\"></div>\n        <div class=\"field\"><label>Temp-ban at risk score</label><input id=\"acSimpleBanRisk\" type=\"number\" min=\"1\" max=\"100\" value=\"95\"></div>\n        <div class=\"field\"><label>Timed action duration</label><input id=\"acSimpleDuration\" maxlength=\"24\" value=\"2h\" placeholder=\"30m / 2h / 1d\"></div>\n      </div>\n      <label class=\"toggleLine\" style=\"margin-top:10px\"><input id=\"acSimpleEnableRiskBan\" type=\"checkbox\" checked> Add a high-risk temporary-ban rule</label>\n      <div class=\"compactNote\" style=\"margin-top:10px\">This does not save immediately. It replaces the visible consequence-rule editor with a clear staged policy, so you can review the generated rules before pressing <b>Save Rules</b>. Advanced rules remain available below.</div>\n    </div>\n\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><div><h3>Enforcement Policy</h3><div class=\"small\">Build clear, staged consequences from evidence without turning every finding into an automatic punishment.</div></div><div class=\"spacer\"></div><span id=\"acConsequenceState\" class=\"small\">Loading policy…</span></div><div id=\"acEnforcementSummary\" class=\"grid\" style=\"margin:10px 0\"></div>\n      <div class=\"compactNote\">Rules can match a finding code, player status, or minimum risk score, then Log, Kick, Temporarily Ban, or Freeze. Kick and timed-ban actions send the expanded reason before disconnecting. When Require Client is enabled, CLIENT_MISSING enters a recovery window after the hello grace period and is disconnected only after that recovery delay; a CLIENT_MISSING Kick rule can override the default player-facing message. Disruptive actions fire once per connection for the same matching evidence.</div>\n      <div class=\"policyPresetBar\">\n        <span class=\"small\" style=\"align-self:center\"><b>Quick policy presets:</b></span>\n        <button data-ac-preset=\"forbidden-log\">Forbidden mod → Log</button>\n        <button data-ac-preset=\"missing-kick\">Missing client → Kick</button>\n        <button data-ac-preset=\"suspicious-freeze\">Suspicious → Freeze 10m</button><button data-ac-preset=\"highrisk-kick\">Risk ≥ 80 → Kick</button>\n      </div>\n      <details class=\"helpDisclosure\"><summary>Finding codes and message placeholders</summary><div>Common codes: <code>FORBIDDEN_MOD</code>, <code>FORBIDDEN_MOD_FINGERPRINT</code>, <code>FORBIDDEN_ASSEMBLY_FINGERPRINT</code>, <code>FORBIDDEN_ASSEMBLY_SIMILARITY</code>, <code>CLIENT_BUILD_UNAPPROVED</code>, <code>HOTKEY_SUSPICIOUS_NAME</code>, <code>CLIENT_COMMAND_SUSPICIOUS</code>, <code>HOTKEY_BLACKLIST_MATCH</code>, <code>HOTKEY_BLACKLIST_OWNER_MATCH</code>, <code>CLIENT_COMMAND_BLACKLIST_MATCH</code>, <code>MOD_CANONICAL_MISMATCH</code>, <code>MOD_DLL_SET_MISMATCH</code>, <code>ASSEMBLY_SIZE_MISMATCH</code>, <code>PROTECTED_ASSET_MODIFIED</code>, <code>PROTECTED_ASSET_DIGEST_MISMATCH</code>, <code>RUNTIME_SURFACE_CHANGED</code>, <code>CLIENT_MISSING</code>, <code>SCAN_TIMEOUT</code>, <code>HEARTBEAT_TIMEOUT</code>, <code>PROTOCOL_MISMATCH</code>, <code>INVALID_REPORT</code>, <code>DUPLICATE_MOD_ID</code>, <code>DUPLICATE_ASSEMBLY_IDENTITY</code>, <code>RUNTIME_UNASSOCIATED_ASSEMBLY_ADDED</code>, <code>RUNTIME_DYNAMIC_ASSEMBLY_ADDED</code>, <code>CLIENT_SELF_CHANGED_DURING_SESSION</code>, <code>RUNTIME_DEBUGGER_ATTACHED</code>, <code>RUNTIME_INSTRUMENTATION_PRESENT</code>, <code>RUNTIME_GENERATION_REGRESSED</code>. Placeholders: <code>{player}</code>, <code>{status}</code>, <code>{risk}</code>, <code>{code}</code>, <code>{subject}</code>, <code>{duration}</code>.</div></details>\n      <div class=\"toolbar\">\n        <button id=\"acConsequenceAdd\">Add Blank Rule</button>\n        <button id=\"acConsequenceSave\" class=\"primary\">Save Rules</button>\n        <label class=\"small\"><input id=\"acConsequenceApplyCurrent\" type=\"checkbox\"> Apply to matching online players immediately</label>\n        <div class=\"spacer\"></div><span class=\"small\">Defaults remain log-only until you explicitly configure enforcement.</span>\n      </div>\n      <datalist id=\"acTriggerSuggestions\"><option value=\"FORBIDDEN_MOD\"><option value=\"FORBIDDEN_MOD_FINGERPRINT\"><option value=\"FORBIDDEN_ASSEMBLY_FINGERPRINT\"><option value=\"FORBIDDEN_ASSEMBLY_SIMILARITY\"><option value=\"CLIENT_BUILD_UNAPPROVED\"><option value=\"HOTKEY_SUSPICIOUS_NAME\"><option value=\"CLIENT_COMMAND_SUSPICIOUS\"><option value=\"HOTKEY_BLACKLIST_MATCH\"><option value=\"HOTKEY_BLACKLIST_OWNER_MATCH\"><option value=\"CLIENT_COMMAND_BLACKLIST_MATCH\"><option value=\"MOD_CANONICAL_MISMATCH\"><option value=\"MOD_DLL_SET_MISMATCH\"><option value=\"ASSEMBLY_SIZE_MISMATCH\"><option value=\"FORBIDDEN_ASSEMBLY_SIZE_MATCH\"><option value=\"CORE_ASSEMBLY_HASH_MISMATCH\"><option value=\"CORE_ASSEMBLY_VERSION_MISMATCH\"><option value=\"CORE_ASSEMBLY_MISSING\"><option value=\"PROTECTED_ASSET_MODIFIED\"><option value=\"PROTECTED_ASSET_DIGEST_MISMATCH\"><option value=\"PROTECTED_ASSET_MISSING\"><option value=\"RUNTIME_SURFACE_CHANGED\"><option value=\"CLIENT_MISSING\"><option value=\"SCAN_TIMEOUT\"><option value=\"HEARTBEAT_TIMEOUT\"><option value=\"PROTOCOL_MISMATCH\"><option value=\"INVALID_REPORT\"><option value=\"PACKET_UNAUTHORIZED_MOVEMENT\"><option value=\"PACKET_BLOCK_REACH\"><option value=\"PACKET_CONNECTED_BREAK_BURST\"><option value=\"Suspicious\"><option value=\"Review\"></datalist>\n      <div class=\"tableWrap dataScrollTall\"><table><thead><tr><th>On</th><th>Name</th><th>Trigger</th><th>Value</th><th>Subject</th><th>Action</th><th>Duration</th><th>Message</th><th></th></tr></thead><tbody id=\"acConsequenceRows\"><tr><td colspan=\"9\" class=\"muted\">No consequence rules loaded yet.</td></tr></tbody></table></div>\n    </div>\n  </div>\n\n  <div class=\"tabPanel\" data-ac-panel=\"integrity\">\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Client Build Integrity</h3><div class=\"spacer\"></div><span id=\"acIntegrityState\" class=\"small\">Loading policy…</span></div>\n      <details class=\"helpDisclosure\" open><summary>Approved-build lock</summary><div>Protocol v9 startup attestation cross-checks the client mod inventory against loaded assemblies and the Client Integrity build fingerprint, adds structural fingerprints, canonical server-mod comparison, Harmony patch census, runtime surface monitoring, protected asset validation, scanner telemetry, and heartbeat-triggered rescans when monitored runtime state changes. Add the SHA-256 from a client build you trust, then enable approved-build enforcement. This blocks ordinary recompiles/renames, but it does not make a fully hostile user-space client impossible to forge.</div></details>\n      <div class=\"toolbar\" style=\"margin-top:10px\">\n        <input id=\"acIntegrityHashInput\" maxlength=\"64\" placeholder=\"approved client DLL/package SHA-256\" style=\"min-width:430px\">\n        <button id=\"acIntegrityHashAdd\">Add Approved Hash</button>\n        <label class=\"small\"><input id=\"acIntegrityRequire\" type=\"checkbox\"> Require approved client build</label>\n      </div>\n      <div class=\"tableWrap dataScroll\"><table><thead><tr><th>Approved SHA-256</th><th style=\"width:150px\">Action</th></tr></thead><tbody id=\"acIntegrityHashRows\"><tr><td colspan=\"2\" class=\"muted\">No approved hashes loaded.</td></tr></tbody></table></div>\n    </div>\n    <div class=\"card perfSection\" style=\"margin-top:12px\">\n      <div class=\"cardHeader\"><h3>Runtime Surface Integrity</h3><div class=\"spacer\"></div><span id=\"acRuntimeSurfaceState\" class=\"small\">Loading runtime surface policy…</span></div>\n      <div class=\"compactNote\"><b>Supporting evidence:</b> suspicious hotkey and client-command names are low-confidence signals and do not justify punishment by themselves. <b>Stronger evidence:</b> same-ID/version server-shared mods whose normalized content differs from the server copy, and protected texture/shader assets whose final loaded bytes differ from the server baseline. A fully hostile client can still forge user-space reports, so PacketGuard and server-authoritative behavior remain the strongest enforcement layer.</div>\n      <div class=\"grid\" style=\"margin-top:10px\">\n        <div class=\"card\"><div class=\"metricLabel\">Hotkey surface</div><div id=\"acSurfaceHotkeys\" class=\"metricValue\">—</div><div class=\"small\">Searches registered keybind code/name text for configurable suspicious terminology.</div></div>\n        <div class=\"card\"><div class=\"metricLabel\">Client commands</div><div id=\"acSurfaceCommands\" class=\"metricValue\">—</div><div class=\"small\">Searches registered client chat commands and subcommands for the same weak signatures.</div></div>\n        <div class=\"card\"><div class=\"metricLabel\">Protected server baseline</div><div id=\"acSurfaceCanonical\" class=\"metricValue\">—</div><div class=\"small\">Primary integrity reference for server-shared mods. Compares exact server version, normalized content and DLL SHA-256 before consulting ModDB.</div></div>\n        <div class=\"card\"><div class=\"metricLabel\">Protected assets</div><div id=\"acSurfaceAssets\" class=\"metricValue\">—</div><div class=\"small\">Hashes configured final loaded texture/shader assets and compares them with the server challenge baseline.</div></div>\n      </div>\n    </div>\n    <div class=\"card perfSection\" style=\"margin-top:12px\">\n      <div class=\"cardHeader\"><h3>Suspicious Package Transfer</h3><div class=\"spacer\"></div><span id=\"acEvidenceState\" class=\"small\">Loading transfer policy…</span></div>\n      <div class=\"compactNote\"><b>Manual, bounded, and player-authorized:</b> administrators may request only a loaded mod package already associated with suspicious Anti-Cheat evidence. The popup appears <b>only after an administrator manually clicks Collect ZIP</b> for that player/mod; scans never open it automatically. No bytes are read or sent until the player selects <b>Agree &amp; Transfer</b>. Declining, closing, or pressing Escape triggers the configurable decline policy shown to the player. Accepted ZIPs are stored under <code>ModConfig/NewfiesServerEssentialsSuite/SuspectedHacks</code> and are <b>automatically deleted 15 days after collection</b>; the small JSON authorization/provenance sidecar is retained for audit history.</div>\n      <div class=\"formGrid\" style=\"margin-top:10px\">\n        <label class=\"toggleLine\"><input id=\"acEvidenceEnabled\" type=\"checkbox\"> Enable suspicious package transfer requests</label>\n        <label>Maximum package (MB)<input id=\"acEvidenceMaxMb\" type=\"number\" min=\"8\" max=\"256\" step=\"1\"></label>\n        <label>Transfer timeout (seconds)<input id=\"acEvidenceTimeout\" type=\"number\" min=\"30\" max=\"300\" step=\"5\"></label>\n        <label>Upload cap (KB/s)<input id=\"acEvidenceUploadKbps\" type=\"number\" min=\"128\" max=\"4096\" step=\"64\"></label>\n        <label>Decline consequence<select id=\"acEvidenceDeclineAction\"><option value=\"None\">None</option><option value=\"Disconnect\">Disconnect</option><option value=\"TempBan\">Temporary Ban</option></select></label>\n        <label id=\"acEvidenceDeclineHoursWrap\">Temporary ban (hours)<input id=\"acEvidenceDeclineHours\" type=\"number\" min=\"1\" max=\"720\" step=\"1\"></label>\n      </div>\n      <div class=\"toolbar\" style=\"margin-top:8px\"><button id=\"acEvidenceSave\" class=\"primary\">Save Transfer Settings</button><div class=\"spacer\"></div><span id=\"acEvidenceStorage\" class=\"small\"></span></div>\n    </div>\n    <div class=\"card perfSection\" style=\"margin-top:12px\">\n      <div class=\"cardHeader\"><div><h3>Advanced / Full Anti-Cheat Configuration</h3><div class=\"small\">Every Anti-Cheat configuration value is available here, including advanced PacketGuard thresholds, risk policy, runtime terms, protected assets, blacklist data and consequence configuration.</div></div><div class=\"spacer\"></div><span id=\"acFullConfigState\" class=\"small\">Not loaded.</span></div>\n      <div class=\"compactNote\"><b>Advanced:</b> this editor writes the complete Anti-Cheat configuration. The module Enabled state and SchemaVersion are intentionally lifecycle-managed elsewhere and are preserved on save. Use the dedicated controls above for common settings.</div>\n      <div class=\"toolbar\" style=\"margin:10px 0\"><button id=\"acFullConfigLoad\">Load Full Configuration</button><button id=\"acFullConfigFormat\">Format JSON</button><button id=\"acFullConfigSave\" class=\"primary\">Save Full Configuration</button><div class=\"spacer\"></div><span class=\"small\">A full save is audited and re-evaluates active sessions.</span></div>\n      <textarea id=\"acFullConfigJson\" spellcheck=\"false\" style=\"width:100%;min-height:520px;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px;line-height:1.45\" placeholder=\"Load the current Anti-Cheat configuration…\"></textarea>\n    </div>\n  </div>\n</section>\n\n\n<section id=\"chatguard\">\n  <div class=\"pageTitle\"><div><h2>ChatGuard</h2><div class=\"subtitle\">Optional standalone chat moderation. ChatGuard runs without Server Suite; this page appears as an integration/control surface when the separate module is installed.</div></div></div>\n  <div class=\"toolbar\"><button id=\"cgRefresh\">Refresh</button><button id=\"cgSave\" class=\"primary\">Save Settings</button><div class=\"spacer\"></div><span id=\"cgState\" class=\"small\">Not loaded.</span></div>\n  <div id=\"cgMetrics\" class=\"grid perfSection\"></div>\n  <div id=\"cgUnavailable\" class=\"infoBox perfSection\" style=\"display:none\"><b>ChatGuard is not installed.</b> Install the standalone <code>NewfiesChatGuard</code> server mod to enable moderation. Server Suite is optional for ChatGuard itself.</div>\n  <div class=\"sectionTabs perfSection\" id=\"cgTabs\">\n    <button id=\"cgTabModeration\" class=\"active\" data-cg-tab=\"moderation\">Moderation & Rules</button>\n    <button id=\"cgTabBanned\" data-cg-tab=\"banned\">Banned Words</button>\n  </div>\n  <div id=\"cgMainPanel\">\n  <div class=\"grid2 perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Protection Posture</h3><div class=\"spacer\"></div><span id=\"cgPostureChip\" class=\"badge\">Not loaded</span></div>\n      <div id=\"cgPosture\" class=\"infoBox\">Load ChatGuard to inspect enforcement posture.</div>\n      <div id=\"cgRuleHits\" class=\"small\" style=\"margin-top:10px\">No rule telemetry yet.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Rule Tester</h3><div class=\"spacer\"></div><span class=\"small\">Dry-run only · no sanctions or counters</span></div>\n      <div class=\"webMapSettings\">\n        <label for=\"cgTestTarget\">Player context</label><div><input id=\"cgTestTarget\" type=\"text\" list=\"cgOnlinePlayers\" placeholder=\"Optional online player\"><div class=\"small\">Add a player to test exemptions and live spam/repeat history.</div></div>\n        <label for=\"cgTestMessage\">Message</label><div><textarea id=\"cgTestMessage\" rows=\"3\" maxlength=\"4000\" spellcheck=\"false\" placeholder=\"Paste a message to test against the current rules\"></textarea></div>\n      </div>\n      <div class=\"toolbar\" style=\"margin-top:10px\"><button id=\"cgTestRun\" class=\"primary\">Run Dry Test</button></div>\n      <div id=\"cgTestResult\" class=\"infoBox\" style=\"margin-top:10px\">Requires ChatGuard 2.1.1+.</div>\n    </div>\n  </div>\n  <datalist id=\"cgOnlinePlayers\"></datalist>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Core Moderation</h3><div class=\"spacer\"></div><span class=\"small\">Stored by the standalone module in <code>NewfiesChatGuard.json</code></span></div>\n    <div class=\"webMapSettings\">\n      <label for=\"cgEnabled\">ChatGuard</label><div><label><input id=\"cgEnabled\" type=\"checkbox\"> Enable ChatGuard moderation</label></div>\n      <label for=\"cgMode\">Mode</label><div><select id=\"cgMode\"><option value=\"Enforce\">Enforce</option><option value=\"LogOnly\">Log only</option></select><div class=\"small\">Log only records matches without applying automatic rule actions. Explicit staff mutes remain staff actions.</div></div>\n      <label for=\"cgNotify\">Player notices</label><div><label><input id=\"cgNotify\" type=\"checkbox\"> Tell players when ChatGuard blocks/warns/mutes them</label></div>\n      <label for=\"cgPrefix\">Notice prefix</label><div><input id=\"cgPrefix\" type=\"text\" maxlength=\"80\" value=\"[ChatGuard]\"></div>\n      <label for=\"cgExemptRoles\">Exempt roles</label><div><input id=\"cgExemptRoles\" type=\"text\" maxlength=\"300\" placeholder=\"admin, moderator\"><div class=\"small\">Comma-separated Vintage Story role codes/names.</div></div>\n      <label for=\"cgExemptUids\">Exempt PlayerUIDs</label><div><textarea id=\"cgExemptUids\" rows=\"3\" spellcheck=\"false\" placeholder=\"One PlayerUID per line\"></textarea></div>\n      <label for=\"cgAuditPreview\">Audit preview</label><div><input id=\"cgAuditPreview\" type=\"number\" min=\"0\" max=\"500\" value=\"160\"><div class=\"small\">Characters of the moderated message stored in ChatGuard's JSONL audit. Set to 0 to store no message text.</div></div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Automatic Rules</h3><div class=\"spacer\"></div><span class=\"small\">Each rule can block, warn, temporarily mute, or kick.</span></div>\n    <div class=\"tableWrap\"><table><thead><tr><th>Rule</th><th>Enabled</th><th>Session hits</th><th>Threshold</th><th>Action</th><th>Mute minutes</th></tr></thead><tbody>\n      <tr><td><b>Flood / spam</b><div class=\"small\">Too many messages in a short window.</div></td><td><input id=\"cgSpamEnabled\" type=\"checkbox\"></td><td id=\"cgHitSpam\">0</td><td><input id=\"cgSpamMax\" type=\"number\" min=\"2\" max=\"30\" style=\"width:72px\"> msgs / <input id=\"cgSpamWindow\" type=\"number\" min=\"1\" max=\"60\" style=\"width:72px\"> sec</td><td><select id=\"cgSpamAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select></td><td><input id=\"cgSpamMute\" type=\"number\" min=\"1\" max=\"10080\" style=\"width:90px\"></td></tr>\n      <tr><td><b>Repeated message</b><div class=\"small\">Same normalized message repeated.</div></td><td><input id=\"cgRepeatEnabled\" type=\"checkbox\"></td><td id=\"cgHitRepeat\">0</td><td><input id=\"cgRepeatMax\" type=\"number\" min=\"2\" max=\"12\" style=\"width:72px\"> repeats / <input id=\"cgRepeatWindow\" type=\"number\" min=\"2\" max=\"120\" style=\"width:72px\"> sec</td><td><select id=\"cgRepeatAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select></td><td><input id=\"cgRepeatMute\" type=\"number\" min=\"1\" max=\"10080\" style=\"width:90px\"></td></tr>\n      <tr><td><b>Excessive caps</b></td><td><input id=\"cgCapsEnabled\" type=\"checkbox\"></td><td id=\"cgHitCaps\">0</td><td>At least <input id=\"cgCapsLetters\" type=\"number\" min=\"4\" max=\"200\" style=\"width:72px\"> letters and <input id=\"cgCapsPercent\" type=\"number\" min=\"50\" max=\"100\" style=\"width:72px\">% uppercase</td><td><select id=\"cgCapsAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select></td><td><input id=\"cgCapsMute\" type=\"number\" min=\"1\" max=\"10080\" style=\"width:90px\"></td></tr>\n      <tr><td><b>Links / domains</b><div class=\"small\">Blocks detected links unless the host is allowlisted below.</div></td><td><input id=\"cgLinksEnabled\" type=\"checkbox\"></td><td id=\"cgHitLinks\">0</td><td><textarea id=\"cgLinksAllowed\" rows=\"3\" spellcheck=\"false\" placeholder=\"example.com&#10;mods.vintagestory.at\"></textarea></td><td><select id=\"cgLinksAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select></td><td><input id=\"cgLinksMute\" type=\"number\" min=\"1\" max=\"10080\" style=\"width:90px\"></td></tr>\n      <tr><td><b>Mention spam</b></td><td><input id=\"cgMentionsEnabled\" type=\"checkbox\"></td><td id=\"cgHitMentions\">0</td><td>More than <input id=\"cgMentionsMax\" type=\"number\" min=\"1\" max=\"30\" style=\"width:72px\"> @mentions</td><td><select id=\"cgMentionsAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select></td><td><input id=\"cgMentionsMute\" type=\"number\" min=\"1\" max=\"10080\" style=\"width:90px\"></td></tr>\n      <tr><td><b>Message length</b></td><td><input id=\"cgLengthEnabled\" type=\"checkbox\"></td><td id=\"cgHitLength\">0</td><td>Max <input id=\"cgLengthMax\" type=\"number\" min=\"32\" max=\"4000\" style=\"width:90px\"> chars</td><td><select id=\"cgLengthAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select></td><td><input id=\"cgLengthMute\" type=\"number\" min=\"1\" max=\"10080\" style=\"width:90px\"></td></tr>\n      <tr><td><b>Blocked words / phrases</b></td><td><input id=\"cgTermsEnabled\" type=\"checkbox\"></td><td id=\"cgHitTerms\">0</td><td><textarea id=\"cgTermsList\" rows=\"4\" spellcheck=\"false\" placeholder=\"One word or phrase per line\"></textarea></td><td><select id=\"cgTermsAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select></td><td><input id=\"cgTermsMute\" type=\"number\" min=\"1\" max=\"10080\" style=\"width:90px\"></td></tr>\n    </tbody></table></div>\n  </div>\n\n  <div class=\"grid2 perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Warning Escalation</h3></div>\n      <div class=\"webMapSettings\">\n        <label for=\"cgEscalationEnabled\">Escalation</label><div><label><input id=\"cgEscalationEnabled\" type=\"checkbox\"> Automatically mute after repeated warnings</label></div>\n        <label for=\"cgEscalationWarnings\">Threshold</label><div><input id=\"cgEscalationWarnings\" type=\"number\" min=\"2\" max=\"20\" value=\"3\"> warnings</div>\n        <label for=\"cgEscalationWindow\">Window</label><div><input id=\"cgEscalationWindow\" type=\"number\" min=\"1\" max=\"10080\" value=\"60\"> minutes</div>\n        <label for=\"cgEscalationMute\">Mute duration</label><div><input id=\"cgEscalationMute\" type=\"number\" min=\"1\" max=\"10080\" value=\"10\"> minutes</div>\n      </div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Manual Moderation</h3></div>\n      <div class=\"webMapSettings\">\n        <label for=\"cgManualTarget\">Online player</label><div><input id=\"cgManualTarget\" type=\"text\" list=\"cgOnlinePlayers\" placeholder=\"Player name or UID\"></div>\n        <label for=\"cgManualMinutes\">Mute minutes</label><div><input id=\"cgManualMinutes\" type=\"number\" min=\"1\" max=\"43200\" value=\"10\"><div class=\"small\">Temporary mutes can be up to 30 days.</div></div>\n        <label for=\"cgManualPermanent\">Permanent</label><div><label><input id=\"cgManualPermanent\" type=\"checkbox\"> Permanent mute instead of a timed mute</label></div>\n        <label for=\"cgManualReason\">Reason</label><div><input id=\"cgManualReason\" type=\"text\" maxlength=\"240\" placeholder=\"Reason shown to the player\"></div>\n      </div>\n      <div class=\"toolbar\" style=\"margin-top:12px\"><button id=\"cgManualInspect\">Inspect</button><button id=\"cgManualWarn\">Warn</button><button id=\"cgManualMute\" class=\"warnButton\">Mute</button></div>\n      <div id=\"cgManualInfo\" class=\"infoBox\" style=\"margin-top:10px\">Enter a player name or UID and choose Inspect to view ChatGuard moderation state.</div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Active Mutes</h3><div class=\"spacer\"></div><span class=\"small\">Equivalent to <code>/cgmutes</code>; permanent mutes are labeled explicitly.</span></div>\n    <div class=\"tableWrap\"><table><thead><tr><th>Player</th><th>Duration / Expires</th><th>Reason</th><th>Actor</th><th>Action</th></tr></thead><tbody id=\"cgMuteRows\"><tr><td colspan=\"5\" class=\"muted\">No active ChatGuard mutes.</td></tr></tbody></table></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Active Warnings</h3><div class=\"spacer\"></div><span class=\"small\">Equivalent to <code>/cgwarnings</code> and <code>/cgclearwarnings</code>.</span></div>\n    <div class=\"tableWrap\"><table><thead><tr><th>Player</th><th>Warnings</th><th>Window</th><th>Oldest expires</th><th>Action</th></tr></thead><tbody id=\"cgWarningRows\"><tr><td colspan=\"5\" class=\"muted\">No active ChatGuard warnings.</td></tr></tbody></table></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Recent Moderation Activity</h3><div class=\"spacer\"></div><span class=\"small\">Session view; ChatGuard also writes its own append-only JSONL audit.</span></div>\n    <div class=\"toolbar\"><input id=\"cgRecentSearch\" type=\"text\" placeholder=\"Filter player, rule, action or detail\" style=\"min-width:280px\"><select id=\"cgRecentAction\"><option value=\"\">All actions</option><option>Warn</option><option>Warn+Mute</option><option>Block</option><option>Mute</option><option>Kick</option><option>LogOnly</option><option>Unmute</option><option>ClearWarnings</option></select><button id=\"cgRecentClearFilter\">Clear filter</button></div>\n    <div class=\"tableWrap\"><table><thead><tr><th>Time</th><th>Player</th><th>Rule</th><th>Action</th><th>Detail</th><th>Message preview</th></tr></thead><tbody id=\"cgRecentRows\"><tr><td colspan=\"6\" class=\"muted\">No ChatGuard actions recorded this session.</td></tr></tbody></table></div>\n  </div>\n\n  <div class=\"infoBox perfSection\"><b>Standalone design:</b> ChatGuard owns its moderation logic, configuration, commands and state. Server Suite __NSS_VERSION__ mirrors the ChatGuard moderation surface here, including dry-run rule testing, per-rule session telemetry, temporary/permanent mutes, warnings, warning clearing, moderation inspection, and filtered audit activity. Removing the Suite does not disable ChatGuard.</div>\n  </div>\n  <div id=\"cgBannedPanel\" style=\"display:none\">\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><div><h3>Banned Words & Phrases</h3><div class=\"small\">Manage ChatGuard's BlockedTerms list without editing the full rule table.</div></div><div class=\"spacer\"></div><button id=\"cgBannedSave\" class=\"primary\">Save Banned Words</button></div>\n      <div class=\"webMapSettings\">\n        <label for=\"cgBannedEnabled\">Rule</label><div><label><input id=\"cgBannedEnabled\" type=\"checkbox\"> Enable banned words / phrases</label></div>\n        <label for=\"cgBannedAction\">Action</label><select id=\"cgBannedAction\"><option>Block</option><option>Warn</option><option>Mute</option><option>Kick</option></select>\n        <label for=\"cgBannedMute\">Mute minutes</label><input id=\"cgBannedMute\" type=\"number\" min=\"1\" max=\"10080\" value=\"5\">\n        <label for=\"cgBannedAdd\">Add one</label><div class=\"row\"><input id=\"cgBannedAdd\" class=\"grow\" type=\"text\" maxlength=\"120\" placeholder=\"word or phrase\"><button id=\"cgBannedAddButton\">Add</button></div>\n        <label for=\"cgBannedBulk\">Bulk add</label><div><textarea id=\"cgBannedBulk\" rows=\"4\" spellcheck=\"false\" placeholder=\"One word or phrase per line\"></textarea><button id=\"cgBannedBulkButton\" style=\"margin-top:6px\">Add Lines</button></div>\n        <label for=\"cgBannedSearch\">Search</label><input id=\"cgBannedSearch\" type=\"search\" placeholder=\"Filter banned words\">\n      </div>\n      <div class=\"tableWrap dataScroll\" style=\"margin-top:12px\"><table><thead><tr><th>Word / phrase</th><th>Action</th></tr></thead><tbody id=\"cgBannedRows\"><tr><td colspan=\"2\" class=\"muted\">No banned words configured.</td></tr></tbody></table></div>\n      <div class=\"compactNote\" style=\"margin-top:10px\">Duplicates are ignored. ChatGuard still validates the final list server-side when settings are saved.</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"reports\">\n  <div class=\"pageTitle\">\n    <div><h2>Reports & Tickets</h2><div class=\"subtitle\">Player-submitted issue reports with assignment, private notes, status history, and staff workflow.</div></div>\n  </div>\n  <div class=\"toolbar\">\n    <button id=\"reportsRefresh\">Refresh</button>\n    <div class=\"segmented\" id=\"reportsFilter\">\n      <button data-report-status=\"open\" class=\"active\">Open</button>\n      <button data-report-status=\"investigating\">Investigating</button>\n      <button data-report-status=\"resolved\">Resolved</button>\n      <button data-report-status=\"all\">All</button>\n    </div>\n    <div class=\"spacer\"></div><span id=\"reportsState\" class=\"small\">Not loaded.</span>\n  </div>\n  <div id=\"reportsMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Command Provider</h3><div class=\"spacer\"></div><span id=\"reportRootCommand\" class=\"small\"></span></div>\n    <div class=\"small\"><code>/report &lt;issue&gt;</code> is registered only when no other mod already owns the root command. <code>/nse report</code> always remains available. Staff management commands use <code>/nse reports</code>, <code>/nse reportstatus</code>, <code>/nse reportassign</code>, and <code>/nse reportnote</code>.</div>\n  </div>\n  <div class=\"reportLayout\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Report Queue</h3><div class=\"spacer\"></div><span id=\"reportsQueueMeta\" class=\"small\"></span></div>\n      <div class=\"tableWrap reportQueueScroll\"><table><thead><tr><th>ID</th><th>Status</th><th>Reporter</th><th>Issue</th><th>Assigned</th><th>Updated</th></tr></thead><tbody id=\"reportsRows\"><tr><td colspan=\"6\" class=\"muted\">Loading reports…</td></tr></tbody></table></div>\n    </div>\n    <div id=\"reportDetail\" class=\"card reportDetailScroll\"><div class=\"emptyAction\"><b>Select a report.</b><br>Its timeline, notes, assignment and workflow controls will appear here.</div></div>\n  </div>\n</section>\n\n<section id=\"admin\">\n  <div class=\"pageTitle\">\n    <div><h2>Player Administration</h2><div class=\"subtitle\">Moderation, player status, read-only inventory inspection, staff notes, maintenance, cleanup, and scheduled shutdown controls. Every action is audited.</div></div>\n  </div>\n  <div class=\"toolbar\">\n    <button id=\"adminRefresh\">Refresh</button>\n    <button id=\"adminUndo\">Undo Last Reversible Action</button>\n    <div class=\"spacer\"></div>\n    <span id=\"adminState\" class=\"small\"></span>\n  </div>\n  <div id=\"adminMetrics\" class=\"grid perfSection\"></div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Players</h3><div class=\"spacer\"></div><span class=\"small\">Online and offline players are separated for faster moderation. Offline players are ordered by Last Seen.</span></div>\n    <div class=\"tableTools\" style=\"margin-top:8px\">\n      <div class=\"segmented\" id=\"adminPlayerTabs\">\n        <button id=\"adminPlayersOnlineTab\" data-player-tab=\"online\" class=\"active\">Online <span id=\"adminOnlineCount\">0</span></button>\n        <button id=\"adminPlayersOfflineTab\" data-player-tab=\"offline\">Offline <span id=\"adminOfflineCount\">0</span></button>\n      </div>\n      <input id=\"adminPlayerFilter\" placeholder=\"Search name, UID, or role…\" style=\"min-width:240px\">\n      <select id=\"adminLastSeenFilter\" title=\"Offline Last Seen window\"><option value=\"all\">Last seen: anytime</option><option value=\"86400\">Last 24h</option><option value=\"604800\">Last 7d</option><option value=\"2592000\">Last 30d</option><option value=\"7776000\">Last 90d</option></select>\n      <select id=\"adminPlayerSort\" title=\"Player sort\"><option value=\"recent\">Most recent</option><option value=\"name\">Name</option><option value=\"playtime\">Playtime</option><option value=\"warnings\">Warnings</option></select>\n      <div class=\"spacer\"></div>\n      <span id=\"adminPlayerTabSummary\" class=\"small\"></span>\n    </div>\n    <div class=\"tableWrap dataScrollTall\">\n      <table>\n        <thead><tr><th>Player</th><th>Status</th><th>Role</th><th>Ping</th><th>Player List</th><th>Last Seen</th><th>Playtime</th><th>Warnings</th><th>Restrictions</th><th>Manage</th></tr></thead>\n        <tbody id=\"adminPlayerRows\"><tr><td colspan=\"10\" class=\"muted\">Loading players…</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div id=\"adminPlayerDetail\" style=\"display:none\">\n__NSS_INVESTIGATION_HTML__\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3 id=\"adminPlayerTitle\">Player</h3><div class=\"spacer\"></div><span id=\"adminPlayerMeta\" class=\"small\"></span></div>\n      <div id=\"adminPlayerSummary\" class=\"grid\"></div>\n      <div class=\"quickActions\" style=\"margin-top:12px\">\n        <button id=\"adminWarn\">Warn</button>\n        <button id=\"adminMute\">Mute</button>\n        <button id=\"adminUnmute\">Unmute</button>\n        <button id=\"adminTempBan\" class=\"danger\">Temp Ban</button>\n        <button id=\"adminUnban\">Clear Temp Ban</button>\n        <button id=\"adminFreeze\">Freeze</button>\n        <button id=\"adminUnfreeze\">Unfreeze</button>\n        <button id=\"adminKick\" class=\"danger\">Kick</button>\n        <button id=\"adminHeal\">Heal</button>\n        <button id=\"adminFeed\">Feed</button>\n        <button id=\"adminRevive\">Revive</button>\n        <button id=\"adminSmite\" class=\"danger\">Smite</button>\n        <button id=\"adminJail\" class=\"danger\">Jail</button>\n        <button id=\"adminUnjail\">Release Jail</button>\n        <button id=\"adminSendBack\">Send Back</button>\n        <button id=\"adminAllowCharSelOnce\">Allow Char Select Once</button>\n        <button id=\"adminAddNote\">Add Staff Note</button><button id=\"adminCopyPlayer\">Copy Player Summary</button>\n      </div>\n      <p class=\"small\">Teleport-to-player and Bring Here stay as in-game commands (<b>/goto</b>, <b>/bring</b>) because a browser session has no physical player entity. The player <b>/back</b> command uses the shared Suite teleport history.</p>\n    </div>\n\n    <div class=\"grid perfSection\">\n      <div class=\"card\">\n        <div class=\"cardHeader\"><h3>Warnings</h3><div class=\"spacer\"></div><span id=\"adminWarningCount\" class=\"small\"></span></div>\n        <div class=\"tableWrap\"><table><thead><tr><th>ID</th><th>Time</th><th>By</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody id=\"adminWarningRows\"></tbody></table></div>\n      </div>\n      <div class=\"card\">\n        <div class=\"cardHeader\"><h3>Staff Notes</h3><div class=\"spacer\"></div><span id=\"adminNoteCount\" class=\"small\"></span></div>\n        <div class=\"tableWrap\"><table><thead><tr><th>ID</th><th>Time</th><th>By</th><th>Note</th><th></th></tr></thead><tbody id=\"adminNoteRows\"></tbody></table></div>\n      </div>\n    </div>\n\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Inventory Manager</h3><div class=\"spacer\"></div><span id=\"adminInventoryCount\" class=\"small\"></span></div>\n      <p id=\"adminInventoryEvidence\" class=\"small\">Inspect live inventory or saved read-only inventory when a player is offline. Capture source and time appear here.</p>\n      <div class=\"inventoryToolbar\">\n        <input id=\"adminInventoryFilter\" type=\"search\" placeholder=\"Filter current inventory by item name or code\">\n        <button id=\"adminInventoryRefresh\">Refresh Inventory</button>\n        <button id=\"adminInventorySnapshot\">Create Snapshot</button>\n        <button id=\"adminInventoryClearSelection\">Clear Selection</button>\n      </div>\n      <div id=\"adminInventoryGrid\" class=\"inventorySections\"></div>\n\n      <div class=\"inventoryWorkbench\">\n        <div class=\"card\">\n          <div class=\"cardHeader\"><h3>Selected Slot</h3><div class=\"spacer\"></div><span id=\"adminSelectedSlotState\" class=\"small\">None</span></div>\n          <div id=\"adminSelectedSlotDetail\" class=\"small\">Select a slot above to inspect or edit it.</div>\n          <div id=\"adminSelectedSlotActions\" class=\"quickActions\"></div>\n        </div>\n        <div id=\"adminInventoryEditWorkbench\" class=\"card\">\n          <div class=\"cardHeader\"><h3>Give / Replace Item</h3><div class=\"spacer\"></div><span id=\"adminCatalogSelected\" class=\"small\">No item selected</span></div>\n          <div class=\"inventoryToolbar\">\n            <input id=\"adminItemSearch\" type=\"search\" placeholder=\"Search item/block name or code\">\n            <button id=\"adminItemSearchBtn\">Search</button>\n            <input id=\"adminGiveQuantity\" type=\"number\" min=\"1\" value=\"1\" style=\"width:90px\" title=\"Quantity\">\n          </div>\n          <div id=\"adminItemSearchResults\" class=\"itemSearchResults\"><div class=\"small\" style=\"padding:8px\">Search for at least two characters.</div></div>\n          <div class=\"quickActions\">\n            <button id=\"adminGiveAuto\">Give to First Free Slot</button>\n            <button id=\"adminGiveSelected\">Give to Selected Empty Slot</button>\n            <button id=\"adminReplaceSelected\" class=\"danger\">Replace Selected Slot</button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"grid\" style=\"margin-top:12px\">\n        <div class=\"card\">\n          <div class=\"cardHeader\"><h3>Inventory Snapshots</h3><div class=\"spacer\"></div><span id=\"adminSnapshotCount\" class=\"small\"></span></div>\n          <div class=\"tableWrap\"><table><thead><tr><th>ID</th><th>Time</th><th>By</th><th>Slots</th><th>Reason</th><th></th></tr></thead><tbody id=\"adminSnapshotRows\"></tbody></table></div>\n        </div>\n        <div class=\"card\">\n          <div class=\"cardHeader\"><h3>Snapshot Comparison</h3><div class=\"spacer\"></div><span id=\"adminSnapshotCompareState\" class=\"small\">Choose Compare</span></div>\n          <div class=\"tableWrap\"><table><thead><tr><th>Inventory</th><th>Slot</th><th>Snapshot</th><th>Current</th><th>Change</th></tr></thead><tbody id=\"adminSnapshotCompareRows\"><tr><td colspan=\"5\" class=\"muted\">No snapshot selected for comparison.</td></tr></tbody></table></div>\n        </div>\n      </div>\n\n      <div class=\"card\" style=\"margin-top:12px\">\n        <div class=\"cardHeader\"><h3>Inventory Audit History</h3><div class=\"spacer\"></div><span class=\"small\">Inventory-only admin actions</span></div>\n        <div class=\"tableWrap\"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Source</th><th>Detail</th></tr></thead><tbody id=\"adminInventoryHistoryRows\"></tbody></table></div>\n      </div>\n    </div>\n\n    <div class=\"card perfSection\">\n      <div class=\"cardHeader\"><h3>Player History</h3><div class=\"spacer\"></div><span class=\"small\">Suite moderation/session history + BlockLogger activity</span></div>\n      <div class=\"tableWrap adminHistoryScroll\"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Source</th><th>Detail</th></tr></thead><tbody id=\"adminHistoryRows\"></tbody></table></div>\n    </div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Maintenance Mode</h3><div class=\"spacer\"></div><span id=\"adminMaintenanceState\" class=\"small\"></span></div>\n      <p class=\"small\">When enabled, non-staff connections are rejected. Existing players are not forcibly removed.</p>\n      <div class=\"quickActions\"><button id=\"adminMaintenanceOn\" class=\"danger\">Enable Maintenance</button><button id=\"adminMaintenanceOff\">Disable Maintenance</button></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Scheduled Shutdown</h3><div class=\"spacer\"></div><span id=\"adminShutdownState\" class=\"small\"></span></div>\n      <p class=\"small\">Schedules announcements, then requests a clean Vintage Story shutdown so the world can save normally.</p>\n      <div class=\"quickActions\"><button id=\"adminShutdownSchedule\" class=\"danger\">Schedule Shutdown</button><button id=\"adminRestartSchedule\" class=\"danger\">Schedule Restart*</button><button id=\"adminShutdownCancel\">Cancel</button></div>\n      <p class=\"small\">*Restart means clean shutdown plus external host/service supervisor restart.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Entity Cleanup</h3><div class=\"spacer\"></div><span id=\"adminCleanupState\" class=\"small\"></span></div>\n      <p class=\"small\">The scan summarizes all loaded entities and identifies dropped items/dead-or-despawning entities. Removal is intentionally limited to dropped items and requires explicit confirmation.</p>\n      <div class=\"quickActions\"><button id=\"adminCleanupScan\">Scan Entities</button><button id=\"adminCleanupRun\" class=\"danger\">Remove Dropped Items</button></div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Recent Admin Audit</h3><div class=\"spacer\"></div><span class=\"small\">Includes both in-game and browser actions</span></div>\n    <div class=\"tableWrap dataScroll\"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th><th>Source</th><th>Detail</th></tr></thead><tbody id=\"adminAuditRows\"></tbody></table></div>\n  </div>\n</section>\n\n\n__NSS_ROLE_HTML__\n\n<section id=\"customization\">\n  <div class=\"pageTitle\"><div><h2>Suite Customization</h2><div class=\"subtitle\">Customize WebPanel identity, density and layout without editing HTML or rebuilding the Suite.</div></div></div>\n  <div class=\"toolbar\"><button id=\"suiteCustomizationRefresh\">Refresh</button><button id=\"suiteCustomizationReset\">Reset Defaults</button><div class=\"spacer\"></div><span id=\"suiteCustomizationState\" class=\"small\">Not loaded.</span><button id=\"suiteCustomizationSave\" class=\"primary\">Save Customization</button></div>\n  <div class=\"grid2 perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Branding &amp; Login</h3></div>\n      <div class=\"field\"><label>Panel name</label><input id=\"suiteCustomizationPanelName\" maxlength=\"80\" style=\"width:100%\" value=\"Newfie's Server Suite\"></div>\n      <div class=\"field\" style=\"margin-top:10px\"><label>Header subtitle</label><input id=\"suiteCustomizationHeaderSubtitle\" maxlength=\"40\" style=\"width:100%\" value=\"WebPanel\"></div>\n      <div class=\"field\" style=\"margin-top:10px\"><label>Login kicker</label><input id=\"suiteCustomizationLoginKicker\" maxlength=\"80\" style=\"width:100%\" value=\"Secure Administration Console\"></div>\n      <div class=\"field\" style=\"margin-top:10px\"><label>Login subtitle</label><textarea id=\"suiteCustomizationLoginSubtitle\" rows=\"3\" maxlength=\"240\"></textarea></div>\n      <div class=\"field\" style=\"margin-top:10px\"><label>Search placeholder</label><input id=\"suiteCustomizationSearchPlaceholder\" maxlength=\"100\" style=\"width:100%\"></div>\n      <div class=\"field\" style=\"margin-top:10px\"><label>Sidebar footer</label><input id=\"suiteCustomizationSidebarFooter\" maxlength=\"120\" style=\"width:100%\"></div>\n      <div class=\"field\" style=\"margin-top:10px\"><label>Accent color</label><div class=\"row\"><input id=\"suiteCustomizationAccent\" type=\"color\" value=\"#69aefa\" style=\"width:64px;height:38px;padding:3px\"><input id=\"suiteCustomizationAccentText\" maxlength=\"7\" value=\"#69AEFA\" style=\"width:110px\"></div></div>\n      <label class=\"field\">Custom logo URL<input id=\"suiteCustomizationLogoUrl\" type=\"text\" maxlength=\"2048\" placeholder=\"https://… or /image.png\"></label><p class=\"small\">Used in the header and login. Empty restores the Suite logo. Use an image visitors can access.</p>\n      <label class=\"toggleLine\" style=\"margin-top:12px\"><input id=\"suiteCustomizationHeaderLogo\" type=\"checkbox\" checked> Show header logo</label>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationShowBuild\" type=\"checkbox\" checked> Show build ID in customization/status context</label>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Theme, Dashboard &amp; Layout</h3></div>\n      <label class=\"field\">Theme<select id=\"suiteCustomizationTheme\"><option value=\"original\">Suite Original</option><option value=\"forest\">Forest</option><option value=\"slate\">Slate</option><option value=\"custom\">Custom palette</option></select></label>\n      <div class=\"row\"><label class=\"field\">Background<input id=\"suiteCustomizationBackground\" type=\"color\"></label><label class=\"field\">Panels<input id=\"suiteCustomizationPanel\" type=\"color\"></label><label class=\"field\">Text<input id=\"suiteCustomizationText\" type=\"color\"></label></div><p class=\"small\">Palette colors apply with Custom palette. Accent, spacing and branding apply to every theme.</p>\n      <label class=\"field\">Frame texture<select id=\"suiteCustomizationTexture\"><option value=\"none\">Smooth</option><option value=\"slate\">Fine slate</option><option value=\"brushed\">Brushed metal</option></select></label>\n      <label class=\"field\">Texture strength (0–25%)<input id=\"suiteCustomizationTextureStrength\" type=\"range\" min=\"0\" max=\"25\" value=\"12\"></label>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationIcons\" type=\"checkbox\" checked> Show module icons</label>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationContrast\" type=\"checkbox\"> Stronger panel borders and focus outlines</label>\n      <p class=\"small\">Textures stay on the frame and navigation. Tables, forms and message text remain smooth. No image downloads or background polling.</p>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationReduceMotion\" type=\"checkbox\"> Reduce animations across the panel and login</label>\n      <div class=\"field\"><label>Dashboard title</label><input id=\"suiteCustomizationDashboardTitle\" maxlength=\"80\" style=\"width:100%\" value=\"Server Dashboard\"></div>\n      <div class=\"field\" style=\"margin-top:10px\"><label>Dashboard subtitle</label><textarea id=\"suiteCustomizationDashboardSubtitle\" rows=\"4\" maxlength=\"240\"></textarea></div>\n      <label class=\"toggleLine\" style=\"margin-top:10px\"><input id=\"suiteCustomizationCompact\" type=\"checkbox\"> Compact layout density</label>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationStatusBar\" type=\"checkbox\" checked> Show global status strip</label>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationModuleStatus\" type=\"checkbox\" checked> Show module status chips</label>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationAttention\" type=\"checkbox\" checked> Show Dashboard Needs Attention</label>\n      <label class=\"toggleLine\"><input id=\"suiteCustomizationOperations\" type=\"checkbox\" checked> Show Dashboard Operations Snapshot</label>\n      <div class=\"row\" style=\"margin-top:10px\"><div class=\"field\"><label>Sidebar width (px)</label><input id=\"suiteCustomizationSidebarWidth\" type=\"number\" min=\"190\" max=\"320\" value=\"232\"></div><div class=\"field\"><label>Card radius (px)</label><input id=\"suiteCustomizationCardRadius\" type=\"number\" min=\"0\" max=\"24\" value=\"14\"></div></div>\n      <div class=\"compactNote\" style=\"margin-top:12px\"><b>Live preview:</b> changes are previewed in this browser as you edit. Save to make them persistent for every administrator.</div>\n      <div id=\"suiteCustomizationPreview\" class=\"infoBox\" style=\"margin-top:12px\">Preview not loaded.</div>\n    </div>\n  </div>\n  <div class=\"card perfSection\"><div class=\"cardHeader\"><h3>Scope &amp; Safety</h3></div><div class=\"compactNote\">Customization is presentation-only. It cannot inject HTML/JavaScript, alter authentication, rename API routes, change module IDs, or bypass permissions. Text is stored as plain text and color/layout values are clamped server-side.</div></div>\n</section>\n\n<section id=\"databaseStorage\">\n  <div class=\"pageTitle\">\n    <div><h2>Database Storage</h2><div class=\"subtitle\">Inspect what each Suite database contains, which subsystem owns it, disk usage, table/index footprint, reclaimable space, WAL growth, backups, and safe ways to reduce storage.</div></div>\n  </div>\n  <div class=\"card perfSection\" id=\"adminDatabaseStorageCard\">\n    <div class=\"cardHeader\">\n      <div>\n        <h3>Database Storage Viewer</h3>\n        <div class=\"small\">See what each Suite-owned SQLite database stores, which subsystem owns each data area, where disk space is going, and the safest tuning option. The Vintage Story world-save database is intentionally not modified or analyzed here.</div>\n      </div>\n      <div class=\"spacer\"></div>\n      <span id=\"adminDatabaseStorageState\" class=\"small\">Loading file totals…</span>\n    </div>\n    <div class=\"toolbar\" style=\"margin-top:10px\">\n      <button id=\"adminDatabaseStorageAnalyze\" class=\"primary\">Analyze Storage</button>\n      <button id=\"adminDatabaseStorageRefresh\">Refresh File Totals</button>\n      <div class=\"spacer\"></div>\n      <span class=\"small\">Detailed table analysis is manual so large databases are not scanned by live dashboard polling. Table usage stays timestamped until re-analyzed.</span>\n    </div>\n    <div class=\"quickActions\" style=\"margin-top:8px\">\n      <button onclick=\"setSection('blocklogger')\">Open BlockLogger Maintenance</button>\n      <button onclick=\"setSection('health')\">Open Database Health</button>\n    </div>\n    <div class=\"infoBox\" style=\"margin-top:10px\"><b>Storage rule:</b> large indexes are not automatically waste—they are what keep BlockLogger/player-history queries fast. Prefer retention, logging scope, snapshot policy, and backup retention before considering compaction. Never delete active SQLite <code>-wal</code>/<code>-shm</code> files by hand.</div>\n    <div id=\"adminDatabaseStorageSummary\" class=\"dbStorageSummary\"></div>\n    <div class=\"dbStorageGraphPanel\">\n      <div class=\"dbStorageGraphHeader\"><div><h3 style=\"margin:0 0 3px\">Live SQLite + WAL</h3><div class=\"small\">Database / WAL / SHM / Backups</div></div><div class=\"spacer\"></div><span id=\"adminDatabaseStorageGraphState\" class=\"small\"></span></div>\n      <div class=\"dbStorageGraphLegend\"><span><i class=\"dbFile\"></i>Database</span><span><i class=\"dbWal\"></i>WAL</span><span><i class=\"dbShm\"></i>SHM</span><span><i class=\"dbBackup\"></i>Backups</span></div>\n      <div class=\"dbStorageGraphWrap\"><canvas id=\"adminDatabaseStorageGraph\" class=\"dbStorageGraph\"></canvas><div class=\"chartTip\" id=\"adminDatabaseStorageGraphTip\"></div></div>\n    </div>\n    <div id=\"adminDatabaseStorageRecommendations\" class=\"dbStorageRecommendations\"></div>\n    <div id=\"adminDatabaseStorageDatabases\"><div class=\"emptyAction\"><b>Database storage totals are loading.</b><br>Press Analyze Storage to calculate per-table and index usage.</div></div>\n  </div>\n\n</section>\n\n<section id=\"health\">\n  <div class=\"pageTitle\">\n    <div>\n      <h2>Suite Health</h2>\n      <div class=\"subtitle\">Health of Newfie's Server Suite modules and backing services: startup self-test, Suite-owned databases and queues, circuit breakers, WebPanel request diagnostics, retention/export policy, and web action safety.</div>\n    </div>\n  </div>\n\n  <div class=\"toolbar\">\n    <button id=\"healthRefresh\" class=\"primary\">Run Self-Test</button>\n    <button id=\"healthIntegrity\">Check BlockLogger DB</button>\n    <button id=\"healthBackup\">Backup BlockLogger DB</button>\n    <button id=\"healthAdminIntegrity\">Check Admin DB</button>\n    <button id=\"healthAdminBackup\">Backup Admin DB</button>\n    <button id=\"healthSafeMode\">Safe Diagnostics: …</button>\n    <button id=\"healthResetBreakers\">Reset Circuit Breakers</button>\n    <button id=\"healthBundle\">Diagnostic Bundle v2</button>\n    <div class=\"spacer\"></div>\n    <span id=\"healthBuild\" class=\"small\"></span>\n  </div>\n\n  <div id=\"healthSummary\" class=\"card perfSection\"><div class=\"empty\">Loading Suite self-test…</div></div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Subsystem Self-Test</h3><div class=\"spacer\"></div><span id=\"healthCheckCount\" class=\"small\"></span></div>\n    <div id=\"healthChecks\" class=\"smartGrid\"></div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>BlockLogger SQLite</h3><div class=\"spacer\"></div><span id=\"databaseState\" class=\"small\"></span></div>\n      <div id=\"databaseHealth\" class=\"small\">Loading database health…</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Essentials Admin SQLite</h3><div class=\"spacer\"></div><span id=\"adminDatabaseState\" class=\"small\"></span></div>\n      <div id=\"adminDatabaseHealth\" class=\"small\">Loading admin database health…</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Retention & Export Privacy</h3></div>\n      <div id=\"retentionPrivacy\" class=\"small\">Loading retention/privacy policy…</div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Web Server Request Diagnostics</h3><div class=\"spacer\"></div><span id=\"webDiagState\" class=\"small\">Collecting request timings…</span></div>\n    <p class=\"small\">Separates worker-queue delay, browser/network time, time waiting on Vintage Story's main thread, and actual main-thread work. This is the quickest way to prove whether the dashboard itself contributed to a lag event.</p>\n    <div id=\"webDiagSummary\" class=\"grid\" style=\"margin-bottom:10px\"></div>\n    <div class=\"tableWrap dataScroll\">\n      <table>\n        <thead><tr><th>Endpoint</th><th>Requests</th><th>Errors</th><th>Avg</th><th>P95</th><th>Max</th><th>Queue wait avg</th><th>Main wait avg</th><th>Main work avg</th><th>Payload</th></tr></thead>\n        <tbody id=\"webDiagEndpoints\"><tr><td colspan=\"10\" class=\"muted\">No web request samples yet.</td></tr></tbody>\n      </table>\n    </div>\n    <div class=\"card\" style=\"margin-top:10px\">\n      <div class=\"cardHeader\"><h4>Recent slow/error requests</h4><div class=\"spacer\"></div><span class=\"small\">last 10 minutes · ≥100ms or HTTP error</span></div>\n      <div class=\"tableWrap\"><table>\n        <thead><tr><th>Time</th><th>Endpoint</th><th>Status</th><th>Total</th><th>Queue wait</th><th>Main wait</th><th>Main work</th><th>Payload</th><th>Interpretation</th></tr></thead>\n        <tbody id=\"webDiagSlow\"><tr><td colspan=\"9\" class=\"muted\">No slow/error web requests.</td></tr></tbody>\n      </table></div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Data Collection Audit</h3><div class=\"spacer\"></div><span id=\"collectionAuditState\" class=\"small\">Loading collector policy…</span></div>\n    <p class=\"small\">Every automatic collector should have a bounded cadence and avoid full world/entity walks. Manual heavy operations are clearly separated from background telemetry.</p>\n    <div id=\"collectionSafeguards\" class=\"infoBox\" style=\"margin-bottom:10px\"></div>\n    <div class=\"tableWrap\"><table><thead><tr><th>Collector</th><th>Cadence</th><th>Thread</th><th>Cost</th><th>Automatic</th><th>Cached/bounded</th><th>Detail</th></tr></thead><tbody id=\"collectionAuditRows\"><tr><td colspan=\"6\" class=\"muted\">Loading collection audit…</td></tr></tbody></table></div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Feature Circuit Breakers</h3><div class=\"spacer\"></div><span class=\"small\">3 consecutive failures → 5-minute local feature disable</span></div>\n    <p class=\"small\">Circuit breakers disable only the failing nonessential feature. Core BlockLogger logging continues.</p>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Feature</th><th>Safety</th><th>State</th><th>Consecutive</th><th>Total failures</th><th>Last error</th></tr></thead>\n        <tbody id=\"breakerRows\"><tr><td colspan=\"6\" class=\"muted\">No feature failures recorded.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Server Essentials Suite Self-Overhead</h3><div class=\"spacer\"></div><span class=\"small\">Wall-clock execution time for the suite itself</span></div>\n    <p class=\"small\">This answers “is the monitoring suite becoming part of the performance problem?” Background maintenance should normally remain tiny; manual scans are shown separately because they are intentionally heavier.</p>\n    <div id=\"overheadSummary\" class=\"grid\"></div>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Feature / action</th><th>Calls</th><th>Last</th><th>Average</th><th>Max</th><th>Status</th></tr></thead>\n        <tbody id=\"overheadRows\"><tr><td colspan=\"6\" class=\"muted\">No overhead samples yet.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Web Endpoint Safety Matrix</h3><div class=\"spacer\"></div><span class=\"small\">Authentication, risk, cooldown, and exclusive-operation policy</span></div>\n    <div class=\"tableWrap endpointSafetyScroll\">\n      <table>\n        <thead><tr><th>Method</th><th>Endpoint</th><th>Access</th><th>Risk</th><th>Safety</th><th>Cooldown</th><th>Exclusive</th></tr></thead>\n        <tbody id=\"policyRows\"><tr><td colspan=\"6\" class=\"muted\">Loading route policy…</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<section id=\"operations\">\n  <div class=\"pageTitle\">\n    <div>\n      <h2>Operations & Audit</h2>\n      <div class=\"subtitle\">Configuration safety snapshots and a persistent audit trail for web administration actions.</div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Performance Comparison Snapshots</h3><div class=\"spacer\"></div><button id=\"performanceSnapshotCreate\" class=\"primary\">Capture Current</button></div>\n    <div class=\"row\">\n      <div class=\"field grow\">\n        <label>Label</label>\n        <input id=\"performanceSnapshotLabel\" placeholder=\"Before mod update, after entity cleanup…\">\n      </div>\n      <div id=\"performanceCompareResult\" class=\"small\" style=\"min-width:300px\">Capture a known state, then compare it with the current server.</div>\n    </div>\n    <div class=\"tableWrap\">\n      <table>\n        <thead><tr><th>Captured</th><th>Label</th><th>Players</th><th>Health</th><th>Delay</th><th>CPU</th><th>Profile P95</th><th>Compare</th></tr></thead>\n        <tbody id=\"performanceSnapshotRows\"><tr><td colspan=\"8\" class=\"muted\">No performance snapshots yet.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\">\n      <h3>Configuration Snapshots</h3>\n      <div class=\"spacer\"></div>\n      <span id=\"configSnapshotState\" class=\"small\"></span>\n      <button id=\"configSnapshotCreate\" class=\"primary\">Create Snapshot</button>\n    </div>\n    <div class=\"row\" style=\"align-items:end;margin-bottom:10px\">\n      <div class=\"field grow\">\n        <label>Snapshot label</label>\n        <input id=\"configSnapshotLabel\" placeholder=\"Before server tuning, before mod update…\">\n      </div>\n      <div class=\"small\" style=\"max-width:420px\"><b>Restore safety:</b> restoring a snapshot automatically creates a backup of the current Newfie's configuration first.</div>\n    </div>\n    <div class=\"warning\"><b>Included:</b> Suite Feature Gates · BlockLogger · Web Server · Animal Limiter · Login Protection · Public Player List. <b>Excluded:</b> external optimizer configs such as Tungsten. Restoring feature gates requires a server restart to fully add/remove subsystem hooks.</div>\n    <div class=\"tableWrap\" style=\"margin-top:10px\">\n      <table>\n        <thead><tr><th>Created</th><th>Label</th><th>Created by</th><th>Included configs</th><th>Action</th></tr></thead>\n        <tbody id=\"configSnapshotRows\"><tr><td colspan=\"5\" class=\"muted\">No configuration snapshots yet.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Audit Summary</h3><div class=\"spacer\"></div><span id=\"auditCount\" class=\"small\"></span></div>\n    <div id=\"auditSummary\" class=\"small\">Loading audit information…</div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Web Administration Audit Log</h3><div class=\"spacer\"></div><button id=\"auditRefresh\">Refresh</button></div>\n    <div class=\"tableWrap dataScrollTall\">\n      <table>\n        <thead><tr><th>Time</th><th>Actor</th><th>Remote</th><th>Action</th><th>Detail</th><th>Result</th></tr></thead>\n        <tbody id=\"auditRows\"><tr><td colspan=\"6\" class=\"muted\">No audit entries loaded.</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<section id=\"playerlist\">\n  <div class=\"pageTitle\"><div><h2>Player List</h2><div class=\"subtitle\">Configure the hold-Tab roster and troubleshoot the Server Essentials player-list backend.</div></div></div>\n\n  <div class=\"card perfSection\" id=\"playerListConfigCard\">\n    <div class=\"cardHeader\"><h3>Roster Configuration</h3><div class=\"spacer\"></div><span id=\"playerListConfigState\" class=\"small\">Not loaded.</span><button id=\"playerListConfigRefresh\">Refresh</button></div>\n    <div class=\"compactNote\" style=\"margin-bottom:12px\"><b>All PlayerList settings live here.</b> The companion remains a separate mod; Server Essentials sends these appearance/layout settings with each roster snapshot.</div>\n\n    <div class=\"row\" style=\"align-items:end\">\n      <div class=\"field grow\"><label for=\"playerListServerName\">Server name</label><input id=\"playerListServerName\" type=\"text\" maxlength=\"96\" placeholder=\"Leave blank to use serverconfig.json name\"></div>\n      <div class=\"field\" style=\"min-width:190px\"><label for=\"playerListOpacity\">Panel opacity <span id=\"playerListOpacityValue\">72%</span></label><input id=\"playerListOpacity\" type=\"range\" min=\"30\" max=\"95\" step=\"1\" value=\"72\" style=\"width:100%\"></div>\n      <div class=\"field\" style=\"min-width:150px\"><label for=\"playerListAccent\">Accent</label><input id=\"playerListAccent\" type=\"color\" value=\"#d6ae63\" style=\"width:100%;height:38px\"></div>\n      <div class=\"field\" style=\"min-width:180px\"><label for=\"playerListScale\">UI scale <span id=\"playerListScaleValue\">1.00×</span></label><input id=\"playerListScale\" type=\"range\" min=\"80\" max=\"135\" step=\"5\" value=\"100\" style=\"width:100%\"></div>\n    </div>\n\n    <div class=\"row\" style=\"align-items:end;margin-top:10px\">\n      <div class=\"field\"><label for=\"playerListAlignment\">Screen position</label><select id=\"playerListAlignment\"><option value=\"CenterTop\">Center top</option><option value=\"LeftTop\">Left top</option><option value=\"RightTop\">Right top</option></select></div>\n      <div class=\"field\"><label for=\"playerListOffsetX\">X offset</label><input id=\"playerListOffsetX\" type=\"number\" min=\"-1200\" max=\"1200\" step=\"1\" value=\"0\"></div>\n      <div class=\"field\"><label for=\"playerListOffsetY\">Y offset</label><input id=\"playerListOffsetY\" type=\"number\" min=\"-100\" max=\"900\" step=\"1\" value=\"22\"></div>\n      <div class=\"field\"><label for=\"playerListRowsPerColumn\">Rows / column</label><input id=\"playerListRowsPerColumn\" type=\"number\" min=\"4\" max=\"16\" step=\"1\" value=\"8\"></div>\n      <div class=\"field\"><label for=\"playerListMaxColumns\">Max columns</label><input id=\"playerListMaxColumns\" type=\"number\" min=\"1\" max=\"5\" step=\"1\" value=\"4\"></div>\n    </div>\n\n    <div class=\"compactNote\" style=\"margin-top:12px;margin-bottom:8px\"><b>Visible information & style</b></div>\n    <div class=\"row\" style=\"align-items:center;gap:16px;flex-wrap:wrap\">\n      <label class=\"toggleLine\"><input id=\"playerListShowRoles\" type=\"checkbox\" checked> Roles</label>\n      <label class=\"toggleLine\"><input id=\"playerListShowPing\" type=\"checkbox\" checked> Ping</label>\n      <label class=\"toggleLine\"><input id=\"playerListShowSession\" type=\"checkbox\" checked> Session time</label>\n      <label class=\"toggleLine\"><input id=\"playerListShowInitials\" type=\"checkbox\" checked> Player initials</label>\n      <label class=\"toggleLine\"><input id=\"playerListShowCapacity\" type=\"checkbox\" checked> Capacity bar</label>\n      <label class=\"toggleLine\"><input id=\"playerListShowHeaders\" type=\"checkbox\"> Column headings</label>\n      <label class=\"toggleLine\"><input id=\"playerListCompactRows\" type=\"checkbox\"> Compact rows</label>\n      <label class=\"toggleLine\"><input id=\"playerListShowPingBars\" type=\"checkbox\" checked> Ping bars</label>\n      <label class=\"toggleLine\"><input id=\"playerListShowFooter\" type=\"checkbox\"> Footer hint</label>\n    </div>\n\n    <div class=\"row\" style=\"margin-top:14px;align-items:center\">\n      <label class=\"toggleLine\"><input id=\"playerListDebugLogging\" type=\"checkbox\"> Debug logging</label>\n      <span class=\"small\">Writes additional <code>[ServerEssentials/PlayerList]</code> request/response diagnostics to the server log.</span>\n      <div class=\"spacer\"></div>\n      <button id=\"playerListConfigSave\" class=\"primary\">Save Player List Configuration</button>\n    </div>\n    <div id=\"playerListEffectiveName\" class=\"small\" style=\"margin-top:11px\"></div>\n  </div>\n\n  <div class=\"card perfSection\" id=\"playerListReservedSlotsCard\">\n    <div class=\"cardHeader\"><h3>Reserved Slots</h3><div class=\"spacer\"></div><span id=\"playerListReservedState\" class=\"small\">Disabled</span><button id=\"playerListReservedSave\" class=\"primary\">Save Reserved Slots</button></div>\n    <div class=\"compactNote\" style=\"margin-bottom:12px\"><b>Off by default.</b> When enabled, non-reserved roles may fill only the public portion of <code>MaxClients</code>. Players in an allowed role can use the remaining reserved capacity. The server's normal maximum player limit is never exceeded.</div>\n    <div class=\"row\" style=\"align-items:end;gap:16px\">\n      <div class=\"field\" style=\"min-width:220px\"><label class=\"toggleLine\"><input id=\"playerListReservedEnabled\" type=\"checkbox\"> Enable reserved slots</label><div class=\"small\" style=\"margin-top:6px\">Non-reserved joins are rejected only when public capacity is full.</div></div>\n      <div class=\"field\" style=\"min-width:170px\"><label for=\"playerListReservedCount\">Reserved slot count</label><input id=\"playerListReservedCount\" type=\"number\" min=\"0\" max=\"256\" step=\"1\" value=\"0\"></div>\n      <div class=\"field grow\"><label for=\"playerListReservedMessage\">Disconnect message</label><input id=\"playerListReservedMessage\" type=\"text\" maxlength=\"240\" value=\"Only reserved slots are left on this server.\"></div>\n    </div>\n    <div class=\"row\" style=\"align-items:flex-start;gap:16px;margin-top:12px\">\n      <div class=\"field grow\"><label for=\"playerListReservedRoles\">Allowed roles — one role name/code per line</label><textarea id=\"playerListReservedRoles\" rows=\"5\" maxlength=\"2048\" placeholder=\"admin&#10;supporter\"></textarea><div id=\"playerListConfiguredRoles\" class=\"small\" style=\"margin-top:7px\">Configured server roles will appear here.</div></div>\n      <div class=\"field grow\"><label>Live capacity</label><div id=\"playerListReservedSummary\" class=\"smartGrid\"><div class=\"empty\">Load Player List configuration to view reserved-slot capacity.</div></div></div>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\" id=\"playerListDiagnosticsCard\">\n    <div class=\"cardHeader\"><h3>Diagnostics & Debugging</h3><div class=\"spacer\"></div><span id=\"playerListDiagnosticState\" class=\"small\">Waiting for status.</span></div>\n    <div id=\"playerListDebugGrid\" class=\"smartGrid\"><div class=\"empty\">Loading player-list diagnostics…</div></div>\n    <div id=\"playerListBackendHelp\" class=\"infoBox\" style=\"margin-top:12px\">Hold Tab in game, then press Refresh. Requests &gt; 0 confirms the companion reached the suite backend; Responses &gt; 0 confirms the complete round trip.</div>\n  </div>\n</section>\n\n\n<section id=\"playercommands\"><div class=\"infoBox\">Home limits and teleport policies are shared with <button type=\"button\" onclick=\"setSection('roles')\">Role Config</button>. Edit them from either page.</div>\n  <div class=\"pageTitle\"><div><h2>Player Commands</h2><div class=\"subtitle\">Manage command availability, teleport rules and player access. Settings apply live when saved.</div></div></div>\n  <div id=\"playerCommandsNotice\" class=\"infoBox\">Loading player command status…</div>\n  <div id=\"playerCommandsMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card playerCommandSaveBar\">\n    <div><b id=\"playerCommandsDraftStatus\" role=\"status\" aria-live=\"polite\">Loading settings…</b><div class=\"small\">Policy edits stay in this tab until you save. Individual command buttons apply immediately.</div></div>\n    <div class=\"quickActions\"><button id=\"playerCommandsRefresh\">Reload</button><button id=\"playerCommandsDiscard\">Discard Edits</button><button id=\"playerCommandsSave\" class=\"primary\">Save Settings</button></div>\n  </div>\n  <div class=\"playerCommandTabs\" role=\"tablist\" aria-label=\"Player command pages\">\n    <button id=\"playerCommandTab-commands\" data-player-command-tab=\"commands\" role=\"tab\" aria-controls=\"playerCommandPanel-commands\" aria-selected=\"true\" tabindex=\"0\">Commands</button>\n    <button id=\"playerCommandTab-teleports\" data-player-command-tab=\"teleports\" role=\"tab\" aria-controls=\"playerCommandPanel-teleports\" aria-selected=\"false\" tabindex=\"-1\">Teleports</button>\n    <button id=\"playerCommandTab-community\" data-player-command-tab=\"community\" role=\"tab\" aria-controls=\"playerCommandPanel-community\" aria-selected=\"false\" tabindex=\"-1\">Messages & Kits</button>\n    <button id=\"playerCommandTab-roles\" data-player-command-tab=\"roles\" role=\"tab\" aria-controls=\"playerCommandPanel-roles\" aria-selected=\"false\" tabindex=\"-1\">Role Policies</button>\n    <button id=\"playerCommandTab-permissions\" data-player-command-tab=\"permissions\" role=\"tab\" aria-controls=\"playerCommandPanel-permissions\" aria-selected=\"false\" tabindex=\"-1\">Player Permissions</button>\n  </div>\n  <div id=\"playerCommandPanel-commands\" class=\"playerCommandPanel\" role=\"tabpanel\" aria-labelledby=\"playerCommandTab-commands\">\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><div><h3>Command Directory</h3><div class=\"small\">See which mod owns each alias and which Suite fallback is available.</div></div></div>\n    <div class=\"playerCommandFilters\">\n      <div class=\"field grow\"><label for=\"playerCommandSearch\">Find a command</label><input id=\"playerCommandSearch\" type=\"search\" placeholder=\"Command, description, privilege or provider\"></div>\n      <div class=\"field\"><label for=\"playerCommandFilter\">Availability</label><select id=\"playerCommandFilter\"><option value=\"all\">All commands</option><option value=\"enabled\">Suite enabled</option><option value=\"disabled\">Suite disabled</option><option value=\"external\">Other providers</option></select></div>\n      <span id=\"playerCommandResultCount\" class=\"small\" role=\"status\"></span>\n    </div>\n    <div id=\"playerCommandsRows\" class=\"playerCommandDirectory\"></div>\n  </div>\n  <div class=\"card perfSection\"><div class=\"cardHeader\"><h3>Feature Switches</h3><div class=\"spacer\"></div><button id=\"playerCommandsEnableAll\">Enable Features</button><button id=\"playerCommandsDisableAll\">Disable Features</button></div><div class=\"compactNote\">These buttons edit the master feature switches. Save Settings to apply. They preserve individual command switches and never change commands owned by other mods. Command policies are on the Teleports and Messages &amp; Kits tabs.</div></div>\n  </div>\n  <div id=\"playerCommandPanel-teleports\" class=\"playerCommandPanel\" role=\"tabpanel\" aria-labelledby=\"playerCommandTab-teleports\" hidden>\n  <div class=\"playerCommandPolicyGrid\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Spawn Policy</h3><div class=\"spacer\"></div></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdSpawnEnabled\" type=\"checkbox\"><span> Enable NSE spawn command</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdSpawnCancelMove\" type=\"checkbox\"><span> Cancel warm-up when player moves</span></label>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>Spawn cooldown (seconds)</label><input id=\"playerCmdSpawnCooldown\" type=\"number\" min=\"0\" max=\"86400\"></div>\n        <div class=\"field\"><label>Warm-up (seconds)</label><input id=\"playerCmdSpawnWarmup\" type=\"number\" min=\"0\" max=\"300\"></div>\n      </div>\n      <div class=\"compactNote\" style=\"margin-top:12px\">Uses Vintage Story's authoritative global world spawn. Warm-up and cooldown values of 0 disable those delays.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Warp Command Policy</h3><div class=\"spacer\"></div></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdWarpsEnabled\" type=\"checkbox\"><span> Enable NSE warp system</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdWarpEnabled\" type=\"checkbox\"><span> Enable player <code>/warp</code> command</span></label>\n      <div class=\"compactNote\" style=\"margin-top:12px\">Destination editing, costs, warm-up and cooldown defaults are available on the dedicated <b>Warp Management</b> page. <button type=\"button\" data-player-command-warps>Open Warp Management</button></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Back Command</h3><div class=\"spacer\"></div></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdBackEnabled\" type=\"checkbox\"><span> Enable <code>/back</code></span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdBackDeaths\" type=\"checkbox\"><span> Save last death location</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdBackTeleports\" type=\"checkbox\"><span> Save origins of Suite teleports</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdBackCancelMove\" type=\"checkbox\"><span> Cancel warm-up when player moves</span></label>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>Cooldown (seconds)</label><input id=\"playerCmdBackCooldown\" type=\"number\" min=\"0\" max=\"86400\"></div>\n        <div class=\"field\"><label>Warm-up (seconds)</label><input id=\"playerCmdBackWarmup\" type=\"number\" min=\"0\" max=\"300\"></div>\n      </div>\n      <div class=\"compactNote\" style=\"margin-top:12px\">Returns to the most recently recorded death or Suite teleport origin. Successful <code>/back</code> swaps the saved position for back-and-forth use.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Homes</h3><div class=\"spacer\"></div></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdHomesEnabled\" type=\"checkbox\"><span> Enable home commands</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdHomeCancelMove\" type=\"checkbox\"><span> Cancel warm-up when player moves</span></label>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>Global home limit</label><input id=\"playerCmdHomeGlobalLimit\" type=\"number\" min=\"0\" max=\"100\"></div>\n        <div class=\"field\"><label>Cooldown (seconds)</label><input id=\"playerCmdHomeCooldown\" type=\"number\" min=\"0\" max=\"86400\"></div>\n        <div class=\"field\"><label>Warm-up (seconds)</label><input id=\"playerCmdHomeWarmup\" type=\"number\" min=\"0\" max=\"300\"></div>\n      </div>\n      <div class=\"field\" style=\"margin-top:12px\"><label>Role limits — one per line: <code>rolecode=limit</code></label><textarea id=\"playerCmdHomeRoleLimits\" rows=\"5\" placeholder=\"supporter=5&#10;default=2\"></textarea></div>\n      <div class=\"field\" style=\"margin-top:12px\"><label>Player overrides — one per line: <code>PlayerUID or exact name=limit</code></label><textarea id=\"playerCmdHomePlayerLimits\" rows=\"5\" placeholder=\"playeruid=8\"></textarea></div>\n      <div class=\"compactNote\" style=\"margin-top:12px\">Limit priority: player override → role override → global limit. Reducing a limit never deletes existing homes.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Player-to-Player Teleports</h3><div class=\"spacer\"></div></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdT2pEnabled\" type=\"checkbox\"><span> Enable <code>/t2p &lt;player&gt;</code> — request permission to teleport to a player</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdT2mEnabled\" type=\"checkbox\"><span> Enable <code>/t2m &lt;player&gt;</code> — request a player teleport to you</span></label>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>/t2p cooldown (seconds)</label><input id=\"playerCmdT2pCooldown\" type=\"number\" min=\"0\" max=\"604800\" value=\"30\"></div>\n        <div class=\"field\"><label>/t2m cooldown (seconds)</label><input id=\"playerCmdT2mCooldown\" type=\"number\" min=\"0\" max=\"604800\" value=\"30\"></div>\n      </div>\n      <div class=\"compactNote\" style=\"margin-top:12px\"><b>/t2p + /t2m consent flow:</b> the target must type <code>/tpaccept</code> within 60 seconds. After acceptance there is a 10-second warmup. For <code>/t2p</code>, the requester teleports to the target; for <code>/t2m</code>, the target teleports to the requester. The configured <code>/t2m</code> cooldown is charged only after a successful accepted teleport. <b>Safe default:</b> roles without an explicit <code>/t2p</code> or <code>/t2m</code> role policy require <code>controlserver</code> or <code>root</code>. Use the role matrix below to grant either command to supporter/moderator/custom roles. Successful teleports are trusted by PacketGuard and participate in <code>/back</code> tracking when enabled.</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Random Teleport</h3><div class=\"spacer\"></div></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdRtpEnabled\" type=\"checkbox\"><span> Enable <code>/rtp</code></span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdRtpCancelMove\" type=\"checkbox\"><span> Cancel warm-up when player moves</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdRtpAvoidLiquids\" type=\"checkbox\"><span> Avoid water/lava landing positions</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdRtpCenterPlayer\" type=\"checkbox\"><span> Center RTP radius on the player's current position instead of server spawn</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdRtpCostEnabled\" type=\"checkbox\"><span> Require item cost</span></label>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>Minimum radius</label><input id=\"playerCmdRtpMinRadius\" type=\"number\" min=\"0\" max=\"5000000\"></div>\n        <div class=\"field\"><label>Maximum radius</label><input id=\"playerCmdRtpMaxRadius\" type=\"number\" min=\"0\" max=\"5000000\"></div>\n        <div class=\"field\"><label>Cooldown (seconds)</label><input id=\"playerCmdRtpCooldown\" type=\"number\" min=\"0\" max=\"604800\"></div>\n        <div class=\"field\"><label>Warm-up (seconds)</label><input id=\"playerCmdRtpWarmup\" type=\"number\" min=\"0\" max=\"300\"></div>\n      </div>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>Cost item code</label><input id=\"playerCmdRtpCostItem\" placeholder=\"game:gear-rusty\"></div>\n        <div class=\"field\"><label>Cost quantity</label><input id=\"playerCmdRtpCostQty\" type=\"number\" min=\"1\" max=\"65535\"></div>\n        <div class=\"field\"><label>Safe-search attempts</label><input id=\"playerCmdRtpAttempts\" type=\"number\" min=\"1\" max=\"100\"></div>\n      </div>\n      <div class=\"compactNote\" style=\"margin-top:12px\">RTP searches for a safe overworld surface before charging the player. By default the radius is measured from server spawn; enable the player-center option for exploration-style RTP around each player's current position. Failed searches or cancelled warm-ups consume nothing.</div>\n    </div>\n  </div>\n  </div>\n  <div id=\"playerCommandPanel-community\" class=\"playerCommandPanel\" role=\"tabpanel\" aria-labelledby=\"playerCommandTab-community\" hidden>\n  <div class=\"playerCommandPolicyGrid\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Private Message Policy</h3><div class=\"spacer\"></div></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdMsgEnabled\" type=\"checkbox\"><span> Enable NSE /msg</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdReplyEnabled\" type=\"checkbox\"><span> Enable NSE /r reply</span></label>\n      <label class=\"toggleLine\"><input id=\"playerCmdRespectMutes\" type=\"checkbox\"><span> Block private messages from suite-muted players</span></label>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>Maximum PM length</label><input id=\"playerCmdMaxLength\" type=\"number\" min=\"32\" max=\"2000\"></div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Starter Kit Policy</h3><div class=\"spacer\"></div><span id=\"playerCmdStarterStatus\" class=\"small\"></span></div>\n      <label class=\"toggleLine\"><input id=\"playerCmdStarterEnabled\" type=\"checkbox\"><span> Enable NSE starter-kit feature</span></label>\n      <div class=\"field\" style=\"margin-top:12px\"><label>Starter-kit provider</label>\n        <select id=\"playerCmdStarterProvider\">\n          <option value=\"Auto\">Auto (prefer Th3Essentials when detected)</option>\n          <option value=\"NSE\">Newfie's Server Essentials</option>\n          <option value=\"Th3Essentials\">Th3Essentials</option>\n        </select>\n      </div>\n      <div class=\"compactNote\" style=\"margin-top:12px\"><code>/setstarterkit</code> snapshots the admin's occupied hotbar slots. Players can claim once with <code>/starterkit</code>. When Th3Essentials is installed, its root kit aliases are left untouched; selecting NSE keeps the suite implementation available through <code>/nse starterkit</code> and <code>/nse setstarterkit</code>.</div>\n    </div>\n\n  </div>\n  </div>\n  <div id=\"playerCommandPanel-roles\" class=\"playerCommandPanel\" role=\"tabpanel\" aria-labelledby=\"playerCommandTab-roles\" hidden>\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><div><h3>Teleport Role Access &amp; Cooldowns</h3><div class=\"small\">Configure each server role independently for commands that move a player.</div></div><div class=\"spacer\"></div><button id=\"playerCmdRolePolicyReset\">Clear All Role Overrides</button></div>\n    <details class=\"compactNote\"><summary>Default access, cooldowns and warp behavior</summary><p><b>Defaults:</b> <code>/spawn</code>, <code>/home</code>, <code>/back</code>, <code>/warp</code> and <code>/rtp</code> remain allowed when a role has no override. For <code>/t2p</code> and <code>/t2m</code>, an unconfigured role is allowed only when it has <code>controlserver</code> or <code>root</code>. Turning Access off blocks that role from the command. A cooldown of <code>-1</code> inherits the normal command/warp cooldown; <code>0</code> removes the cooldown for that role. For <code>/warp</code>, a role cooldown overrides the destination/default cooldown, while each warp's own role/privilege access rules still also apply.</p></details>\n    <div class=\"toolbar\" style=\"margin-top:12px\"><label for=\"playerCmdRoleCommand\">Command</label><select id=\"playerCmdRoleCommand\" aria-label=\"Command to configure\"><option value=\"spawn\">/spawn</option><option value=\"home\">/home</option><option value=\"back\">/back</option><option value=\"warp\">/warp</option><option value=\"t2p\">/t2p</option><option value=\"t2m\">/t2m</option><option value=\"rtp\">/rtp</option></select><span class=\"small\">Inherited follows the server default or the saved * policy. Choose Override to change a role.</span></div>\n    <div class=\"tableWrap\" style=\"margin-top:12px;overflow:auto\">\n      <table class=\"compactTable\">\n        <thead><tr><th>Role</th><th>Policy</th><th>Access</th><th>Cooldown (seconds)</th></tr></thead>\n        <tbody id=\"playerCmdRolePolicyRows\"><tr><td colspan=\"4\" class=\"muted\">Loading server roles…</td></tr></tbody>\n      </table>\n    </div>\n  </div>\n  </div>\n  <div id=\"playerCommandPanel-permissions\" class=\"playerCommandPanel\" role=\"tabpanel\" aria-labelledby=\"playerCommandTab-permissions\" hidden>\n  <div class=\"card perfSection permissionManagerCard\">\n    <div class=\"cardHeader\"><div><h3>Role & Permissions Manager</h3><div class=\"small\">Inspect configured Vintage Story roles and safely manage online-player role/direct privilege overrides.</div></div><div class=\"spacer\"></div><button id=\"playerPermRefresh\">Refresh Permissions</button></div>\n    <div class=\"compactNote\"><b>Persistence:</b> role assignments and direct permanent grants use Vintage Story's permission APIs. Role definitions themselves still come from <code>serverconfig.json</code>; this panel intentionally does not rewrite server role definitions while the server is live.</div>\n    <div class=\"playerPermissionSearch\"><label for=\"playerPermissionSearch\">Find an online player</label><input id=\"playerPermissionSearch\" type=\"search\" placeholder=\"Name, UID or role\" style=\"width:100%\"><span id=\"playerPermissionSearchCount\" class=\"small\" role=\"status\"></span></div><datalist id=\"playerPermissionPrivilegeOptions\"></datalist>\n    <div class=\"split\" style=\"margin-top:12px\">\n      <div><div class=\"cardHeader\"><h3 style=\"font-size:15px\">Configured Roles</h3></div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Role</th><th>Level</th><th>Privileges</th></tr></thead><tbody id=\"playerPermRoleRows\"><tr><td colspan=\"3\" class=\"muted\">Load permissions to inspect roles.</td></tr></tbody></table></div></div>\n      <div><div class=\"cardHeader\"><h3 style=\"font-size:15px\">Online Player Access</h3></div><div class=\"tableWrap dataScroll\"><table><thead><tr><th>Player</th><th>Role</th><th>Direct grants</th><th>Denied</th><th>Manage</th></tr></thead><tbody id=\"playerPermPlayerRows\"><tr><td colspan=\"5\" class=\"muted\">Load permissions to inspect players.</td></tr></tbody></table></div></div>\n    </div>\n    <div class=\"compactNote\" style=\"margin-top:10px\">Use direct grants for exceptions. Use Deny when a player must lose a privilege even if their role grants it. Changing a player's role can alter many permissions at once.</div>\n  </div>\n\n  </div>\n</section>\n\n<section id=\"warps\">\n  <div class=\"pageTitle\"><div><h2>Warp Management</h2><div class=\"subtitle\">Create destinations, configure teleport costs, and manage global warp behavior.</div></div></div>\n  <div id=\"warpManagementNotice\" class=\"infoBox\">Warps are stored in <code>NewfiesWarps.json</code>. Global <code>/warp</code> access is controlled from Player Commands; each destination can also require specific roles or privileges here.</div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Warp Defaults</h3><div class=\"spacer\"></div><button id=\"warpReload\">Reload Warps</button><button id=\"warpDefaultsSave\" class=\"primary\">Save Defaults</button></div>\n    <label class=\"toggleLine\"><input id=\"warpDefaultCancelMove\" type=\"checkbox\" checked> Cancel warm-up when player moves</label>\n    <div class=\"row\" style=\"margin-top:12px\">\n      <div class=\"field\"><label>Default cooldown (seconds)</label><input id=\"warpDefaultCooldown\" type=\"number\" min=\"0\" max=\"86400\" value=\"60\"></div>\n      <div class=\"field\"><label>Default warm-up (seconds)</label><input id=\"warpDefaultWarmup\" type=\"number\" min=\"0\" max=\"300\" value=\"5\"></div>\n    </div>\n    <div class=\"compactNote\" style=\"margin-top:12px\">Individual warps can override the cooldown, warm-up, movement rule, and optional item cost. Use <code>-1</code> below to inherit a default.</div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Warp Destinations</h3><div class=\"spacer\"></div><span id=\"warpCountState\" class=\"small\">0 configured</span><button id=\"warpNew\">New</button><button id=\"warpSave\" class=\"primary\">Save Warp</button></div>\n    <div class=\"row\" style=\"align-items:end;flex-wrap:wrap\">\n      <div class=\"field\"><label>Name</label><input id=\"warpName\" maxlength=\"32\" placeholder=\"market\"></div>\n      <div class=\"field\"><label>Display name</label><input id=\"warpDisplayName\" maxlength=\"64\" placeholder=\"Market\"></div>\n      <label class=\"toggleLine\"><input id=\"warpEnabled\" type=\"checkbox\" checked> Enabled</label>\n      <div class=\"field\"><label>X</label><input id=\"warpX\" type=\"number\" step=\"0.01\"></div>\n      <div class=\"field\"><label>Y</label><input id=\"warpY\" type=\"number\" step=\"0.01\"></div>\n      <div class=\"field\"><label>Z</label><input id=\"warpZ\" type=\"number\" step=\"0.01\"></div>\n    </div>\n    <div class=\"row\" style=\"align-items:end;flex-wrap:wrap;margin-top:10px\">\n      <div class=\"field\"><label>Cooldown override</label><input id=\"warpCooldown\" type=\"number\" min=\"-1\" max=\"86400\" value=\"-1\"></div>\n      <div class=\"field\"><label>Warm-up override</label><input id=\"warpWarmup\" type=\"number\" min=\"-1\" max=\"300\" value=\"-1\"></div>\n      <div class=\"field\"><label>Cancel on move</label><select id=\"warpCancelMove\"><option value=\"default\">Default</option><option value=\"true\">On</option><option value=\"false\">Off</option></select></div>\n      <label class=\"toggleLine\"><input id=\"warpCostEnabled\" type=\"checkbox\"> Require item cost</label>\n      <div class=\"field grow\"><label>Cost item code</label><input id=\"warpCostItem\" placeholder=\"game:gear-rusty\"></div>\n      <div class=\"field\"><label>Quantity</label><input id=\"warpCostQty\" type=\"number\" min=\"1\" max=\"65535\" value=\"1\"></div>\n    </div>\n    <div class=\"compactNote\" style=\"margin-top:12px\"><b>Warp Access Control</b> · Leave Public for everyone with <code>/warp</code>. Root/controlserver staff always bypass individual warp restrictions for administration/testing.</div>\n    <div class=\"row\" style=\"align-items:flex-start;flex-wrap:wrap;margin-top:10px\">\n      <div class=\"field\" style=\"min-width:210px\"><label>Access policy</label><select id=\"warpAccessMode\"><option value=\"public\">Public</option><option value=\"any\">Any listed role or privilege</option><option value=\"all\">Role + all listed privileges</option></select></div>\n      <div class=\"field\" style=\"min-width:250px\"><label>Allowed roles</label><select id=\"warpAllowedRoles\" multiple size=\"5\" style=\"min-width:240px\"></select><div class=\"small\">Ctrl/Cmd-click to select multiple roles.</div></div>\n      <div class=\"field grow\" style=\"min-width:300px\"><label>Required privileges</label><input id=\"warpRequiredPrivileges\" list=\"warpPrivilegeSuggestions\" placeholder=\"example: chat, nse.vipwarp\"><datalist id=\"warpPrivilegeSuggestions\"></datalist><div class=\"small\">Comma-separated. In Any mode one match is enough; in All mode every listed privilege is required.</div></div>\n    </div>\n    <div class=\"compactNote\" style=\"margin:12px 0\">In-game shortcut: stand at a destination and use <code>/setwarp &lt;name&gt;</code>. Optional cost: <code>/setwarpcost &lt;warp&gt; game:gear-rusty 2</code>.</div>\n    <div class=\"tableWrap\"><table><thead><tr><th>Warp</th><th>Position</th><th>Cooldown</th><th>Warm-up</th><th>Cost</th><th>Access</th><th>Status</th><th>Actions</th></tr></thead><tbody id=\"warpRows\"></tbody></table></div>\n  </div>\n</section>\n\n\n<section id=\"discord\">\n  <div class=\"pageTitle\"><div><h2>Discord</h2><div class=\"subtitle\">Bot health, announcements, account linking, and channel routing for the unified Discord module.</div></div></div>\n  <div id=\"discordNotice\" class=\"infoBox\">Loading Discord integration status…</div>\n  <div id=\"discordMetrics\" class=\"grid perfSection\"></div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Connection & Chat Bridge</h3><div class=\"spacer\"></div><button id=\"discordRefresh\">Refresh</button><button id=\"discordTestChat\">Test Main Channel</button></div>\n    <div class=\"row\" style=\"align-items:center;margin-bottom:12px\">\n      <label class=\"toggleLine\"><input id=\"discordTransportEnabled\" type=\"checkbox\"> Discord module enabled</label>\n      <label class=\"toggleLine\"><input id=\"discordChatEnabled\" type=\"checkbox\"> Chat bridge enabled</label>\n      <label class=\"toggleLine\"><input id=\"discordGameToDiscord\" type=\"checkbox\"> Game → Discord</label>\n      <label class=\"toggleLine\"><input id=\"discordDiscordToGame\" type=\"checkbox\"> Discord → Game</label>\n    </div>\n    <div class=\"row\" style=\"align-items:center;margin-bottom:12px\">\n      <label class=\"toggleLine\"><input id=\"discordBoldGameSenderLabel\" type=\"checkbox\" checked> Bold VS role + player label in Discord</label>\n      <label class=\"toggleLine\"><input id=\"discordUseGameRoleColor\" type=\"checkbox\"> Use VS role color in Discord</label>\n      <span class=\"small\">Role color uses a Discord embed accent bar because Discord does not support arbitrary inline text colors.</span>\n    </div>\n    <div class=\"row\" style=\"align-items:center;margin-bottom:12px\">\n      <div class=\"field\"><label>Discord → game sender-name color</label><input id=\"discordNameColor\" type=\"color\" value=\"#5865F2\" style=\"width:86px;height:38px;padding:3px\"></div>\n      <button id=\"discordSaveNameColor\">Save Color</button>\n      <label class=\"toggleLine\"><input id=\"discordShowDcTag\" type=\"checkbox\"> Add [DC] before Discord names</label>\n      <label class=\"toggleLine\"><input id=\"discordBoldSenderName\" type=\"checkbox\"> Bold Discord sender names in game</label>\n      <span class=\"small\">Only the sender label is colored/bolded; message text stays normal.</span>\n    </div>\n    <div class=\"row\" style=\"align-items:center;margin-bottom:12px\">\n      <label class=\"toggleLine\"><input id=\"discordCommandsEnabled\" type=\"checkbox\"> Slash commands enabled</label>\n      <label class=\"toggleLine\"><input id=\"discordPlayerInfoCommands\" type=\"checkbox\"> Player info commands (/players, /restarttime)</label>\n      <label class=\"toggleLine\"><input id=\"discordStaffCommands\" type=\"checkbox\"> Staff moderation (/announce, /kick, /ban, /mute)</label>\n      <label class=\"toggleLine\"><input id=\"discordRestartCommands\" type=\"checkbox\"> Restart command (/restart)</label>\n    </div>\n    <div class=\"row\">\n      <div class=\"field grow\"><label>Guild ID</label><input id=\"discordGuildId\" placeholder=\"Discord server/guild snowflake\"></div>\n      <button id=\"discordSaveGuild\">Save Guild</button>\n      <div class=\"field grow\"><label>Invite URL</label><input id=\"discordInviteUrl\" placeholder=\"https://discord.gg/...\"></div>\n      <button id=\"discordSaveInvite\">Save Invite</button>\n    </div>\n    <div class=\"compactNote\" style=\"margin-top:12px\"><b>Security:</b> the bot token is never returned by this API and never appears in Shift+L. This page only reports whether a server-side token is configured.</div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Discord Announcements</h3><div class=\"spacer\"></div><span class=\"small\">Channel ID 0 inherits the main chat channel.</span></div>\n    <div class=\"tableWrap dataScrollTall\">\n      <table><thead><tr><th>Event</th><th>Enabled</th><th>Channel ID</th><th>Message format</th><th></th></tr></thead><tbody id=\"discordAnnouncementRows\"></tbody></table>\n    </div>\n  </div>\n\n  <div class=\"card perfSection\">\n    <div class=\"cardHeader\"><h3>Community MOTD Discord Feeds</h3><div class=\"spacer\"></div><span class=\"small\">Choose which Discord channels supply the MOTD feed content.</span></div>\n    <div class=\"row\" style=\"align-items:center;margin-bottom:12px\">\n      <label class=\"toggleLine\"><input id=\"discordMotdEnabled\" type=\"checkbox\"> Enable Discord MOTD provider</label>\n      <span class=\"small\">The Community MOTD page separately controls which feeds are displayed or merged.</span>\n    </div>\n    <div class=\"row\">\n      <div class=\"field grow\"><label>Announcements channel ID</label><input id=\"discordMotdAnnouncementsChannel\" placeholder=\"0 = no Discord announcements feed\"></div><button id=\"discordSaveMotdAnnouncements\">Save</button>\n      <div class=\"field grow\"><label>Updates channel ID</label><input id=\"discordMotdUpdatesChannel\" placeholder=\"0 = no Discord updates feed\"></div><button id=\"discordSaveMotdUpdates\">Save</button>\n    </div>\n    <div class=\"row\" style=\"margin-top:10px\">\n      <div class=\"field grow\"><label>Events channel ID</label><input id=\"discordMotdEventsChannel\" placeholder=\"0 = no Discord events feed\"></div><button id=\"discordSaveMotdEvents\">Save</button>\n      <div class=\"field\"><label>Recent messages per feed</label><input id=\"discordMotdMaxItems\" type=\"number\" min=\"1\" max=\"25\"></div><button id=\"discordSaveMotdMaxItems\">Save</button>\n    </div>\n    <div class=\"compactNote\" style=\"margin-top:12px\">Channel IDs are owned by Discord 1.0.8. The Community MOTD settings decide whether Announcements, Updates, and Events are enabled and whether local content is merged with these Discord feeds.</div>\n  </div>\n\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Account Linking</h3><div class=\"spacer\"></div><span id=\"discordLinkModuleState\" class=\"small\"></span></div>\n      <label class=\"toggleLine\"><input id=\"discordLinkEnabled\" type=\"checkbox\"> Enable Discord account linking</label>\n      <label class=\"toggleLine\"><input id=\"discordLinkCommands\" type=\"checkbox\"> Enable Discord /link commands</label>\n      <label class=\"toggleLine\"><input id=\"discordLinkMultiple\" type=\"checkbox\"> Allow one Discord account to link multiple VS accounts</label>\n      <label class=\"toggleLine\"><input id=\"discordLinkLog\" type=\"checkbox\"> Log link/unlink changes</label>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <div class=\"field\"><label>Code length</label><input id=\"discordCodeLength\" type=\"number\" min=\"6\" max=\"12\"></div>\n        <button id=\"discordSaveCodeLength\">Save</button>\n        <div class=\"field\"><label>Expiry seconds</label><input id=\"discordCodeExpiry\" type=\"number\" min=\"60\" max=\"3600\"></div>\n        <button id=\"discordSaveCodeExpiry\">Save</button>\n        <div class=\"field\"><label>Cooldown seconds</label><input id=\"discordCodeCooldown\" type=\"number\" min=\"0\" max=\"600\"></div>\n        <button id=\"discordSaveCodeCooldown\">Save</button>\n      </div>\n      <div id=\"discordLinkCounts\" class=\"compactNote\" style=\"margin-top:12px\"></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Channels & Routing</h3><div class=\"spacer\"></div></div>\n      <div class=\"row\">\n        <div class=\"field grow\"><label>Main chat channel ID</label><input id=\"discordChatChannel\"></div><button id=\"discordSaveChatChannel\">Save</button>\n      </div>\n      <div class=\"row\" style=\"margin-top:10px;align-items:center\">\n        <label class=\"toggleLine\"><input id=\"discordAdminAuditEnabled\" type=\"checkbox\"> Admin audit</label>\n        <div class=\"field grow\"><label>Admin audit channel ID</label><input id=\"discordAdminChannel\"></div><button id=\"discordSaveAdminChannel\">Save</button><button id=\"discordTestAdmin\">Test</button>\n      </div>\n      <div class=\"row\" style=\"margin-top:10px;align-items:center\">\n        <label class=\"toggleLine\"><input id=\"discordAntiCheatEnabled\" type=\"checkbox\"> Client Integrity / Anti-Cheat</label>\n        <div class=\"field grow\"><label>Anti-Cheat channel ID</label><input id=\"discordAntiCheatChannel\"></div><button id=\"discordSaveAntiCheatChannel\">Save</button><button id=\"discordTestAntiCheat\">Test</button>\n      </div>\n      <details class=\"helpDisclosure\" style=\"margin-top:12px\"><summary>Connected guild text channels</summary><div><pre id=\"discordChannelList\" class=\"status\">No channel list loaded.</pre></div></details>\n    </div>\n  </div>\n</section>\n\n<section id=\"web\">\n  <div class=\"pageTitle\"><div><h2>Web Server</h2><div class=\"subtitle\">Panel availability, exposure, authentication, accounts, and session security.</div></div></div>\n  <div id=\"webSecurity\"></div>\n  <div id=\"webMetrics\" class=\"grid perfSection\"></div>\n  <div class=\"card perfSection\" id=\"featureGatesCard\">\n    <div class=\"cardHeader\"><h3>Suite Feature Gates</h3><div class=\"spacer\"></div><button id=\"featureGatesRefresh\">Refresh</button></div>\n    <div class=\"compactNote\" style=\"margin-bottom:10px\"><b>Performance master switches:</b> an OFF feature is not started on the next server boot, so its listeners, timers, workers, file watchers, and network hooks are not registered. Changes are saved immediately but require a server restart to fully apply.</div>\n    <div id=\"featureGateRows\" class=\"smartGrid\"><div class=\"empty\">Loading feature gates…</div></div>\n  </div>\n  <div class=\"card perfSection\" id=\"webAccountsCard\">\n    <div class=\"cardHeader\"><h3>Panel Admin Accounts</h3><div class=\"spacer\"></div><span id=\"webAccountCount\" class=\"small\"></span><button id=\"webAccountsRefresh\">Refresh</button></div>\n    <div class=\"compactNote\" style=\"margin-bottom:10px\">The primary web credential is the <b>Owner</b>. Additional accounts have separate passwords and can be revoked without changing the Owner password. Only the Owner can manage accounts.</div>\n    <div id=\"webOwnerAccount\" class=\"infoBox\" style=\"margin-bottom:12px\">Loading Owner account…</div>\n    <div id=\"webAccountCreateArea\">\n      <div class=\"row\" style=\"align-items:end;margin-bottom:12px\">\n        <div class=\"field grow\"><label>Username</label><input id=\"webAccountUsername\" autocomplete=\"off\" placeholder=\"staffname\"></div>\n        <div class=\"field grow\"><label>Password</label><input id=\"webAccountPassword\" type=\"password\" autocomplete=\"new-password\" placeholder=\"minimum 10 characters\"></div>\n        <div class=\"field\"><label>Role</label><select id=\"webAccountRole\"><option value=\"Administrator\">Administrator</option><option value=\"ReadOnly\">Read Only</option></select></div>\n        <button id=\"webAccountCreate\" class=\"primary\">Add Account</button>\n      </div>\n      <div class=\"compactNote\" style=\"margin-bottom:12px\"><b>Administrator:</b> full authenticated panel access. <b>Read Only:</b> can inspect status/diagnostics but server-side mutation endpoints reject changes.</div>\n    </div>\n    <div class=\"tableWrap dataScroll\">\n      <table><thead><tr><th>User</th><th>Role</th><th>State</th><th>Created</th><th>Last login</th><th>Actions</th></tr></thead><tbody id=\"webAccountRows\"><tr><td colspan=\"6\" class=\"muted\">Loading accounts…</td></tr></tbody></table>\n    </div>\n    <div id=\"webAccountResetArea\" class=\"row\" style=\"align-items:end;margin-top:12px\">\n      <div class=\"field grow\"><label>Reset password for</label><select id=\"webAccountResetUser\"><option value=\"\">Select account…</option></select></div>\n      <div class=\"field grow\"><label>New password</label><input id=\"webAccountResetPassword\" type=\"password\" autocomplete=\"new-password\" placeholder=\"minimum 10 characters\"></div>\n      <button id=\"webAccountResetPasswordBtn\">Reset Password</button>\n    </div>\n  </div>\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Owner Credential</h3></div>\n      <div class=\"compactNote\">Change the primary Owner password from Vintage Story chat/console with <b>controlserver</b>. Existing web sessions are invalidated when the password changes.</div>\n      <pre class=\"status\" style=\"margin-top:10px\">/serverutils web password &lt;your-password&gt;</pre>\n    </div>\n    <div class=\"card\">\n      <div class=\"cardHeader\"><h3>Exposure Guidance</h3></div>\n      <div class=\"compactNote\">Loopback-only access can run without login for local administration. For LAN/public exposure, use named credentials and HTTPS through a trusted reverse proxy or tunnel. Network/bind settings remain deliberately controlled from the game/config rather than this browser.</div>\n    </div>\n  </div>\n  <details class=\"helpDisclosure\" style=\"margin-top:12px\"><summary>Technical listener and request details</summary><div><pre id=\"webStatus\" class=\"status\">Loading…</pre></div></details>\n</section>\n\n<section id=\"help\">\n  <div class=\"pageTitle\"><div><h2>Help & About</h2><div class=\"subtitle\">What the measurements mean, what they do not mean, keyboard shortcuts, privacy, and build identity.</div></div></div>\n  <div class=\"grid\">\n    <div class=\"card\"><div class=\"metricLabel\">Mod version</div><div class=\"metricValue\">__NSS_VERSION__</div></div>\n    <div class=\"card\"><div class=\"metricLabel\">Build</div><div class=\"metricValue\" style=\"font-size:17px\">__NSS_BUILD_ID__</div></div>\n    <div class=\"card\"><div class=\"metricLabel\">Vintage Story target</div><div class=\"metricValue\">1.22.7</div></div>\n    <div class=\"card\"><div class=\"metricLabel\">Dashboard philosophy</div><div class=\"metricValue\" style=\"font-size:17px\">Evidence first</div><div class=\"small\">Measured ≠ inferred ≠ correlated</div></div>\n  </div>\n  <div class=\"helpGrid\">\n    <div class=\"card helpTerm\"><h3>Measured</h3><p class=\"small\">A value taken directly from server counters, stored logs, or the manual engine profiler. Examples: CPU, heap, server-wide bytes, BlockLogger queue, FrameProfiler timing.</p></div>\n    <div class=\"card helpTerm\"><h3>Inferred</h3><p class=\"small\">A conclusion derived from measured signals. Example: possible retained-memory growth based on a rising post-Gen2 heap floor.</p></div>\n    <div class=\"card helpTerm\"><h3>Correlated</h3><p class=\"small\">Two events changed at similar times. Correlation is a lead for investigation, not automatic mod blame or causation.</p></div>\n    <div class=\"card helpTerm\"><h3>Activity Proxy</h3><p class=\"small\">Block/container activity counts show where interactions are happening. They are intentionally not labeled block-entity CPU cost.</p></div>\n    <div class=\"card helpTerm\"><h3>Pressure Score</h3><p class=\"small\">A triage score combining entity count, unique entity types and players in a chunk. It is not milliseconds of chunk CPU time.</p></div>\n    <div class=\"card helpTerm\"><h3>P95 Tick Time</h3><p class=\"small\">95% of measured profiled ticks were at or below this time. Use the manual engine profiler when exact timing/ownership matters.</p></div>\n  </div>\n  <div class=\"grid perfSection\">\n    <div class=\"card\">\n      <h3>Keyboard Shortcuts</h3>\n      <p><span class=\"kbd\">Ctrl K</span> Global search / command palette</p>\n      <p><span class=\"kbd\">G</span> then <span class=\"kbd\">D</span> Dashboard · <span class=\"kbd\">P</span> Performance · <span class=\"kbd\">A</span> Action Center · <span class=\"kbd\">M</span> Memory · <span class=\"kbd\">H</span> Suite Health</p>\n      <p><span class=\"kbd\">R</span> Refresh current page when not typing</p>\n      <p><span class=\"kbd\">Esc</span> Close command palette / notification panel / incident detail</p>\n    </div>\n    <div class=\"card\">\n      <h3>Privacy & Safety</h3>\n      <p class=\"small\">Diagnostic bundles exclude session tokens, CSRF tokens, password hashes/salts, one-time plaintext passwords and raw configuration snapshot JSON. Audit remote addresses are redacted in exported bundles.</p>\n      <p class=\"small\">Safe Diagnostics Mode keeps lightweight diagnostics on, browser Live Updates off, and locks state-changing Tungsten operations plus the manual engine profiler.</p>\n    </div>\n  </div>\n  <div class=\"card perfSection\">\n    <h3>Workflow</h3>\n    <p class=\"small\">A typical investigation is: <b>Alert → incident black box → timeline → entity/chunk or memory evidence → manual engine profile when exact timing is required → measured optimization/config comparison → diagnostic bundle if support is needed.</b></p>\n  </div>\n</section>\n</main>\n</div>\n\n<div id=\"notificationPanel\">\n  <div class=\"cardHeader\"><h3>Notifications</h3><div class=\"spacer\"></div><button id=\"notificationClose\">Close</button></div>\n  <div id=\"notificationList\"><div class=\"emptyAction\">No active alerts.</div></div>\n</div>\n\n<div id=\"panelLeaderboardOverlay\" class=\"overlay\" aria-hidden=\"true\">\n  <div class=\"modal leaderboardPanelModal\">\n    <div class=\"modalHeader panelLbHeader\"><div class=\"panelLbTitle\"><span class=\"panelLbTitleIcon\">\ud83c\udfc6</span><div><h3>Server Leaderboards</h3><div class=\"small\">XSkills · Playtime · Community progression</div></div></div><div class=\"spacer\"></div><button id=\"panelLeaderboardRefresh\">Refresh</button><button id=\"panelLeaderboardClose\">Close</button></div>\n    <div class=\"panelLbTabs\"><button class=\"panelLbTab active\" data-panel-lb-tab=\"overview\">Overview</button><button class=\"panelLbTab\" data-panel-lb-tab=\"skills\">Skills</button><button class=\"panelLbTab\" data-panel-lb-tab=\"playtime\">Playtime</button></div>\n    <div id=\"panelLeaderboardStatus\" class=\"panelLbStatus\"></div>\n    <div id=\"panelLeaderboardNotice\"></div>\n    <div id=\"panelLeaderboardBody\" class=\"panelLbBody\"><div class=\"panelLbEmpty\">Open the leaderboard to load rankings.</div></div>\n  </div>\n</div>\n\n<div id=\"commandOverlay\" class=\"overlay\">\n  <div class=\"modal\">\n    <div class=\"modalHeader\"><h3>Search Server Essentials Suite</h3><div class=\"spacer\"></div><span class=\"small\">Ctrl+K · Enter · Esc</span><button id=\"commandClose\">Close</button></div>\n    <input id=\"commandInput\" class=\"commandInput\" placeholder=\"Search pages, actions, alerts, mods, watchlist…\">\n    <div id=\"commandResults\" class=\"commandResults\"></div>\n  </div>\n</div>\n\n<div id=\"dashboardCustomizeOverlay\" class=\"overlay\">\n  <div class=\"modal\">\n    <div class=\"modalHeader\"><h3>Customize Dashboard</h3><div class=\"spacer\"></div><button id=\"dashboardCustomizeReset\">Reset</button><button id=\"dashboardCustomizeClose\">Done</button></div>\n    <p class=\"small\">These choices are stored only in this browser.</p>\n    <div id=\"dashboardCustomizeList\" class=\"customizeList\"></div>\n  </div>\n</div>\n\n<button id=\"backToTop\" type=\"button\" aria-label=\"Back to top\" title=\"Back to top\"></button>\n<div id=\"toastHost\"></div>\n\n<script>\nlet csrfToken = \"\";\nlet currentSessionUser = \"\";\nlet currentSessionRole = \"\";\nlet currentSessionOwner = false;\nlet currentSection = localStorage.getItem('nsu.section') || \"dashboard\";\nif(currentSection==='playerAnalytics')currentSection='serverStatus';\nconst sectionScrollPositions = new Map();\nfunction rememberSectionScroll(section=currentSection){if(section)sectionScrollPositions.set(section,window.scrollY||0)}\nfunction restoreSectionScroll(section){\n  const top=sectionScrollPositions.get(section)||0;\n  requestAnimationFrame(()=>window.scrollTo({top,behavior:'auto'}));\n}\nlet liveUpdates = false;\nlet liveTimer = null;\nlet nextLiveRefreshAt = 0;\nlet liveRequestInFlight = false;\nlet lastSectionLiveRefresh = 0;\nlet lastUserActivityAt = Date.now();\nlet lastLiveNetworkAt = 0;\nconst LIVE_ACTIVE_INTERVAL_MS = 4000;\nconst LIVE_IDLE_AFTER_MS = 5 * 60 * 1000;\nconst LIVE_IDLE_INTERVAL_MS = 15000;\nconst MAX_PARALLEL_DASHBOARD_GETS = 3;\nlet activeDashboardGets = 0;\nconst queuedDashboardGets = [];\nconst inFlightDashboardGets = new Map();\nconst sectionRefreshAt = new Map();\nconst SECTION_REFRESH_INTERVAL_MS = {\n  dashboard:8000, serverStatus:8000, reports:10000, logIntelligence:10000,\n  actionCenter:8000, performance:12000, tickDebug:3000, memory:12000, profiler:12000,\n  animals:8000, loginProtection:10000, chatguard:10000, customPatches:12000, communit