led')?.checked,\n    chunkCacheMiB:Math.round(Number($('acOreShieldCacheMiB')?.value||96)),\n    maxCachedChunks:Math.round(Number($('acOreShieldMaxChunks')?.value||4096)),\n    additionalOrePatterns:lines('acOreShieldAdditionalPatterns'),\n    excludedBlockPatterns:lines('acOreShieldExcludedPatterns')\n  };\n}\nasync function saveAntiCheatOreShield(){\n  if(currentSessionRole==='ReadOnly')return;\n  const payload=collectAntiCheatOreShield();\n  if(!payload.enabled&&!confirm('Disable Ore Shield? Hidden ore will be sent normally to clients while it is off. PacketGuard and Client Integrity remain active.'))return;\n  const btn=$('acOreShieldSave');if(btn){btn.disabled=true;btn.dataset.originalText=btn.textContent;btn.textContent='Saving…';}\n  try{\n    const d=await api('/api/anticheat/oreshield',{method:'POST',body:JSON.stringify(payload)});\n    toast(d.message||'Ore Shield settings saved.','success');\n    await loadAntiCheat(false);\n    setAntiCheatTab('oreshield');\n  }catch(e){toast(e.message,'error');}\n  finally{if(btn){btn.disabled=currentSessionRole==='ReadOnly';btn.textContent=btn.dataset.originalText||'Save Ore Shield Settings';delete btn.dataset.originalText;}}\n}\n\n\nlet packetSettingsDirty=false, packetSettingsSaving=false, packetLatestSettings=null;\nfunction updatePacketDraftState(){\n  $('acPacketDraftState').textContent=packetSettingsDirty?'Unsaved changes':'Settings saved';\n  $('acPacketDiscard').hidden=!packetSettingsDirty;\n}\nconst packetDraftInput=e=>{if(e.target.matches('input')&&currentSessionRole!=='ReadOnly'){packetSettingsDirty=true;updatePacketDraftState();}};\n['input','change'].forEach(event=>document.querySelector('[data-ac-panel=\"packet\"]').addEventListener(event,packetDraftInput));\n$('acPacketDiscard').onclick=()=>{if(packetSettingsSaving)return;packetSettingsDirty=false;if(packetLatestSettings)renderAntiCheatPacketGuard(packetLatestSettings.pg,packetLatestSettings.h);updatePacketDraftState();};\nfunction selectPacketSection(k