iskSuspiciousThreshold:Math.round(acNum('acClientIntegrityRiskSuspicious',50)),incidentCorrelationEnabled:!!$('acIncidentCorrelationEnabled').checked,incidentCorrelationWindowSeconds:Math.round(acNum('acIncidentCorrelationWindow',90)),incidentCorrelationRequiredCategories:Math.round(acNum('acIncidentCorrelationCategories',2)),incidentCorrelationMaxRiskBonus:Math.round(acNum('acIncidentCorrelationMaxBonus',20)),\n  historyEnabled:!!$('acHistoryEnabled').checked,historyRetentionDays:Math.round(acNum('acHistoryRetentionDays',90)),historyMaxRecords:Math.round(acNum('acHistoryMaxRecords',500))\n};}\nfunction collectAntiCheatClientSettings(){\n  const startup=Math.round(acNum('acStartupChallengeTimeout',300));\n  const hard=Math.max(startup,Math.round(acNum('acStartupHardLimit',900)));\n  if($('acStartupHardLimit'))$('acStartupHardLimit').value=String(hard);\n  return {\n    requireClient:!!$('acRequireClient').checked || !!$('acStrictClientModDbEnforcement')?.checked,\n    clientModDbVerificationEnabled:!!$('acClientModDbVerification').checked || !!$('acStrictClientModDbEnforcement')?.checked,\n    strictClientModDbEnforcementEnabled:!!$('acStrictClientModDbEnforcement')?.checked,\n    requireHardenedClientCapabilities:!!$('acRequireHardenedCapabilities')?.checked,\n    requireCurrentClientRelease:!!$('acRequireCurrentClientRelease')?.checked,\n    startupIntegrityGateEnabled:!!$('acStartupGateEnabled')?.checked,\n    startupIntegrityGateBlockWorldInteractions:!!$('acStartupGateBlockInteractions')?.checked,\n    startupIntegrityGateRequireClean:!!$('acStartupGateRequireClean')?.checked,\n    startupIntegrityGateDisconnectOnFailure:!!$('acStartupGateDisconnectFailure')?.checked,\n    startupIntegrityGateNoticeCooldownSeconds:Math.round(acNum('acStartupGateNoticeCooldown',4)),\n    challengeTimeoutSeconds:Math.round(acNum('acRoutineChallengeTimeout',30)),\n    startupChallengeTimeoutSeconds:startup,\n    startupChallengeHeartbeatExtensionSeconds:Math.round(acNum('acStartupHeartbeatExtension',120)),\n    startupChallengeHardLimitSeconds:hard,\n    clientHelloGraceSeconds:Math.round(acNum('acClientHelloGrace',90)),\n    clientHelloDisconnectDelaySeconds:Math.round(acNum('acClientHelloDisconnectDelay',60)),\n    heartbeatTimeoutSeconds:Math.round(acNum('acHeartbeatTimeout',180)),\n    rescanMinutes:Math.round(acNum('acRescanMinutes',15)),\n    runtimeRescanOnChange:!!$('acRuntimeRescanOnChange').checked,\n    runtimeChangeRescanCooldownSeconds:Math.round(acNum('acRuntimeChangeCooldown',30))\n  };\n}\nasync function saveAntiCheatClientSettings(){\n  if(currentSessionRole==='ReadOnly')return;\n  const payload=collectAntiCheatClientSettings();\n  if(!payload.requireClient&&!confirm('Client requirement is OFF. Players without Client Integrity will no longer be disconnected by the Anti-Cheat missing-client watchdog. Continue?'))return;\n  if(!payload.clientModDbVerificationEnabled&&!confirm('Turn OFF official ModDB client-mod verification? Local inventory/blacklist checks remain, but modified copies of allowed ModDB releases will no longer be automatically compared to official fingerprints.'))return;\n  if(payload.strictClientModDbEnforcementEnabled&&!antiCheatSnapshot.strictClientModDbEnforcementEnabled&&!confirm('Enable strict client-mod database enforcement now? Any reported third-party mod that does not exactly match the server baseline, an approved custom fingerprint, or an official same-version ModDB fingerprint will be kicked.'))return;\n  if(payload.requireCurrentClientRelease&&!antiCheatSnapshot.requireCurrentClientRelease){const required=String(antiCheatSnapshot.expectedClientVersion||antiCheatSnapshot.serverCompanionVersion||'the server-installed version');if(!confirm(`Require every client to match server-installed Client Integrity v${required} now? Clients reporting a different semantic version will fail the startup compatibility gate until they install the same version.`))return;}\n  if(payload.requireHardenedClientCapabilities&&!antiCheatSnapshot.requireHardenedClientCapabilities&&!confirm('Require hardened report-hash v2 and bound-heartbeat support now? Clients missing those capabilities will fail the startup compatibility gate.'))return;\n  const btn=$('acClientSettingsSave');\n  if(btn){btn.disabled=true;btn.dataset.originalText=btn.textContent;btn.textContent='Saving…';}\n  try{\n    const d=await api('/api/anticheat/client-settings',{method:'POST',body:JSON.stringify(payload)});\n    toast(d.message||'Client scan settings saved.','success');\n    await loadAntiCheat(false);\n  }catch(e){toast(e.message,'error');await loadAntiCheat(false);}\n  finally{if(btn){btn.disabled=currentSessionRole==='ReadOnly';btn.textContent=btn.dataset.originalText||'Save Client Scan Settings';delete btn.dataset.originalText;}}\n}\nasync function loadAntiCheatFullConfig(){\n  if(!$('acFullConfigJson'))return;\n  $('acFullConfigState').textContent='Loading…';\n  try{const d=await api('/api/anticheat/full-config');$('acFullConfigJson').value=String(d.json||'{}');$('acFullConfigState').textContent='Loaded current configuration.';}catch(e){$('acFullConfigState').textContent='Load failed';toast(e.message,'error');}\n}\nfunction formatAntiCheatFullConfig(){\n  try{$('acFullConfigJson').value=JSON.stringify(JSON.parse($('acFullConfigJson').value||'{}'),null,2);$('acFullConfigState').textContent='JSON formatted.';}catch(e){toast('Invalid JSON: '+e.message,'error');}\n}\nasync function saveAntiCheatFullConfig(){\n  if(currentSessionRole==='ReadOnly')return;\n  let json=$('acFullConfigJson').value||'';\n  try{json=JSON.stringify(JSON.parse(json),null,2);$('acFullConfigJson').value=json;}catch(e){toast('Invalid JSON: '+e.message,'error');return;}\n  const typed=prompt('This saves the complete Anti-Cheat configuration and can immediately change live protection behavior. Type SAVE to continue:','');if(typed!=='SAVE')return;\n  const btn=$('acFullConfigSave');if(btn){btn.disabled=true;btn.textContent='Saving…';}\n  try{const d=await api('/api/anticheat/full-config',{method:'POST',body:JSON.stringify({json})});toast(d.message||'Full Anti-Cheat configuration saved.','success');$('acFullConfigState').textContent='Saved.';await loadAntiCheat(false);await loadAntiCheatFullConfig();}catch(e){toast(e.message,'error');$('acFullConfigState').textContent='Save failed.';}finally{if(btn){btn.disabled=currentSessionRole==='ReadOnly';btn.textContent='Save Full Configuration';}}\n}\nasync function saveAntiCheatModuleState(){\n  const enabled=!!$('acModuleEnabled').checked;\n  if(!enabled&&!confirm('Disable Anti-Cheat? Client scans, repack detection, PacketGuard checks and automatic Anti-Cheat consequences will stop. Stored reports and the rest of Server Essentials will remain available.'))return;\n  try{\n    const d=await api('/api/anticheat/settings',{method:'POST',body:JSON.stringify({enabled})});\n    toast(d.message||(enabled?'Anti-Cheat enabled.':'Anti-Cheat disabled.'),'success');\n    await loadAntiCheat(false);\n  }catch(e){toast(e.message,'error');await loadAntiCheat(false);}\n}\nasync function saveAntiCheatPacketGuard(){\n  const invalid=[...document.querySelectorAll('[data-ac-panel=packet] input[type=number]')].find(e=>e.value.trim()===''||!e.checkValidity());\n  if(invalid){selectPacketSection(invalid.closest('[data-packet-section]')?.dataset.packetSection||'movement');invalid.focus();invalid.reportValidity();return;}\n  const payload=collectAntiCheatPacketGuard();\n  if(!payload.exemptAdmins&&!confirm('Administrator exemption is OFF. Survival-mode administrators will be checked like normal players. Continue?'))return;\n  if(!payload.exemptMountedPlayers&&!confirm('Mounted-player exemption is OFF. Fast or modded mounts may produce movement findings. Continue?'))return;\n  if(!payload.tpRunesCompatibility&&antiCheatPacketGuard.tpRunesDetected&&!confirm('TP Runes is installed but compatibility is OFF. Legitimate rune teleports may be reported as unauthorized movement. Continue?'))return;\n  const saveBtn=$('acPacketSave');\n  if(saveBtn){saveBtn.disabled=true;saveBtn.dataset.originalText=saveBtn.textContent;saveBtn.textContent='Saving…';}\n  try{\n    packetSettingsSaving=true;\n    document.querySelectorAll('[data-ac-panel=packet] input').forEach(e=>e.disabled=true);$('acPacketDiscard').disabled=true;\n    const d=await api('/api/anticheat/packetguard',{method:'POST',body:JSON.stringify(payload)});\n    packetSettingsDirty=false;updatePacketDraftState();\n    await loadAntiCheat(false);\n    const warningSaved=!!antiCheatPacketGuard.playerWarningEnabled===!!payload.playerWarningEnabled;\n    const noclipSaved=!!antiCheatPacketGuard.noclipEnabled===!!payload.noclipEnabled;\n    if(!warningSaved||!noclipSaved){\n      toast(`Packet protection save did not persist: player warnings ${warningSaved?'OK':'MISMATCH'}, noclip ${noclipSaved?'OK':'MISMATCH'}.`,'error');\n      return;\n    }\n    toast(d.message||'Packet protection saved.','success');\n  }catch(e){toast(e.message,'error');}\n  finally{packetSettingsSaving=false;document.querySelectorAll('[data-ac-panel=packet] input').forEach(e=>e.disabled=currentSessionRole==='ReadOnly');$('acPacketDiscard').disabled=currentSessionRole==='ReadOnly';if(saveBtn){saveBtn.disabled=currentSessionRole==='ReadOnly';saveBtn.textContent=saveBtn.dataset.originalText||'Save Packet Protection';delete saveBtn.dataset.originalText;}}\n}\nfunction acSeverityBadge(sev){const n=Number(sev||0);const label=['Info','Low','Moderate','High','Critical'][Math.max(0,Math.min(4,n))]||String(n);const cls=n>=4?'high':n>=2?'medium':'low';return `<span class=\"badge ${cls}\">${esc(label)}</span>`;}\nasync function loadAntiCheatHistory(playerFilter='',findingFilter=null){\n  if(!$('acHistoryRows'))return;\n  $('acHistoryState').textContent='Loading…';\n  try{\n    const q=String(playerFilter||'').trim();\n    const finding=String(findingFilter===null?($('acHistoryFindingFilter')?.value||''):findingFilter).trim();\n    const d=await api('/api/anticheat/history?limit=250'+(q?'&player='+encodeURIComponent(q):'')+(finding?'&finding='+encodeURIComponent(finding):''));const rows=d.incidents||[];\n    const findingSelect=$('acHistoryFindingFilter');\n    if(findingSelect){\n      const selected=String(d.findingFilter||finding||'');\n      findingSelect.innerHTML='<option value=\"\">All findings</option>'+(d.findingOptions||[]).map(code=>`<option value=\"${esc(code)}\">${esc(code)}</option>`).join('');\n      findingSelect.value=selected;\n    }\n    $('acHistoryState').textContent=`${Number(d.totalRecords||0)} stored · ${rows.length} shown${finding?' · '+finding:''}${d.storageError?' · '+d.storageError:''}`;\n    $('acHistoryMetrics').innerHTML=metric('Stored reports',Number(d.totalRecords||0))+metric('Players',Number(d.uniquePlayers||0))+metric('Last 24 hours',Number(d.last24Hours||0),Number(d.last24Hours||0)>0?'warn':'')+metric('Retention',`${Number(d.retentionDays||0)}d`)+metric('Max records',Number(d.maxRecords||0));\n    $('acHistoryRows').innerHTML=rows.length?rows.map(x=>{const pos=`${Number(x.x||0).toFixed(1)}, ${Number(x.y||0).toFixed(1)}, ${Number(x.z||0).toFixed(1)}${Number(x.dimension||0)!==0?` · dim ${Number(x.dimension)}`:''}`;const risk=`${Number(x.riskBefore||0)} → ${Number(x.riskAfter||0)}`;return `<tr><td>${esc(acDate(x.unixMilliseconds))}</td><td><b>${esc(x.playerName||'')}</b><div class=\"small\"><code>${esc(x.playerUid||'')}</code></div></td><td>${acSeverityBadge(x.severity)}</td><td><b>${esc(x.confidence||'Low')}</b><div class=\"small\">${Number(x.confidenceScore||0)}/100 · ${Number(x.corroboratingSignals||0)} nearby</div></td><td><code>${esc(x.code||'')}</code><div class=\"small\">${esc(x.category||'Other')} · ${esc(x.summary||'')}</div></td><td><b>${esc(risk)}</b><div class=\"small\">${esc(x.statusAfter||'')}</div></td><td><code>${esc(pos)}</code></td><td><span title=\"${esc(x.evidence||'')}\">${esc(String(x.evidence||'').slice(0,150))}${String(x.evidence||'').length>150?'…':''}</span><div class=\"small\" style=\"margin-top:4px\"><b>Why:</b> ${esc(x.why||'')}</div><div class=\"small\"><b>Next:</b> ${esc(x.recommendedAction||'')}</div></td><td>${x.consequence?esc(x.consequence):'<span class=\"muted\">None</span>'}</td></tr>`;}).join(''):'<tr><td colspan=\"9\" class=\"muted\">No persistent anti-cheat reports match this filter.</td></tr>';\n  }catch(e){$('acHistoryState').textContent='Load failed';toast(e.message,'error');}\n}\n\nasync function clearAllAntiCheatHistory(){\n  if(currentSessionRole==='ReadOnly')return;\n  if(!confirm(t('ac.historyClearConfirm')))return;\n  const btn=$('acHistoryClearAll');if(btn)btn.disabled=true;\n  try{\n    const d=await api('/api/anticheat/history/clear',{method:'POST',body:'{}'});\n    toast(d.message||t('ac.historyCleared'),'success');\n    await loadAntiCheatHistory('','');\n  }catch(e){toast(e.message||t('ac.historyClearFailed'),'error');}\n  finally{if(btn)btn.disabled=false;}\n}\n\nfunction acAssemblyClassBadge(x){\n  const n=String(x?.assemblyName||x?.fileName||'').replace(/\\.dll$/i,'').trim();\n  const l=n.toLowerCase();\n  if((x?.associatedModIds||[]).length||x?.associatedWithLoadedMod)return '<span class=\"badge low\">Mod-associated</span>';\n  if(n==='System'||n.startsWith('System.')||n==='Accessibility'||n==='netstandard'||n==='mscorlib'||n.startsWith('Microsoft.')||n==='WindowsBase'||n==='PresentationCore'||n==='PresentationFramework')return '<span class=\"badge low\">Framework / normal</span>';\n  if(l==='vintagestory'||l==='vintagestoryapi'||l==='vintagestorylib'||l==='xplatforminterface')return '<span class=\"badge low\">Game runtime</span>';\n  if(l.startsWith('opentk.'))return '<span class=\"badge low\">Graphics / window runtime</span>';\n  if(l==='skiasharp'||l==='cairo-sharp'||l==='animatedgif')return '<span class=\"badge low\">Graphics / media dependency</span>';\n  if(l==='csogg'||l==='csvorbis')return '<span class=\"badge low\">Audio runtime dependency</span>';\n  if(l==='0harmony'||l==='harmonysharedstate'||l.startsWith('monomod.')||l==='mono.cecil'||l==='mono.nat'||l==='icsharpcode.sharpziplib'||l==='newtonsoft.json'||l==='open.nat'||l==='protobuf-net'||l.startsWith('sqlitepclraw.')||l==='sqlitepclraw'||l==='commandline'||l==='tavis.jsonpatch'||l==='tungsten')return '<span class=\"badge low\">Runtime dependency</span>';\n  return '<span class=\"badge moderate\">Unassociated / review</span>';\n}\n\nfunction antiCheatModPolicyHtml(x){\n  const id=String(x?.modId||'').toLowerCase();\n  if(!id)return '<span class=\"muted\">Unknown ID</span>';\n  if(['game','survival','creative'].includes(id))return '<span class=\"badge low\">Core</span>';\n  if(antiCheatRequiredMods.has(id))return '<span class=\"badge low\">Required</span>';\n  if(antiCheatForbiddenMods.has(id))return currentSessionRole==='ReadOnly'?'<span class=\"badge high\">Blacklisted</span>':`<span class=\"badge high\">Blacklisted</span> <button data-ac-blacklist-add=\"${esc(id)}\">Refresh fingerprint</button>`;\n  return currentSessionRole==='ReadOnly'?'<span class=\"muted\">Allowed</span>':`<button class=\"danger\" data-ac-blacklist-add=\"${esc(id)}\">Blacklist + fingerprint</button>`;\n}\nfunction renderAntiCheatModInventoryRow(x,includeScope=true){\n  const modState=acClientModState(x),tone=modState.tone||'',label=modState.label;\n  const official=x.officialFileName?`<div class=\"small\">Official ${esc(x.officialVersion||x.version||'')} · ${formatBytesTotal(Number(x.officialPackageBytes||0))} · ${Number(x.officialDllCount||0)} DLL${Number(x.officialDllCount||0)===1?'':'s'} · ${formatBytesTotal(Number(x.officialDllBytes||0))}</div>`:'';\n  const compare=(x.officialFileName||x.serverBaselineAvailable)?acRenderLiveModComparison(x,modState):'';\n  const scope=x.loadedOnServer?'<span class=\"badge low\">Shared</span>':'<span class=\"badge\">Client-only</span>';\n  const cell=(name,html)=>`<td><span class=\"mobileCellLabel\">${esc(name)}</span><div class=\"mobileCellValue\">${html}</div></td>`;\n  const cells=[\n    cell('Mod',`<b>${esc(x.modId||'')}</b>`),\n    cell('Version',esc(x.version||'')),\n    cell('Type',esc(x.modType||''))\n  ];\n  if(includeScope)cells.push(cell('Scope',scope));\n  cells.push(cell('File',`${esc(x.fileName||'')}<div class=\"small\">${Number(x.packageBytes||0)>0?formatBytesTotal(Number(x.packageBytes||0)):'Unavailable'} package · ${Number(x.dllCount||0)} DLL${Number(x.dllCount||0)===1?'':'s'} · ${Number(x.dllBytes||0)>0?formatBytesTotal(Number(x.dllBytes||0)):'Unavailable'} DLL bytes</div>`));\n  cells.push(cell('SHA-256',`<code title=\"Package: ${esc(x.sha256||'')}&#10;Normalized content: ${esc(x.contentSha256||'')}&#10;Package bytes: ${Number(x.packageBytes||0)}&#10;DLL count: ${Number(x.dllCount||0)}&#10;DLL bytes: ${Number(x.dllBytes||0)}\">${esc((x.sha256||'').slice(0,16))}${(x.sha256||'').length>16?'…':''}</code>`));\n  cells.push(cell('ModDB Verification',`<span class=\"badge ${tone}\">${esc(label)}</span>${official}${compare}<div class=\"small muted\" title=\"${esc(x.modDbMessage||'')}\">${x.modDbCheckedUtc?`checked ${esc(acRelativeAge(x.modDbCheckedUtc).text)}`:esc(x.modDbMessage||'')}</div>`));\n  cells.push(cell('Policy',antiCheatModPolicyHtml(x)));\n  return `<tr>${cells.join('')}</tr>`;\n}\n\nasync function loadAntiCheatPlayer(player){\n  setAntiCheatTab('players');\n  try{\n    const previousPlayer=antiCheatSelectedPlayer;\n    const d=await api('/api/anticheat/player?player='+encodeURIComponent(player));\n    const resolvedPlayer=d.playerUid||player;if(!previousPlayer||String(previousPlayer)!==String(resolvedPlayer)){antiCheatDrawerTab='overview';antiCheatInventoryLoadedFor='';antiCheatInventoryData=[];antiCheatInventorySnapshots=[];antiCheatInventoryHistory=[];antiCheatInventorySelectedSlot=null;antiCheatInventorySelectedCatalogItem=null;antiCheatInventorySearchCache=[];antiCheatInventoryPlayer={};antiCheatInventoryStatus={};if($('acTabInventoryCount')){$('acTabInventoryCount').textContent='—';$('acTabInventoryCount').classList.remove('good','warn','bad');}}antiCheatSelectedPlayer=resolvedPlayer;\n    $('acDetail').style.display='block';$('acDetailBackdrop')?.classList.add('open');document.body.classList.add('acDrawerOpen');$('acDetailTitle').textContent=`${d.playerName||'Player'} · ${d.status||'Unknown'}`;\n    const selfHash=String(d.clientAssemblySha256||d.clientPackageSha256||'').toLowerCase();\n    const trusted=selfHash&&antiCheatApprovedHashes.has(selfHash);\n    const fam=(d.riskFamilies||[]).map(f=>`<span class=\"stateChip ${f.status==='Suspicious'?'bad':f.status==='Review'?'warn':'good'}\">${esc(f.family||'Risk')} ${Number(f.score||0)} · ${esc(f.status||'Clean')}</span>`).join('');\n    const findings=d.findings||[];\n    const signalCounts={hotkeys:findings.filter(x=>String(x.code||'').startsWith('HOTKEY_')).length,commands:findings.filter(x=>String(x.code||'').startsWith('CLIENT_COMMAND_')).length,assets:findings.filter(x=>String(x.code||'').startsWith('PROTECTED_ASSET_')).length,canonical:findings.filter(x=>['MOD_CANONICAL_MISMATCH','MOD_SERVER_VERSION_MISMATCH','MOD_DLL_SET_MISMATCH','ASSEMBLY_SERVER_HASH_MISMATCH','ASSEMBLY_SIZE_MISMATCH'].includes(String(x.code||''))).length};\n    const verdict=d.startupGatePending?'PENDING':String(d.startupGateVerdict||'NotStarted');\n    const verdictClass=d.startupGatePending?'warn':d.startupIntegrityVerified?(verdict==='Clean'?'good':verdict==='Suspicious'?'bad':'warn'):'muted';\n    const strongFindings=[...findings].sort((a,b)=>Number(b.serverAuthoritative)-Number(a.serverAuthoritative)||Number(b.confidenceScore||0)-Number(a.confidenceScore||0)||Number(b.riskPoints||0)-Number(a.riskPoints||0)||Number(b.severity||0)-Number(a.severity||0));\n    const serverEvidence=findings.filter(x=>x.serverAuthoritative||String(x.evidenceDomain||'')==='ServerBehavior');\n    const riskEvidence=findings.filter(x=>Number(x.riskPoints||0)>0);\n    const integrityEvidence=findings.filter(x=>/Integrity|Patch|Static|Runtime/i.test(String(x.evidenceDomain||'')));\n    const highConfidence=findings.filter(x=>Number(x.confidenceScore||0)>=75);\n    const scanAge=acRelativeAge(d.lastScanUtc), heartbeatAge=acRelativeAge(d.lastHeartbeatUtc);\n    const statusTone=String(d.status||'').toLowerCase()==='suspicious'?'bad':String(d.status||'').toLowerCase()==='review'?'warn':'good';\n    const modStates=(d.mods||[]).map(x=>acClientModState(x));\n    const clientOnlyModCount=(d.mods||[]).filter(x=>!x.loadedOnServer).length;\n    const modOfficial=modStates.filter(x=>x.key==='official').length;\n    const modModified=modStates.filter(x=>x.key==='modified').length;\n    const modDiagnostic=modStates.filter(x=>x.key==='diagnostic').length;\n    const modApproved=modStates.filter(x=>x.key==='approved').length;\n    const modPending=modStates.filter(x=>x.key==='pending').length;\n    const scanMetrics=Array.isArray(d.scannerMetrics)?d.scannerMetrics:[];\n    const scanDuration=scanMetrics.reduce((n,x)=>n+Number(x.durationMs||0),0);\n    const slowestScanner=[...scanMetrics].sort((a,b)=>Number(b.durationMs||0)-Number(a.durationMs||0))[0];\n    const cacheHits=scanMetrics.reduce((n,x)=>n+Number(x.cacheHits||0),0),cacheMisses=scanMetrics.reduce((n,x)=>n+Number(x.cacheMisses||0),0),cacheTotal=cacheHits+cacheMisses;\n    const cacheRate=cacheTotal?Math.round(cacheHits*100/cacheTotal):0;\n    const playerDiagnostics=Array.isArray(d.recentConnectionDiagnostics)?d.recentConnectionDiagnostics:[];\n    const lastDiag=[...playerDiagnostics].sort((a,b)=>Number(b.utc||0)-Number(a.utc||0))[0];\n    if($('acDrawerQuickBar'))$('acDrawerQuickBar').innerHTML=`<span class=\"stateChip ${statusTone}\">${esc(d.status||'Unknown')} · risk ${Number(d.riskScore||0)}</span><span class=\"stateChip ${d.currentClientReleaseSupported?'good':'warn'}\">Client v${esc(d.clientVersion||'missing')} ${d.currentClientReleaseSupported?'matches server':'version differs'}</span><span class=\"stateChip ${heartbeatAge.cls==='bad'?'bad':heartbeatAge.cls==='warn'?'warn':'good'}\">Heartbeat ${esc(heartbeatAge.text)}</span><span class=\"stateChip ${modModified?'bad':modDiagnostic?'warn':'good'}\">Mods ${clientOnlyModCount} client-only · ${modOfficial} verified · ${modModified} modified</span><span class=\"stateChip ${Number(d.findingCount||0)?'warn':'good'}\">${Number(d.findingCount||0)} findings</span>${lastDiag?`<span class=\"stateChip\">Last stage: ${esc(lastDiag.stage||lastDiag.code||'connection')}</span>`:''}`;\n    $('acPlayerOverview').innerHTML=`\n      <div class=\"acInfoTile ${statusTone}\"><div class=\"k\">Risk & Verdict</div><div class=\"v\">${Number(d.riskScore||0)} · ${acStatusBadge(d.status||'Unknown')}</div>${acRiskMeter(d.riskScore)}<div class=\"sub\">${riskEvidence.length} risk-contributing · ${highConfidence.length} high-confidence · ${Number(d.networkPacketsDropped||0)} dropped client packets</div></div>\n      <div class=\"acInfoTile ${d.startupGatePending?'warn':verdict==='Clean'?'good':verdict==='Suspicious'?'bad':'accent'}\"><div class=\"k\">Startup Integrity</div><div class=\"v ${verdictClass}\">${esc(verdict)}</div><div class=\"sub\">${d.startupIntegrityVerified?'Attestation completed':'Awaiting verified startup state'}${Number(d.startupGateBlockedActions||0)>0?` · ${Number(d.startupGateBlockedActions||0)} blocked interactions`:''}<br>${d.startupGateCompletedUtc?`Completed ${esc(acRelativeAge(d.startupGateCompletedUtc).text)}`:'Gate has not completed'}</div></div>\n      <div class=\"acInfoTile accent\"><div class=\"k\">Client Identity</div><div class=\"v\">v${esc(d.clientVersion||'missing')}</div><div class=\"sub\">Game ${esc(d.gameVersion||'—')} · ${esc(d.platform||'—')}<br>${Number(d.reportedModCount||0)} mods · ${Number(d.assemblyCount||0)} assemblies · build ${trusted?'approved':'unapproved / unknown'}<br>Package telemetry: ${d.packageMetricsSupported?'<span class=\"good\">available</span>':'<span class=\"warn\">unavailable</span>'}<br>Server version match: ${d.currentClientReleaseSupported?`<span class=\"good\">matches v${esc(String(antiCheatSnapshot.expectedClientVersion||'unknown'))}</span>`:`<span class=\"warn\">client v${esc(d.clientVersion||'unknown')} / server v${esc(String(antiCheatSnapshot.expectedClientVersion||'unknown'))}</span>`}<br>Challenge queue: ${d.challengeQueueingSupported?'<span class=\"good\">supported</span>':'<span class=\"warn\">not advertised</span>'}<br>Hardened transport: ${d.hardenedCapabilitiesSupported?'<span class=\"good\">report v2 + bound heartbeat</span>':'<span class=\"warn\">compatibility mode</span>'}</div></div>\n      <div class=\"acInfoTile ${Number(d.runtimeUnassociatedNewAssemblyCount||0)>0?'warn':'good'}\"><div class=\"k\">Runtime Surface</div><div class=\"v\">Gen ${Number(d.runtimeGeneration||0)}</div><div class=\"sub\">${Number(d.runtimeLoadedAssemblyCount||0)} loaded · ${Number(d.runtimeDynamicAssemblyCount||0)} dynamic · ${Number(d.runtimeNewAssemblyCount||0)} new · ${Number(d.runtimeUnassociatedNewAssemblyCount||0)} unassociated</div></div>\n      <div class=\"acInfoTile ${Number(d.suspiciousHarmonyOwnerCount||0)>0?'bad':'good'}\"><div class=\"k\">Harmony / Patches</div><div class=\"v\">${Number(d.harmonyPatchCount||0)} patches</div><div class=\"sub\">${Number(d.suspiciousHarmonyOwnerCount||0)} suspicious owners · digest <code>${esc((d.harmonyPatchDigest||'').slice(0,12)||'—')}</code></div></div>\n      <div class=\"acInfoTile ${signalCounts.hotkeys+signalCounts.commands+signalCounts.assets+signalCounts.canonical>0?'warn':'good'}\"><div class=\"k\">Integrity Signals</div><div class=\"v\">${signalCounts.hotkeys+signalCounts.commands+signalCounts.assets+signalCounts.canonical}</div><div class=\"sub\">Hotkeys ${signalCounts.hotkeys} · commands ${signalCounts.commands} · assets ${signalCounts.assets} · canonical mod/DLL ${signalCounts.canonical}</div></div>\n      <div class=\"acInfoTile ${modModified?'bad':modDiagnostic?'warn':'good'}\"><div class=\"k\">Mod Verification</div><div class=\"v\">${modOfficial} verified</div><div class=\"sub\">${modApproved} approved custom · ${modDiagnostic} diagnostic · ${modModified} modified · ${modPending} pending</div></div>\n      <div class=\"acInfoTile ${scanMetrics.some(x=>!x.success)?'warn':'good'}\"><div class=\"k\">Scan Performance</div><div class=\"v\">${scanDuration} ms</div><div class=\"sub\">${scanMetrics.length} scanner${scanMetrics.length===1?'':'s'} · cache ${cacheTotal?cacheRate+'%':'n/a'}${slowestScanner?`<br>Slowest: ${esc(slowestScanner.scanner||'scanner')} ${Number(slowestScanner.durationMs||0)} ms`:''}</div></div>\n      <div class=\"acInfoTile ${lastDiag&&/kick|reject|timeout|fail/i.test(String(lastDiag.action||'')+' '+String(lastDiag.code||''))?'warn':'good'}\"><div class=\"k\">Connection Health</div><div class=\"v\">${esc(heartbeatAge.text)}</div><div class=\"sub\">${playerDiagnostics.length} recent diagnostic event${playerDiagnostics.length===1?'':'s'}${lastDiag?`<br>${esc(lastDiag.stage||'Connection')} · ${esc(lastDiag.action||lastDiag.code||'Observe')}`:'<br>No connection warnings recorded'}</div></div>`;\n    const topReasons=strongFindings.slice(0,5);\n    $('acInvestigationSummary').innerHTML=`\n      <div class=\"acInvestigationCard\"><h4>Evidence posture</h4><div class=\"acEvidenceGrid\">\n        <div class=\"acEvidenceStat server\"><b>${serverEvidence.length}</b><span>Server-authoritative</span></div>\n        <div class=\"acEvidenceStat ${highConfidence.length?'strong':''}\"><b>${highConfidence.length}</b><span>High-confidence</span></div>\n        <div class=\"acEvidenceStat\"><b>${integrityEvidence.length}</b><span>Integrity / patch</span></div>\n        <div class=\"acEvidenceStat\"><b>${riskEvidence.length}</b><span>Risk-contributing</span></div>\n        <div class=\"acEvidenceStat\"><b>${Number(d.evidenceCandidates?.length||0)}</b><span>Capturable packages</span></div>\n        <div class=\"acEvidenceStat\"><b>${Number(d.collectedEvidence?.length||0)}</b><span>Preserved ZIPs</span></div>\n      </div><div class=\"small\" style=\"margin-top:9px\">Scan <span class=\"${scanAge.cls}\">${esc(scanAge.text)}</span> · heartbeat <span class=\"${heartbeatAge.cls}\">${esc(heartbeatAge.text)}</span>. Client-only telemetry should be corroborated before disruptive enforcement; server-authoritative evidence is highlighted separately.</div></div>\n      <div class=\"acInvestigationCard\"><h4>Top investigation drivers</h4><div class=\"acReasonList\">${topReasons.length?topReasons.map(x=>`<div class=\"acReason ${acFindingStrength(x)}\"><b>${esc(x.summary||x.code||'Finding')}</b><div class=\"meta\">${acEvidenceDomainBadge(x.evidenceDomain,x.serverAuthoritative)} · ${esc(x.confidence||'Low')} ${Number(x.confidenceScore||0)}/100 · ${Number(x.riskPoints||0)} risk point${Number(x.riskPoints||0)===1?'':'s'}${x.subject?` · ${esc(x.subject)}`:''}</div></div>`).join(''):'<div class=\"small muted\">No active findings. The current client report is not producing investigation drivers.</div>'}</div></div>`;\n    $('acDetailSummary').innerHTML=`${fam?`<div class=\"stateRow\" style=\"margin:0 0 8px\">${fam}</div>`:''}<b>Last scan:</b> <span class=\"${scanAge.cls}\">${esc(acDate(d.lastScanUtc))}</span> · <b>Heartbeat:</b> <span class=\"${heartbeatAge.cls}\">${esc(acDate(d.lastHeartbeatUtc))}</span>${d.lastConsequence?` · <b>Last consequence:</b> ${esc(d.lastConsequence)} (${esc(acDate(d.lastConsequenceUtc))})`:''}<br><b>Client DLL SHA-256:</b> <code class=\"acHash\">${esc(selfHash||'unavailable')}</code> ${trusted?'<span class=\"badge low\">Approved</span>':(selfHash&&currentSessionRole!=='ReadOnly'?`<button data-ac-approve-self=\"${esc(selfHash)}\">Approve this build</button>`:'')} · <b>MVID:</b> <code>${esc(d.clientAssemblyMvid||'—')}</code><br><b>Runtime digest:</b> <code>${esc(d.runtimeDigest||'—')}</code>`;\n    renderAntiCheatPlayerConnection(d,playerDiagnostics);\n    const historyEventCount=renderAntiCheatPlayerTimeline(d);\n    const approveBtn=document.querySelector('[data-ac-approve-self]');if(approveBtn)approveBtn.onclick=()=>updateAntiCheatIntegrityPolicy('add',approveBtn.dataset.acApproveSelf);\n    const f=findings;$('acFindingRows').innerHTML=f.length?[...f].sort((a,b)=>Number(b.serverAuthoritative)-Number(a.serverAuthoritative)||Number(b.riskPoints||0)-Number(a.riskPoints||0)||Number(b.confidenceScore||0)-Number(a.confidenceScore||0)||Number(b.severity||0)-Number(a.severity||0)).map(x=>{const age=acRelativeAge(x.observedUtc);return `<tr><td>${acSeverityBadge(x.severity)}</td><td><b>${esc(x.confidence||'Low')}</b><div class=\"small\">${Number(x.confidenceScore||0)}/100 · +${Number(x.corroboratingSignals||0)} nearby</div></td><td>${acEvidenceDomainBadge(x.evidenceDomain,x.serverAuthoritative)}<div class=\"small\" style=\"margin-top:4px\">${esc(x.category||'Other')}</div></td><td><b>${Number(x.riskPoints||0)}</b></td><td><span class=\"${age.cls}\" title=\"${esc(acDate(x.observedUtc))}\">${esc(age.text)}</span></td><td><code>${esc(x.code||'')}</code><div class=\"small\">${esc(x.subject||'—')}</div></td><td class=\"acFindingSummary\"><b>${esc(x.summary||'')}</b><div class=\"why\">${esc(x.why||'')}</div><div class=\"next\"><b>Next:</b> ${esc(x.recommendedAction||'')}</div></td></tr>`;}).join(''):'<tr><td colspan=\"7\" class=\"muted\">No findings.</td></tr>';\n    const ec=d.evidenceCandidates||[];$('acEvidenceCandidateRows').innerHTML=ec.length?ec.map(x=>`<tr><td><b>${esc(x.modId||'')}</b><div class=\"small\">${esc(x.version||'')} · ${esc(x.fileName||'')}</div></td><td>${acSeverityBadge(x.severity)} <code>${esc(x.reason||'')}</code></td><td>${Number(x.packageBytes||0)>0?formatBytesTotal(Number(x.packageBytes||0)):'<span class=\"muted\">Not reported</span>'}<div class=\"small\">${Number(x.packageBytes||0)>0||Number(x.dllCount||0)>0||Number(x.dllBytes||0)>0?`${Number(x.dllCount||0)} DLLs · ${formatBytesTotal(Number(x.dllBytes||0))}`:'Package metrics unavailable'}</div></td><td>${x.alreadyCollected?`<span class=\"badge low\">Stored</span><div class=\"small\">${esc(x.lastCollectedFile||'')}</div>`:'<span class=\"muted\">Not stored</span>'}</td><td>${x.transferInProgress?'<span class=\"badge moderate\">Transferring…</span>':currentSessionRole==='ReadOnly'?'<span class=\"muted\">Read only</span>':`<button class=\"${Number(x.severity||0)>=3?'danger':'primary'}\" data-ac-evidence-mod=\"${esc(x.modId||'')}\">${x.alreadyCollected?'Collect Again':'Collect ZIP'}</button>`}</td></tr>`).join(''):'<tr><td colspan=\"5\" class=\"muted\">No mod packages are currently tied to suspicious findings.</td></tr>';\n    document.querySelectorAll('[data-ac-evidence-mod]').forEach(b=>b.onclick=()=>requestAntiCheatEvidence(antiCheatSelectedPlayer,b.dataset.acEvidenceMod));\n    const ce=d.collectedEvidence||[];$('acCollectedEvidenceRows').innerHTML=ce.length?ce.map(x=>{const diff=acRenderEvidenceDiff(x);const diffStatus=String(x.officialDiffStatus||'NotAnalyzed');const btn=currentSessionRole==='ReadOnly'?'':`<div style=\"margin-top:7px\"><button data-ac-evidence-analyze=\"${esc(x.fileName||'')}\">${diffStatus==='NotAnalyzed'?'Compare to ModDB':'Recompare'}</button></div>`;return `<tr class=\"acEvidenceStored\"><td>${esc(acDate(x.collectedUtc))}${Number(x.authorizationUtc||0)>0?`<div class=\"small\">Authorized ${esc(acDate(x.authorizationUtc))} · popup · requested by ${esc(x.requestedBy||'administrator')} · ${esc(String(x.declinePolicyAction||'TempBan'))}${String(x.declinePolicyAction||'TempBan')==='TempBan'?` ${Number(x.declinePolicyHours||24)}h`:''} decline policy</div>`:''}</td><td><b>${esc(x.modId||'')}</b><div class=\"small\">${esc(x.version||'—')} · ${esc(x.originalFileName||'')}</div></td><td><code>${esc(x.fileName||'')}</code>${x.generatedArchive?'<div class=\"small\">Generated archive from folder/loose mod</div>':'<div class=\"small\">Original ZIP bytes</div>'}</td><td>${formatBytesTotal(Number(x.bytes||0))}</td><td><code class=\"acHash\">${esc(x.sha256||'')}</code></td><td>${diff}${btn}</td></tr>`;}).join(''):'<tr><td colspan=\"6\" class=\"muted\">No stored transferred packages for this player.</td></tr>';\n    document.querySelectorAll('[data-ac-evidence-analyze]').forEach(b=>b.onclick=()=>analyzeAntiCheatEvidence(b.dataset.acEvidenceAnalyze));\n    const m=Array.isArray(d.mods)?d.mods:[];\n    const clientOnlyMods=m.filter(x=>!x.loadedOnServer).sort((a,b)=>String(a.modId||'').localeCompare(String(b.modId||''))||String(a.version||'').localeCompare(String(b.version||'')));\n    if($('acClientOnlyModsCount'))$('acClientOnlyModsCount').textContent=`${clientOnlyMods.length} client-only`;\n    if($('acAllModsCount'))$('acAllModsCount').textContent=`${m.length} total`;\n    if($('acClientOnlyModRows'))$('acClientOnlyModRows').innerHTML=clientOnlyMods.length?clientOnlyMods.map(x=>renderAntiCheatModInventoryRow(x,false)).join(''):'<tr><td colspan=\"7\" class=\"muted\">No client-only mods reported. Every reported mod is shared with the server baseline or no client mod inventory is available.</td></tr>';\n    $('acModRows').innerHTML=m.length?m.map(x=>renderAntiCheatModInventoryRow(x,true)).join(''):'<tr><td colspan=\"8\" class=\"muted\">No third-party client mods were reported.</td></tr>';\n    document.querySelectorAll('[data-ac-blacklist-add]').forEach(b=>b.onclick=()=>updateAntiCheatBlacklist('add',b.dataset.acBlacklistAdd,antiCheatSelectedPlayer));\n    const a=d.assemblies||[];$('acAssemblyRows').innerHTML=a.length?a.map(x=>{const cls=acAssemblyClassBadge(x);return `<tr><td><b>${esc(x.assemblyName||'')}</b><div class=\"small\">${esc(x.fileName||'—')} · ${formatBytesTotal(Number(x.fileSizeBytes||0))}</div></td><td>${esc(x.version||'')}</td><td>${cls}</td><td>${esc((x.associatedModIds||[]).join(', ')||'—')}</td><td><code title=\"Binary SHA-256: ${esc(x.sha256||'')}&#10;Structure SHA-256: ${esc(x.structureSha256||'')}&#10;Similarity tokens: ${Number(x.structureTokenCount||0)}&#10;IL behavior SHA-256: ${esc(x.behaviorSha256||'')}&#10;IL behavior tokens: ${Number(x.behaviorTokenCount||0)}\">${esc((x.sha256||x.structureSha256||'').slice(0,16))}${(x.sha256||x.structureSha256||'').length>16?'…':''}</code></td><td><code>${esc((x.moduleVersionId||'').slice(0,18))}${(x.moduleVersionId||'').length>18?'…':''}</code></td></tr>`}).join(''):'<tr><td colspan=\"6\" class=\"muted\">No assembly inventory accepted.</td></tr>';\n    const ra=d.runtimeNewAssemblies||[];$('acRuntimeRows').innerHTML=ra.length?ra.map(x=>`<tr><td><b>${esc(x.assemblyName||'')}</b><div class=\"small\">${esc(x.version||'')}</div></td><td>${esc(x.fileName||'—')}</td><td>${esc(x.loadContextName||'—')}</td><td>${x.isDynamic?'<span class=\"badge high\">Dynamic</span>':acAssemblyClassBadge(x)}</td><td><code title=\"SHA-256: ${esc(x.sha256||'')}&#10;MVID: ${esc(x.moduleVersionId||'')}\">${esc(((x.sha256||x.moduleVersionId||'')).slice(0,18))}${(x.sha256||x.moduleVersionId||'').length>18?'…':''}</code></td></tr>`).join(''):'<tr><td colspan=\"5\" class=\"muted\">No post-baseline runtime changes reported.</td></tr>';\n    const sm=d.scannerMetrics||[];$('acScannerRows').innerHTML=sm.length?sm.map(x=>`<tr><td><b>${esc(x.scanner||'')}</b></td><td>${x.success?'<span class=\"badge low\">OK</span>':'<span class=\"badge high\">Failed</span>'}</td><td>${Number(x.durationMs||0)} ms</td><td>${Number(x.modCount||0)} mods · ${Number(x.assemblyCount||0)} assemblies · ${Number(x.findingCount||0)} findings</td><td>${Number(x.cacheHits||0)} hits · ${Number(x.cacheMisses||0)} misses</td></tr>`).join(''):'<tr><td colspan=\"5\" class=\"muted\">No scanner telemetry loaded.</td></tr>';\n    const failedScanners=sm.filter(x=>!x.success).length;\n    const antiCheatAttention=findings.length+Number(d.runtimeUnassociatedNewAssemblyCount||0)+failedScanners;\n    const connectionProblems=playerDiagnostics.filter(x=>/kick|reject|timeout|fail|mismatch/i.test(`${x.action||''} ${x.code||''}`)).length;\n    const evidenceCount=Number(ec.length||0)+Number(ce.length||0);\n    setAntiCheatDrawerTabCount('acTabAntiCheatCount',antiCheatAttention,antiCheatAttention?'warn':'good');\n    setAntiCheatDrawerTabCount('acTabModsCount',m.length,modModified?'bad':modDiagnostic||modPending?'warn':'good');\n    setAntiCheatDrawerTabCount('acTabConnectionCount',playerDiagnostics.length,connectionProblems?'warn':'good');\n    setAntiCheatDrawerTabCount('acTabHistoryCount',historyEventCount,historyEventCount?'':'good');\n    setAntiCheatDrawerTabCount('acTabEvidenceCount',evidenceCount,ec.length?'warn':ce.length?'good':'');\n    setAntiCheatDrawerTab(antiCheatDrawerTab,false);\n  }catch(e){toast(e.message,'error');}\n}\nfunction jumpAntiCheatDrawer(targetId){const tab=String(targetId||'').replace(/^acDrawerTab/,'').toLowerCase();if(['overview','anticheat','mods','inventory','connection','history','evidence'].includes(tab)){setAntiCheatDrawerTab(tab,true);return;}const el=$(targetId);if(!el)return;el.scrollIntoView({behavior:(currentMotionPreference==='off'||window.matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('suiteReducedMotion'))?'auto':'smooth',block:'start'});}\nasync function copyAntiCheatPlayerUid(){if(!antiCheatSelectedPlayer)return;await copyText(antiCheatSelectedPlayer,'Player UID copied.');}\nasync function refreshAntiCheatPlayerDrawer(){if(!antiCheatSelectedPlayer)return;await loadAntiCheatPlayer(antiCheatSelectedPlayer);if(antiCheatDrawerTab==='inventory')await loadAntiCheatInventory(true);}\n\nasync function requestAntiCheatRescan(player){if(!player)return;try{const d=await api('/api/anticheat/rescan',{method:'POST',body:JSON.stringify({player})});toast(d.message||'Rescan requested.','success');setTimeout(()=>loadAntiCheat(false),500);}catch(e){toast(e.message,'error');}}\nasync function analyzeAntiCheatEvidence(fileName){\n  if(currentSessionRole==='ReadOnly'||!fileName)return;\n  try{\n    const d=await api('/api/anticheat/evidence/analyze',{method:'POST',body:JSON.stringify({fileName})});\n    toast(d.message||'Evidence package compared with ModDB.','success');\n    if(antiCheatSelectedPlayer)await loadAntiCheatPlayer(antiCheatSelectedPlayer);\n  }catch(e){toast(e.message,'error');}\n}\nfunction acEvidenceDeclinePolicyText(action,hours){action=String(action||'TempBan');if(action==='None')return 'no automatic punishment';if(action==='Disconnect')return 'disconnect';return `${Number(hours||24)}-hour temporary ban`;}\nfunction syncAntiCheatEvidenceDeclineUi(){const action=String($('acEvidenceDeclineAction')?.value||'TempBan');const wrap=$('acEvidenceDeclineHoursWrap');if(wrap)wrap.style.display=action==='TempBan'?'':'none';}\nasync function requestAntiCheatEvidence(player,modId){\n  if(!player||!modId)return;\n  const policy=acEvidenceDeclinePolicyText(antiCheatSnapshot.suspectPackageDeclineAction,antiCheatSnapshot.suspectPackageDeclineTempBanHours);\n  if(!confirm(`Collect ZIP for ${modId} from ${player}? This manual click is what triggers the player's in-game permission popup; scans never open it automatically. No package bytes can be prepared or transferred unless the player clicks Agree & Transfer. Declining, closing the popup, or pressing Escape triggers: ${policy}.`))return;\n  try{\n    const d=await api('/api/anticheat/evidence/request',{method:'POST',body:JSON.stringify({player,modId})});\n    toast(d.message||'Package transfer authorization requested.','success');\n    setTimeout(()=>loadAntiCheatPlayer(player),1800);\n  }catch(e){toast(e.message,'error');}\n}\nasync function saveAntiCheatEvidenceSettings(){\n  if(currentSessionRole==='ReadOnly')return;\n  try{\n    const payload={enabled:!!$('acEvidenceEnabled').checked,maxMb:Number($('acEvidenceMaxMb').value||96),timeoutSeconds:Number($('acEvidenceTimeout').value||120),uploadKbps:Number($('acEvidenceUploadKbps').value||384),declineAction:String($('acEvidenceDeclineAction')?.value||'TempBan'),declineTempBanHours:Number($('acEvidenceDeclineHours')?.value||24)};\n    const d=await api('/api/anticheat/evidence/settings',{method:'POST',body:JSON.stringify(payload)});\n    toast(d.message||'Package transfer settings saved.','success');\n    await loadAntiCheat(false);\n  }catch(e){toast(e.message,'error');}\n}\nasync function updateAntiCheatBlacklist(action,modId,player=\"\"){\n  modId=String(modId||'').trim().toLowerCase();\n  if(!modId){toast('Enter a mod ID first.','error');return;}\n  if(action==='add'&&!confirm(`Blacklist ${modId}? Existing accepted client scans will be re-evaluated immediately. If an enabled automatic consequence matches FORBIDDEN_MOD, it may also be enforced.`))return;\n  if(action==='remove'&&!confirm(`Remove ${modId} from the anti-cheat blacklist?`))return;\n  try{\n    const d=await api('/api/anticheat/blacklist',{method:'POST',body:JSON.stringify({action,modId,player})});\n    toast(d.message||(action==='add'?'Mod blacklisted.':'Mod removed from blacklist.'),'success');\n    if(action==='add')$('acBlacklistInput').value='';\n    if(action==='add'&&!player)await resolveAntiCheatBlacklistFingerprint(modId,true);\n    await loadAntiCheat(false);\n    if(antiCheatSelectedPlayer)await loadAntiCheatPlayer(antiCheatSelectedPlayer);\n  }catch(e){toast(e.message,'error');}\n}\nasync function updateAntiCheatBlacklistProfile(action){\n  if(currentSessionRole==='ReadOnly'){toast('Read-only accounts cannot change blacklist profiles.','error');return;}\n  const select=$('acBlacklistProfileSelect');\n  const profileId=String(select?.value||'').trim();\n  const name=String($('acBlacklistProfileName')?.value||'').trim();\n  if(action==='load'&&!profileId){toast('Choose a saved profile to load.','error');return;}\n  if(action==='delete'&&!profileId){toast('Choose a saved profile to delete.','error');return;}\n  if((action==='save-as'||(action==='save'&&!profileId))&&!name){toast('Enter a profile name first.','error');return;}\n  if(action==='load'&&!confirm('Load this profile into the active blacklist? Unsaved active-list edits will be replaced.'))return;\n  if(action==='load-default'&&!confirm('Replace the active blacklist with the built-in default unfair-mod list? You can edit it after loading.'))return;\n  if(action==='delete'&&!confirm('Delete this saved blacklist profile? The current active blacklist will be left unchanged.'))return;\n  try{\n    const d=await api('/api/anticheat/blacklist/profile',{method:'POST',body:JSON.stringify({action,profileId,name})});\n    toast(d.message||'Blacklist profile updated.','success');\n    await loadAntiCheat(false);\n    if(d.profileId&&$('acBlacklistProfileSelect'))$('acBlacklistProfileSelect').value=d.profileId;\n  }catch(e){toast(e.message,'error');}\n}\nfunction acSplitList(value){return String(value||'').split(/[\\s,;]+/).map(x=>x.trim()).filter(Boolean);}\nfunction acValidSha(value){return /^[0-9a-f]{64}$/i.test(String(value||'').trim());}\nfunction acValidMvid(value){return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(value||'').trim());}\nfunction clearAntiCheatManualForm(){\n  antiCheatManualEditingId='';\n  $('acManualLabel').value='';$('acManualVersion').value='';$('acManualFileName').value='';$('acManualNotes').value='';\n  $('acManualPackageSha').value='';$('acManualContentSha').value='';$('acManualAssemblyHashes').value='';$('acManualMvids').value='';$('acManualStructureHashes').value='';\n  $('acManualSave').textContent='Save Manual Fingerprint';\n}\nfunction openAntiCheatManualEditor(modId,entryId=''){\n  modId=String(modId||'').trim().toLowerCase();if(!modId)return;\n  antiCheatManualTarget=modId;$('acManualFingerprintEditor').style.display='block';$('acManualFingerprintTarget').innerHTML=`Target: <code>${esc(modId)}</code>`;\n  clearAntiCheatManualForm();renderAntiCheatManualEntries();\n  if(entryId)editAntiCheatManualFingerprint(entryId);\n  $('acManualFingerprintEditor').scrollIntoView({behavior:'smooth',block:'nearest'});\n}\nfunction renderAntiCheatManualEntries(){\n  const fp=antiCheatForbiddenFingerprints.get(antiCheatManualTarget);const entries=Array.isArray(fp?.manualEntries)?fp.manualEntries:[];\n  $('acManualState').textContent=`${entries.length} manual entr${entries.length===1?'y':'ies'} · Mod DB refreshes do not overwrite these`;\n  $('acManualRows').innerHTML=entries.length?entries.map(x=>{\n    const counts=[];if(x.packageSha256)counts.push('package');if(x.contentSha256)counts.push('content');const ah=(x.assemblySha256s||[]).length,mv=(x.assemblyMvids||[]).length,sh=(x.assemblyStructureSha256s||[]).length;if(ah)counts.push(`${ah} assembly SHA`);if(mv)counts.push(`${mv} MVID`);if(sh)counts.push(`${sh} structure SHA`);\n    const actions=currentSessionRole==='ReadOnly'?'<span class=\"muted\">Read only</span>':`<button data-ac-manual-edit=\"${esc(x.id||'')}\">Edit</button> <button data-ac-manual-delete=\"${esc(x.id||'')}\">Delete</button>`;\n    return `<tr><td><b>${esc(x.label||'Manual fingerprint')}</b>${x.notes?`<div class=\"small\" title=\"${esc(x.notes)}\">${esc(x.notes.slice(0,100))}${x.notes.length>100?'…':''}</div>`:''}</td><td>${esc(x.version||'—')}<div class=\"small\">${esc(x.fileName||'—')}</div></td><td>${esc(counts.join(' · ')||'—')}</td><td>${acDate(x.updatedUtc||x.createdUtc)}</td><td>${actions}</td></tr>`;\n  }).join(''):'<tr><td colspan=\"5\" class=\"muted\">No manual fingerprint entries. Paste a known hash above to create one.</td></tr>';\n  document.querySelectorAll('[data-ac-manual-edit]').forEach(b=>b.onclick=()=>editAntiCheatManualFingerprint(b.dataset.acManualEdit));\n  document.querySelectorAll('[data-ac-manual-delete]').forEach(b=>b.onclick=()=>deleteAntiCheatManualFingerprint(b.dataset.acManualDelete));\n  const ro=currentSessionRole==='ReadOnly';['acManualLabel','acManualVersion','acManualFileName','acManualNotes','acManualPackageSha','acManualContentSha','acManualAssemblyHashes','acManualMvids','acManualStructureHashes'].forEach(id=>$(id).disabled=ro);$('acManualSave').disabled=ro;$('acManualNew').disabled=ro;\n}\nfunction editAntiCheatManualFingerprint(entryId){\n  const fp=antiCheatForbiddenFingerprints.get(antiCheatManualTarget);const x=(fp?.manualEntries||[]).find(v=>String(v.id||'')===String(entryId||''));if(!x)return;\n  antiCheatManualEditingId=x.id||'';$('acManualLabel').value=x.label||'';$('acManualVersion').value=x.version||'';$('acManualFileName').value=x.fileName||'';$('acManualNotes').value=x.notes||'';$('acManualPackageSha').value=x.packageSha256||'';$('acManualContentSha').value=x.contentSha256||'';$('acManualAssemblyHashes').value=(x.assemblySha256s||[]).join('\\n');$('acManualMvids').value=(x.assemblyMvids||[]).join('\\n');$('acManualStructureHashes').value=(x.assemblyStructureSha256s||[]).join('\\n');if($('acManualBehaviorHashes'))$('acManualBehaviorHashes').value=(x.assemblyBehaviorSha256s||[]).join('\\n');$('acManualSave').textContent='Update Manual Fingerprint';\n}\nasync function saveAntiCheatManualFingerprint(){\n  if(currentSessionRole==='ReadOnly'||!antiCheatManualTarget)return;\n  const packageSha=$('acManualPackageSha').value.trim().toLowerCase(),contentSha=$('acManualContentSha').value.trim().toLowerCase();\n  const assemblySha256s=acSplitList($('acManualAssemblyHashes').value).map(x=>x.toLowerCase()),assemblyMvids=acSplitList($('acManualMvids').value),assemblyStructureSha256s=acSplitList($('acManualStructureHashes').value).map(x=>x.toLowerCase());\n  const badHashes=[...(packageSha?[packageSha]:[]),...(contentSha?[contentSha]:[]),...assemblySha256s,...assemblyStructureSha256s].filter(x=>!acValidSha(x));if(badHashes.length){toast(`Invalid SHA-256: ${badHashes[0]}`,'error');return;}\n  const badMvid=assemblyMvids.find(x=>!acValidMvid(x));if(badMvid){toast(`Invalid assembly MVID: ${badMvid}`,'error');return;}\n  if(!packageSha&&!contentSha&&!assemblySha256s.length&&!assemblyMvids.length&&!assemblyStructureSha256s.length){toast('Enter at least one exact fingerprint.','error');return;}\n  if(!confirm(`Save this manual blacklist fingerprint for ${antiCheatManualTarget}? Current accepted client scans will be re-evaluated immediately, and matching consequence rules may run.`))return;\n  const payload={action:'save',modId:antiCheatManualTarget,entryId:antiCheatManualEditingId,label:$('acManualLabel').value.trim(),version:$('acManualVersion').value.trim(),fileName:$('acManualFileName').value.trim(),notes:$('acManualNotes').value.trim(),packageSha256:packageSha,contentSha256:contentSha,assemblySha256s,assemblyMvids,assemblyStructureSha256s};\n  try{const d=await api('/api/anticheat/blacklist/manual',{method:'POST',body:JSON.stringify(payload)});toast(d.message||'Manual fingerprint saved.','success');clearAntiCheatManualForm();await loadAntiCheat(false);renderAntiCheatManualEntries();}catch(e){toast(e.message,'error');}\n}\nasync function deleteAntiCheatManualFingerprint(entryId){\n  if(currentSessionRole==='ReadOnly'||!antiCheatManualTarget||!entryId)return;if(!confirm(`Delete this manual fingerprint from ${antiCheatManualTarget}?`))return;\n  try{const d=await api('/api/anticheat/blacklist/manual',{method:'POST',body:JSON.stringify({action:'delete',modId:antiCheatManualTarget,entryId})});toast(d.message||'Manual fingerprint removed.','success');if(antiCheatManualEditingId===entryId)clearAntiCheatManualForm();await loadAntiCheat(false);renderAntiCheatManualEntries();}catch(e){toast(e.message,'error');}\n}\nasync function resolveAntiCheatBlacklistFingerprint(modId,quiet=false){\n  modId=String(modId||'').trim().toLowerCase();\n  if(!modId)return false;\n  try{\n    const d=await api('/api/anticheat/blacklist/resolve',{method:'POST',body:JSON.stringify({modId})});\n    if(!quiet)toast(d.message||`Resolved ${modId}.`,'success');\n    return true;\n  }catch(e){if(!quiet)toast(`${modId}: ${e.message}`,'error');return false;}\n}\nasync function saveAntiCheatFingerprintReleaseDepth(){\n  if(currentSessionRole==='ReadOnly')return;\n  const input=$('acFingerprintReleaseDepth');\n  const releaseDepth=Math.max(1,Math.min(20,Number(input?.value||6)||6));\n  if(input)input.value=String(releaseDepth);\n  try{\n    const d=await api('/api/anticheat/blacklist/fingerprint-settings',{method:'POST',body:JSON.stringify({releaseDepth})});\n    toast(d.message||`Fingerprint history set to ${releaseDepth} release${releaseDepth===1?'':'s'} per mod.`,'success');\n    await loadAntiCheat(false);\n  }catch(e){toast(e.message,'error');}\n}\nasync function bulkResolveAntiCheatBlacklistFingerprints(refreshAll=false){\n  if(currentSessionRole==='ReadOnly')return;\n  const allIds=[...antiCheatForbiddenMods];\n  const ids=refreshAll?allIds:allIds.filter(id=>{const fp=antiCheatForbiddenFingerprints.get(id);return !fp||Number(fp.releaseCount||0)===0;});\n  if(!ids.length){toast(refreshAll?'There are no active blacklist entries to refresh.':'All active blacklist entries already have Mod DB release fingerprints.','success');return;}\n  const depth=Math.max(1,Math.min(20,Number($('acFingerprintReleaseDepth')?.value||6)||6));\n  const actionText=refreshAll?'force-refresh every active blacklist entry':'resolve only blacklist entries missing Mod DB fingerprints';\n  if(!confirm(`This will ${actionText} (${ids.length} mod${ids.length===1?'':'s'}) from the official Vintage Story Mod DB using up to ${depth} release${depth===1?'':'s'} per mod. ZIPs are downloaded in memory only. Continue?`))return;\n  // Save the visible depth first so every resolve call uses exactly what the operator selected.\n  try{await api('/api/anticheat/blacklist/fingerprint-settings',{method:'POST',body:JSON.stringify({releaseDepth:depth})});}catch(e){toast(`Could not save fingerprint depth: ${e.message}`,'error');return;}\n  const btn=$(refreshAll?'acBlacklistRefreshAll':'acBlacklistResolveMissing');\n  const other=$(refreshAll?'acBlacklistResolveMissing':'acBlacklistRefreshAll');\n  btn.disabled=true;if(other)other.disabled=true;let ok=0;let failed=0;\n  try{\n    for(let i=0;i<ids.length;i++){\n      const id=ids[i];\n      $('acBlacklistState').textContent=`${refreshAll?'Refreshing':'Resolving'} ${id}… ${i+1}/${ids.length}`;\n      if(await resolveAntiCheatBlacklistFingerprint(id,true))ok++;else failed++;\n      if(i<ids.length-1)await new Promise(r=>setTimeout(r,1100));\n    }\n    toast(`${refreshAll?'Fingerprint refresh':'Missing fingerprint resolution'} complete: ${ok} succeeded, ${failed} failed.`,failed?'warn':'success');\n    await loadAntiCheat(false);\n  }finally{\n    btn.disabled=currentSessionRole==='ReadOnly';\n    if(other)other.disabled=currentSessionRole==='ReadOnly';\n  }\n}\nasync function updateAntiCheatIntegrityPolicy(action,hash=''){\n  hash=String(hash||'').trim().toLowerCase();\n  if((action==='add'||action==='remove')&&!/^[0-9a-f]{64}$/.test(hash)){toast('Enter a valid 64-character SHA-256 hash.','error');return;}\n  if(action==='add'&&!confirm('Approve this Client Integrity build hash? Only approve hashes from a client build you compiled or otherwise trust.'))return;\n  if(action==='remove'&&!confirm('Remove this approved client build hash?'))return;\n  try{const d=await api('/api/anticheat/integrity-policy',{method:'POST',body:JSON.stringify({action,hash})});toast(d.message||'Integrity policy updated.','success');$('acIntegrityHashInput').value='';await loadAntiCheat(false);if(antiCheatSelectedPlayer)await loadAntiCheatPlayer(antiCheatSelectedPlayer);}catch(e){toast(e.message,'error');}\n}\nasync function setAntiCheatBuildLock(enabled){\n  if(enabled&&antiCheatApprovedHashes.size===0){toast('Add at least one trusted client hash before enabling build lock.','error');$('acIntegrityRequire').checked=false;return;}\n  if(enabled&&!confirm('Require approved Client Integrity builds? Players reporting an unapproved client hash will become Suspicious and may trigger configured consequences.')){$('acIntegrityRequire').checked=false;return;}\n  try{const d=await api('/api/anticheat/integrity-policy',{method:'POST',body:JSON.stringify({action:'require',requireApproved:!!enabled})});toast(d.message||'Build-lock policy updated.','success');await loadAntiCheat(false);}catch(e){toast(e.message,'error');$('acIntegrityRequire').checked=!enabled;}\n}\n\nfunction applySimpleAntiCheatEnforcement(){\n  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot change Anti-Cheat enforcement.','error');return;}\n  const forbidden=String($('acSimpleForbiddenAction')?.value||'Kick');\n  const missing=String($('acSimpleMissingAction')?.value||'Kick');\n  const suspicious=String($('acSimpleSuspiciousAction')?.value||'Freeze');\n  let kickRisk=Math.max(1,Math.min(100,Math.floor(Number($('acSimpleKickRisk')?.value||85))));\n  let banRisk=Math.max(1,Math.min(100,Math.floor(Number($('acSimpleBanRisk')?.value||95))));\n  if(banRisk<=kickRisk)banRisk=Math.min(100,kickRisk+5);\n  const duration=String($('acSimpleDuration')?.value||'2h').trim()||'2h';\n  const now=Date.now();\n  const rules=[\n    {id:`simple-forbidden-${now}`,name:'Exact forbidden client fingerprint',enabled:true,triggerType:'FindingCode',triggerValue:'FORBIDDEN_MOD_FINGERPRINT',subject:'',action:forbidden,duration,message:'Forbidden client modification detected: {subject} ({code}).'},\n    {id:`simple-forbidden-assembly-${now}`,name:'Exact forbidden assembly fingerprint',enabled:true,triggerType:'FindingCode',triggerValue:'FORBIDDEN_ASSEMBLY_FINGERPRINT',subject:'',action:forbidden,duration,message:'Forbidden client assembly fingerprint detected: {subject} ({code}).'},\n    {id:`simple-missing-${now}`,name:'Required Client Integrity missing',enabled:true,triggerType:'FindingCode',triggerValue:'CLIENT_MISSING',subject:'',action:missing,duration,message:\"Newfie's Client Integrity is required to play on this server.\"},\n    {id:`simple-suspicious-${now}`,name:'Suspicious client review',enabled:true,triggerType:'Status',triggerValue:'Suspicious',subject:'',action:suspicious,duration,message:'Your client integrity state requires staff review. Risk: {risk}.'},\n    {id:`simple-riskkick-${now}`,name:`High risk ≥ ${kickRisk}`,enabled:true,triggerType:'RiskAtLeast',triggerValue:String(kickRisk),subject:'',action:'Kick',duration,message:'Anti-Cheat enforcement triggered at risk {risk}. Finding: {code}. Contact staff if you believe this is an error.'}\n  ];\n  if($('acSimpleEnableRiskBan')?.checked){\n    rules.push({id:`simple-riskban-${now}`,name:`Critical risk ≥ ${banRisk}`,enabled:true,triggerType:'RiskAtLeast',triggerValue:String(banRisk),subject:'',action:'TempBan',duration,message:'Critical Anti-Cheat risk {risk}. Finding: {code}. Temporary restriction: {duration}.'});\n  }\n  antiCheatConsequenceRules=rules;\n  renderAntiCheatConsequences();\n  $('acConsequenceState').textContent=`${rules.length} generated rule${rules.length===1?'':'s'} — review then Save Rules`;\n  toast('Quick Enforcement Setup applied to the rule editor. Review and Save Rules to make it live.','success');\n}\n\nfunction addAntiCheatPreset(kind){\n  const presets={\n    'forbidden-log':{name:'Forbidden mod detected',enabled:true,triggerType:'FindingCode',triggerValue:'FORBIDDEN_MOD_FINGERPRINT',subject:'',action:'Log',duration:'30m',message:'Forbidden client mod detected for {player}: {subject} ({code}).'},\n    'missing-kick':{name:'Client required',enabled:true,triggerType:'FindingCode',triggerValue:'CLIENT_MISSING',subject:'',action:'Kick',duration:'30m',message:\"Newfie's Client Integrity is required to play on this server.\"},\n    'suspicious-freeze':{name:'Suspicious player review',enabled:true,triggerType:'Status',triggerValue:'Suspicious',subject:'',action:'Freeze',duration:'10m',message:'Your client integrity state requires staff review. Risk: {risk}.'},\n    'highrisk-kick':{name:'Very high risk kick',enabled:true,triggerType:'RiskScore',triggerValue:'80',subject:'',action:'Kick',duration:'30m',message:'Anti-Cheat enforcement triggered at risk {risk}. Finding: {code}. Contact staff if you believe this is an error.'}\n  };\n  const p=presets[kind];if(!p)return;\n  antiCheatConsequenceRules.push(Object.assign({id:`web-${Date.now()}-${Math.random().toString(16).slice(2)}`},p));\n  renderAntiCheatConsequences();\n    if($('acEnforcementSummary'))$('acEnforcementSummary').innerHTML=metric('Rules',antiCheatConsequenceRules.length)+metric('Enabled',antiCheatConsequenceRules.filter(r=>r.enabled!==false).length,'good')+metric('Disruptive',antiCheatConsequenceRules.filter(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||''))).length,antiCheatConsequenceRules.some(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||'')))?'warn':'neutral')+metric('Mode',antiCheatConsequenceRules.some(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||'')))?'Active enforcement':'Observe / log','neutral');\n  toast('Preset added. Review it, then Save Rules.','success');\n}\nfunction newAntiCheatConsequenceRule(){\n  return {id:`web-${Date.now()}-${Math.random().toString(16).slice(2)}`,name:'New consequence',enabled:true,triggerType:'FindingCode',triggerValue:'FORBIDDEN_MOD',subject:'',action:'Log',duration:'30m',message:'Anti-cheat policy matched for {player}: {code} {subject}.'};\n}\nfunction renderAntiCheatConsequences(){\n  const ro=currentSessionRole==='ReadOnly';\n  $('acConsequenceState').textContent=`${antiCheatConsequenceRules.length} rule${antiCheatConsequenceRules.length===1?'':'s'} configured`;\n  $('acConsequenceAdd').disabled=ro;\n  $('acConsequenceSave').disabled=ro;\n  $('acConsequenceApplyCurrent').disabled=ro;\n  ['acSimpleForbiddenAction','acSimpleMissingAction','acSimpleSuspiciousAction','acSimpleKickRisk','acSimpleBanRisk','acSimpleDuration','acSimpleEnableRiskBan','acSimpleApply'].forEach(id=>{const e=$(id);if(e)e.disabled=ro;});\n  const dis=ro?' disabled':'';\n  $('acConsequenceRows').innerHTML=antiCheatConsequenceRules.length?antiCheatConsequenceRules.map((r,i)=>`<tr data-ac-rule=\"${i}\">\n    <td><input data-field=\"enabled\" type=\"checkbox\"${r.enabled!==false?' checked':''}${dis}></td>\n    <td><input data-field=\"name\" maxlength=\"80\" value=\"${esc(r.name||'Consequence')}\"${dis}></td>\n    <td><select data-field=\"triggerType\"${dis}><option value=\"FindingCode\"${r.triggerType==='FindingCode'?' selected':''}>Finding code</option><option value=\"Status\"${r.triggerType==='Status'?' selected':''}>Status</option><option value=\"RiskAtLeast\"${r.triggerType==='RiskAtLeast'?' selected':''}>Risk ≥</option><option value=\"FamilyRiskAtLeast\"${r.triggerType==='FamilyRiskAtLeast'?' selected':''}>Family risk ≥</option></select></td>\n    <td><input data-field=\"triggerValue\" list=\"acTriggerSuggestions\" maxlength=\"80\" value=\"${esc(r.triggerValue||'')}\" placeholder=\"FORBIDDEN_MOD / Suspicious / 50\"${dis}></td>\n    <td><input data-field=\"subject\" maxlength=\"80\" value=\"${esc(r.subject||'')}\" placeholder=\"optional mod ID\"${dis}></td>\n    <td><select data-field=\"action\"${dis}><option value=\"Log\"${r.action==='Log'?' selected':''}>Log</option><option value=\"Kick\"${r.action==='Kick'?' selected':''}>Kick</option><option value=\"TempBan\"${r.action==='TempBan'?' selected':''}>Timed ban</option><option value=\"Freeze\"${r.action==='Freeze'?' selected':''}>Timed freeze</option></select></td>\n    <td><input data-field=\"duration\" maxlength=\"24\" style=\"width:90px\" value=\"${esc(r.duration||'30m')}\" placeholder=\"30m\"${dis}></td>\n    <td><input data-field=\"message\" maxlength=\"240\" style=\"min-width:280px\" value=\"${esc(r.message||'')}\"${dis}></td>\n    <td><button data-ac-rule-preview=\"${i}\">Preview</button> ${ro?'<span class=\"muted\">Read only</span>':`<button class=\"danger\" data-ac-rule-remove=\"${i}\">Remove</button>`}</td>\n  </tr>`).join(''):'<tr><td colspan=\"9\" class=\"muted\">No rules configured. Without rules, anti-cheat detects and reports but performs no automatic moderation action.</td></tr>';\n  document.querySelectorAll('[data-ac-rule-preview]').forEach(b=>b.onclick=()=>previewAntiCheatConsequence(Number(b.dataset.acRulePreview)));\n  document.querySelectorAll('[data-ac-rule-remove]').forEach(b=>b.onclick=()=>{antiCheatConsequenceRules.splice(Number(b.dataset.acRuleRemove),1);renderAntiCheatConsequences();\n    if($('acEnforcementSummary'))$('acEnforcementSummary').innerHTML=metric('Rules',antiCheatConsequenceRules.length)+metric('Enabled',antiCheatConsequenceRules.filter(r=>r.enabled!==false).length,'good')+metric('Disruptive',antiCheatConsequenceRules.filter(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||''))).length,antiCheatConsequenceRules.some(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||'')))?'warn':'neutral')+metric('Mode',antiCheatConsequenceRules.some(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||'')))?'Active enforcement':'Observe / log','neutral');});\n}\nfunction previewAntiCheatConsequence(index){\n  antiCheatConsequenceRules=collectAntiCheatConsequences();\n  const r=antiCheatConsequenceRules[index];if(!r)return;\n  const sample={player:'ExamplePlayer',status:r.triggerType==='Status'?(r.triggerValue||'Suspicious'):'Suspicious',risk:(r.triggerType==='RiskAtLeast'||r.triggerType==='FamilyRiskAtLeast')?(String(r.triggerValue||'50').split(':').pop()||'50'):'50',code:r.triggerType==='FindingCode'?(r.triggerValue||'FORBIDDEN_MOD'):'FORBIDDEN_MOD',subject:r.subject||'examplemod',duration:r.duration||'30m'};\n  let msg=String(r.message||'Anti-cheat policy matched for {player}.');for(const [k,v] of Object.entries(sample))msg=msg.replaceAll(`{${k}}`,String(v));\n  const action=String(r.action||'Log');let shown=msg;\n  if(action==='Kick')shown=`You are being kicked from the server. Reason: ${msg}`;\n  else if(action==='TempBan')shown=`You have been temporarily banned for ${sample.duration}. Reason: ${msg}`;\n  else if(action==='Freeze')shown=`You have been frozen for ${sample.duration}. Reason: ${msg}`;\n  else shown=`Log only (no player disconnect): ${msg}`;\n  alert(`Player-facing preview (sample values):\\n\\n${shown}`);\n}\nfunction collectAntiCheatConsequences(){\n  return [...document.querySelectorAll('#acConsequenceRows tr[data-ac-rule]')].map((row,i)=>{\n    const get=f=>row.querySelector(`[data-field=\"${f}\"]`);\n    const original=antiCheatConsequenceRules[i]||{};\n    return {id:original.id||newAntiCheatConsequenceRule().id,name:get('name').value.trim(),enabled:get('enabled').checked,triggerType:get('triggerType').value,triggerValue:get('triggerValue').value.trim(),subject:get('subject').value.trim(),action:get('action').value,duration:get('duration').value.trim(),message:get('message').value.trim()};\n  });\n}\nasync function saveAntiCheatConsequences(){\n  const rules=collectAntiCheatConsequences();\n  const disruptive=rules.filter(r=>r.enabled&&r.action!=='Log');\n  const applyCurrent=$('acConsequenceApplyCurrent').checked;\n  if(disruptive.length&&!confirm(`Save ${rules.length} consequence rule(s)? ${disruptive.length} enabled rule(s) can automatically kick, temporarily ban, or freeze players.`))return;\n  if(applyCurrent){const typed=prompt('This can immediately punish currently matching online players. Type APPLY to continue:','');if(typed!=='APPLY')return;}\n  try{\n    const d=await api('/api/anticheat/consequences',{method:'POST',body:JSON.stringify({rules,applyCurrent})});\n    toast(d.message||'Consequence policy saved.','success');\n    $('acConsequenceApplyCurrent').checked=false;\n    await loadAntiCheat(false);\n  }catch(e){toast(e.message,'error');}\n}\n$('acConsequenceAdd').onclick=()=>{antiCheatConsequenceRules.push(newAntiCheatConsequenceRule());renderAntiCheatConsequences();\n    if($('acEnforcementSummary'))$('acEnforcementSummary').innerHTML=metric('Rules',antiCheatConsequenceRules.length)+metric('Enabled',antiCheatConsequenceRules.filter(r=>r.enabled!==false).length,'good')+metric('Disruptive',antiCheatConsequenceRules.filter(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||''))).length,antiCheatConsequenceRules.some(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||'')))?'warn':'neutral')+metric('Mode',antiCheatConsequenceRules.some(r=>r.enabled!==false&&['Kick','TempBan','Freeze'].includes(String(r.action||'')))?'Active enforcement':'Observe / log','neutral');};\ndocument.querySelectorAll('[data-ac-preset]').forEach(b=>b.onclick=()=>addAntiCheatPreset(b.dataset.acPreset));\n$('acConsequenceSave').onclick=()=>saveAntiCheatConsequences();\nif($('acSimpleApply'))$('acSimpleApply').onclick=applySimpleAntiCheatEnforcement;\n\n$('acRefresh').onclick=()=>loadAntiCheat(true);\n$('acModuleSave').onclick=()=>saveAntiCheatModuleState();\n$('acClientSettingsSave').onclick=()=>saveAntiCheatClientSettings();\nif($('acFullConfigLoad'))$('acFullConfigLoad').onclick=loadAntiCheatFullConfig;\nif($('acFullConfigFormat'))$('acFullConfigFormat').onclick=formatAntiCheatFullConfig;\nif($('acFullConfigSave'))$('acFullConfigSave').onclick=saveAntiCheatFullConfig;\n$('acOreShieldSave').onclick=()=>saveAntiCheatOreShield();\n$('acPacketSave').onclick=()=>saveAntiCheatPacketGuard();\n$('acHistoryLoad').onclick=()=>loadAntiCheatHistory(($('acHistoryPlayerFilter').value||'').trim(),$('acHistoryFindingFilter').value||'');\nif($('acHistoryClearAll'))$('acHistoryClearAll').onclick=clearAllAntiCheatHistory;\n$('acHistoryClearFilter').onclick=()=>{$('acHistoryPlayerFilter').value='';$('acHistoryFindingFilter').value='';loadAntiCheatHistory('','');};\n$('acHistoryPlayerFilter').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();loadAntiCheatHistory(($('acHistoryPlayerFilter').value||'').trim(),$('acHistoryFindingFilter').value||'');}});\n$('acHistoryFindingFilter').addEventListener('change',()=>loadAntiCheatHistory(($('acHistoryPlayerFilter').value||'').trim(),$('acHistoryFindingFilter').value||''));\n$('acBlacklistAdd').onclick=()=>updateAntiCheatBlacklist('add',$('acBlacklistInput').value);\n$('acFingerprintReleaseDepthSave').onclick=()=>saveAntiCheatFingerprintReleaseDepth();\n$('acFingerprintReleaseDepth').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveAntiCheatFingerprintReleaseDepth();}});\n$('acBlacklistResolveMissing').onclick=()=>bulkResolveAntiCheatBlacklistFingerprints(false);\n$('acBlacklistRefreshAll').onclick=()=>bulkResolveAntiCheatBlacklistFingerprints(true);\n$('acBlacklistProfileLoad').onclick=()=>updateAntiCheatBlacklistProfile('load');\n$('acBlacklistProfileSave').onclick=()=>updateAntiCheatBlacklistProfile('save');\n$('acBlacklistProfileSaveAs').onclick=()=>updateAntiCheatBlacklistProfile('save-as');\n$('acBlacklistProfileDelete').onclick=()=>updateAntiCheatBlacklistProfile('delete');\n$('acBlacklistLoadDefault').onclick=()=>updateAntiCheatBlacklistProfile('load-default');\n$('acBlacklistProfileSelect').onchange=()=>{const id=String($('acBlacklistProfileSelect').value||'');const p=(window.__acBlacklistProfiles||[]).find(x=>String(x.id||'')===id);if(p)$('acBlacklistProfileName').value=String(p.name||'');};\n$('acManualSave').onclick=()=>saveAntiCheatManualFingerprint();\n$('acManualNew').onclick=()=>clearAntiCheatManualForm();\n$('acManualClose').onclick=()=>{$('acManualFingerprintEditor').style.display='none';antiCheatManualTarget='';antiCheatManualEditingId='';};\n$('acIntegrityHashAdd').onclick=()=>updateAntiCheatIntegrityPolicy('add',$('acIntegrityHashInput').value);\n$('acIntegrityRequire').onchange=()=>setAntiCheatBuildLock($('acIntegrityRequire').checked);\n$('acBlacklistInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();updateAntiCheatBlacklist('add',$('acBlacklistInput').value);}});\nif($('acPlayerSearch'))$('acPlayerSearch').addEventListener('input',renderAntiCheatPlayers);\nif($('acPlayerFilter'))$('acPlayerFilter').addEventListener('change',renderAntiCheatPlayers);\ndocument.querySelectorAll('[data-ac-sort]').forEach(btn=>btn.addEventListener('click',()=>{\n  const key=String(btn.dataset.acSort||'risk');\n  if(antiCheatPlayerSortKey===key)antiCheatPlayerSortDir=antiCheatPlayerSortDir==='desc'?'asc':'desc';\n  else{antiCheatPlayerSortKey=key;antiCheatPlayerSortDir=key==='player'?'asc':'desc';}\n  renderAntiCheatPlayers();\n}));\nif($('acApprovalUploadButton'))$('acApprovalUploadButton').onclick=uploadAntiCheatApprovalZip;\nif($('acClientModsSearch'))$('acClientModsSearch').addEventListener('input',renderAntiCheatClientMods);\nif($('acClientModsFilter'))$('acClientModsFilter').addEventListener('change',renderAntiCheatClientMods);\nif($('acClientModsResolveAll'))$('acClientModsResolveAll').onclick=resolveAllAntiCheatModDbFingerprints;\nfunction closeAntiCheatPlayerDrawer(){\n  if($('acDetail'))$('acDetail').style.display='none';\n  $('acDetailBackdrop')?.classList.remove('open');\n  document.body.classList.remove('acDrawerOpen');\n  antiCheatSelectedPlayer='';\n}\nconst suiteNativeCheckedDescriptor=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'checked');\nfunction suiteLinkedLabel(cb){\n  if(!cb?.id)return null;\n  const safeId=window.CSS&&typeof CSS.escape==='function'?CSS.escape(cb.id):cb.id.replace(/([\\\"'\\[\\]#. :>+~*^$|=()])/g,'\\\\$1');\n  return document.querySelector(`label[for=\"${safeId}\"]`);\n}\nfunction syncSuiteSwitchState(cb){\n  if(!cb?.classList?.contains('suiteSwitchInput'))return;\n  const on=!!cb.checked;\n  cb.setAttribute('aria-checked',on?'true':'false');\n  const track=cb.nextElementSibling?.classList.contains('suiteSwitchTrack')?cb.nextElementSibling:null;\n  if(track){\n    track.classList.toggle('isOn',on);\n    track.dataset.state=on?'on':'off';\n    track.setAttribute('aria-label',on?'On':'Off');\n  }\n  const wrappingLabel=cb.parentElement?.tagName==='LABEL'?cb.parentElement:null;\n  const linkedLabel=suiteLinkedLabel(cb);\n  wrappingLabel?.classList.toggle('switchOn',on);\n  linkedLabel?.classList.toggle('switchOn',on);\n}\nfunction bindSuiteSwitchState(cb){\n  if(cb.dataset.suiteSwitchStateBound)return;\n  const sync=()=>syncSuiteSwitchState(cb);\n  cb.addEventListener('change',sync);\n  cb.addEventListener('input',sync);\n  if(suiteNativeCheckedDescriptor?.get&&suiteNativeCheckedDescriptor?.set){\n    try{\n      Object.defineProperty(cb,'checked',{\n        configurable:true,\n        enumerable:!!suiteNativeCheckedDescriptor.enumerable,\n        get(){return suiteNativeCheckedDescriptor.get.call(this);},\n        set(value){suiteNativeCheckedDescriptor.set.call(this,value);syncSuiteSwitchState(this);}\n      });\n    }catch{}\n  }\n  cb.dataset.suiteSwitchStateBound='1';\n}\nfunction syncAllSuiteSwitches(root=document){\n  const scope=root?.querySelectorAll?root:document;\n  if(root?.matches?.('input.suiteSwitchInput'))syncSuiteSwitchState(root);\n  scope.querySelectorAll('input.suiteSwitchInput').forEach(syncSuiteSwitchState);\n}\nfunction enhanceToggleSwitches(root=document){\n  const scope=root?.querySelectorAll?root:document;\n  const boxes=[];\n  if(root?.matches?.('input[type=\"checkbox\"]'))boxes.push(root);\n  boxes.push(...scope.querySelectorAll('input[type=\"checkbox\"]'));\n  boxes.forEach(cb=>{\n    const wrappingLabel=cb.parentElement?.tagName==='LABEL'?cb.parentElement:null;\n    const linkedLabel=suiteLinkedLabel(cb);\n    const forced=cb.matches('[data-field=\"enabled\"],.discordRouteEnabled');\n    const label=wrappingLabel||linkedLabel;\n    if(!label&&!forced)return; // multi-select/compare checkboxes remain normal checkboxes\n\n    cb.setAttribute('role','switch');\n    cb.classList.add('suiteSwitchInput');\n\n    if(!cb.nextElementSibling?.classList.contains('suiteSwitchTrack')){\n      const track=document.createElement('span');\n      track.className='suiteSwitchTrack';\n      track.setAttribute('aria-hidden','true');\n      cb.insertAdjacentElement('afterend',track);\n      if(!wrappingLabel){\n        track.addEventListener('click',e=>{e.preventDefault();if(!cb.disabled){cb.click();cb.focus();}});\n      }\n    }\n\n    if(wrappingLabel){\n      const wasBlock=wrappingLabel.style.display==='block'||getComputedStyle(wrappingLabel).display==='block';\n      wrappingLabel.classList.add('switchToggle');\n      if(wasBlock)wrappingLabel.classList.add('switchBlock');\n    }else if(linkedLabel){\n      linkedLabel.classList.add('linkedSwitchLabel');\n    }else{\n      cb.parentElement?.classList.add('switchCell');\n    }\n\n    bindSuiteSwitchState(cb);\n    syncSuiteSwitchState(cb);\n  });\n}\nlet suiteSwitchObserver=null;\nfunction initToggleSwitchObserver(){\n  suiteSwitchObserver?.disconnect();\n  suiteSwitchObserver=new MutationObserver(muts=>{\n    muts.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===Node.ELEMENT_NODE)enhanceToggleSwitches(n);}));\n  });\n  suiteSwitchObserver.observe(document.body,{subtree:true,childList:true});\n  document.addEventListener('reset',()=>setTimeout(()=>syncAllSuiteSwitches(),0),true);\n}\n$('acDetailClose').onclick=closeAntiCheatPlayerDrawer;\nif($('acDetailBackdrop'))$('acDetailBackdrop').onclick=closeAntiCheatPlayerDrawer;\nif($('acDetailCopyUid'))$('acDetailCopyUid').onclick=copyAntiCheatPlayerUid;\nif($('acDetailRefresh'))$('acDetailRefresh').onclick=refreshAntiCheatPlayerDrawer;\ndocument.querySelectorAll('[data-ac-drawer-tab]').forEach(b=>{\n  b.onclick=()=>setAntiCheatDrawerTab(b.dataset.acDrawerTab,true);\n  b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-ac-drawer-tab]')];let i=tabs.indexOf(b);if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else i=(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setAntiCheatDrawerTab(tabs[i].dataset.acDrawerTab,true);};\n});\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('acDrawerOpen'))closeAntiCheatPlayerDrawer();});\nfunction openSelectedAntiCheatFullHistory(){if(!antiCheatSelectedPlayer)return;$('acHistoryPlayerFilter').value=antiCheatSelectedPlayer;setAntiCheatTab('history');closeAntiCheatPlayerDrawer();}\n$('acDetailHistory').onclick=openSelectedAntiCheatFullHistory;\nif($('acDrawerOpenFullHistory'))$('acDrawerOpenFullHistory').onclick=openSelectedAntiCheatFullHistory;\nif($('acInventoryRefresh'))$('acInventoryRefresh').onclick=()=>loadAntiCheatInventory(true);\nif($('acInventorySnapshot'))$('acInventorySnapshot').onclick=()=>acInventoryCreateSnapshot();\nif($('acInventoryClearSelection'))$('acInventoryClearSelection').onclick=()=>{antiCheatInventorySelectedSlot=null;renderAntiCheatInventory();};\nif($('acInventoryFilter'))$('acInventoryFilter').addEventListener('input',renderAntiCheatInventory);\nif($('acInventoryItemSearchBtn'))$('acInventoryItemSearchBtn').onclick=()=>acInventorySearchItems();\nif($('acInventoryItemSearch'))$('acInventoryItemSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();acInventorySearchItems();}});\nif($('acInventoryGiveAuto'))$('acInventoryGiveAuto').onclick=()=>acInventoryGiveSelectedItem(true);\nif($('acInventoryGiveSelected'))$('acInventoryGiveSelected').onclick=()=>acInventoryGiveSelectedItem(false);\nif($('acInventoryReplaceSelected'))$('acInventoryReplaceSelected').onclick=()=>acInventoryReplaceSelectedItem();\n$('acDetailRescan').onclick=()=>requestAntiCheatRescan(antiCheatSelectedPlayer);\nif($('acEvidenceSave'))$('acEvidenceSave').onclick=saveAntiCheatEvidenceSettings;if($('acEvidenceDeclineAction'))$('acEvidenceDeclineAction').onchange=syncAntiCheatEvidenceDeclineUi;\n\nfunction panelAccountRoleLabel(role){return role==='ReadOnly'?'Read Only':(role||'Administrator');}\n\nasync function loadWebAccounts(showLoading=true){\n  if(!currentSessionOwner){if($('webAccountsCard'))$('webAccountsCard').style.display='none';return;}\n  if($('webAccountsCard'))$('webAccountsCard').style.display='block';\n  if(showLoading)$('webAccountRows').innerHTML='<tr><td colspan=\"6\" class=\"muted\">Loading accounts…</td></tr>';\n  try{\n    const d=await api('/api/web/accounts');\n    const owner=d.owner||{};\n    const rows=d.accounts||[];\n    $('webAccountCount').textContent=`${rows.length} / ${Number(d.maximum||50)} additional`;\n    $('webOwnerAccount').innerHTML=`<b>${esc(owner.username||'admin')}</b> <span class=\"badge low\">Owner</span> · ${owner.passwordConfigured?'password configured':'<span class=\"warn\">password not configured</span>'}<br><span class=\"small\">The Owner account is managed with <code>/serverutils web username</code> and <code>/serverutils web password</code> and cannot be deleted here.</span>`;\n    $('webAccountRows').innerHTML=rows.length?rows.map(a=>{\n      const created=Number(a.createdUnixMilliseconds||0);\n      const last=Number(a.lastLoginUnixMilliseconds||0);\n      const locked=!!a.locked;\n      const state=!a.enabled?'<span class=\"badge muted\">Disabled</span>':locked?'<span class=\"badge high\">Locked</span>':'<span class=\"badge low\">Enabled</span>';\n      const login=last?`${esc(new Date(last).toLocaleString())}${a.lastLoginRemote?`<div class=\"small\">${esc(a.lastLoginRemote)}</div>`:''}`:'Never';\n      const role=a.role||'Administrator';\n      return `<tr>\n        <td><b>${esc(a.username||'')}</b></td>\n        <td>${esc(panelAccountRoleLabel(role))}</td>\n        <td>${state}</td>\n        <td>${created?esc(new Date(created).toLocaleString()):'—'}</td>\n        <td>${login}</td>\n        <td><div class=\"rowActions\">\n          <button class=\"iconBtn\" data-webacct-toggle=\"${esc(a.id)}\" data-enabled=\"${a.enabled?'1':'0'}\">${a.enabled?'Disable':'Enable'}</button>\n          <button class=\"iconBtn\" data-webacct-role=\"${esc(a.id)}\" data-role=\"${esc(role)}\">${role==='ReadOnly'?'Make Admin':'Make Read Only'}</button>\n          ${locked?`<button class=\"iconBtn\" data-webacct-unlock=\"${esc(a.id)}\">Unlock</button>`:''}\n          <button class=\"iconBtn\" data-webacct-reset-select=\"${esc(a.id)}\">Reset Password</button>\n          <button class=\"iconBtn danger\" data-webacct-delete=\"${esc(a.id)}\" data-name=\"${esc(a.username||'')}\">Delete</button>\n        </div></td>\n      </tr>`;\n    }).join(''):'<tr><td colspan=\"6\" class=\"muted\">No additional panel accounts. The Owner account is still active.</td></tr>';\n    $('webAccountResetUser').innerHTML='<option value=\"\">Select account…</option>'+rows.map(a=>`<option value=\"${esc(a.id)}\">${esc(a.username||'')}</option>`).join('');\n\n    document.querySelectorAll('[data-webacct-toggle]').forEach(b=>b.onclick=()=>webAccountAction(b.dataset.webacctToggle,b.dataset.enabled==='1'?'disable':'enable'));\n    document.querySelectorAll('[data-webacct-role]').forEach(b=>b.onclick=()=>webAccountAction(b.dataset.webacctRole,'role',b.dataset.role==='ReadOnly'?'Administrator':'ReadOnly'));\n    document.querySelectorAll('[data-webacct-unlock]').forEach(b=>b.onclick=()=>webAccountAction(b.dataset.webacctUnlock,'unlock'));\n    document.querySelectorAll('[data-webacct-reset-select]').forEach(b=>b.onclick=()=>{$('webAccountResetUser').value=b.dataset.webacctResetSelect||'';$('webAccountResetPassword').focus();});\n    document.querySelectorAll('[data-webacct-delete]').forEach(b=>b.onclick=()=>{if(confirm(`Delete panel account ${b.dataset.name||''}? Any active sessions for that user will be signed out.`))webAccountAction(b.dataset.webacctDelete,'delete');});\n  }catch(e){$('webAccountRows').innerHTML=`<tr><td colspan=\"6\" class=\"bad\">${esc(e.message)}</td></tr>`;}\n}\n\nasync function createWebAccount(){\n  const username=$('webAccountUsername').value.trim();\n  const password=$('webAccountPassword').value;\n  const role=$('webAccountRole').value;\n  if(!username||password.length<10){toast('Enter a valid username and a password of at least 10 characters.','error');return;}\n  try{\n    const d=await api('/api/web/accounts/create',{method:'POST',body:JSON.stringify({username,password,role})});\n    $('webAccountUsername').value='';$('webAccountPassword').value='';\n    toast(d.message||'Panel account created.','success');\n    await loadWebAccounts(false);\n  }catch(e){toast(e.message,'error');}\n}\n\nasync function webAccountAction(id,action,value='',password=''){\n  if(!id)return;\n  try{\n    const d=await api('/api/web/accounts/action',{method:'POST',body:JSON.stringify({id,action,value,password})});\n    toast(d.message||'Panel account updated.','success');\n    await loadWebAccounts(false);\n  }catch(e){toast(e.message,'error');}\n}\n\nasync function resetWebAccountPassword(){\n  const id=$('webAccountResetUser').value;\n  const password=$('webAccountResetPassword').value;\n  if(!id){toast('Select an account first.','error');return;}\n  if(password.length<10){toast('The new password must be at least 10 characters.','error');return;}\n  await webAccountAction(id,'password','',password);\n  $('webAccountResetPassword').value='';\n}\n\n$('webAccountsRefresh').onclick=()=>loadWebAccounts(true);\n$('webAccountCreate').onclick=createWebAccount;\n$('webAccountResetPasswordBtn').onclick=resetWebAccountPassword;\n\nconst featureGateLabels={\n  blocklogger:'BlockLogger audit/storage', ingamegui:'In-game admin GUI', admin:'Administration', anticheat:'Anti-Cheat server', afk:'AFK Mode',\n  animallimiter:'Animal Limiter', loginprotection:'Login Protection', webdashboard:'Web Dashboard', webconsole:'Web Console', webmap:'Web Map',\n  announcements:'Announcements', reports:'Reports & Tickets', analytics:'Player Analytics', diagnostics:'Profiler / Diagnostics',\n  modupdates:'Mod Update Checker', logintelligence:'Log Intelligence', performancecenter:'Performance Center', operationscenter:'Operations Center'\n};\n\nasync function loadFeatureGates(){\n  if(!$('featureGateRows'))return;\n  $('featureGateRows').innerHTML='<div class=\"empty\">Loading feature gates…</div>';\n  try{\n    const d=await api('/api/features');\n    const rows=d.features||[];\n    const activeMap=Object.fromEntries((d.activeFeatures||[]).map(x=>[String(x.name||''),!!x.enabled]));\n    $('featureGateRows').innerHTML=rows.map(f=>{\n      const name=String(f.name||'');\n      const enabled=!!f.enabled;\n      const active=Object.prototype.hasOwnProperty.call(activeMap,name)?activeMap[name]:enabled;\n      const pending=active!==enabled;\n      const label=featureGateLabels[name]||name;\n      const disabled=currentSessionRole==='ReadOnly'?'disabled':'';\n      const stateText=pending?`${active?'ON':'OFF'} → ${enabled?'ON':'OFF'}`:(enabled?'ON':'OFF');\n      const stateClass=pending?'warn':(enabled?'low':'muted');\n      const pendingText=pending?'<div class=\"small warn\" style=\"margin:0 0 10px\">Pending restart</div>':'';\n      return `<div class=\"card\" style=\"padding:12px\"><div class=\"cardHeader\"><b>${esc(label)}</b><span class=\"badge ${stateClass}\">${stateText}</span></div><div class=\"small\" style=\"margin:6px 0 10px\">${esc(name)}</div>${pendingText}<button data-feature-gate=\"${esc(name)}\" data-enabled=\"${enabled?'1':'0'}\" ${disabled}>${enabled?'Turn Off':'Turn On'}</button></div>`;\n    }).join('')||'<div class=\"empty\">No feature gates returned.</div>';\n    document.querySelectorAll('[data-feature-gate]').forEach(b=>b.onclick=()=>setFeatureGate(b.dataset.featureGate,b.dataset.enabled!=='1'));\n  }catch(e){$('featureGateRows').innerHTML=`<div class=\"bad\">${esc(e.message)}</div>`;}\n}\n\nasync function setFeatureGate(feature,enabled){\n  if(!feature)return;\n  const action=enabled?'enable':'disable';\n  if(!confirm(`${action[0].toUpperCase()+action.slice(1)} ${feature}? The change takes full effect after a server restart.`))return;\n  try{\n    const d=await api('/api/features',{method:'POST',body:JSON.stringify({feature,enabled})});\n    toast(d.message||'Feature gate saved. Restart required.','success');\n    await loadFeatureGates();\n  }catch(e){toast(e.message,'error');}\n}\n\n$('featureGatesRefresh').onclick=()=>loadFeatureGates();\n\nfunction roleColorMapToText(map){\n  return Object.entries(map||{}).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))).map(([role,color])=>`${role}=${color}`).join('\\n');\n}\nfunction parseRoleColorMap(text){\n  const out={};\n  for(const raw of String(text||'').split(/\\r?\\n/)){\n    const line=raw.trim(); if(!line)continue;\n    const eq=line.indexOf('='); if(eq<=0)continue;\n    const role=line.slice(0,eq).trim(); let color=line.slice(eq+1).trim();\n    if(!role||role.length>64)continue;\n    if(!color.startsWith('#'))color='#'+color;\n    if(!/^#[0-9a-f]{6}$/i.test(color))continue;\n    out[role]=color.toUpperCase();\n    if(Object.keys(out).length>=64)break;\n  }\n  return out;\n}\nfunction renderChatDisplayRoleColorPreview(){\n  const target=$('chatDisplayRoleColorPreview'); if(!target)return;\n  const map=parseRoleColorMap($('chatDisplayRoleColors')?.value||'');\n  const entries=Object.entries(map);\n  target.innerHTML=entries.length?entries.map(([role,color])=>`<span style=\"display:inline-flex;align-items:center;gap:5px;margin:2px 12px 2px 0\"><span style=\"width:10px;height:10px;border-radius:50%;background:${esc(color)};display:inline-block\"></span><b style=\"color:${esc(color)}\">${esc(role)}</b> <code>${esc(color)}</code></span>`).join(''):'No custom role colors configured.';\n}\n\nasync function loadPlayerListConfig(){\n  try{\n    const d=await api('/api/playerlist/config');\n    $('playerListServerName').value=String(d.serverName||'');\n    const opacity=Math.max(30,Math.min(95,Number(d.backgroundOpacityPercent||72)));\n    $('playerListOpacity').value=String(opacity);\n    $('playerListOpacityValue').textContent=`${opacity}%`;\n    const scale=Math.max(80,Math.min(135,Math.round(Number(d.layoutScale||1)*100)));\n    $('playerListScale').value=String(scale);\n    $('playerListScaleValue').textContent=`${(scale/100).toFixed(2)}×`;\n    $('playerListAccent').value=/^#[0-9a-f]{6}$/i.test(String(d.accentHex||''))?String(d.accentHex):'#d6ae63';\n    $('playerListAlignment').value=String(d.alignment||'CenterTop');\n    $('playerListOffsetX').value=String(Number(d.offsetX||0));\n    $('playerListOffsetY').value=String(Number(d.offsetY??22));\n    $('playerListRowsPerColumn').value=String(Number(d.rowsPerColumn||8));\n    $('playerListMaxColumns').value=String(Number(d.maxColumns||4));\n    $('playerListShowRoles').checked=d.showRoles!==false;\n    $('playerListShowPing').checked=d.showPing!==false;\n    $('playerListShowSession').checked=d.showSessionTime!==false;\n    $('playerListShowInitials').checked=d.showPlayerInitials!==false;\n    $('playerListShowCapacity').checked=d.showCapacityBar!==false;\n    $('playerListShowHeaders').checked=!!d.showColumnHeaders;\n    $('playerListCompactRows').checked=!!d.compactRows;\n    $('playerListShowPingBars').checked=d.showPingBars!==false;\n    $('playerListShowFooter').checked=!!d.showFooterHint;\n    $('playerListReservedEnabled').checked=!!d.reservedSlotsEnabled;\n    $('playerListReservedCount').value=String(Number(d.reservedSlots||0));\n    $('playerListReservedCount').max=String(Math.max(0,Number(d.maxClients||256)));\n    $('playerListReservedRoles').value=Array.isArray(d.reservedSlotRoles)?d.reservedSlotRoles.join('\\n'):'';\n    $('playerListReservedMessage').value=String(d.reservedSlotsFullMessage||'Only reserved slots are left on this server.');\n    const roleList=Array.isArray(d.configuredRoles)?d.configuredRoles:[];\n    $('playerListConfiguredRoles').innerHTML=roleList.length?`Server roles: ${roleList.map(r=>`<code>${esc(r.code||r.name||'')}</code>${r.name&&r.name!==r.code?` (${esc(r.name)})`:''}`).join(' · ')}`:'No server roles reported.';\n    const maxClients=Number(d.maxClients||0),publicLimit=Number(d.publicSlotLimit||maxClients),publicOnline=Number(d.publicOnline||0),reservedOnline=Number(d.reservedEligibleOnline||0),rejects=Number(d.reservedSlotRejections||0);\n    $('playerListReservedState').textContent=d.reservedSlotsEnabled?`ON · ${Number(d.reservedSlots||0)} reserved`:'OFF';\n    $('playerListReservedSummary').innerHTML=[\n      ['Server capacity',maxClients,`${publicLimit} public · ${Number(d.reservedSlots||0)} reserved`],\n      ['Public players',publicOnline,`${Math.max(0,publicLimit-publicOnline)} public slot(s) remaining`],\n      ['Reserved-role players',reservedOnline,'Players whose role may use reserved capacity'],\n      ['Rejected joins',rejects,'Non-reserved joins rejected since server start']\n    ].map(x=>`<div class=\"card\"><div class=\"metricLabel\">${esc(x[0])}</div><div class=\"metricValue\" style=\"font-size:18px\">${esc(x[1])}</div><div class=\"small\">${esc(x[2])}</div></div>`).join('');\n    $('playerListDebugLogging').checked=!!d.debugLogging;\n    $('playerListEffectiveName').textContent=`Effective header: ${d.effectiveServerName||'(unnamed server)'} · Config: ${d.configFile||'NewfiesPlayerList.json'} · Schema ${Number(d.configSchemaVersion||6)} · Style ${Number(d.styleVersion||5)}`;\n    $('playerListConfigState').textContent=d.available?'Backend ready':'Backend unavailable';\n\n    const requests=Number(d.requestsReceived||0),responses=Number(d.responsesSent||0),throttled=Number(d.requestsThrottled||0);\n    const buildFailures=Number(d.requestBuildFailures||0),sendFailures=Number(d.responseSendFailures||0);\n    const snapshotAge=Number(d.cachedSnapshotAgeMs??-1);\n    const responseGap=Math.max(0,requests-responses-throttled);\n    const debugItems=[\n      ['Backend',d.available?'READY':'UNAVAILABLE',d.available?'PlayerList service is registered':'PlayerList service is not running'],\n      ['Network channel',d.backendChannel||'newfies-public-playerlist-v1',`Protocol ${Number(d.protocolVersion||1)} · Companion ${d.companionModId||'newfiesplayerlist'} ${d.companionRecommendedVersion||''}`],\n      ['Backend build',d.backendBuild||'—',`Cache ${Number(d.snapshotCacheMs||750)}ms · Throttle ${Number(d.requestThrottleMs||750)}ms`],\n      ['Roster source',d.rosterSource||'—',`${Number(d.cachedPlayerCount||0)} players in cached roster`],\n      ['Snapshot age',snapshotAge<0?'Not built':`${snapshotAge} ms`,'Roster cache refreshes on demand and roster changes'],\n      ['Client hellos',Number(d.clientHellosReceived||0),'Handshake count since this server start'],\n      ['Requests',requests,`${responses} responses sent`],\n      ['Throttled',throttled,'Requests rejected by the anti-spam interval'],\n      ['Unanswered',responseGap,responseGap>0?'Requests not accounted for by response/throttle counters':'No unexplained request gap'],\n      ['Build failures',buildFailures,buildFailures?'Check the server log for roster build exceptions':'No roster build failures'],\n      ['Send failures',sendFailures,sendFailures?'Check the server log for network send exceptions':'No response send failures'],\n      ['Role name colors',d.useRoleNameColors?'ON':'OFF',`${Object.keys(d.roleNameColors||{}).length} shared override(s) · managed in Chat Display`],\n      ['Reserved slots',d.reservedSlotsEnabled?`${Number(d.reservedSlots||0)} RESERVED`:'OFF',`${Number(d.publicSlotLimit||0)} public slots · ${Number(d.reservedSlotRejections||0)} rejected join(s)`],\n      ['Debug logging',d.debugLogging?'ON':'OFF','Extra PlayerList backend log entries']\n    ];\n    $('playerListDebugGrid').innerHTML=debugItems.map(x=>`<div class=\"card\"><div class=\"metricLabel\">${esc(x[0])}</div><div class=\"metricValue\" style=\"font-size:18px\">${esc(x[1])}</div><div class=\"small\">${esc(x[2])}</div></div>`).join('');\n\n    const healthy=!!d.available&&buildFailures===0&&sendFailures===0&&responseGap===0;\n    $('playerListDiagnosticState').textContent=healthy?'Healthy':(d.available?'Needs attention':'Unavailable');\n    $('playerListBackendHelp').className=(sendFailures>0||buildFailures>0||responseGap>0)?'warning':'infoBox';\n    $('playerListBackendHelp').innerHTML=sendFailures>0\n      ? '<b>Response send failures detected.</b> Requests reached the suite, but Vintage Story rejected or failed the server-to-client response. Check <code>[ServerEssentials/PlayerList]</code> in the server log.'\n      : buildFailures>0\n        ? '<b>Roster build failures detected.</b> Check the server log for the underlying exception. Enable <b>Debug logging</b> above for additional PlayerList traces.'\n        : responseGap>0\n          ? '<b>Some requests are not accounted for.</b> Enable <b>Debug logging</b>, reproduce with Tab, then inspect <code>[ServerEssentials/PlayerList]</code> in the server log.'\n          : responses>0\n            ? '<b>Round trip confirmed.</b> The suite backend is receiving and answering player-list requests normally.'\n            : requests>0\n              ? '<b>Requests are arriving but no responses are recorded.</b> Check the server log for handler/send errors.'\n              : '<b>No roster requests recorded yet.</b> Hold Tab in game, then Refresh this page. If the companion reports <code>NotConnected</code>, verify the running Server Essentials DLL advertises the same PlayerList channel.';\n  }catch(e){\n    $('playerListConfigState').textContent=e.message;\n    $('playerListDiagnosticState').textContent='Failed to load';\n    $('playerListDebugGrid').innerHTML=`<div class=\"empty\">${esc(e.message)}</div>`;\n  }\n}\n\nasync function savePlayerListConfig(){\n  const body={\n    serverName:String($('playerListServerName').value||'').trim(),\n    backgroundOpacity:Math.max(.30,Math.min(.95,Number($('playerListOpacity').value||72)/100)),\n    layoutScale:Math.max(.80,Math.min(1.35,Number($('playerListScale').value||100)/100)),\n    accentHex:String($('playerListAccent').value||'#d6ae63'),\n    alignment:String($('playerListAlignment').value||'CenterTop'),\n    offsetX:Number($('playerListOffsetX').value||0),\n    offsetY:Number($('playerListOffsetY').value||22),\n    rowsPerColumn:Number($('playerListRowsPerColumn').value||8),\n    maxColumns:Number($('playerListMaxColumns').value||4),\n    showRoles:!!$('playerListShowRoles').checked,\n    showPing:!!$('playerListShowPing').checked,\n    showSessionTime:!!$('playerListShowSession').checked,\n    showPlayerInitials:!!$('playerListShowInitials').checked,\n    showCapacityBar:!!$('playerListShowCapacity').checked,\n    showColumnHeaders:!!$('playerListShowHeaders').checked,\n    compactRows:!!$('playerListCompactRows').checked,\n    showPingBars:!!$('playerListShowPingBars').checked,\n    showFooterHint:!!$('playerListShowFooter').checked,\n    reservedSlotsEnabled:!!$('playerListReservedEnabled').checked,\n    reservedSlots:Number($('playerListReservedCount').value||0),\n    reservedSlotRoles:String($('playerListReservedRoles').value||''),\n    reservedSlotsFullMessage:String($('playerListReservedMessage').value||'Only reserved slots are left on this server.').trim(),\n    debugLogging:!!$('playerListDebugLogging').checked\n  };\n  try{\n    const d=await api('/api/playerlist/config',{method:'POST',body:JSON.stringify(body)});\n    toast(d.message||'Player-list configuration saved.','success');\n    await loadPlayerListConfig();\n  }catch(e){toast(e.message,'error')}\n}\n\n$('playerListOpacity').oninput=()=>{$('playerListOpacityValue').textContent=`${$('playerListOpacity').value}%`;};\n$('playerListScale').oninput=()=>{$('playerListScaleValue').textContent=`${(Number($('playerListScale').value)/100).toFixed(2)}×`;};\n$('playerListConfigSave').onclick=savePlayerListConfig;\n$('playerListReservedSave').onclick=savePlayerListConfig;\n$('playerListConfigRefresh').onclick=()=>loadPlayerListConfig();\nwireDiscordPanel();\n\nlet discordData=null;\nconst discordAnnouncementDefs=[\n  ['playerJoin','Player joined'],\n  ['playerLeave','Player left'],\n  ['playerDeath','Player death'],\n  ['serverStarted','Server started'],\n  ['serverStopping','Server stopping'],\n  ['discordLinked','Discord account linked'],\n  ['discordUnlinked','Discord account unlinked']\n];\n\nfunction discordRoute(d,key){return (d&&d[key])||{enabled:false,channelId:'0',format:''};}\nfunction discordSetValue(id,value){const e=$(id);if(e)e.value=value??'';}\nfunction discordSetChecked(id,value){const e=$(id);if(e)e.checked=!!value;}\nfunction discordMutationsDisabled(){return currentSessionRole==='ReadOnly';}\n\nfunction renderDiscordAnnouncementRows(d){\n  const body=$('discordAnnouncementRows');if(!body)return;\n  body.innerHTML=discordAnnouncementDefs.map(([key,label])=>{\n    const r=discordRoute(d,key);\n    return `<tr data-discord-route=\"${esc(key)}\"><td><b>${esc(label)}</b></td><td><input class=\"discordRouteEnabled\" type=\"checkbox\" ${r.enabled?'checked':''}></td><td><input class=\"discordRouteChannel\" value=\"${esc(r.channelId||'0')}\" placeholder=\"0 = main channel\"></td><td><input class=\"discordRouteFormat\" value=\"${esc(r.format||'')}\" style=\"min-width:280px\"></td><td><button class=\"discordRouteSave\">Save</button></td></tr>`;\n  }).join('');\n  body.querySelectorAll('tr[data-discord-route]').forEach(row=>{\n    const key=row.dataset.discordRoute;\n    const save=row.querySelector('.discordRouteSave');\n    if(save)save.onclick=()=>saveDiscordAnnouncement(key,row);\n    if(discordMutationsDisabled())row.querySelectorAll('input,button').forEach(e=>e.disabled=true);\n  });\n}\n\nfunction renderDiscord(d){\n  discordData=d||{};\n  const transport=!!d.transportAvailable, link=!!d.linkAvailable;\n  const connected=!!d.transportConnected;\n  const notice=$('discordNotice');\n  if(notice){\n    if(!transport&&!link)notice.innerHTML='<b>Discord module not detected.</b> Install Newfie\\'s Server Essentials - Discord 1.0.0+ to manage it here.';\n    else if(transport&&!d.botTokenConfigured)notice.innerHTML='<b>Discord Integration is loaded, but no bot token is configured.</b> The token remains server-side and is never exposed through this panel.';\n    else if(transport&&!connected&&d.transportEnabled)notice.innerHTML='<b>Discord Integration is enabled but disconnected.</b> Check the server log, bot token, Guild ID, and Discord connectivity.';\n    else notice.innerHTML=`<b>${connected?'Discord bot connected.':'Discord controls available.'}</b> ${link?'Account linking is available.':'Account linking is unavailable; upgrade the Discord module to 1.0.0+.'}`;\n  }\n  if($('discordMetrics'))$('discordMetrics').innerHTML=\n    metric('Bot',!transport?'Not installed':(connected?'Connected':(d.transportEnabled?'Disconnected':'Disabled')),connected?'good':(d.transportEnabled?'warn':'neutral'),d.botName||'')+\n    metric('Account linking',link?'Available':'Unavailable',link?'good':'neutral')+\n    metric('Linked accounts',Number(d.linkedAccountCount||0),link?'good':'neutral')+\n    metric('Pending codes',Number(d.pendingLinkCodeCount||0),Number(d.pendingLinkCodeCount||0)>0?'warn':'neutral')+\n    metric('Token',d.botTokenConfigured?'Configured':'Not configured',d.botTokenConfigured?'good':'warn','Server-side only')+\n    metric('Guild',d.guildId&&d.guildId!=='0'?d.guildId:'Not set',d.guildId&&d.guildId!=='0'?'good':'neutral');\n\n  discordSetChecked('discordTransportEnabled',d.transportEnabled);\n  discordSetChecked('discordChatEnabled',d.chatEnabled);\n  discordSetChecked('discordGameToDiscord',d.gameToDiscord);\n  discordSetChecked('discordDiscordToGame',d.discordToGame);\n  discordSetChecked('discordBoldGameSenderLabel',d.gameBoldSenderLabel!==false);\n  discordSetChecked('discordUseGameRoleColor',d.gameUseRoleColor);\n  discordSetValue('discordNameColor',d.discordNameColor||'#5865F2');\n  discordSetChecked('discordShowDcTag',d.discordShowDcTag);\n  discordSetChecked('discordBoldSenderName',d.discordBoldSenderName);\n  discordSetChecked('discordMotdEnabled',d.motdEnabled!==false);\n  discordSetValue('discordMotdAnnouncementsChannel',d.motdAnnouncementsChannelId||'0');\n  discordSetValue('discordMotdUpdatesChannel',d.motdUpdatesChannelId||'0');\n  discordSetValue('discordMotdEventsChannel',d.motdEventsChannelId||'0');\n  discordSetValue('discordMotdMaxItems',Number(d.motdMaxItemsPerFeed||8));\n  discordSetChecked('discordCommandsEnabled',d.commandsEnabled);\n  discordSetChecked('discordPlayerInfoCommands',d.playerInfoCommandsEnabled);\n  discordSetChecked('discordStaffCommands',d.staffCommandsEnabled);\n  discordSetChecked('discordRestartCommands',d.restartCommandsEnabled);\n  discordSetValue('discordGuildId',d.guildId||'0');\n  discordSetValue('discordInviteUrl',d.inviteUrl||'');\n  discordSetValue('discordChatChannel',d.chatChannelId||'0');\n  discordSetChecked('discordAdminAuditEnabled',d.adminAuditEnabled);\n  discordSetValue('discordAdminChannel',d.adminAuditChannelId||'0');\n  discordSetChecked('discordAntiCheatEnabled',d.antiCheatDiscordEnabled);\n  discordSetValue('discordAntiCheatChannel',d.antiCheatChannelId||'0');\n\n  discordSetChecked('discordLinkEnabled',d.linkEnabled);\n  discordSetChecked('discordLinkCommands',d.linkCommandsEnabled);\n  discordSetChecked('discordLinkMultiple',d.linkAllowMultipleVs);\n  discordSetChecked('discordLinkLog',d.linkLogChanges);\n  discordSetValue('discordCodeLength',Number(d.linkCodeLength||8));\n  discordSetValue('discordCodeExpiry',Number(d.linkCodeExpirySeconds||300));\n  discordSetValue('discordCodeCooldown',Number(d.linkCodeCooldownSeconds||30));\n  if($('discordLinkModuleState'))$('discordLinkModuleState').textContent=link?'Available in Discord module':'Unavailable';\n  if($('discordLinkCounts'))$('discordLinkCounts').textContent=link?`${Number(d.linkedAccountCount||0)} linked account(s) · ${Number(d.pendingLinkCodeCount||0)} pending code(s)`:'Upgrade Newfie\\'s Server Essentials - Discord to 1.0.0+ to enable account linking.';\n  if($('discordChannelList'))$('discordChannelList').textContent=(d.channels||'').trim()||'No connected guild text channels reported.';\n  renderDiscordAnnouncementRows(d);\n\n  const mutating=document.querySelectorAll('#discord input,#discord select,#discord textarea,#discord button:not(#discordRefresh)');\n  mutating.forEach(e=>{e.disabled=discordMutationsDisabled() || ((!transport)&&!String(e.id||'').startsWith('discordLink'));});\n  ['discordLinkEnabled','discordLinkMultiple','discordLinkLog','discordCodeLength','discordCodeExpiry','discordCodeCooldown'].forEach(id=>{const e=$(id);if(e)e.disabled=discordMutationsDisabled()||!link;});\n  const linkCommands=$('discordLinkCommands');if(linkCommands)linkCommands.disabled=discordMutationsDisabled()||!transport;\n}\n\n\n__NSS_PLAYER_COMMANDS_SCRIPT__\n__NSS_ROLE_SCRIPT__\n__NSS_POLISH_SCRIPT__\n\nlet warpState=null;\nfunction resetWarpEditor(){\n  $('warpName').value='';$('warpDisplayName').value='';$('warpEnabled').checked=true;\n  $('warpX').value='';$('warpY').value='';$('warpZ').value='';\n  $('warpCooldown').value='-1';$('warpWarmup').value='-1';$('warpCancelMove').value='default';\n  $('warpCostEnabled').checked=false;$('warpCostItem').value='';$('warpCostQty').value='1';\n  if($('warpAccessMode'))$('warpAccessMode').value='public';\n  if($('warpAllowedRoles'))Array.from($('warpAllowedRoles').options).forEach(o=>o.selected=false);\n  if($('warpRequiredPrivileges'))$('warpRequiredPrivileges').value='';\n  syncWarpAccessControls();\n}\nfunction setWarpEditor(w){\n  if(!w){resetWarpEditor();return;}\n  $('warpName').value=w.name||'';$('warpDisplayName').value=w.displayName||w.name||'';$('warpEnabled').checked=w.enabled!==false;\n  $('warpX').value=Number(w.x??0);$('warpY').value=Number(w.y??0);$('warpZ').value=Number(w.z??0);\n  $('warpCooldown').value=Number(w.cooldownSeconds??-1);$('warpWarmup').value=Number(w.warmupSeconds??-1);\n  $('warpCancelMove').value=w.cancelOnMove===true?'true':w.cancelOnMove===false?'false':'default';\n  $('warpCostEnabled').checked=!!w.costEnabled;$('warpCostItem').value=w.costItemCode||'';$('warpCostQty').value=Number(w.costQuantity||1);\n  const roles=Array.isArray(w.allowedRoles)?w.allowedRoles:[], privs=Array.isArray(w.requiredPrivileges)?w.requiredPrivileges:[];\n  if($('warpAccessMode'))$('warpAccessMode').value=(roles.length||privs.length)?(String(w.accessMode||'any').toLowerCase()==='all'?'all':'any'):'public';\n  if($('warpAllowedRoles'))Array.from($('warpAllowedRoles').options).forEach(o=>o.selected=roles.some(r=>String(r).toLowerCase()===String(o.value).toLowerCase()));\n  if($('warpRequiredPrivileges'))$('warpRequiredPrivileges').value=privs.join(', ');\n  syncWarpAccessControls();\n}\nfunction parseWarpAccessList(value){return [...new Set(String(value||'').split(/[;,\\n]+/).map(v=>v.trim()).filter(Boolean))];}\nfunction selectedWarpRoles(){const el=$('warpAllowedRoles');return el?Array.from(el.selectedOptions).map(o=>o.value).filter(Boolean):[];}\nfunction warpAccessSummary(w){\n  const roles=Array.isArray(w.allowedRoles)?w.allowedRoles:[], privs=Array.isArray(w.requiredPrivileges)?w.requiredPrivileges:[];\n  if(!roles.length&&!privs.length)return t('warp.public');\n  const mode=String(w.accessMode||'any').toLowerCase()==='all'?t('warp.all'):t('warp.any');\n  const parts=[];if(roles.length)parts.push(`${t('warp.roles')}: ${roles.join(', ')}`);if(privs.length)parts.push(`${t('warp.privileges')}: ${privs.join(', ')}`);\n  return `${mode} · ${parts.join(' · ')}`;\n}\nfunction syncWarpAccessControls(){\n  const publicMode=($('warpAccessMode')?.value||'public')==='public';\n  const ro=currentSessionRole==='ReadOnly'||warpState?.available===false;\n  if($('warpAllowedRoles'))$('warpAllowedRoles').disabled=ro||publicMode;\n  if($('warpRequiredPrivileges'))$('warpRequiredPrivileges').disabled=ro||publicMode;\n}\nfunction populateWarpAccessOptions(d){\n  const roles=[...new Set([...(Array.isArray(d?.availableRoles)?d.availableRoles:[]),...((d?.warps||[]).flatMap(w=>Array.isArray(w.allowedRoles)?w.allowedRoles:[]))])].sort((a,b)=>String(a).localeCompare(String(b)));\n  const privs=Array.isArray(d?.availablePrivileges)?d.availablePrivileges:[];\n  const roleEl=$('warpAllowedRoles');if(roleEl){const selected=new Set(Array.from(roleEl.selectedOptions).map(o=>o.value.toLowerCase()));roleEl.innerHTML=roles.map(r=>`<option value=\"${esc(r)}\" ${selected.has(String(r).toLowerCase())?'selected':''}>${esc(r)}</option>`).join('');}\n  const datalist=$('warpPrivilegeSuggestions');if(datalist)datalist.innerHTML=privs.map(v=>`<option value=\"${esc(v)}\"></option>`).join('');\n}\nfunction renderWarps(d){\n  warpState=d||{warps:[]};\n  $('warpDefaultCooldown').value=Number(d?.defaultCooldownSeconds??60);\n  $('warpDefaultWarmup').value=Number(d?.defaultWarmupSeconds??5);\n  $('warpDefaultCancelMove').checked=d?.defaultCancelOnMove!==false;\n  populateWarpAccessOptions(warpState);\n  const rows=Array.isArray(warpState.warps)?warpState.warps:[];\n  if($('warpCountState'))$('warpCountState').textContent=`${rows.length} configured`;\n  const body=$('warpRows');if(!body)return;\n  body.innerHTML=rows.map(w=>{\n    const cost=w.costEnabled?`${Number(w.costQuantity||1)} × ${esc(w.costItemCode||'')}`:'Free';\n    const cd=Number(w.cooldownSeconds??-1)<0?'Default':`${Number(w.cooldownSeconds)}s`;\n    const warm=Number(w.warmupSeconds??-1)<0?'Default':`${Number(w.warmupSeconds)}s`;\n    const access=warpAccessSummary(w);\n    return `<tr data-warp-name=\"${esc(w.name||'')}\"><td><b>${esc(w.displayName||w.name||'')}</b><br><code>${esc(w.name||'')}</code></td><td><code>${Number(w.x||0).toFixed(1)}, ${Number(w.y||0).toFixed(1)}, ${Number(w.z||0).toFixed(1)}</code></td><td>${esc(cd)}</td><td>${esc(warm)}</td><td>${cost}</td><td><span class=\"small\">${esc(access)}</span></td><td><span class=\"badge ${w.enabled!==false?'low':'medium'}\">${w.enabled!==false?'Enabled':'Disabled'}</span></td><td><button class=\"warpEdit\">Edit</button> <button class=\"warpDelete danger\">Delete</button></td></tr>`;\n  }).join('')||'<tr><td colspan=\"8\" class=\"empty\">No warps configured. Use /setwarp in game or create one above.</td></tr>';\n  body.querySelectorAll('tr[data-warp-name]').forEach(row=>{\n    const name=row.dataset.warpName||'';\n    row.querySelector('.warpEdit')?.addEventListener('click',()=>setWarpEditor(rows.find(x=>String(x.name||'').toLowerCase()===name.toLowerCase())));\n    row.querySelector('.warpDelete')?.addEventListener('click',()=>deleteWarp(name));\n  });\n  const ro=currentSessionRole==='ReadOnly';\n  ['warpDefaultCooldown','warpDefaultWarmup','warpDefaultCancelMove','warpNew','warpSave','warpReload','warpDefaultsSave','warpName','warpDisplayName','warpEnabled','warpX','warpY','warpZ','warpCooldown','warpWarmup','warpCancelMove','warpCostEnabled','warpCostItem','warpCostQty','warpAccessMode','warpAllowedRoles','warpRequiredPrivileges'].forEach(id=>{const e=$(id);if(e)e.disabled=ro||warpState.available===false;});\n  syncWarpAccessControls();\n  if(ro)body.querySelectorAll('button').forEach(e=>e.disabled=true);\n}\nasync function loadWarps(showLoading=true){\n  try{const d=await api('/api/warps');renderWarps(d);}\n  catch(e){if(showLoading)toast(e.message,'error');renderWarps({available:false,warps:[]});}\n}\nasync function saveWarpDefaults(){\n  if(currentSessionRole==='ReadOnly'||warpState?.available!==true)return;\n  const button=$('warpDefaultsSave');\n  if(button.disabled)return;\n  for(const id of ['warpDefaultCooldown','warpDefaultWarmup']){\n    const el=$(id);if(el.value.trim()===''||!el.checkValidity()){el.reportValidity();toast('Enter valid warp delays.','error');return;}\n  }\n  button.disabled=true;\n  try{\n    const result=await api('/api/warps/settings',{method:'POST',body:JSON.stringify({enabled:warpState.enabled!==false,defaultCooldownSeconds:Number($('warpDefaultCooldown').value),defaultWarmupSeconds:Number($('warpDefaultWarmup').value),defaultCancelOnMove:$('warpDefaultCancelMove').checked})});\n    renderWarps(result.snapshot||await api('/api/warps'));\n    toast(result.message||'Warp defaults saved.','success');\n  }catch(e){toast(e.message,'error');}\n  finally{button.disabled=currentSessionRole==='ReadOnly'||warpState?.available!==true;}\n}\nasync function saveWarp(){\n  const move=$('warpCancelMove').value;\n  const payload={\n    name:$('warpName').value||'',displayName:$('warpDisplayName').value||'',enabled:!!$('warpEnabled').checked,\n    x:Number($('warpX').value||0),y:Number($('warpY').value||0),z:Number($('warpZ').value||0),\n    cooldownSeconds:Math.round(Number($('warpCooldown').value??-1)),warmupSeconds:Math.round(Number($('warpWarmup').value??-1)),\n    cancelOnMove:move==='true'?true:move==='false'?false:null,\n    costEnabled:!!$('warpCostEnabled').checked,costItemCode:$('warpCostItem').value||'',costQuantity:Math.round(Number($('warpCostQty').value||1)),\n    accessMode:($('warpAccessMode')?.value||'public')==='all'?'all':'any',\n    allowedRoles:($('warpAccessMode')?.value||'public')==='public'?[]:selectedWarpRoles(),\n    requiredPrivileges:($('warpAccessMode')?.value||'public')==='public'?[]:parseWarpAccessList($('warpRequiredPrivileges')?.value||'')\n  };\n  if(!payload.name.trim()){toast('Warp name is required.','error');return;}\n  try{const d=await api('/api/warps/upsert',{method:'POST',body:JSON.stringify(payload)});toast(d.message||'Warp saved.','success');renderWarps(d.snapshot||await api('/api/warps'));await loadPlayerCommands(false);}\n  catch(e){toast(e.message,'error');await loadWarps(false);}\n}\nasync function deleteWarp(name){\n  if(!confirm(`Delete warp ${name}?`))return;\n  try{const d=await api('/api/warps/delete',{method:'POST',body:JSON.stringify({name})});toast(d.message||'Warp deleted.','success');renderWarps(d.snapshot||await api('/api/warps'));resetWarpEditor();await loadPlayerCommands(false);}\n  catch(e){toast(e.message,'error');await loadWarps(false);}\n}\nasync function reloadWarps(){\n  try{const d=await api('/api/warps/reload',{method:'POST',body:'{}'});toast(d.message||'Warps reloaded.','success');renderWarps(d.snapshot||await api('/api/warps'));await loadPlayerCommands(false);}\n  catch(e){toast(e.message,'error');}\n}\n$('warpDefaultsSave').onclick=saveWarpDefaults;\n$('warpNew').onclick=resetWarpEditor;\n$('warpSave').onclick=saveWarp;\n$('warpReload').onclick=reloadWarps;\n$('warpCostEnabled').addEventListener('change',()=>{$('warpCostItem').disabled=currentSessionRole==='ReadOnly'||!$('warpCostEnabled').checked;$('warpCostQty').disabled=currentSessionRole==='ReadOnly'||!$('warpCostEnabled').checked;});\nif($('warpAccessMode'))$('warpAccessMode').addEventListener('change',syncWarpAccessControls);\n\nasync function loadDiscord(showLoading=true){\n  if(showLoading&&$('discordNotice'))$('discordNotice').textContent='Loading Discord integration status…';\n  try{\n    const d=await api('/api/discord');\n    renderDiscord(d);\n    const available=!!(d.transportAvailable||d.linkAvailable);\n    setNavStatus('discord',!available?'neutral':(d.transportConnected?'good':(d.transportEnabled?'warn':'neutral')),!available?'Discord module not installed':(d.transportConnected?'Discord bot connected':(d.transportEnabled?'Discord enabled but disconnected':'Discord integration disabled')));\n  }catch(e){\n    if($('discordNotice'))$('discordNotice').innerHTML=`<b>Could not load Discord controls:</b> ${esc(e.message)}`;\n    setNavStatus('discord','bad','Discord status request failed');\n  }\n}\n\nasync function postDiscordSetting(key,type,value,refresh=true){\n  const body={key,boolValue:false,intValue:0,stringValue:''};\n  if(type==='bool')body.boolValue=!!value;\n  else if(type==='int')body.intValue=Number(value||0);\n  else body.stringValue=String(value??'');\n  try{\n    const d=await api('/api/discord/settings',{method:'POST',body:JSON.stringify(body)});\n    if(d.message)toast(d.message,'success');\n    if(refresh)await loadDiscord(false);\n    return true;\n  }catch(e){toast(e.message,'error');if(refresh)await loadDiscord(false);return false;}\n}\n\nasync function saveDiscordAnnouncement(key,row){\n  const channel=(row.querySelector('.discordRouteChannel')?.value||'0').trim();\n  const format=row.querySelector('.discordRouteFormat')?.value||'';\n  const enabled=!!row.querySelector('.discordRouteEnabled')?.checked;\n  try{\n    const d=await api('/api/discord/settings',{method:'POST',body:JSON.stringify({key:`event.${key}.route`,boolValue:enabled,intValue:0,stringValue:channel,target:format})});\n    toast(d.message||'Discord announcement saved.','success');\n    renderDiscord(d);\n  }catch(e){toast(e.message,'error');await loadDiscord(false);}\n}\n\nasync function testDiscord(target){\n  try{const d=await api('/api/discord/test',{method:'POST',body:JSON.stringify({target})});toast(d.message||'Discord test queued.','success');await loadDiscord(false);}catch(e){toast(e.message,'error');}\n}\n\nfunction wireDiscordPanel(){\n  if(!$('discordRefresh'))return;\n  $('discordRefresh').onclick=()=>loadDiscord(true);\n  $('discordTestChat').onclick=()=>testDiscord('chat');\n  $('discordTestAdmin').onclick=()=>testDiscord('admin');\n  $('discordTestAntiCheat').onclick=()=>testDiscord('anticheat');\n  $('discordTransportEnabled').onchange=e=>postDiscordSetting('transport.enabled','bool',e.target.checked);\n  $('discordChatEnabled').onchange=e=>postDiscordSetting('chat.enabled','bool',e.target.checked);\n  $('discordGameToDiscord').onchange=e=>postDiscordSetting('chat.gametodiscord','bool',e.target.checked);\n  $('discordDiscordToGame').onchange=e=>postDiscordSetting('chat.discordtogame','bool',e.target.checked);\n  $('discordBoldGameSenderLabel').onchange=e=>postDiscordSetting('chat.boldgamesenderlabel','bool',e.target.checked);\n  $('discordUseGameRoleColor').onchange=e=>postDiscordSetting('chat.usegamerolecolor','bool',e.target.checked);\n  $('discordShowDcTag').onchange=e=>postDiscordSetting('chat.showdctag','bool',e.target.checked);\n  $('discordBoldSenderName').onchange=e=>postDiscordSetting('chat.bolddiscordname','bool',e.target.checked);\n  $('discordSaveNameColor').onclick=()=>postDiscordSetting('chat.discordnamecolor','string',$('discordNameColor').value);\n  $('discordCommandsEnabled').onchange=e=>postDiscordSetting('commands.enabled','bool',e.target.checked);\n  $('discordPlayerInfoCommands').onchange=e=>postDiscordSetting('commands.playerinfoenabled','bool',e.target.checked);\n  $('discordStaffCommands').onchange=e=>postDiscordSetting('commands.staffenabled','bool',e.target.checked);\n  $('discordRestartCommands').onchange=e=>postDiscordSetting('commands.restartenabled','bool',e.target.checked);\n  $('discordAdminAuditEnabled').onchange=e=>postDiscordSetting('adminaudit.enabled','bool',e.target.checked);\n  $('discordAntiCheatEnabled').onchange=e=>postDiscordSetting('anticheat.enabled','bool',e.target.checked);\n  $('discordMotdEnabled').onchange=e=>postDiscordSetting('motd.enabled','bool',e.target.checked);\n  $('discordLinkEnabled').onchange=e=>postDiscordSetting('link.enabled','bool',e.target.checked);\n  $('discordLinkCommands').onchange=e=>postDiscordSetting('commands.linkenabled','bool',e.target.checked);\n  $('discordLinkMultiple').onchange=e=>postDiscordSetting('link.allowmultiplevs','bool',e.target.checked);\n  $('discordLinkLog').onchange=e=>postDiscordSetting('link.logchanges','bool',e.target.checked);\n  $('discordSaveGuild').onclick=()=>postDiscordSetting('transport.guildid','string',$('discordGuildId').value);\n  $('discordSaveInvite').onclick=()=>postDiscordSetting('transport.inviteurl','string',$('discordInviteUrl').value);\n  $('discordSaveChatChannel').onclick=()=>postDiscordSetting('chat.channelid','string',$('discordChatChannel').value);\n  $('discordSaveAdminChannel').onclick=()=>postDiscordSetting('adminaudit.channelid','string',$('discordAdminChannel').value);\n  $('discordSaveAntiCheatChannel').onclick=()=>postDiscordSetting('anticheat.channelid','string',$('discordAntiCheatChannel').value);\n  $('discordSaveMotdAnnouncements').onclick=()=>postDiscordSetting('motd.announcementschannelid','string',$('discordMotdAnnouncementsChannel').value);\n  $('discordSaveMotdUpdates').onclick=()=>postDiscordSetting('motd.updateschannelid','string',$('discordMotdUpdatesChannel').value);\n  $('discordSaveMotdEvents').onclick=()=>postDiscordSetting('motd.eventschannelid','string',$('discordMotdEventsChannel').value);\n  $('discordSaveMotdMaxItems').onclick=()=>postDiscordSetting('motd.maxitemsperfeed','int',$('discordMotdMaxItems').value);\n  $('discordSaveCodeLength').onclick=()=>postDiscordSetting('link.codelength','int',$('discordCodeLength').value);\n  $('discordSaveCodeExpiry').onclick=()=>postDiscordSetting('link.codeexpiryseconds','int',$('discordCodeExpiry').value);\n  $('discordSaveCodeCooldown').onclick=()=>postDiscordSetting('link.codecooldownseconds','int',$('discordCodeCooldown').value);\n}\n\n\nlet chatGuardData=null;\nfunction chatGuardRule(c,key){return (c&&c[key])||{};}\nfunction chatGuardTime(ms){const n=Number(ms||0);return n>0?new Date(n).toLocaleString():'—';}\nfunction chatGuardLines(value){return String(value||'').split(/\\r?\\n|,/).map(x=>x.trim()).filter(Boolean);}\nfunction chatGuardVersionAtLeast(major,minor,patch){\n  const parts=String(chatGuardData?.version||'0.0.0').split('.').map(x=>Number.parseInt(x,10)||0);\n  if(parts[0]!==major)return parts[0]>major;\n  if(parts[1]!==minor)return parts[1]>minor;\n  return parts[2]>=patch;\n}\nfunction setChatGuardRule(prefix,rule){\n  const r=rule||{};\n  const enabled=$(prefix+'Enabled');if(enabled)enabled.checked=r.Enabled!==false;\n  const action=$(prefix+'Action');if(action)action.value=r.Action||'Warn';\n  const mute=$(prefix+'Mute');if(mute)mute.value=Number(r.MuteMinutes||5);\n}\nfunction chatGuardRuleHit(rule){\n  const stats=Array.isArray(chatGuardData?.ruleStats)?chatGuardData.ruleStats:[];\n  const row=stats.find(x=>String(x.Rule||'').toLowerCase()===String(rule||'').toLowerCase());\n  return Number(row?.Matches||0);\n}\nfunction renderChatGuardRecent(){\n  if(!$('cgRecentRows'))return;\n  const recent=Array.isArray(chatGuardData?.recent)?chatGuardData.recent:[];\n  const q=String($('cgRecentSearch')?.value||'').trim().toLowerCase();\n  const action=String($('cgRecentAction')?.value||'').trim().toLowerCase();\n  const filtered=recent.filter(x=>{\n    if(action&&String(x.Action||'').toLowerCase()!==action)return false;\n    if(!q)return true;\n    return [x.PlayerName,x.PlayerUid,x.Rule,x.Action,x.Detail,x.MessagePreview,x.Actor].some(v=>String(v||'').toLowerCase().includes(q));\n  });\n  $('cgRecentRows').innerHTML=filtered.length?filtered.slice(0,100).map(x=>`<tr><td>${esc(chatGuardTime(Number(x.TimestampUtcMs||0)))}</td><td>${esc(x.PlayerName||x.PlayerUid||'—')}</td><td>${esc(x.Rule||'—')}</td><td>${esc(x.Action||'—')}</td><td>${esc(x.Detail||'')}</td><td>${esc(x.MessagePreview||'')}</td></tr>`).join(''):'<tr><td colspan=\"6\" class=\"muted\">No moderation activity matches this filter.</td></tr>';\n}\nfunction renderChatGuardTestResult(test){\n  const host=$('cgTestResult');if(!host)return;\n  if(!test||!test.DryRun){host.innerHTML=chatGuardVersionAtLeast(2,1,1)?'Enter a message and run a dry test.':'Requires ChatGuard 2.1.1+.';return;}\n  const checks=Array.isArray(test.Checks)?test.Checks:[];\n  const summary=test.Matched?`Would match <b>${esc(test.Rule||'—')}</b> → <b>${esc(test.Action||'—')}</b><br>${esc(test.Detail||'')}`:`<b>No enforced match.</b><br>${esc(test.Detail||'')}`;\n  const rows=checks.map(x=>`<div class=\"small\" style=\"margin-top:4px\"><b class=\"${x.Matched?'bad':'good'}\">${x.Matched?'MATCH':'PASS'}</b> · ${esc(x.Rule||'—')} — ${esc(x.Detail||'')}</div>`).join('');\n  host.innerHTML=summary+(test.Exempt?'<br><span class=\"small\">Target is exempt from enforcement.</span>':'')+(rows?`<div style=\"margin-top:10px\">${rows}</div>`:'');\n}\nlet chatGuardTab='moderation';\nfunction setChatGuardTab(tab){\n  chatGuardTab=tab==='banned'?'banned':'moderation';\n  if($('cgMainPanel'))$('cgMainPanel').style.display=chatGuardTab==='moderation'?'':'none';\n  if($('cgBannedPanel'))$('cgBannedPanel').style.display=chatGuardTab==='banned'?'':'none';\n  if($('cgTabModeration'))$('cgTabModeration').classList.toggle('active',chatGuardTab==='moderation');\n  if($('cgTabBanned'))$('cgTabBanned').classList.toggle('active',chatGuardTab==='banned');\n}\nfunction chatGuardBannedTerms(){\n  const c=chatGuardData?.config||{},terms=chatGuardRule(c,'BlockedTerms');\n  return Array.isArray(terms.Terms)?terms.Terms:[];\n}\nfunction syncChatGuardBannedEditor(){\n  const terms=chatGuardRule(chatGuardData?.config||{},'BlockedTerms');\n  if($('cgBannedEnabled'))$('cgBannedEnabled').checked=terms.Enabled!==false;\n  if($('cgBannedAction'))$('cgBannedAction').value=terms.Action||'Block';\n  if($('cgBannedMute'))$('cgBannedMute').value=Number(terms.MuteMinutes||5);\n  renderChatGuardBannedRows();\n}\nfunction renderChatGuardBannedRows(){\n  if(!$('cgBannedRows'))return;\n  const q=String($('cgBannedSearch')?.value||'').trim().toLowerCase();\n  const rows=chatGuardBannedTerms().filter(x=>!q||String(x).toLowerCase().includes(q));\n  $('cgBannedRows').innerHTML=rows.length?rows.map(term=>`<tr><td><code>${esc(term)}</code></td><td><button data-cg-banned-remove=\"${encodeURIComponent(term)}\" ${currentSessionRole==='ReadOnly'?'disabled':''}>Remove</button></td></tr>`).join(''):'<tr><td colspan=\"2\" class=\"muted\">No banned words or phrases match this view.</td></tr>';\n  document.querySelectorAll('[data-cg-banned-remove]').forEach(b=>b.onclick=()=>removeChatGuardBanned(decodeURIComponent(b.dataset.cgBannedRemove||'')));\n}\nfunction addChatGuardBanned(values){\n  if(currentSessionRole==='ReadOnly')return;\n  const c=chatGuardData?.config;if(!c)return;\n  c.BlockedTerms=c.BlockedTerms||{};\n  const existing=Array.isArray(c.BlockedTerms.Terms)?c.BlockedTerms.Terms:[];\n  const map=new Map(existing.map(x=>[String(x).toLowerCase(),String(x)]));\n  values.map(x=>String(x||'').trim()).filter(Boolean).forEach(x=>{if(x.length<=120&&!map.has(x.toLowerCase()))map.set(x.toLowerCase(),x)});\n  c.BlockedTerms.Terms=[...map.values()].slice(0,500);\n  if($('cgTermsList'))$('cgTermsList').value=c.BlockedTerms.Terms.join('\\n');\n  if($('cgBannedAdd'))$('cgBannedAdd').value='';\n  if($('cgBannedBulk'))$('cgBannedBulk').value='';\n  renderChatGuardBannedRows();\n}\nfunction removeChatGuardBanned(term){\n  const c=chatGuardData?.config;if(!c?.BlockedTerms)return;\n  c.BlockedTerms.Terms=(c.BlockedTerms.Terms||[]).filter(x=>String(x).toLowerCase()!==String(term).toLowerCase());\n  if($('cgTermsList'))$('cgTermsList').value=c.BlockedTerms.Terms.join('\\n');\n  renderChatGuardBannedRows();\n}\nfunction applyBannedControlsToMainRule(){\n  if(!chatGuardData?.config)return;\n  const terms=chatGuardData.config.BlockedTerms=chatGuardData.config.BlockedTerms||{};\n  terms.Enabled=!!$('cgBannedEnabled')?.checked;\n  terms.Action=$('cgBannedAction')?.value||'Block';\n  terms.MuteMinutes=Math.max(1,Math.min(10080,Math.round(Number($('cgBannedMute')?.value||5))));\n  if($('cgTermsEnabled'))$('cgTermsEnabled').checked=terms.Enabled;\n  if($('cgTermsAction'))$('cgTermsAction').value=terms.Action;\n  if($('cgTermsMute'))$('cgTermsMute').value=terms.MuteMinutes;\n  if($('cgTermsList'))$('cgTermsList').value=(terms.Terms||[]).join('\\n');\n}\n\nfunction renderChatGuard(){\n  const d=chatGuardData||{};\n  const c=d.config||{};\n  if(!$('cgState'))return;\n  const available=!!d.available;\n  const supports211=chatGuardVersionAtLeast(2,1,1);\n  const supportsTester=chatGuardVersionAtLeast(2,1,1);\n  const warningsList=Array.isArray(d.warnings)?d.warnings:[];\n  const warnedPlayers=warningsList.filter(x=>Number(x.ActiveWarnings||0)>0).length;\n  $('cgState').textContent=available?`ChatGuard ${d.version||''} · ${d.enabled?'Enabled':'Disabled'} · ${d.mode||'—'}`:'Standalone ChatGuard is not installed.';\n  if(available&&(d.stateStorageError||d.auditStorageError||Number(d.auditDroppedEntries||0)>0))$('cgState').textContent+=' · '+[d.stateStorageError,d.auditStorageError,Number(d.auditDroppedEntries||0)>0?`${Number(d.auditDroppedEntries)} audit entry(s) dropped`:null].filter(Boolean).join(' · ');\n  setNavStatus('chatguard',!available?'neutral':(!d.enabled?'neutral':(String(d.mode).toLowerCase()==='logonly'?'warn':'good')),!available?'Standalone ChatGuard not installed':`${d.enabled?'Enabled':'Disabled'} · ${d.mode||'—'}`);\n  setNavBadge('chatguard',Number(d.activeMutes||0)+warnedPlayers,(Number(d.activeMutes||0)+warnedPlayers)>0?'attention':'info',`${Number(d.activeMutes||0)} active mute(s) · ${warnedPlayers} warned player(s)`);\n  $('cgMetrics').innerHTML=\n    metric('Module',available?`v${d.version||'?'}`:'Not installed',available?'good':'')+\n    metric('Mode',available?(d.enabled?(d.mode||'—'):'Disabled'):'—',available&&d.enabled?(String(d.mode).toLowerCase()==='logonly'?'warn':'good'):'')+\n    metric('Scanned',Number(d.scannedMessages||0).toLocaleString())+\n    metric('Rule matches',Number(d.matchedRules||0).toLocaleString(),Number(d.matchedRules||0)>0?'warn':'')+\n    metric('Blocked',Number(d.blockedMessages||0).toLocaleString(),Number(d.blockedMessages||0)>0?'warn':'')+\n    metric('Warnings issued',Number(d.warningsIssued||0).toLocaleString())+\n    metric('Warned players',warnedPlayers,warnedPlayers>0?'warn':'good')+\n    metric('Mutes issued',Number(d.mutesIssued||0).toLocaleString())+\n    metric('Active mutes',Number(d.activeMutes||0),Number(d.activeMutes||0)>0?'warn':'good');\n  if(!available){$('cgUnavailable').style.display='block';return;}else $('cgUnavailable').style.display='none';\n\n  $('cgEnabled').checked=c.Enabled!==false;\n  $('cgMode').value=c.Mode||'Enforce';\n  $('cgNotify').checked=c.NotifyPlayers!==false;\n  $('cgPrefix').value=c.NotificationPrefix||'[ChatGuard]';\n  $('cgExemptRoles').value=Array.isArray(c.ExemptRoleCodes)?c.ExemptRoleCodes.join(', '):'';\n  $('cgExemptUids').value=Array.isArray(c.ExemptPlayerUids)?c.ExemptPlayerUids.join('\\n'):'';\n  $('cgAuditPreview').value=Number(c.AuditMessagePreviewCharacters??160);\n\n  const spam=chatGuardRule(c,'Spam');setChatGuardRule('cgSpam',spam);$('cgSpamMax').value=Number(spam.MaxMessages||5);$('cgSpamWindow').value=Number(spam.WindowSeconds||4);\n  const repeat=chatGuardRule(c,'Repeat');setChatGuardRule('cgRepeat',repeat);$('cgRepeatMax').value=Number(repeat.MaxRepeats||3);$('cgRepeatWindow').value=Number(repeat.WindowSeconds||20);\n  const caps=chatGuardRule(c,'Caps');setChatGuardRule('cgCaps',caps);$('cgCapsLetters').value=Number(caps.MinLetters||12);$('cgCapsPercent').value=Number(caps.MaxUppercasePercent||75);\n  const links=chatGuardRule(c,'Links');setChatGuardRule('cgLinks',links);$('cgLinksAllowed').value=Array.isArray(links.AllowedDomains)?links.AllowedDomains.join('\\n'):'';\n  const mentions=chatGuardRule(c,'Mentions');setChatGuardRule('cgMentions',mentions);$('cgMentionsMax').value=Number(mentions.MaxMentions||5);\n  const length=chatGuardRule(c,'Length');setChatGuardRule('cgLength',length);$('cgLengthMax').value=Number(length.MaxCharacters||500);\n  const terms=chatGuardRule(c,'BlockedTerms');setChatGuardRule('cgTerms',terms);$('cgTermsList').value=Array.isArray(terms.Terms)?terms.Terms.join('\\n'):'';\n  syncChatGuardBannedEditor();\n  setChatGuardTab(chatGuardTab);\n  const escalation=c.Escalation||{};$('cgEscalationEnabled').checked=escalation.Enabled!==false;$('cgEscalationWindow').value=Number(escalation.WarningWindowMinutes||60);$('cgEscalationWarnings').value=Number(escalation.WarningsBeforeMute||3);$('cgEscalationMute').value=Number(escalation.MuteMinutes||10);\n\n  const hitMap={cgHitSpam:'Spam',cgHitRepeat:'Repeat',cgHitCaps:'Caps',cgHitLinks:'Link',cgHitMentions:'MentionSpam',cgHitLength:'MessageLength',cgHitTerms:'BlockedTerm'};\n  Object.entries(hitMap).forEach(([id,rule])=>{if($(id))$(id).textContent=chatGuardRuleHit(rule).toLocaleString();});\n  const stats=Array.isArray(d.ruleStats)?d.ruleStats:[];\n  const hot=stats.slice().sort((a,b)=>Number(b.Matches||0)-Number(a.Matches||0)).filter(x=>Number(x.Matches||0)>0).slice(0,4);\n  if($('cgRuleHits'))$('cgRuleHits').innerHTML=hot.length?`Top session hits: ${hot.map(x=>`<b>${esc(x.Rule||'Rule')}</b> ${Number(x.Matches||0).toLocaleString()}`).join(' · ')}`:'No rule matches recorded this session.';\n  const posture=!d.enabled?'Disabled':String(d.mode||'').toLowerCase()==='logonly'?'Observe only':'Enforcing';\n  if($('cgPostureChip')){$('cgPostureChip').textContent=posture;$('cgPostureChip').className='badge '+(!d.enabled?'':String(d.mode||'').toLowerCase()==='logonly'?'warn':'good');}\n  if($('cgPosture'))$('cgPosture').innerHTML=!d.enabled?'<b>Moderation is disabled.</b> ChatGuard will not automatically process rule actions.':String(d.mode||'').toLowerCase()==='logonly'?'<b>LogOnly mode.</b> Rule matches are observed and audited, but automatic sanctions are not enforced.':'<b>Enforce mode.</b> Enabled rules can block, warn, mute, or kick according to their configured actions.';\n  const online=Array.isArray(d.onlinePlayers)?d.onlinePlayers:[];\n  if($('cgOnlinePlayers'))$('cgOnlinePlayers').innerHTML=online.map(x=>`<option value=\"${esc(x.PlayerName||'')}\">${esc((x.Role||'')+(x.Exempt?' · exempt':''))}</option>`).join('');\n  renderChatGuardTestResult(d.test);\n  renderChatGuardRecent();\n\n  const mutes=Array.isArray(d.mutes)?d.mutes:[];\n  $('cgMuteRows').innerHTML=mutes.length?mutes.map(x=>{\n    const duration=x.Permanent?'Permanent':chatGuardTime(Number(x.ExpiresUtcMs||0));\n    return `<tr><td>${esc(x.PlayerName||x.PlayerUid||'—')}<br><span class=\"small\"><code>${esc(x.PlayerUid||'')}</code></span></td><td class=\"${x.Permanent?'bad':''}\"><b>${esc(duration)}</b></td><td>${esc(x.Reason||'')}</td><td>${esc(x.Actor||'')}</td><td><button class=\"smallButton\" data-cg-unmute=\"${esc(x.PlayerUid||'')}\" data-cg-name=\"${esc(x.PlayerName||'')}\">Unmute</button></td></tr>`;\n  }).join(''):'<tr><td colspan=\"5\" class=\"muted\">No active ChatGuard mutes.</td></tr>';\n\n  const warningWindow=Number(escalation.WarningWindowMinutes||60);\n  const warningThreshold=Number(escalation.WarningsBeforeMute||3);\n  $('cgWarningRows').innerHTML=warningsList.length?warningsList.filter(x=>Number(x.ActiveWarnings||0)>0).map(x=>{\n    const times=Array.isArray(x.WarningUtcMs)?x.WarningUtcMs.map(Number).filter(Number.isFinite):[];\n    const oldest=times.length?Math.min(...times):0;\n    const expires=oldest?oldest+warningWindow*60000:0;\n    return `<tr><td>${esc(x.PlayerName||x.PlayerUid||'—')}<br><span class=\"small\"><code>${esc(x.PlayerUid||'')}</code></span></td><td><b>${Number(x.ActiveWarnings||0)}/${warningThreshold}</b></td><td>${warningWindow} min</td><td>${esc(expires?chatGuardTime(expires):'—')}</td><td>${supports211?`<button class=\"smallButton\" data-cg-clearwarnings=\"${esc(x.PlayerUid||'')}\" data-cg-name=\"${esc(x.PlayerName||'')}\">Clear</button>`:'<span class=\"small\">Requires ChatGuard 2.1.1+</span>'}</td></tr>`;\n  }).join(''):'<tr><td colspan=\"5\" class=\"muted\">No active ChatGuard warnings.</td></tr>';\n\n  document.querySelectorAll('[data-cg-unmute]').forEach(btn=>btn.onclick=()=>{\n    const reason=window.prompt('Reason for unmuting this player:','Manual staff unmute');\n    if(reason===null)return;\n    chatGuardAction('unmute',btn.dataset.cgUnmute||'',btn.dataset.cgName||'',0,reason,false);\n  });\n  document.querySelectorAll('[data-cg-clearwarnings]').forEach(btn=>btn.onclick=()=>{\n    const reason=window.prompt('Reason for clearing this player\\'s warnings:','Manual warning reset');\n    if(reason===null)return;\n    chatGuardAction('clearwarnings',btn.dataset.cgClearwarnings||'',btn.dataset.cgName||'',0,reason,false);\n  });\n  const ro=currentSessionRole==='ReadOnly';\n  document.querySelectorAll('#chatguard input,#chatguard select,#chatguard textarea,#chatguard button').forEach(el=>{if(el.id!=='cgRefresh'&&el.id!=='cgManualInspect')el.disabled=ro;});\n  $('cgRefresh').disabled=false;\n  $('cgManualInspect').disabled=false;\n  if($('cgManualPermanent')){\n    $('cgManualPermanent').disabled=ro||!supports211;\n    $('cgManualPermanent').title=supports211?'Permanent mute supported by ChatGuard 2.1.1+.':'Update ChatGuard to 2.1.1+ for permanent mutes from the Suite WebPanel.';\n  }\n  if($('cgTestRun')){$('cgTestRun').disabled=ro||!supportsTester;$('cgTestRun').title=supportsTester?'Dry-run the current rules without changing state.':'ChatGuard 2.1.1+ supports the Rule Tester.';}\n}\nfunction inspectChatGuardTarget(){\n  const target=String($('cgManualTarget')?.value||'').trim();\n  const host=$('cgManualInfo');\n  if(!host)return;\n  if(!target){host.innerHTML='<b>Enter a player name or UID.</b>';return;}\n  const key=target.toLowerCase();\n  const mutes=Array.isArray(chatGuardData?.mutes)?chatGuardData.mutes:[];\n  const warnings=Array.isArray(chatGuardData?.warnings)?chatGuardData.warnings:[];\n  const mute=mutes.find(x=>String(x.PlayerUid||'').toLowerCase()===key||String(x.PlayerName||'').toLowerCase()===key);\n  const warning=warnings.find(x=>String(x.PlayerUid||'').toLowerCase()===key||String(x.PlayerName||'').toLowerCase()===key);\n  const c=chatGuardData?.config||{}, escalation=c.Escalation||{};\n  const name=mute?.PlayerName||warning?.PlayerName||target;\n  const uid=mute?.PlayerUid||warning?.PlayerUid||'No retained ChatGuard record';\n  const muteText=mute?(mute.Permanent?`Permanent — ${mute.Reason||'no reason'}`:`Until ${chatGuardTime(Number(mute.ExpiresUtcMs||0))} — ${mute.Reason||'no reason'}`):'None';\n  const wc=Number(warning?.ActiveWarnings||0);\n  host.innerHTML=`<b>${esc(name)}</b><br><span class=\"small\">UID: <code>${esc(uid)}</code></span><br>Mute: <b>${esc(muteText)}</b><br>Warnings: <b>${wc}/${Number(escalation.WarningsBeforeMute||3)}</b> active in a ${Number(escalation.WarningWindowMinutes||60)} minute window.${!mute&&!warning?'<br><span class=\"small\">No active/persisted ChatGuard sanction is present for this lookup. New warns/mutes still require the player online.</span>':''}`;\n}\n\nfunction buildChatGuardConfig(){\n  const base=JSON.parse(JSON.stringify(chatGuardData?.config||{}));\n  base.SchemaVersion=1;base.Enabled=!!$('cgEnabled').checked;base.Mode=$('cgMode').value;base.NotifyPlayers=!!$('cgNotify').checked;base.NotificationPrefix=$('cgPrefix').value||'[ChatGuard]';base.ExemptRoleCodes=chatGuardLines($('cgExemptRoles').value);base.ExemptPlayerUids=chatGuardLines($('cgExemptUids').value);base.AuditMessagePreviewCharacters=Number($('cgAuditPreview').value||0);\n  const rule=(prefix,extra={})=>Object.assign({Enabled:!!$(prefix+'Enabled').checked,Action:$(prefix+'Action').value,MuteMinutes:Number($(prefix+'Mute').value||5)},extra);\n  base.Spam=rule('cgSpam',{MaxMessages:Number($('cgSpamMax').value||5),WindowSeconds:Number($('cgSpamWindow').value||4)});\n  base.Repeat=rule('cgRepeat',{MaxRepeats:Number($('cgRepeatMax').value||3),WindowSeconds:Number($('cgRepeatWindow').value||20)});\n  base.Caps=rule('cgCaps',{MinLetters:Number($('cgCapsLetters').value||12),MaxUppercasePercent:Number($('cgCapsPercent').value||75)});\n  base.Links=rule('cgLinks',{AllowedDomains:chatGuardLines($('cgLinksAllowed').value)});\n  base.Mentions=rule('cgMentions',{MaxMentions:Number($('cgMentionsMax').value||5)});\n  base.Length=rule('cgLength',{MaxCharacters:Number($('cgLengthMax').value||500)});\n  base.BlockedTerms=rule('cgTerms',{Terms:chatGuardLines($('cgTermsList').value)});\n  base.Escalation={Enabled:!!$('cgEscalationEnabled').checked,WarningWindowMinutes:Number($('cgEscalationWindow').value||60),WarningsBeforeMute:Number($('cgEscalationWarnings').value||3),MuteMinutes:Number($('cgEscalationMute').value||10)};\n  return base;\n}\nasync function loadChatGuard(showLoading=true){\n  if(showLoading&&$('cgState'))$('cgState').textContent='Loading…';\n  try{chatGuardData=await api('/api/chatguard');renderChatGuard();}\n  catch(e){if($('cgState'))$('cgState').textContent=e.message;if(showLoading)toast(e.message,'error');}\n}\nasync function saveChatGuard(){\n  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot change ChatGuard settings.','error');return;}\n  try{chatGuardData=await api('/api/chatguard/settings',{method:'POST',body:JSON.stringify(buildChatGuardConfig())});renderChatGuard();toast(chatGuardData.message||'ChatGuard settings saved.','success');}\n  catch(e){toast(e.message,'error');}\n}\nasync function testChatGuard(){\n  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot run the ChatGuard tester.','error');return;}\n  if(!chatGuardVersionAtLeast(2,1,1)){toast('The Rule Tester requires ChatGuard 2.1.1 or newer.','error');return;}\n  const message=String($('cgTestMessage')?.value||'');\n  const targetName=String($('cgTestTarget')?.value||'').trim();\n  if(!message.trim()){toast('Enter a message to test.','error');return;}\n  try{chatGuardData=await api('/api/chatguard/test',{method:'POST',body:JSON.stringify({targetName,message})});renderChatGuard();toast('ChatGuard dry-run complete.','success');}\n  catch(e){toast(e.message,'error');}\n}\nasync function chatGuardAction(action,targetUid='',targetName='',minutes=0,reason='',permanent=false){\n  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot run ChatGuard actions.','error');return;}\n  if((permanent||action==='clearwarnings')&&!chatGuardVersionAtLeast(2,1,1)){toast('This action requires ChatGuard 2.1.1 or newer.','error');return;}\n  try{\n    chatGuardData=await api('/api/chatguard/action',{method:'POST',body:JSON.stringify({action,targetUid,targetName,minutes,reason,permanent})});\n    renderChatGuard();\n    inspectChatGuardTarget();\n    toast(chatGuardData.message||'ChatGuard action completed.','success');\n  }catch(e){toast(e.message,'error');}\n}\n\n\n\nfunction chatLayoutPreview(){\n const format=$('chatDisplayLayout').value,counts={role:0,name:0,timestamp:0,message:0};let error='';\n const values={role:$('chatDisplayRole').checked?'[Player]':'',name:'ExamplePlayer',timestamp:$('chatDisplayTimestamp').checked?'['+($('chatDisplayTimestampFormat').value||'HH:mm')+']':'',message:'Hello world'};\n const text=format.replace(/\\{([^{}]*)\\}( ?)/g,(whole,key,space)=>{if(!(key in counts)){error='Unknown placeholder: '+key;return whole;}counts[key]++;return values[key]+(!values[key]&&['role','timestamp'].includes(key)?'':space);});\n if(counts.name!==1||counts.message!==1||Object.values(counts).some(n=>n>1)||/[{}]/.test(text))error='Use name and message once; optional role and timestamp once.';\n if(/[\\r\\n\\t]/.test(format)||format.trimStart().startsWith('/'))error='Use a single line without a leading slash.';\n $('chatLayoutError').textContent=error;$('chatDisplayPreview').textContent='Preview: '+text;\n}\nlet chatDisplayData=null;\nfunction renderChatDisplay(){\n  const d=chatDisplayData||{};\n  if(!$('chatDisplayState'))return;\n  $('chatDisplayState').textContent=d.available===false?'Service unavailable':'Live settings loaded';\n  $('chatMarkdownEnabled').checked=d.markdownEnabled!==false;\n  $('chatMarkdownColors').checked=!!d.markdownAllowColors;\n  $('chatMarkdownLinks').checked=!!d.markdownAllowLinks;\n  $('chatMarkdownRoles').value=Array.isArray(d.markdownAllowedRoleCodes)?d.markdownAllowedRoleCodes.join(', '):'';\n  $('chatDisplayRole').checked=!!d.showRoleBeforeName;\n  $('chatDisplayBoldName').checked=!!d.boldPlayerName;\n  $('chatDisplayTimestamp').checked=!!d.showTimestampBeforeMessage;\n  $('chatDisplayLayout').value=d.chatFormat||'{role} {name}: {timestamp} {message}';\n  $('chatDisplayTimestampFormat').value=d.timestampFormat||'HH:mm';\n  $('chatDisplayUtc').checked=!!d.useUtcTimestamp;\n  $('chatDisplayGeneral').checked=d.formatGeneralChat!==false;\n  $('chatDisplayOtherGroups').checked=!!d.formatOtherChatGroups;\n  $('chatDisplayAdditionalGroups').value=Array.isArray(d.additionalFormattedChatGroupIds)?d.additionalFormattedChatGroupIds.join(', '):'';\n  $('chatDisplayUseRoleColors').checked=!!d.useRoleNameColors;\n  $('chatDisplayRoleColors').value=roleColorMapToText(d.roleNameColors);\n  renderChatDisplayRoleColorPreview();\n  $('chatDisplayPreview').textContent='Preview: '+(d.preview||'ExamplePlayer: Hello world');\n  $('chatLayoutError').textContent='';\n  const extraGroups=Array.isArray(d.additionalFormattedChatGroupIds)?d.additionalFormattedChatGroupIds:[];\n  $('chatDisplayMetrics').innerHTML=\n    metric('Message Markdown',d.markdownEnabled!==false?'ON':'OFF',d.markdownEnabled!==false?'good':'')+\n    metric('General chat',d.formatGeneralChat!==false?'FORMATTED':'PASS-THROUGH',d.formatGeneralChat!==false?'good':'')+\n    metric('All other groups',d.formatOtherChatGroups?'FORMATTED':'PASS-THROUGH',d.formatOtherChatGroups?'warn':'good')+\n    metric('Specific extra groups',extraGroups.length?extraGroups.join(', '):'None')+\n    metric('Role prefix',d.showRoleBeforeName?'ON':'OFF',d.showRoleBeforeName?'good':'')+\n    metric('Role name colors',d.useRoleNameColors?`${Object.keys(d.roleNameColors||{}).length} OVERRIDES`:'OFF',d.useRoleNameColors?'good':'')+\n    metric('Bold player name',d.boldPlayerName?'ON':'OFF',d.boldPlayerName?'good':'')+\n    metric('Timestamp',d.showTimestampBeforeMessage?'ON':'OFF',d.showTimestampBeforeMessage?'good':'')+\n    metric('Timezone',d.useUtcTimestamp?'UTC':'Server local')+\n    metric('Format',d.timestampFormat||'HH:mm');\n  const ro=currentSessionRole==='ReadOnly';\n  ['chatDisplayLayout','chatLayoutDefault','chatLayoutTimeFirst','chatLayoutTimeAfterName','chatMarkdownEnabled','chatMarkdownColors','chatMarkdownLinks','chatMarkdownRoles','chatDisplayRole','chatDisplayBoldName','chatDisplayTimestamp','chatDisplayTimestampFormat','chatDisplayUtc','chatDisplayGeneral','chatDisplayOtherGroups','chatDisplayAdditionalGroups','chatDisplayUseRoleColors','chatDisplayRoleColors','chatDisplaySave'].forEach(id=>{const e=$(id);if(e)e.disabled=ro||d.available===false;});\n}\nasync function loadChatDisplay(showLoading=true){\n  if(showLoading&&$('chatDisplayState'))$('chatDisplayState').textContent='Loading…';\n  try{chatDisplayData=await api('/api/chat-display');renderChatDisplay();}\n  catch(e){if($('chatDisplayState'))$('chatDisplayState').textContent=e.message;if(showLoading)toast(e.message,'error');}\n}\nasync function saveChatDisplay(){\n  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot change chat display settings.','error');return;}\n  const payload={\n    markdownEnabled:!!$('chatMarkdownEnabled').checked,\n    markdownAllowColors:!!$('chatMarkdownColors').checked,\n    markdownAllowLinks:!!$('chatMarkdownLinks').checked,\n    markdownAllowedRoleCodes:($('chatMarkdownRoles').value||'').split(/[,;\\s]+/).filter(Boolean),\n    chatFormat:$('chatDisplayLayout').value,\n    showRoleBeforeName:!!$('chatDisplayRole').checked,\n    boldPlayerName:!!$('chatDisplayBoldName').checked,\n    showTimestampBeforeMessage:!!$('chatDisplayTimestamp').checked,\n    timestampFormat:$('chatDisplayTimestampFormat').value||'HH:mm',\n    useUtcTimestamp:!!$('chatDisplayUtc').checked,\n    formatGeneralChat:!!$('chatDisplayGeneral').checked,\n    formatOtherChatGroups:!!$('chatDisplayOtherGroups').checked,\n    additionalFormattedChatGroupIds:($('chatDisplayAdditionalGroups').value||'').split(/[;,\\s]+/).map(v=>Number(v)).filter(v=>Number.isInteger(v)&&v>=0),\n    useRoleNameColors:!!$('chatDisplayUseRoleColors').checked,\n    roleNameColors:parseRoleColorMap($('chatDisplayRoleColors').value||''),\n    roleColorRevision:chatDisplayData?.roleColorRevision\n  };\n  try{\n    const d=await api('/api/chat-display/settings',{method:'POST',body:JSON.stringify(payload)});\n    chatDisplayData=d.chatDisplay||chatDisplayData;\n    renderChatDisplay();toast(d.message||'Chat display settings saved.','success');\n  }catch(e){toast(e.message,'error');}\n}\n\n\n\nlet suiteCustomizationData=null,suiteCustomizationDirty=false,suiteCustomizationBusy=false;\nconst SUITE_CUSTOMIZATION_DEFAULTS={\n  panelName:\"Newfie's Server Suite\",headerSubtitle:'WebPanel',loginKicker:'Secure Administration Console',\n  loginSubtitle:'Remote server administration. Fresh installs on 127.0.0.1 enter automatically without a login.',\n  dashboardTitle:'Server Dashboard',\n  dashboardSubtitle:'Actionable server and Suite overview: what needs attention, current operations state, health evidence, and recent lag.',\n  searchPlaceholder:'Search Server Essentials Suite…',sidebarFooterText:\"Newfie's Server Suite · Server Administration\",\n  surfaceTexture:'slate',textureStrength:12,showModuleIcons:true,highContrastBorders:false,theme:'original',backgroundHex:'#101820',panelHex:'#192631',textHex:'#E3EDF5',logoUrl:'',reduceMotion:false,accentHex:'#69AEFA',showBuildId:true,showHeaderLogo:true,compactLayout:false,sidebarWidth:232,cardRadius:14,\n  showStatusBar:true,showModuleStatus:true,showDashboardAttention:true,showDashboardOperations:true\n};\nfunction normalizeAccentHex(value){\n  const v=String(value||'').trim().toUpperCase();\n  return /^#[0-9A-F]{6}$/.test(v)?v:SUITE_CUSTOMIZATION_DEFAULTS.accentHex;\n}\nfunction applySuiteCustomization(d,updateForm=false){\n  const c=Object.assign({},SUITE_CUSTOMIZATION_DEFAULTS,d||{});\n  c.accentHex=normalizeAccentHex(c.accentHex);\n  c.sidebarWidth=clamp(Number(c.sidebarWidth)||232,190,320);\n  c.cardRadius=clamp(Number(c.cardRadius??14),0,24);\n  document.documentElement.style.setProperty('--accent',c.accentHex);\n  document.documentElement.style.setProperty('--suite-sidebar-width',`${c.sidebarWidth}px`);\n  document.documentElement.style.setProperty('--radius-md',`${c.cardRadius}px`);\n  document.documentElement.style.setProperty('--radius-lg',`${Math.min(30,c.cardRadius+4)}px`);\n  const palettes={forest:['#101B16','#1B2E24','#E5F0E6'],slate:['#151821','#252B3B','#E9EDFA']};\n  const palette=palettes[c.theme]||[c.backgroundHex,c.panelHex,c.textHex];\n  ['--suite-bg','--suite-panel','--suite-text'].forEach((key,i)=>document.documentElement.style.setProperty(key,normalizeAccentHex(palette[i])));\n  document.body.classList.toggle('suiteThemed',c.theme!=='original');\n  document.body.dataset.suiteTexture=['none','slate','brushed'].includes(c.surfaceTexture)?c.surfaceTexture:'slate';\n  document.documentElement.style.setProperty('--suite-grain',String(clamp(Number(c.textureStrength)||0,0,25)/100));\n  document.body.classList.toggle('suiteNoIcons',c.showModuleIcons===false);\n  document.body.classList.toggle('suiteContrast',!!c.highContrastBorders);\n  document.body.classList.toggle('suiteReducedMotion',!!c.reduceMotion);\n  document.querySelectorAll('.loginBrandImage,.headerBrand img').forEach(img=>{if(!img.dataset.originalSrc)img.dataset.originalSrc=img.src;const v=String(c.logoUrl||'');img.src=(/^https:\\/\\//i.test(v)||v.startsWith('/')&&!v.startsWith('//')&&!v.includes('\\\\'))?v:img.dataset.originalSrc;img.onerror=()=>{img.onerror=null;img.src=img.dataset.originalSrc;};});\n  document.body.classList.toggle('suiteCompact',!!c.compactLayout);\n  document.body.classList.toggle('suiteHideStatus',c.showStatusBar===false);\n  document.body.classList.toggle('suiteHideModuleStatus',c.showModuleStatus===false);\n  document.body.classList.toggle('suiteHideHeaderLogo',c.showHeaderLogo===false);\n  document.title=c.panelName;\n  if($('suiteBrandName'))$('suiteBrandName').textContent=c.panelName;\n  if($('suiteHeaderSubtitle'))$('suiteHeaderSubtitle').textContent=c.headerSubtitle;\n  if($('suiteHeaderTitle'))$('suiteHeaderTitle').textContent=c.panelName;\n  if($('suiteLoginKicker'))$('suiteLoginKicker').textContent=c.loginKicker;\n  const loginSubtitle=document.querySelector('#loginView [data-login-subtitle]');if(loginSubtitle)loginSubtitle.textContent=c.loginSubtitle;\n  if($('suiteDashboardTitle'))$('suiteDashboardTitle').textContent=c.dashboardTitle;\n  if($('suiteDashboardSubtitle'))$('suiteDashboardSubtitle').textContent=c.dashboardSubtitle;\n  if($('suiteSidebarFooter'))$('suiteSidebarFooter').textContent=c.sidebarFooterText;\n  if($('commandOpen')&&$('commandOpen').childNodes.length)$('commandOpen').childNodes[0].nodeValue=`⌕ ${c.searchPlaceholder} `;\n  if($('commandInput'))$('commandInput').placeholder=c.searchPlaceholder;\n  if($('dashboardAttentionCard'))$('dashboardAttentionCard').style.display=c.showDashboardAttention===false?'none':'';\n  if($('dashboardOperationsCard'))$('dashboardOperationsCard').style.display=c.showDashboardOperations===false?'none':'';\n  const mobile=document.querySelector('.mobileNavHead span'); if(mobile)mobile.textContent=c.panelName;\n  const crumb=document.querySelector('#breadcrumbBar > span:first-child'); if(crumb)crumb.textContent=c.panelName;\n  if(updateForm){\n    for(const [id,key] of Object.entries({suiteCustomizationTheme:'theme',suiteCustomizationBackground:'backgroundHex',suiteCustomizationPanel:'panelHex',suiteCustomizationText:'textHex',suiteCustomizationLogoUrl:'logoUrl'}))if($(id))$(id).value=c[key];\n    $('suiteCustomizationTexture').value=c.surfaceTexture;\n    $('suiteCustomizationTextureStrength').value=c.textureStrength;\n    $('suiteCustomizationIcons').checked=c.showModuleIcons!==false;\n    $('suiteCustomizationContrast').checked=!!c.highContrastBorders;\n    $('suiteCustomizationReduceMotion').checked=!!c.reduceMotion;\n    if($('suiteCustomizationPanelName'))$('suiteCustomizationPanelName').value=c.panelName;\n    if($('suiteCustomizationHeaderSubtitle'))$('suiteCustomizationHeaderSubtitle').value=c.headerSubtitle;\n    if($('suiteCustomizationLoginKicker'))$('suiteCustomizationLoginKicker').value=c.loginKicker;\n    if($('suiteCustomizationLoginSubtitle'))$('suiteCustomizationLoginSubtitle').value=c.loginSubtitle;\n    if($('suiteCustomizationDashboardTitle'))$('suiteCustomizationDashboardTitle').value=c.dashboardTitle;\n    if($('suiteCustomizationDashboardSubtitle'))$('suiteCustomizationDashboardSubtitle').value=c.dashboardSubtitle;\n    if($('suiteCustomizationSearchPlaceholder'))$('suiteCustomizationSearchPlaceholder').value=c.searchPlaceholder;\n    if($('suiteCustomizationSidebarFooter'))$('suiteCustomizationSidebarFooter').value=c.sidebarFooterText;\n    if($('suiteCustomizationAccent'))$('suiteCustomizationAccent').value=c.accentHex.toLowerCase();\n    if($('suiteCustomizationAccentText'))$('suiteCustomizationAccentText').value=c.accentHex;\n    if($('suiteCustomizationShowBuild'))$('suiteCustomizationShowBuild').checked=c.showBuildId!==false;\n    if($('suiteCustomizationHeaderLogo'))$('suiteCustomizationHeaderLogo').checked=c.showHeaderLogo!==false;\n    if($('suiteCustomizationCompact'))$('suiteCustomizationCompact').checked=!!c.compactLayout;\n    if($('suiteCustomizationSidebarWidth'))$('suiteCustomizationSidebarWidth').value=c.sidebarWidth;\n    if($('suiteCustomizationCardRadius'))$('suiteCustomizationCardRadius').value=c.cardRadius;\n    if($('suiteCustomizationStatusBar'))$('suiteCustomizationStatusBar').checked=c.showStatusBar!==false;\n    if($('suiteCustomizationModuleStatus'))$('suiteCustomizationModuleStatus').checked=c.showModuleStatus!==false;\n    if($('suiteCustomizationAttention'))$('suiteCustomizationAttention').checked=c.showDashboardAttention!==false;\n    if($('suiteCustomizationOperations'))$('suiteCustomizationOperations').checked=c.showDashboardOperations!==false;\n  }\n  if($('suiteCustomizationPreview')){\n    const build=(c.showBuildId!==false&&c.buildId)?`<br><span class=\"small\">Build: <code>${esc(c.buildId)}</code></span>`:'';\n    const mode=c.compactLayout?'Compact':'Standard';\n    $('suiteCustomizationPreview').innerHTML=`<b>${esc(c.panelName)}</b> <span class=\"badge low\">${esc(c.headerSubtitle)}</span><br>${esc(c.dashboardTitle)} — ${esc(c.dashboardSubtitle)}<br><span class=\"small\">${esc(mode)} layout · ${c.sidebarWidth}px sidebar · ${c.cardRadius}px cards</span>${build}`;\n  }\n}\nfunction readSuiteCustomizationForm(){\n  return {\n    surfaceTexture:$('suiteCustomizationTexture').value,textureStrength:Number($('suiteCustomizationTextureStrength').value),showModuleIcons:$('suiteCustomizationIcons').checked,highContrastBorders:$('suiteCustomizationContrast').checked,\n    theme:$('suiteCustomizationTheme').value,backgroundHex:$('suiteCustomizationBackground').value,panelHex:$('suiteCustomizationPanel').value,textHex:$('suiteCustomizationText').value,logoUrl:$('suiteCustomizationLogoUrl').value.trim(),reduceMotion:$('suiteCustomizationReduceMotion').checked,\n    panelName:String($('suiteCustomizationPanelName')?.value||SUITE_CUSTOMIZATION_DEFAULTS.panelName).trim(),\n    headerSubtitle:String($('suiteCustomizationHeaderSubtitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.headerSubtitle).trim(),\n    loginKicker:String($('suiteCustomizationLoginKicker')?.value||SUITE_CUSTOMIZATION_DEFAULTS.loginKicker).trim(),\n    loginSubtitle:String($('suiteCustomizationLoginSubtitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.loginSubtitle).trim(),\n    dashboardTitle:String($('suiteCustomizationDashboardTitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.dashboardTitle).trim(),\n    dashboardSubtitle:String($('suiteCustomizationDashboardSubtitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.dashboardSubtitle).trim(),\n    searchPlaceholder:String($('suiteCustomizationSearchPlaceholder')?.value||SUITE_CUSTOMIZATION_DEFAULTS.searchPlaceholder).trim(),\n    sidebarFooterText:String($('suiteCustomizationSidebarFooter')?.value||SUITE_CUSTOMIZATION_DEFAULTS.sidebarFooterText).trim(),\n    accentHex:normalizeAccentHex($('suiteCustomizationAccentText')?.value||$('suiteCustomizationAccent')?.value),\n    showBuildId:$('suiteCustomizationShowBuild')?.checked!==false,\n    showHeaderLogo:$('suiteCustomizationHeaderLogo')?.checked!==false,\n    compactLayout:!!$('suiteCustomizationCompact')?.checked,\n    sidebarWidth:clamp(Number($('suiteCustomizationSidebarWidth')?.value||232),190,320),\n    cardRadius:clamp(Number($('suiteCustomizationCardRadius')?.value??14),0,24),\n    showStatusBar:$('suiteCustomizationStatusBar')?.checked!==false,\n    showModuleStatus:$('suiteCustomizationModuleStatus')?.checked!==false,\n    showDashboardAttention:$('suiteCustomizationAttention')?.checked!==false,\n    showDashboardOperations:$('suiteCustomizationOperations')?.checked!==false\n  };\n}\nfunction previewSuiteCustomization(){\n  if(suiteCustomizationBusy)return;\n  suiteCustomizationDirty=true;\n  if($('suiteCustomizationState'))$('suiteCustomizationState').textContent='Unsaved preview — save or reload to discard';\n  const c=readSuiteCustomizationForm();\n  c.buildId=suiteCustomizationData?.buildId||'';\n  applySuiteCustomization(c,false);\n}\nasync function loadSuiteCustomization(showLoading=true){\n  if(suiteCustomizationBusy)return;\n  if(suiteCustomizationDirty&&currentSection==='customization')return;\n\n  if(showLoading&&$('suiteCustomizationState'))$('suiteCustomizationState').textContent='Loading…';\n  try{\n    suiteCustomizationData=await api('/api/customization');suiteCustomizationDirty=false;\n    applySuiteCustomization(suiteCustomizationData,true);\n    if($('suiteCustomizationState'))$('suiteCustomizationState').textContent='Live customization loaded';\n    const ro=currentSessionRole==='ReadOnly';\n    document.querySelectorAll('#customization input,#customization textarea,#customization select,#customization button').forEach(e=>{if(e.id!=='suiteCustomizationRefresh')e.disabled=ro;});\n    if($('suiteCustomizationRefresh'))$('suiteCustomizationRefresh').disabled=false;\n  }catch(e){if($('suiteCustomizationState'))$('suiteCustomizationState').textContent=e.message;if(showLoading)toast(e.message,'error');}\n}\nasync function saveSuiteCustomization(){\n  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot change Suite customization.','error');return;}\n  if(suiteCustomizationBusy)return;\n  const payload=readSuiteCustomizationForm();suiteCustomizationBusy=true;document.querySelectorAll('#customization input,#customization textarea,#customization select,#customization button').forEach(e=>e.disabled=true);\n  try{\n    const d=await api('/api/customization',{method:'POST',body:JSON.stringify(payload)});\n    suiteCustomizationData=Object.assign({},d.customization||payload);suiteCustomizationDirty=false;\n    applySuiteCustomization(suiteCustomizationData,true);\n    if($('suiteCustomizationState'))$('suiteCustomizationState').textContent='Saved';\n    toast(d.message||'Suite customization saved.','success');\n  }catch(e){toast(e.message,'error');}finally{suiteCustomizationBusy=false;document.querySelectorAll('#customization input,#customization textarea,#customization select,#customization button').forEach(e=>e.disabled=currentSessionRole==='ReadOnly'&&e.id!=='suiteCustomizationRefresh');}\n}\nfunction resetSuiteCustomization(){\n  if(currentSessionRole==='ReadOnly'||suiteCustomizationBusy)return;\n  const c=Object.assign({},SUITE_CUSTOMIZATION_DEFAULTS,{buildId:suiteCustomizationData?.buildId||''});\n  applySuiteCustomization(c,true);previewSuiteCustomization();\n  toast('Default customization loaded in the editor. Save to persist it.','success');\n}\n\n__NSS_MOTD_DECLARATIONS__\n\nasync function loadWebStatus(){\n  try{\n    const w=await api('/api/web/status');\n    setNavStatus('web',w.running?'good':'bad',w.running?'Web dashboard listener running':'Web dashboard listener stopped');\n    setNavStatus('console',w.running?'good':'bad',w.running?'Web Console host available':'Web Console host unavailable');\n    $('webStatus').textContent=\n`Enabled: ${w.enabled}\nRunning: ${w.running}\nBind address: ${w.bindAddress}\nPort: ${w.port}\nListen address: ${w.listenAddress}\nLocal GUI URL: ${w.localUrl||'(not available)'}\nPublic GUI URL: ${w.publicUrl||'(not configured)'}\nOwner username: ${w.username}\nAuthenticated as: ${w.authenticatedAs||currentSessionUser} (${panelAccountRoleLabel(w.authenticatedRole||currentSessionRole)})\nAdditional panel accounts: ${Number(w.panelAccounts||0)}\nOwner password configured: ${w.passwordConfigured}\nAuthentication: ${w.localAnonymousMode?'LOCAL LOOPBACK / NO LOGIN':'NAMED PANEL LOGIN'}\nActive sessions: ${w.activeSessions}\nSession timeout: ${w.sessionTimeoutMinutes} minutes\nSecure cookies: ${w.secureCookies}\nAllowed networks: ${(w.allowedNetworks||[]).length?w.allowedNetworks.join(', '):'any'}\nLast error: ${w.lastError||'(none)'}\nRequests: ${Number((w.diagnostics||{}).totalRequests||0).toLocaleString()} total / ${Number((w.diagnostics||{}).requestsLastMinute||0)} per minute\nRequest latency: avg ${Number((w.diagnostics||{}).averageRequestMilliseconds||0).toFixed(1)}ms / P95 ${Number((w.diagnostics||{}).p95RequestMilliseconds||0).toFixed(1)}ms / max ${Number((w.diagnostics||{}).maxRequestMilliseconds||0).toFixed(1)}ms\nMain-thread wait/work avg: ${Number((w.diagnostics||{}).averageMainThreadWaitMilliseconds||0).toFixed(1)}ms / ${Number((w.diagnostics||{}).averageMainThreadWorkMilliseconds||0).toFixed(1)}ms\nWorkers: ${Number((w.diagnostics||{}).activeWorkers||0)}/${Number(w.workerCount||(w.diagnostics||{}).workerCount||0)} active · queue ${Number((w.diagnostics||{}).queueDepth||0)}/${Number(w.requestQueueCapacity||(w.diagnostics||{}).queueCapacity||0)} · queue P95 ${Number((w.diagnostics||{}).p95QueueWaitMilliseconds||0).toFixed(1)}ms\nSnapshot cache: ${Number((w.diagnostics||{}).snapshotCacheHits||0)} hit / ${Number((w.diagnostics||{}).snapshotCacheMisses||0)} miss · ${Number((w.diagnostics||{}).snapshotRefreshes||0)} refreshes\nHTTP errors: ${Number((w.diagnostics||{}).errorResponses||0)} / auth rejects ${Number((w.diagnostics||{}).unauthorizedResponses||0)} / rate limits ${Number((w.diagnostics||{}).rateLimitedResponses||0)} / busy rejects ${Number((w.diagnostics||{}).rejectedBusyRequests||0)}`;\n\n    const diag=w.diagnostics||{};\n    $('webMetrics').innerHTML=metric('Listener',w.running?'Running':'Stopped',w.running?'good':'bad',`${w.bindAddress||'—'}:${Number(w.port||0)}`)+metric('Web workers',`${Number(diag.activeWorkers||0)}/${Number(w.workerCount||diag.workerCount||0)}`,Number(diag.queueDepth||0)>0?'warn':'good',`queue ${Number(diag.queueDepth||0)}/${Number(w.requestQueueCapacity||diag.queueCapacity||0)}`)+metric('Queue P95',`${Number(diag.p95QueueWaitMilliseconds||0).toFixed(1)} ms`,Number(diag.p95QueueWaitMilliseconds||0)>100?'warn':'good')+metric('Authentication',w.localAnonymousMode?'Local loopback':'Named login',w.localAnonymousMode?'warn':'good')+metric('Active sessions',Number(w.activeSessions||0))+metric('Panel accounts',Number(w.panelAccounts||0)+1)+metric('Session timeout',`${Number(w.sessionTimeoutMinutes||0)} min`)+metric('Request P95',`${Number(diag.p95RequestMilliseconds||0).toFixed(1)} ms`,Number(diag.p95RequestMilliseconds||0)>500?'warn':'good');\n    $('webSecurity').innerHTML=w.localAnonymousMode\n      ? '<div class=\"warning\"><b>LOCAL LOOPBACK MODE:</b> no login is required because the listener is bound to loopback only.<br><b>Set one with:</b> <code>/serverutils web password &lt;your-password&gt;</code> (minimum 10 characters) before changing to a LAN/public bind.</div>'\n      : (w.secureCookies\n          ? '<div class=\"infoBox\">Secure cookie flag is enabled. Make sure admins reach the dashboard through HTTPS.</div>'\n          : '<div class=\"warning\">Secure cookie flag is OFF. Direct remote HTTP is plaintext. Use a trusted HTTPS reverse proxy for Internet-facing access.</div>');\n    if(currentSessionRole==='ReadOnly')$('webSecurity').innerHTML='<div class=\"infoBox\"><b>READ ONLY SESSION:</b> this account can inspect the panel, but server-changing actions and heavy diagnostic launches are blocked by the server.</div>'+$('webSecurity').innerHTML;\n  }catch(e){$('webStatus').textContent=e.message;}\n}\n\nfunction refreshShortcutSection(){\n  switch(currentSection){\n    case 'dashboard': loadDashboard(true); break;\n    case 'serverStatus': loadServerStatus(true); break;\n    case 'reports': loadReports(true); break;\n    case 'playerlist': loadPlayerListConfig(); break;\n    case 'roles': loadRoles(); break;\n    case 'playercommands': loadPlayerCommands(true); break;\n    case 'warps': loadPlayerCommands(false); loadWarps(true); break;\n    case 'anticheat': loadAntiCheat(true); break;\n    case 'chatguard': loadChatGuard(true); break;\n    case 'logIntelligence': loadLogIntelligence(true); break;\n    case 'actionCenter': loadActionCenter(true); break;\n    case 'performance': loadPerformanceCenter(true); break;\n    case 'tickDebug': loadTickDebug(true); break;\n    case 'memory': loadMemoryCenter(true); break;\n    case 'profiler': loadProfiler(true); break;\n    case 'optimizations': loadOptimizations(); break;\n    case 'restarts': loadRestartSchedule(true); break;\n    case 'chatDisplay': loadChatDisplay(true); break;\n    case 'animals': loadAnimalStatus(true); break;\n    case 'loginProtection': loadLoginProtection(); break;\n    case 'customPatches': loadCustomPatches(false); loadContentPatches(false); break;\n    case 'communityMotd': loadCommunityMotd(true); break;\n    case 'compatibility': loadCompatibility(false); break;\n    case 'mods': loadMods(true); break;\n    case 'admin': loadAdmin(true); loadAdminDatabaseStorage(false); break;\n    case 'health': loadSystemHealth(true); break;\n    case 'operations': loadOperationsAudit(true); break;\n    case 'customization': loadSuiteCustomization(true); break;\n    case 'discord': loadDiscord(true); break;\n    case 'web': loadWebStatus(); loadFeatureGates(); if(currentSessionOwner)loadWebAccounts(true); break;\n    default: refreshGlobalStatus(true); break;\n  }\n}\n\nif($('suiteCustomizationRefresh'))$('suiteCustomizationRefresh').onclick=()=>{if(suiteCustomizationBusy)return;if(suiteCustomizationDirty&&!confirm('Discard unsaved customization preview and reload?'))return;suiteCustomizationDirty=false;loadSuiteCustomization(true);};\nif($('suiteCustomizationSave'))$('suiteCustomizationSave').onclick=saveSuiteCustomization;\nif($('suiteCustomizationReset'))$('suiteCustomizationReset').onclick=resetSuiteCustomization;\n['suiteCustomizationTexture','suiteCustomizationTextureStrength','suiteCustomizationIcons','suiteCustomizationContrast','suiteCustomizationTheme','suiteCustomizationBackground','suiteCustomizationPanel','suiteCustomizationText','suiteCustomizationLogoUrl','suiteCustomizationReduceMotion','suiteCustomizationPanelName','suiteCustomizationHeaderSubtitle','suiteCustomizationLoginKicker','suiteCustomizationLoginSubtitle','suiteCustomizationDashboardTitle','suiteCustomizationDashboardSubtitle','suiteCustomizationSearchPlaceholder','suiteCustomizationSidebarFooter','suiteCustomizationAccentText','suiteCustomizationShowBuild','suiteCustomizationHeaderLogo','suiteCustomizationCompact','suiteCustomizationSidebarWidth','suiteCustomizationCardRadius','suiteCustomizationStatusBar','suiteCustomizationModuleStatus','suiteCustomizationAttention','suiteCustomizationOperations'].forEach(id=>{const e=$(id);if(e)e.addEventListener('input',previewSuiteCustomization);if(e&&e.type==='checkbox')e.addEventListener('change',previewSuiteCustomization);});\nif($('suiteCustomizationAccent'))$('suiteCustomizationAccent').addEventListener('input',()=>{if($('suiteCustomizationAccentText'))$('suiteCustomizationAccentText').value=String($('suiteCustomizationAccent').value||'').toUpperCase();previewSuiteCustomization();});\n__NSS_MOTD_BINDINGS__\n\n$('adminRefresh').onclick=()=>{loadAdmin(true);loadAdminDatabaseStorage(false);};\n$('adminDatabaseStorageAnalyze').onclick=()=>loadAdminDatabaseStorage(true);\n$('adminDatabaseStorageRefresh').onclick=()=>loadAdminDatabaseStorage(false);\nconst adminDbStorageCanvas=$('adminDatabaseStorageGraph');\nif(adminDbStorageCanvas){\n  adminDbStorageCanvas.addEventListener('mousemove',e=>{\n    const rect=adminDbStorageCanvas.getBoundingClientRect();\n    const y=e.clientY-rect.top;\n    const hit=adminDatabaseStorageGraphHitAreas.find(a=>y>=a.y&&y<=a.y+a.h);\n    const tip=$('adminDatabaseStorageGraphTip');\n    const next=hit?hit.index:-1;\n    if(next!==adminDatabaseStorageGraphHover){adminDatabaseStorageGraphHover=next;renderAdminDatabaseStorageGraph();}\n    if(!tip||!hit){if(tip)tip.style.display='none';return;}\n    const r=hit.row;\n    const share=(v)=>r.total>0?`${(Number(v||0)*100/r.total).toFixed(1)}%`:'0.0%';\n    tip.innerHTML=`<b>${esc(r.db.name||r.db.key||'Database')}</b><br>Database: <b>${esc(formatBytesTotal(r.database))}</b> · ${share(r.database)}<br>WAL: <b>${esc(formatBytesTotal(r.wal))}</b> · ${share(r.wal)}<br>SHM: <b>${esc(formatBytesTotal(r.shm))}</b> · ${share(r.shm)}<br>Backups: <b>${esc(formatBytesTotal(r.backups))}</b> · ${share(r.backups)}<br>Total: <b>${esc(formatBytesTotal(r.total))}</b>`;\n    tip.style.display='block';\n    const left=Math.min(rect.width-235,Math.max(8,e.clientX-rect.left+12));\n    const top=Math.min(rect.height-125,Math.max(8,e.clientY-rect.top+12));\n    tip.style.left=`${left}px`;tip.style.top=`${top}px`;\n  });\n  adminDbStorageCanvas.addEventListener('mouseleave',()=>{\n    adminDatabaseStorageGraphHover=-1;\n    const tip=$('adminDatabaseStorageGraphTip');if(tip)tip.style.display='none';\n    renderAdminDatabaseStorageGraph();\n  });\n}\n$('adminPlayersOnlineTab').onclick=()=>setAdminPlayerTab('online');\n$('adminPlayersOfflineTab').onclick=()=>setAdminPlayerTab('offline');\n$('adminPlayerFilter').addEventListener('input',renderAdminPlayerList);\n$('adminLastSeenFilter').addEventListener('change',renderAdminPlayerList);\n$('adminPlayerSort').addEventListener('change',renderAdminPlayerList);\n$('adminUndo').onclick=()=>adminUndoLast();\n$('adminWarn').onclick=()=>adminPromptAction('warn');\n$('adminMute').onclick=()=>adminPromptAction('mute');\n$('adminUnmute').onclick=()=>adminPromptAction('unmute');\n$('adminTempBan').onclick=()=>adminPromptAction('tempban');\n$('adminUnban').onclick=()=>adminPromptAction('unban');\n$('adminFreeze').onclick=()=>adminPromptAction('freeze');\n$('adminUnfreeze').onclick=()=>adminPromptAction('unfreeze');\n$('adminKick').onclick=()=>adminPromptAction('kick');\n$('adminHeal').onclick=()=>adminPromptAction('heal');\n$('adminFeed').onclick=()=>adminPromptAction('feed');\n$('adminRevive').onclick=()=>adminPromptAction('revive');\n$('adminSmite').onclick=()=>adminPromptAction('smite');\n$('adminJail').onclick=()=>adminPromptAction('jail');\n$('adminUnjail').onclick=()=>adminPromptAction('unjail');\n$('adminSendBack').onclick=()=>adminPromptAction('sendback');\n$('adminAllowCharSelOnce').onclick=()=>adminPromptAction('allowcharselonce');\n$('adminAddNote').onclick=()=>adminPromptAction('note');\n$('adminCopyPlayer').onclick=adminCopyPlayerSummary;\n$('adminInventoryRefresh').onclick=refreshAdminInventory;\n$('adminInventorySnapshot').onclick=()=>adminCreateInventorySnapshot();\n$('adminInventoryClearSelection').onclick=()=>{adminSelectedInventorySlot=null;renderAdminInventory();};\n$('adminInventoryFilter').addEventListener('input',renderAdminInventory);\n$('adminItemSearchBtn').onclick=()=>adminSearchItems();\n$('adminItemSearch').addEventListener('keydown',e=>{if(e.key==='Enter')adminSearchItems();});\n$('adminGiveAuto').onclick=()=>adminGiveSelectedItem(true);\n$('adminGiveSelected').onclick=()=>adminGiveSelectedItem(false);\n$('adminReplaceSelected').onclick=()=>adminReplaceSelectedItem();\n$('adminMaintenanceOn').onclick=()=>adminMaintenance(true);\n$('adminMaintenanceOff').onclick=()=>adminMaintenance(false);\n$('adminShutdownSchedule').onclick=()=>adminShutdown(true,false);\n$('adminRestartSchedule').onclick=()=>adminShutdown(true,true);\n$('adminShutdownCancel').onclick=()=>adminShutdown(false,false);\n$('adminCleanupScan').onclick=()=>adminCleanup(false);\n$('adminCleanupRun').onclick=()=>adminCleanup(true);\n\ndocument.addEventListener('keydown',e=>{\n  const tag=String(document.activeElement&&document.activeElement.tagName||'').toLowerCase();\n  const typing=tag==='input'||tag==='textarea'||tag==='select'||document.activeElement?.isContentEditable;\n\n  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){\n    e.preventDefault();openCommandPalette();return;\n  }\n\n  if($('commandOverlay').classList.contains('open')){\n    if(e.key==='Escape'){e.preventDefault();closeCommandPalette();return}\n    if(e.key==='ArrowDown'){e.preventDefault();commandSelectedIndex=Math.min(commandResultCache.length-1,commandSelectedIndex+1);renderCommandResults();return}\n    if(e.key==='ArrowUp'){e.preventDefault();commandSelectedIndex=Math.max(0,commandSelectedIndex-1);renderCommandResults();return}\n    if(e.key==='Enter'){e.preventDefault();runCommandIndex(commandSelectedIndex);return}\n  }\n\n  if(e.key==='Escape'){\n    $('notificationPanel').classList.remove('open');\n    $('dashboardCustomizeOverlay').classList.remove('open');\n    if($('perfIncidentDetailCard')&&$('perfIncidentDetailCard').style.display!=='none'){\n      $('perfIncidentDetailCard').style.display='none';selectedPerformanceIncidentStart=0;setBreadcrumb();\n    }\n    return;\n  }\n\n  if(typing)return;\n\n  if(shortcutPrefix==='g'){\n    const map={d:'dashboard',p:'performance',a:'actionCenter',m:'memory',h:'health'};\n    const section=map[e.key.toLowerCase()];\n    shortcutPrefix='';\n    clearTimeout(shortcutPrefixTimer);\n    if(section){e.preventDefault();setSection(section,true)}\n    return;\n  }\n\n  if(e.key.toLowerCase()==='g'){\n    shortcutPrefix='g';\n    clearTimeout(shortcutPrefixTimer);\n    shortcutPrefixTimer=setTimeout(()=>shortcutPrefix='',1200);\n    return;\n  }\n\n  if(e.key.toLowerCase()==='r'){\n    e.preventDefault();refreshShortcutSection();return;\n  }\n});\n\nconst tableObserver=new MutationObserver(()=>{\n  clearTimeout(window.__nsuTableEnhanceTimer);\n  window.__nsuTableEnhanceTimer=setTimeout(()=>{enhanceImportantTables();syncWorkspacePage();},60);\n});\ntableObserver.observe(document.querySelector('main'),{subtree:true,childList:true});\n\nsetInterval(()=>{\n  if($('app').style.display!=='none'&&!document.hidden&&Date.now()-lastNavIndicatorRefresh>60000){\n    lastNavIndicatorRefresh=Date.now();\n    refreshNavIndicators(false);\n  }\n  if(lastSuccessfulUpdate&&$('offlineBanner').classList.contains('visible')){\n    const age=Math.max(0,Math.round((Date.now()-lastSuccessfulUpdate)/1000));\n    $('offlineDetail').textContent=`Displaying the last successful data. Last good response ${age}s ago.`;\n  }\n  if(liveUpdates){\n    $('globalUpdated').title='WebDashboard v2: lightweight live snapshot every 4 seconds; active page data refreshes on a slower per-section cadence';\n    setGlobalLiveState();\n  }\n},1000);\n\nconst markWebActivity=()=>{lastUserActivityAt=Date.now();};\n['pointerdown','keydown','touchstart'].forEach(evt=>document.addEventListener(evt,markWebActivity,{passive:true}));\nwindow.addEventListener('scroll',markWebActivity,{passive:true});\n\ndocument.addEventListener('visibilitychange',()=>{\n  if(document.hidden){\n    if(webMapTerrainProgressTimer){clearTimeout(webMapTerrainProgressTimer);webMapTerrainProgressTimer=null;}\n    return;\n  }\n  markWebActivity();\n  if(liveUpdates){lastSectionLiveRefresh=0;lastLiveNetworkAt=0;refreshLiveV2();}\n  if(consoleLiveEnabled&&currentSection==='console')loadConsole(false);\n  if(currentSection==='webmap'&&webMapData?.terrain?.state==='exporting')scheduleWebMapTerrainProgressPoll();\n});\n\n\nif($('cgRefresh'))$('cgRefresh').onclick=()=>loadChatGuard(true);\nif($('cgTabModeration'))$('cgTabModeration').onclick=()=>setChatGuardTab('moderation');\nif($('cgTabBanned'))$('cgTabBanned').onclick=()=>setChatGuardTab('banned');\nif($('cgBannedSearch'))$('cgBannedSearch').oninput=renderChatGuardBannedRows;\nif($('cgBannedAddButton'))$('cgBannedAddButton').onclick=()=>addChatGuardBanned([$('cgBannedAdd')?.value||'']);\nif($('cgBannedBulkButton'))$('cgBannedBulkButton').onclick=()=>addChatGuardBanned(chatGuardLines($('cgBannedBulk')?.value||''));\nif($('cgBannedSave'))$('cgBannedSave').onclick=()=>{applyBannedControlsToMainRule();saveChatGuard();};\n$('cgSave').onclick=saveChatGuard;\n$('cgManualMute').onclick=()=>chatGuardAction('mute','',$('cgManualTarget').value.trim(),Number($('cgManualMinutes').value||10),$('cgManualReason').value.trim(),!!$('cgManualPermanent').checked);\n$('cgManualWarn').onclick=()=>chatGuardAction('warn','',$('cgManualTarget').value.trim(),0,$('cgManualReason').value.trim(),false);\n$('cgManualInspect').onclick=inspectChatGuardTarget;\nif($('cgTestRun'))$('cgTestRun').onclick=testChatGuard;\nif($('cgRecentSearch'))$('cgRecentSearch').oninput=renderChatGuardRecent;\nif($('cgRecentAction'))$('cgRecentAction').onchange=renderChatGuardRecent;\nif($('cgRecentClearFilter'))$('cgRecentClearFilter').onclick=()=>{if($('cgRecentSearch'))$('cgRecentSearch').value='';if($('cgRecentAction'))$('cgRecentAction').value='';renderChatGuardRecent();};\nfor(const [id,format] of Object.entries({chatLayoutDefault:'{role} {name}: {timestamp} {message}',chatLayoutTimeFirst:'{timestamp} {role} {name}: {message}',chatLayoutTimeAfterName:'{role} {name} {timestamp}: {message}'}))$(id).onclick=()=>{if(currentSessionRole==='ReadOnly')return;$('chatDisplayLayout').value=format;chatLayoutPreview();};\n$('chatDisplayLayout').oninput=chatLayoutPreview;\n$('chatDisplayRefresh').onclick=()=>loadChatDisplay(true);\nif($('chatDisplaySave'))$('chatDisplaySave').onclick=saveChatDisplay;\n['chatDisplayLayout','chatDisplayRole','chatDisplayBoldName','chatDisplayTimestamp','chatDisplayTimestampFormat','chatDisplayUtc','chatDisplayGeneral','chatDisplayOtherGroups','chatDisplayAdditionalGroups','chatDisplayUseRoleColors'].forEach(id=>{\n  const el=$(id);if(!el)return;el.onchange=()=>{\n    if(!chatDisplayData)return;\n    chatDisplayData.showRoleBeforeName=!!$('chatDisplayRole').checked;\n    chatDisplayData.boldPlayerName=!!$('chatDisplayBoldName').checked;\n    chatDisplayData.showTimestampBeforeMessage=!!$('chatDisplayTimestamp').checked;\n    chatDisplayData.timestampFormat=$('chatDisplayTimestampFormat').value||'HH:mm';\n    chatDisplayData.useUtcTimestamp=!!$('chatDisplayUtc').checked;\n    chatDisplayData.formatGeneralChat=!!$('chatDisplayGeneral').checked;\n    chatDisplayData.formatOtherChatGroups=!!$('chatDisplayOtherGroups').checked;\n    chatDisplayData.additionalFormattedChatGroupIds=($('chatDisplayAdditionalGroups').value||'').split(/[;,\\s]+/).map(v=>Number(v)).filter(v=>Number.isInteger(v)&&v>=0);\n    chatDisplayData.useRoleNameColors=!!$('chatDisplayUseRoleColors').checked;\n    chatDisplayData.roleNameColors=parseRoleColorMap($('chatDisplayRoleColors').value||'');\n    renderChatDisplayRoleColorPreview();\n    chatLayoutPreview();\n\n  };\n});\nif($('chatDisplayRoleColors'))$('chatDisplayRoleColors').oninput=()=>{\n  if(chatDisplayData)chatDisplayData.roleNameColors=parseRoleColorMap($('chatDisplayRoleColors').value||'');\n  renderChatDisplayRoleColorPreview();\n};\n\ndocument.querySelectorAll('#rangeButtons button').forEach(\n  btn=>btn.classList.toggle('active',Number(btn.dataset.range)===profilerRangeSeconds)\n);\nlet panelLeaderboardData=null;\nlet panelLeaderboardTab='overview';\nlet panelLeaderboardProfileName='';\nconst panelLeaderboardOverlay=$('panelLeaderboardOverlay');\nconst panelLeaderboardBody=$('panelLeaderboardBody');\nconst panelLeaderboardStatus=$('panelLeaderboardStatus');\nconst panelLeaderboardNotice=$('panelLeaderboardNotice');\n\nfunction panelLbDuration(seconds){\n  seconds=Math.max(0,Number(seconds)||0);const d=Math.floor(seconds/86400),h=Math.floor((seconds%86400)/3600),m=Math.floor((seconds%3600)/60);\n  if(d)return `${d.toLocaleString()}d ${h}h`;if(h)return `${h.toLocaleString()}h ${m}m`;return `${m.toLocaleString()}m`;\n}\nfunction panelLbNumber(value){value=Math.max(0,Number(value)||0);if(value>=1e9)return `${(value/1e9).toFixed(value>=1e10?1:2).replace(/\\.?0+$/,'')}B`;if(value>=1e6)return `${(value/1e6).toFixed(value>=1e7?1:2).replace(/\\.?0+$/,'')}M`;if(value>=1e3)return `${(value/1e3).toFixed(value>=1e4?1:2).replace(/\\.?0+$/,'')}K`;return Math.round(value).toLocaleString()}\nfunction panelLbDate(ms){const n=Number(ms)||0;if(!n)return '—';try{return new Date(n).toLocaleDateString()}catch{return '—'}}\nfunction panelLbPlayerMarkup(row){return `${row?.online?'<span class=\"panelLbOnline\"></span>':''}${esc(row?.player||'Unknown')}`}\nfunction panelLbRankClass(rank){rank=Number(rank)||0;return rank>=1&&rank<=3?` r${rank}`:''}\nfunction panelLbRows(rows,formatter){rows=Array.isArray(rows)?rows:[];if(!rows.length)return '<div class=\"panelLbEmpty\">No ranked progress yet.</div>';return `<div class=\"panelLbRows\">${rows.map(r=>`<div class=\"panelLbRow\"><span class=\"panelLbRank${panelLbRankClass(r.rank)}\">#${Number(r.rank||0)}</span><span class=\"panelLbPlayer\" data-panel-lb-player=\"${esc(r.player||'')}\">${panelLbPlayerMarkup(r)}</span><span class=\"panelLbValue\">${esc(formatter(r))}</span></div>`).join('')}</div>`}\nfunction panelLbCard(title,icon,rows,formatter){return `<div class=\"panelLbCard\"><div class=\"panelLbCardHead\"><span>${icon}</span><span>${esc(title)}</span></div>${panelLbRows(rows,formatter)}</div>`}\nfunction bindPanelLbPlayers(){panelLeaderboardBody?.querySelectorAll('[data-panel-lb-player]').forEach(el=>el.onclick=()=>{panelLeaderboardProfileName=el.dataset.panelLbPlayer||'';renderPanelLeaderboard()})}\nfunction renderPanelLeaderboardStatus(){\n  const d=panelLeaderboardData||{};const tracked=Number(d.playerCount||0),offline=Number(d.offlinePlayerCount||0),online=Math.max(0,tracked-offline),xoff=Number(d.xSkillsOfflinePlayerCount||0);\n  if(panelLeaderboardStatus)panelLeaderboardStatus.innerHTML=`<span class=\"panelLbChip gold\">♛ ${tracked.toLocaleString()} tracked</span><span class=\"panelLbChip good\">● ${online.toLocaleString()} online</span><span class=\"panelLbChip\">◌ ${offline.toLocaleString()} offline</span><span class=\"panelLbChip ${d.xSkillsDetected?'good':''}\">✦ ${d.xSkillsDetected?`${Number(d.xSkillsPlayerCount||0).toLocaleString()} XSkills players`:'XSkills unavailable'}</span>${d.xSkillsDetected?`<span class=\"panelLbChip\">↳ ${xoff.toLocaleString()} offline XSkills</span>`:''}`;\n  if(panelLeaderboardNotice)panelLeaderboardNotice.innerHTML=d.xSkillsStatus?`<div class=\"panelLbNotice\">${esc(d.xSkillsStatus)}</div>`:'';\n}\nfunction renderPanelLeaderboardProfile(){\n  const d=panelLeaderboardData||{};const p=(d.players||[]).find(x=>String(x.player||'').toLowerCase()===String(panelLeaderboardProfileName||'').toLowerCase());if(!p){panelLeaderboardProfileName='';renderPanelLeaderboard();return}\n  const skills=Array.isArray(p.topSkills)?p.topSkills:[];\n  panelLeaderboardBody.innerHTML=`<button class=\"panelLbBack\" id=\"panelLbBack\">← Back</button><div class=\"panelLbProfileHero\"><div class=\"panelLbProfileName\">${p.online?'<span class=\"panelLbOnline\"></span>':''}${esc(p.player||'')}</div><div class=\"small\">${p.online?'Online now':'Offline'} · Public progression profile</div><div class=\"panelLbProfileStats\"><div class=\"panelLbStat\"><div class=\"panelLbStatLabel\">Tracked Playtime</div><div class=\"panelLbStatValue\">${panelLbDuration(p.totalPlaySeconds)}</div></div><div class=\"panelLbStat\"><div class=\"panelLbStatLabel\">Total Skill Levels</div><div class=\"panelLbStatValue\">${Number(p.totalSkillLevels||0).toLocaleString()}</div></div><div class=\"panelLbStat\"><div class=\"panelLbStatLabel\">Cumulative Skill XP</div><div class=\"panelLbStatValue\">${panelLbNumber(p.totalSkillExperience)}</div></div><div class=\"panelLbStat\"><div class=\"panelLbStatLabel\">Skills Progressed</div><div class=\"panelLbStatValue\">${Number(p.skillsLeveled||0).toLocaleString()}</div></div><div class=\"panelLbStat\"><div class=\"panelLbStatLabel\">First Seen</div><div class=\"panelLbStatValue\">${panelLbDate(p.firstSeenUnixMilliseconds)}</div></div><div class=\"panelLbStat\"><div class=\"panelLbStatLabel\">Last Seen</div><div class=\"panelLbStatValue\">${p.online?'Now':panelLbDate(p.lastSeenUnixMilliseconds)}</div></div></div>${skills.length?`<div style=\"margin-top:12px;font-weight:900\">Top Skills</div><div class=\"panelLbSkills\" style=\"margin-top:8px\">${skills.map(sk=>`<div class=\"panelLbSkill\"><div class=\"panelLbSkillHead\"><span class=\"panelLbSkillIcon\">${esc(sk.icon||'★')}</span><div><div class=\"panelLbSkillName\">${esc(sk.displayName||sk.name||'Skill')}</div><div class=\"panelLbSkillSub\">Level ${Number(sk.level||0).toLocaleString()} · ${panelLbNumber(sk.experience)} current XP</div></div></div></div>`).join('')}</div>`:''}</div>`;\n  $('panelLbBack').onclick=()=>{panelLeaderboardProfileName='';renderPanelLeaderboard()};\n}\nfunction renderPanelLeaderboard(){\n  if(!panelLeaderboardBody)return;renderPanelLeaderboardStatus();document.querySelectorAll('[data-panel-lb-tab]').forEach(b=>b.classList.toggle('active',(b.dataset.panelLbTab||'overview')===panelLeaderboardTab));\n  const d=panelLeaderboardData;if(!d){panelLeaderboardBody.innerHTML='<div class=\"panelLbEmpty\">Loading leaderboard…</div>';return}if(d.enabled===false){panelLeaderboardBody.innerHTML=`<div class=\"panelLbEmpty\">${esc(d.xSkillsStatus||'Leaderboards are disabled.')}</div>`;return}if(panelLeaderboardProfileName){renderPanelLeaderboardProfile();return}\n  if(panelLeaderboardTab==='skills'){\n    const skills=Array.isArray(d.skills)?d.skills:[];panelLeaderboardBody.innerHTML=skills.length?`<div class=\"panelLbSkills\">${skills.map(sk=>{const accent=/^#[0-9a-fA-F]{6}$/.test(sk.accent||'')?sk.accent:'#60a5fa';return `<div class=\"panelLbSkill\" style=\"--skillAccent:${accent}\"><div class=\"panelLbSkillHead\"><span class=\"panelLbSkillIcon\">${esc(sk.icon||'★')}</span><div><div class=\"panelLbSkillName\">${esc(sk.displayName||sk.name||'Skill')}</div><div class=\"panelLbSkillSub\">Top ${Number(d.topCount||5)} by level and XP</div></div></div>${panelLbRows(sk.entries,r=>`Lv. ${Number(r.level||0).toLocaleString()} · ${panelLbNumber(r.experience)} XP`)}</div>`}).join('')}</div>`:'<div class=\"panelLbEmpty\">No XSkills rankings are available.</div>';\n  }else if(panelLeaderboardTab==='playtime'){\n    panelLeaderboardBody.innerHTML=`<div class=\"panelLbGrid\">${panelLbCard('Most Tracked Playtime','⏱',d.playtime,r=>r.displayValue||panelLbDuration(r.value))}${panelLbCard('Longest Current Session','⌛',d.currentSession,r=>r.displayValue||panelLbDuration(r.value))}${panelLbCard('Server Veterans','★',d.veterans,r=>r.displayValue||'—')}</div>`;\n  }else{\n    panelLeaderboardBody.innerHTML=`<div class=\"panelLbGrid\">${panelLbCard('Top Total Skill Levels','♛',d.totalLevels,r=>r.displayValue||Math.round(Number(r.value||0)).toLocaleString())}${panelLbCard('Top Cumulative Skill XP','✦',d.totalExperience,r=>r.displayValue||panelLbNumber(r.value))}${panelLbCard('Most Tracked Playtime','⏱',d.playtime,r=>r.displayValue||panelLbDuration(r.value))}${panelLbCard('Longest Current Session','⌛',d.currentSession,r=>r.displayValue||panelLbDuration(r.value))}</div>`;\n  }\n  bindPanelLbPlayers();\n}\nasync function loadPanelLeaderboard(){\n  panelLeaderboardData=null;panelLeaderboardProfileName='';renderPanelLeaderboard();\n  try{panelLeaderboardData=await api('/api/leaderboard');renderPanelLeaderboard()}catch(e){panelLeaderboardBody.innerHTML=`<div class=\"panelLbEmpty\">Leaderboard unavailable: ${esc(e.message||e)}</div>`}\n}\nfunction openPanelLeaderboard(){panelLeaderboardOverlay?.classList.add('open');panelLeaderboardOverlay?.setAttribute('aria-hidden','false');loadPanelLeaderboard()}\nfunction closePanelLeaderboard(){panelLeaderboardOverlay?.classList.remove('open');panelLeaderboardOverlay?.setAttribute('aria-hidden','true');panelLeaderboardProfileName=''}\nif($('leaderboardTopBtn'))$('leaderboardTopBtn').onclick=openPanelLeaderboard;\nif($('panelLeaderboardClose'))$('panelLeaderboardClose').onclick=closePanelLeaderboard;\nif($('panelLeaderboardRefresh'))$('panelLeaderboardRefresh').onclick=loadPanelLeaderboard;\ndocument.querySelectorAll('[data-panel-lb-tab]').forEach(b=>b.onclick=()=>{panelLeaderboardTab=b.dataset.panelLbTab||'overview';panelLeaderboardProfileName='';renderPanelLeaderboard()});\npanelLeaderboardOverlay?.addEventListener('click',e=>{if(e.target===panelLeaderboardOverlay)closePanelLeaderboard()});\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape'&&panelLeaderboardOverlay?.classList.contains('open'))closePanelLeaderboard()});\n\nrenderBlockLoggerSavedViews();\nrenderDashboardWatchlist();\nenhanceToggleSwitches();\ninitToggleSwitchObserver();\nsetModsTab(modsActiveTab,false);\nsetGlobalLiveState();\nenhanceImportantTables();\ninitHeaderLayout();\ninitUiScale();\ninitMotionPreference();\ninitLocalization();\ncheckSession();\n// Local workspace preferences change presentation only; server permissions remain authoritative.\nlet workspaceJumpSignature='';\nlet workspaceCollapsedCards={};\nlet workspaceViewPrefs={compact:false,focus:false};\ntry{workspaceViewPrefs={...workspaceViewPrefs,...JSON.parse(localStorage.getItem('nsu.workspaceView')||'{}')};}catch{}\ntry{const saved=JSON.parse(localStorage.getItem('nsu.workspaceCollapsedCards')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))workspaceCollapsedCards=saved;}catch{}\nconst workspacePageKeywords={admin:'inventory offline saved player moderation mute ban',anticheat:'packet render distance fly flight ore shield integrity evidence mod',blocklogger:'audit history investigation rollback logs blocks containers',performance:'lag cpu tick tps entity load',web:'account login permissions access listener',operations:'audit staff actions configuration history',databaseStorage:'sqlite disk database tables storage'};\n\nfunction saveWorkspacePreference(key,value){\n  try{localStorage.setItem(key,JSON.stringify(value));}catch{}\n}\nfunction applyWorkspaceView(){\n  document.body.classList.toggle('workspaceCompact',!!workspaceViewPrefs.compact);\n  document.body.classList.toggle('workspaceFocus',!!workspaceViewPrefs.focus);\n  $('workspaceDensity')?.setAttribute('aria-pressed',String(!!workspaceViewPrefs.compact));\n  $('workspaceFocus')?.setAttribute('aria-pressed',String(!!workspaceViewPrefs.focus));\n  if($('workspaceFocus'))$('workspaceFocus').textContent=workspaceViewPrefs.focus?'Exit focus':'Focus page';\n  window.dispatchEvent(new Event('resize'));\n}\nfunction filterWorkspacePages(){\n  const input=$('workspaceNavSearch');\n  const query=(input?.value||'').trim().toLocaleLowerCase();\n  const words=query.split(/\\s+/).filter(Boolean);\n  $('nav').classList.toggle('workspaceSearching',!!query);\n  input?.parentElement.classList.toggle('hasQuery',!!query);\n  let count=0;\n  document.querySelectorAll('#nav .navGroup').forEach(group=>{\n    let matches=0;\n    const label=group.querySelector('.navGroupToggle')?.textContent||'';\n    group.querySelectorAll('button[data-section]').forEach(button=>{\n      const haystack=[button.textContent,label,workspacePageKeywords[button.dataset.section]||''].join(' ').toLocaleLowerCase();\n      const visible=words.every(word=>haystack.includes(word));\n      button.classList.toggle('workspaceFiltered',!visible);\n      if(visible){matches++;count++;}\n    });\n    group.classList.toggle('workspaceFiltered',!matches);\n    if(query)group.querySelector('.navGroupToggle')?.setAttribute('aria-expanded',String(!!matches));\n  });\n  $('workspaceNavEmpty').hidden=count>0||!query;\n  if(!query)syncNavGroups();\n}\nfunction clearWorkspacePageSearch(){\n  if(!$('workspaceNavSearch')?.value)return;\n  $('workspaceNavSearch').value='';filterWorkspacePages();\n}\nfunction workspaceCardKey(card,section){\n  const heading=card.querySelector(':scope > .cardHeader h3')?.textContent.trim()||card.id;\n  return section+':'+(card.id||heading).slice(0,120);\n}\nfunction setWorkspaceCardCollapsed(card,collapsed,persist=true){\n  card.classList.toggle('workspaceCardCollapsed',collapsed);\n  const toggle=card.querySelector(':scope > .cardHeader .workspaceCardToggle');\n  const title=card.querySelector(':scope > .cardHeader h3')?.textContent.trim()||'panel';\n  if(toggle){\n    toggle.textContent=collapsed?'+':'−';\n    toggle.setAttribute('aria-expanded',String(!collapsed));\n    toggle.setAttribute('aria-label',(collapsed?'Expand ':'Collapse ')+title);\n    toggle.title=(collapsed?'Expand ':'Collapse ')+title;\n  }\n  if(persist){\n    workspaceCollapsedCards[card.dataset.workspaceCardKey]=collapsed;\n    const keys=Object.keys(workspaceCollapsedCards);\n    if(keys.length>200)keys.slice(0,keys.length-200).forEach(key=>delete workspaceCollapsedCards[key]);\n    saveWorkspacePreference('nsu.workspaceCollapsedCards',workspaceCollapsedCards);\n  }\n  if(!collapsed && persist)window.dispatchEvent(new Event('resize'));\n}\nfunction syncWorkspacePage(){\n  const section=$(currentSection);\n  if(!section||!$('workspaceJump'))return;\n  const cards=Array.from(section.querySelectorAll('.card')).filter(card=>!card.parentElement.closest('.card'));\n  cards.forEach((card,index)=>{\n    const header=card.querySelector(':scope > .cardHeader');\n    const title=header?.querySelector('h3')?.textContent.trim();\n    if(!header||!title)return;\n    card.classList.add('workspaceCard');\n    if(!card.id)card.id=`workspace-${currentSection}-${index}`;\n    if(!header.querySelector('.workspaceCardToggle')){\n      card.dataset.workspaceCardKey=workspaceCardKey(card,currentSection);\n      const toggle=document.createElement('button');toggle.type='button';toggle.className='workspaceCardToggle';\n      toggle.onclick=()=>{setWorkspaceCardCollapsed(card,!card.classList.contains('workspaceCardCollapsed'));};\n      header.append(toggle);\n      setWorkspaceCardCollapsed(card,workspaceCollapsedCards[card.dataset.workspaceCardKey]===true,false);\n    }\n  });\n  const visible=cards.filter(card=>card.classList.contains('workspaceCard')&&card.getClientRects().length>0);\n  const entries=visible.map(card=>[card.id,card.querySelector(':scope > .cardHeader h3')?.textContent.trim().slice(0,100)||'Panel']);\n  const signature=JSON.stringify([currentSection,entries]);\n  if(signature===workspaceJumpSignature)return;\n  workspaceJumpSignature=signature;\n  const select=$('workspaceJump');select.replaceChildren(new Option('On this page',''));\n  entries.forEach(([id,label])=>select.add(new Option(label,id)));\n  select.disabled=entries.length===0;\n}\nfunction initWorkspacePages(){\n  $('workspaceNavSearch').oninput=filterWorkspacePages;\n  $('workspaceNavSearch').onkeydown=event=>{\n    if(event.key==='Escape'){event.preventDefault();event.stopPropagation();clearWorkspacePageSearch();}\n    if(event.key==='Enter'){\n      const first=document.querySelector('#nav .navGroup:not(.workspaceFiltered) button[data-section]:not(.workspaceFiltered)');\n      if(first){event.preventDefault();first.click();}\n    }\n  };\n  $('workspaceNavClear').onclick=()=>{clearWorkspacePageSearch();$('workspaceNavSearch').focus();};\n  $('workspaceDensity').onclick=()=>{workspaceViewPrefs.compact=!workspaceViewPrefs.compact;saveWorkspacePreference('nsu.workspaceView',workspaceViewPrefs);applyWorkspaceView();};\n  $('workspaceFocus').onclick=()=>{workspaceViewPrefs.focus=!workspaceViewPrefs.focus;saveWorkspacePreference('nsu.workspaceView',workspaceViewPrefs);applyWorkspaceView();};\n  $('workspaceRefresh').onclick=()=>setSection(currentSection,true);\n  $('workspaceJump').onchange=event=>{\n    const card=$(event.target.value);event.target.value='';if(!card)return;\n    setWorkspaceCardCollapsed(card,false);\n    const behavior=window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth';\n    card.scrollIntoView({behavior,block:'start'});\n    const header=card.querySelector('.cardHeader');if(header){header.tabIndex=-1;header.focus({preventScroll:true});}\n  };\n  document.querySelectorAll('[data-workspace-go]').forEach(button=>button.onclick=()=>{\n    if(button.dataset.workspaceGo==='anticheat')setAntiCheatTab('players');\n    setSection(button.dataset.workspaceGo,true);\n  });\n  document.addEventListener('click',event=>{\n    if(event.target.closest('[data-ac-tab],[data-ac-drawer-tab]'))requestAnimationFrame(syncWorkspacePage);\n  });\n  applyWorkspaceView();syncWorkspacePage();\n}\ninitWorkspacePages();\n__NSS_INTERFACE_SCRIPT__\n</script>\n</body>\n</html>\n".Replace("__NSS_VERSION__", "1.2.44").Replace("__NSS_BUILD_ID__", "newfies-server-essentials-suite-1.2.44-ms11-motd-roleplay1").Replace("__NSS_MOTD_DECLARATIONS__", "let communityMotdData=null;\nlet communityMotdConfig=null;\nlet communityMotdContentTab='main';\nlet communityMotdBaseline=null,communityMotdBaselineForm='',communityMotdDirty=false,communityMotdRevision=0,communityMotdBusy=false,communityMotdLoading=false,motdPreviewTimer=null;\nconst COMMUNITY_MOTD_CONTENT_KEYS={main:'Content',announcements:'AnnouncementsVtml',updates:'UpdatesVtml',events:'EventsVtml',rules:'RulesVtml',serverinfo:'ServerInfoVtml',commands:'CommandsVtml'};\nfunction motdBool(id){return !!$(id)?.checked;}\nfunction motdInt(id,fallback){const n=Number($(id)?.value);return Number.isFinite(n)?Math.trunc(n):fallback;}\nfunction stashCommunityMotdEditor(){\n  if(!communityMotdConfig)return;\n  const key=COMMUNITY_MOTD_CONTENT_KEYS[communityMotdContentTab]||'Content';\n  communityMotdConfig[key]=String($('communityMotdEditor')?.value||'');\n  if(key==='Content')communityMotdConfig.ContentLines=[];\n}\nfunction selectCommunityMotdContentTab(tab){\n  if(!COMMUNITY_MOTD_CONTENT_KEYS[tab])return;\n  stashCommunityMotdEditor();\n  communityMotdContentTab=tab;\n  document.querySelectorAll('#communityMotdContentTabs button[data-motd-content]').forEach(b=>b.classList.toggle('active',b.dataset.motdContent===tab));\n  const key=COMMUNITY_MOTD_CONTENT_KEYS[tab];\n  if($('communityMotdEditor'))$('communityMotdEditor').value=String(communityMotdConfig?.[key]||'');\n  if($('motdNewsBuilder'))$('motdNewsBuilder').hidden=!['announcements','updates'].includes(tab);\n  updateCommunityMotdDraft();\n  previewCommunityMotd();\n}\nfunction renderCommunityMotd(){\n  const d=communityMotdData||{},available=!!d.available,c=communityMotdConfig||{};\n  if($('communityMotdMissing'))$('communityMotdMissing').style.display=available?'none':'block';\n  if($('communityMotdState'))$('communityMotdState').textContent=available?(d.message||'Companion connected'):(d.message||'Companion unavailable');\n  if($('communityMotdStatus'))$('communityMotdStatus'