ccess)throw Error(d.message||'Save failed.');\n    contentPatchesData=d.snapshot||await api('/api/content-patches');renderContentPatches();\n    const saved=(contentPatchesData.patches||[]).find(x=>x.id===request.id)||(contentPatchesData.patches||[]).findLast(x=>x.file===pgResult.generated.file&&x.path===pgResult.generated.path);\n    pgId=saved?.id||'';pgPreviewRequest=JSON.stringify(pgRequest());\n    toast(activate?'Patch staged. Restart the server to apply it.':'Disabled draft saved.','success');\n  }catch(e){toast(e.message,'error');}finally{pgBusy=false;pgAccess();}\n}\nfunction pgDownload(){if(!pgResult)return;const url=URL.createObjectURL(new Blob([pgResult.preview.patchJson],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='balance-patch.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}\nfunction pgReset(){pgId='';$('pgName').value='';$('pgNotes').value='';pgInvalidate();}\n$('pgSearch').addEventListener('input',()=>{clearTimeout(pgSearchTimer);pgSearchTimer=setTimeout(pgSearchAssets,250);});\n$('pgKind').onchange=()=>{pgInspection=null;pgId='';pgInvalidate();pgSearchAssets();};\n$('pgAsset').onchange=pgSelectAsset;$('pgRoot').onchange=pgRootChanged;$('pgPreset').onchange=pgChangeType;$('pgIngredient').onchange=pgChangeType;$('pgField').onchange=pgFillField;$('pgOperation').onchange=()=>{pgInvalidate();pgValueControls();};\nfor(const id of ['pgName','pgQuantity','pgCode','pgValue','pgRecipeEnabled','pgSide','pgNotes','pgScalarNumber','pgScalarText','pgScalarBoolean'])$(id).addEventListener('input',pgInvalidate);\n$('pgPreview').onclick=pgGenerate;$('pgSaveDraft').onclick=()=>pgSave(false);$('pgApply').onclick=()=>pgSave(true);$('pgDownload').onclick=pgDownload;$('pgReset').onclick=pgReset;\n$('pgExport').onclick=()=>window.open('/api/content-patches/export','_blank','noopener');")
		.Replace("__NSS_POLISH_SCRIPT__", "let retentionData=null,retentionPrevious=null,retentionBusy=false;\nlet investigationData=null,investigationGeneration=0,investigationBusy=false,investigationBlocksBusy=false;\nlet roleBatchDraft=null,rolePolishGeneration=0;\nfunction polishDownload(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}\nfunction polishMetric(label,value,note=''){return `<div class=\"card\"><div class=\"metricLabel\">${esc(label)}</div><div class=\"metricValue\" style=\"font-size:20px\">${esc(value)}</div><div class=\"small\">${esc(note)}</div></div>`;}\nfunction policyPreviewMarkup(d){if(!d)return '<p class=\"small\">Policies unavailable.</p>';return `<p><b>${esc(d.name||d.code||'Role')}</b> · Home limit ${Number(d.homeLimit??0)} (${esc(d.homeSource||'')}) · ${Number(d.claimAllowance||0)} claim blocks / ${Number(d.claimAreas||0)} areas</p><div class=\"tableWrap\"><table><thead><tr><th>Command</th><th>Access</th><th>Cooldown</th><th>Source</th></tr></thead><tbody>${(d.commands||[]).map(c=>`<tr><td>/${esc(c.command)}</td><td>${c.allowed?'Allowed':'Denied'}</td><td>${Number(c.cooldownSeconds||0)}s</td><td>${esc(c.source)}</td></tr>`).join('')}</tbody></table></div><details><summary>${(d.privileges||[]).length} effective privileges</summary><p class=\"small\">${esc((d.privileges||[]).join(', ')||'None')}</p><p class=\"small\">Direct denials: ${esc((d.deniedPrivileges||[]).join(', ')||'None')}</p></details><p class=\"small\">${esc(d.note||'')}</p>`;}\nasync function loadRetentionCounters(){if(retentionBusy)return;retentionBusy=true;$('retentionRefresh').disabled=true;$('retentionState').textContent='Capturing counters…';try{const d=await api('/api/operations/diagnostics');retentionPrevious=retentionData;retentionData=d;const w=d.webPanel||{},a=d.admin||{},c=d.antiCheat||{},l=d.logger||