$('investigationBody').innerHTML='';$('investigationBlockRows').innerHTML='';$('investigationExport').disabled=true;$('investigationLoad').disabled=false;$('investigationBlocks').disabled=false;$('investigationState').textContent='Details load when requested';}\nfunction decisionMarkup(d){if(!d)return '<p class=\"small\">No current decision telemetry.</p>';return `<p>${esc(d.speedExplanation||'')}</p><p class=\"small\">Confirmed unmounted speed: ${Number(d.confirmedSpeedReports||0)} / ${Number(d.requiredReports||3)} observations in ${Number(d.repeatWindowSeconds||60)}s · Repeat bonus ${Number(d.repeatRiskBonus||0)} / ${Number(d.requiredBonus||50)}. ${esc(d.note||'')}</p><div class=\"tableWrap\"><table><thead><tr><th>Rule</th><th>Action</th><th>State</th></tr></thead><tbody>${(d.rules||[]).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.action)}</td><td>${esc(r.state)}</td></tr>`).join('')||'<tr><td colspan=\"3\">No enabled consequence rules.</td></tr>'}</tbody></table></div>`;}\nasync function loadPlayerInvestigation(){if(!adminSelectedPlayer||investigationBusy)return;const player=adminSelectedPlayer,generation=investigationGeneration;investigationBusy=true;$('investigationLoad').disabled=true;$('investigationState').textContent='Loading bounded investigation summary…';try{const d=await api('/api/admin/investigation?player='+encodeURIComponent(player));if(generation!==investigationGeneration)return;investigationData=d;const ac=d.antiCheat,p=d.player||{};$('investigationBody').innerHTML=`<div class=\"grid\">${polishMetric('Anti-cheat risk',ac?`${ac.riskScore}/100`:'No current session',ac?.status||'')}${polishMetric('Restrictions',[p.muted?'Muted':'',p.banned?'Banned':'',p.frozen?'Frozen':'',p.jailed?'Jailed':''].filter(Boolean).join(' · ')||'None')}${polishMetric('Inventory snapshots',(d.inventorySnapshots||[]).length,'Header records only')}</div><details open><summary>Why enforcement did or did not act</summary>${decisionMarkup(ac?.decision)}</details><details><summary>Effective role policies</summary>${policyPreviewMarkup(d.role?.effective)}</details><div class=\"tableWrap\"><table><thead><tr><th>Evidence</th><th>Risk points</th><th>Confidence</th><th>Explanation</th></tr></thead><tbody>${(ac?.findings||[]).map(f=>`<tr><td>${esc(f.code)}<br><small>${esc(f.subject)}</small></td><td>${Number(f.riskPoints||0)}</td><td>${esc(f.confidence)}</td><td>${esc(f.why||f.summary)}<details><summary>Evidence</summary><p class=\"small\">${esc(f.evidence)}</p></details></td></tr>`).join('')||'<tr><td colspan=\"4\">No current anti-cheat findings.</td></tr>'}</tbody></table></div><details><summary>Recorded risk changes (${(d.riskHistory||[]).length})</summary><div class=\"tableWrap\"><table><thead><tr><th>Time</th><th>Finding</th><th>Risk before → after</th><th>Consequence</th></tr></thead><tbody>${(d.riskHistory||[]).map(r=>`<tr><td>${esc(fmtAdminTime(r.unixMilliseconds))}</td><td>${esc(r.code)}</td><td>${Number(r.riskBefore||0)} → ${Number(r.riskAfter||0)}</td><td>${esc(r.consequence||'No recorded action')}</td></tr>`).join('')||'<tr><td colspan=\"4\">No recorded risk changes.</td></tr>'}</tbody></table></div></details><p class=\"small\">${esc(d.detailNote)}</p>`;$('investigationState').textContent=`Captured ${fmtAdminTime(d.capturedAt)}`;$('investigationExport').disabled=false;}catch(e){if(generation===investigationGeneration){$('investigationState').textContent='Investigation failed: '+e.message;toast(e.message,'error');}}finally{if(generation===investigationGeneration){investigationBusy=false;$('investigationLoad').disabled=false;}}}\nasync function loadInvestigationBlocks(){if(!adminSelectedPlayer||investigationBlocksBusy)return;const player=adminSelectedPlayer,generation=investigationGeneration;investigationBlocksBusy=true;$('investigationBlocks').disabled=true;try{const d=await api('/api/admin/block-history?player='+encodeURIComponent(player));if(generation!==investigationGeneration)return;const rows=d.history||[];$('investigationBlockRows').innerHTML=`<table><thead><tr><th>Time</th><th>Action</th><th>Block</th><th>Position</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.timestampUtc)}</td><td>${esc(r.action)}</td><td>${esc(r.blockCode)}</td><td>${Number(r.x)}, ${Number(r.y)}, ${Number(r.z)} · ${esc(r.dimension)}</td></tr>`).join('')||'<tr><td colspan=\"4\">No recorded block history.</td></tr>'}</tbody></table>`;if(investigationData)investigationData.blockHistory=rows;}catch(e){if(generation===investigationGeneration)toast(e.message,'error');}finally{if(generation===investigationGeneration){investigationBlocksBusy=false;$('investigationBlocks').disabled=false;}}}\nfunction invalidateRoleBatch(){rolePolishGeneration++;roleBatchDraft=null;$('roleBatchApply').disabled=true;$('roleBatchState').textContent='Preview required before applying.';}\nfunction bindRolePolish(){invalidateRoleBatch();document.querySelectorAll('[data-role-batch-uid]').forEach(e=>e.onchange=invalidateRoleBatch);document.querySelectorAll('[data-role-effective]').forEach(b=>b.onclick=async()=>{const p=rolePlayersData[Number(b.dataset.roleEffective)],generation=++rolePolishGeneration;if(!p)return;b.disabled=true;try{const d=await api('/api/roles/effective?player='+encodeURIComponent(p.playerUid));if(generation!==rolePolishGeneration)return;$('roleEffectiveResult').hidden=false;$('roleEffectiveResult').innerHTML=`<b>${esc(d.playerName||p.playerName)}</b>${policyPreviewMarkup(d.effective)}`;}catch(e){toast(e.message,'error');}finally{b.disabled=false;}});$('roleBatchPreview').disabled=currentSessionRole==='ReadOnly';}\nasync function previewRoleDraft(){if(!roleCanWrite()||!$('roleEditor').reportValidity())return;const selected=roleSelected,draft=roleRead(),signature=roleDefinitionSignature(draft),generation=++rolePolishGeneration;$('rolePreview').disabled=true;try{const d=await api('/api/roles/preview',{method:'POST',body:JSON.stringify({action:roleSelected==='__new'?'create':'save',revision:draft.revision,role:draft.row})});if(generation!==rolePolishGeneration||selected!==roleSelected||signature!==roleDefinitionSignature(roleRead()))return;if(!d.success)throw new Error(d.message);$('rolePreviewResult').hidden=false;$('rolePreviewResult').innerHTML=`<p>${Number(d.affectedPlayers||0)} assigned players would use this definition. Nothing has been saved.</p>${policyPreviewMarkup(d.effective)}`;}catch(e){toast(e.message,'error');}finally{roleSync();}}\nasync function previewRoleBatch(){if(!roleCanWrite())return;const selected=new Set([...document.querySelectorAll('[data-role-batch-uid]:checked')].map(e=>e.dataset.roleBatchUid));if(selected.size<1||selected.size>50){toast('Select 1–50 players.','error');return;}const payload={revision:rolesData.revision,roleCode:$('rolePlayerTarget').value,preview:true,players:rolePlayersData.filter(p=>selected.has(p.playerUid)).map(p=>({playerUid:p.playerUid,expectedRoleCode:p.roleCode}))};const generation=++rolePolishGeneration;$('roleBatchPreview').disabled=true;try{const d=await api('/api/roles/batch',{method:'POST',body:JSON.stringify(payload)});if(generation!==rolePolishGeneration)return;if(!d.success)throw new Error(d.message);const current=[...document.querySelectorAll('[data-role-batch-uid]:checked')].map(e=>e.dataset.roleBatchUid);if(payload.roleCode!==$('rolePlayerTarget').value||current.length!==selected.size||current.some(uid=>!selected.has(uid)))return;roleBatchDraft=payload;$('roleBatchApply').disabled=false;$('roleBatchState').textContent=`Previewed ${payload.players.length} players → ${payload.roleCode}. Direct grants/denials stay in place.`;$('roleEffectiveResult').hidden=false;$('roleEffectiveResult').innerHTML=(d.players||[]).map(p=>`<details><summary>${esc(p.playerName||p.playerUid)}</summary>${policyPreviewMarkup(p.effective)}</details>`).join('');}catch(e){toast(e.message,'error');}finally{$('roleBatchPreview').disabled=!roleCanWrite();}}\nasync function applyRoleBatch(){if(!roleCanWrite()||!roleBatchDraft)return;const payload=roleBatchDra