		.Replace("__NSS_INTERFACE_STYLE__", "/* UI1: shared surfaces use the owner's existing theme, accent and density tokens. */\nbody.suiteThemed #app section{--bg:var(--suite-bg);--panel:var(--suite-panel);--text:var(--suite-text)}\n#app section{--ui-inset:color-mix(in srgb,var(--panel) 84%,var(--bg));--ui-soft:color-mix(in srgb,var(--accent) 8%,var(--panel))}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .pageTitle{padding-bottom:14px;border-bottom:1px solid var(--line);margin-bottom:18px}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .card{box-shadow:0 4px 16px #00000012;background:var(--panel);border-color:var(--line)}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .cardHeader{gap:10px;align-items:center;flex-wrap:wrap}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) h3{font-size:14px;letter-spacing:.01em}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .tableWrap{border:1px solid var(--line);border-radius:8px}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) th{background:var(--ui-inset);font-size:11px;letter-spacing:.03em}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) td{font-variant-numeric:tabular-nums;vertical-align:top}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) tbody tr:nth-child(even){background:color-mix(in srgb,var(--text) 2%,transparent)}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) tbody tr:hover{background:var(--ui-soft)}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .compactNote{background:var(--ui-inset);border:1px solid var(--line);color:var(--muted);line-height:1.65}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .toolbar{gap:8px;align-items:center}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) input[type=search]{min-width:0}\n.uiTabs{display:flex;flex-wrap:wrap;gap:5px;padding:5px;background:var(--ui-inset);border:1px solid var(--line);border-radius:10px;margin:14px 0}\n#app .uiTabs button{background:transparent;border-color:transparent;color:var(--muted);border-radius:6px;min-height:34px;padding:7px 13px;font-size:12px;font-weight:650}\n#app .uiTabs button[aria-selected=true]{background:var(--ui-soft);border-color:var(--line);color:var(--text);box-shadow:inset 0 -2px var(--accent)}\n[data-ui-pane][hidden]{display:none!important}\n.uiIdentity{border-left:3px solid var(--accent)!important;scroll-margin-top:90px}\n#app #adminPlayerTitle{font-size:20px;line-height:1.25;overflow-wrap:anywhere}\n#adminPlayerMeta{overflow-wrap:anywhere;max-width:100%;font-variant-numeric:tabular-nums}\n#adminPlayerSummary{grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px}\n#app #adminPlayerSummary .card{padding:10px;background:var(--ui-inset);box-shadow:none}\n#app #adminPlayerSummary .metricValue{font-size:15px!important;line-height:1.4}\n#app #adminMetrics{grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}\n#app #adminMetrics .card{padding:11px 13px}\n#app #adminMetrics .metricValue{font-size:24px}\n.uiActionGroups{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-top:14px}\n.uiActionGroup{margin:0;padding:10px;border:1px solid var(--line);border-radius:8px;min-width:0;background:var(--ui-inset)}\n.uiActionGroup legend{padding:0 6px;color:var(--muted);font-size:11px;font-weight:650;letter-spacing:.04em}\n.uiActionGroup .quickActions{gap:6px;margin:0}\n#app .uiActionGroup button{font-size:11px;padding:6px 9px}\n#adminPlayerRows tr.uiSelectedPlayer{background:var(--ui-soft)!important;box-shadow:inset 3px 0 var(--accent)}\n#roles .roleWorkspace{grid-template-columns:minmax(210px,260px) minmax(0,1fr);align-items:start;gap:18px}\n.uiRoleRail{position:sticky;top:88px}\n.uiRoleRail .toolbar{display: