(--ui-inset);border-color:var(--line)}\n#databaseStorage .dbStorageDatabaseHeader{background:var(--panel);padding:16px}\n#databaseStorage .dbStorageGuidance{min-width:220px;line-height:1.65}\n#databaseStorage .dbStorageContent .bar{border-radius:3px}\n#customPatches #patchGeneratorCard>h3,#customPatches #pgPreviewPanel>h3{margin-top:22px;padding-top:16px;border-top:1px solid var(--line)}\n#customPatches #pgPreviewPanel{background:var(--ui-inset);border:1px solid var(--line);border-radius:9px;padding:16px;margin-top:16px}\n#customPatches :is(#pgBefore,#pgAfter,#pgJson){background:var(--bg);border:1px solid var(--line);border-radius:7px;padding:12px;font-size:12px;line-height:1.6}\n#customPatches #pgAfter{border-left:3px solid var(--accent)}\n#customPatches #patchAdvancedRuntime{border:1px solid var(--line);border-radius:9px;padding:14px;background:var(--ui-inset)}\n\n/* UI2: static procedural frame textures. No extra requests or animation loops. */\n:root{--suite-grain:.12;--ui-success:#56c7ac;--ui-warning:#e4b96a;--ui-danger:#ef8383}\n#app>header,#nav{isolation:isolate}\n#app>header::before,#nav::before{content:\"\";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:var(--suite-grain);background-image:repeating-linear-gradient(118deg,#d4e3ed1c 0 1px,transparent 1px 5px),repeating-linear-gradient(28deg,#0004 0 1px,transparent 1px 7px)}\nbody[data-suite-texture=none] #app>header::before,body[data-suite-texture=none] #nav::before{display:none}\nbody[data-suite-texture=brushed] #app>header::before,body[data-suite-texture=brushed] #nav::before{background-image:repeating-linear-gradient(0deg,#c6d9eb44 0 1px,#0003 1px 2px,transparent 2px 4px)}\n#app>header{border-bottom:1px solid color-mix(in srgb,var(--accent) 28%,var(--line))}\n#nav .navGroupBody>button{gap:9px}\n.uiModuleIcon{width:17px;height:17px;flex:none;color:var(--muted);stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;fill:none}\n#nav button.active .uiModuleIcon{color: