		.Replace("__NSS_INTERFACE_SCRIPT__", "// Local view state only: switching tabs never fetches inventories or mutates settings.\nfunction uiInstallTabs(host,entries,key,before,onChange=()=>{}){\n const nav=document.createElement('div');nav.className='uiTabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label',key==='player'?'Selected player views':'Profiler views');\n let selected=entries[0].key;try{const saved=localStorage.getItem('nsu.ui1.'+key);if(entries.some(e=>e.key===saved))selected=saved;}catch{}\n for(const entry of entries){const button=document.createElement('button');button.type='button';button.dataset.uiTab=key+':'+entry.key;button.id='ui1-'+key+'-'+entry.key;button.textContent=entry.label;button.setAttribute('role','tab');\n  entry.nodes.filter(Boolean).forEach((node,index)=>{node.dataset.uiPane=key+':'+entry.key;node.setAttribute('role','tabpanel');node.setAttribute('aria-labelledby',button.id);if(!node.id)node.id='ui1-'+key+'-'+entry.key+'-pane-'+index;});\n  button.setAttribute('aria-controls',entry.nodes.filter(Boolean).map(n=>n.id).join(' '));button.onclick=()=>select(entry.key);nav.append(button);\n }\n function select(value){selected=value;for(const entry of entries){const active=entry.key===value;const b=nav.querySelector('[data-ui-tab=\"'+key+':'+entry.key+'\"]');b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;entry.nodes.filter(Boolean).forEach(node=>node.hidden=!active);}try{localStorage.setItem('nsu.ui1.'+key,value);}catch{}onChange(value);if(typeof syncWorkspacePage==='function')syncWorkspacePage();}\n nav.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...nav.querySelectorAll('button')],at=entries.findIndex(x=>x.key===selected),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(at+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].click();buttons[next].focus();};\n host.insertBefore(nav,before||null);select(selected);return {select,nav};\n}\nfunction uiRefreshTable(id){\n enhanceTableByBodyId(id);const body=$(id),wrap=body?.closest('.tableWrap');if(!wrap)return;\n const filter=wrap.previousElementSibling?.querySelector('.tableTools input,input');if(filter)filter.dispatchEvent(new Event('input'));\n const sorted=body.closest('table').querySelector('th[data-sort-dir]');if(sorted){const dir=sorted.dataset.sortDir;sorted.dataset.sortDir=dir==='asc'?'desc':'asc';sorted.click();}\n}\nfunction uiMarkSelectedPlayer(){\n document.querySelectorAll('#adminPlayerRows tr').forEach(row=>{row.classList.toggle('uiSelectedPlayer',row.dataset.uiPlayer===adminSelectedPlayer);});\n}\nfunction uiInitPlayerViews(){\n const host=$('adminPlayerDetail'),identity=$('adminPlayerTitle').closest('.card'),investigation=$('investigationLoad').closest('.card');identity.classList.add('uiIdentity');host.prepend(identity);\n const notes=$('adminWarningRows').closest('.grid'),inventory=$('adminInventoryGrid').closest('.card'),history=$('adminHistoryRows').closest('.card');\n uiInstallTabs(host,[{key:'overview',label:'Notes & warnings',nodes:[notes]},{key:'investigation',label:'Investigation',nodes:[investigation]},{key:'inventory',label:'Inventory',nodes:[inventory]},{key:'history',label:'Player history',nodes:[history]}],'player',identity.nextSibling);\n const actions=$('adminWarn').parentElement,groups=document.createElement('div');groups.className='uiActionGroups';\n const definitions=[['Moderation',['adminWarn','adminMute','adminUnmute','adminKick']],['Restrictions',['adminTempBan','adminUnban','adminFreeze','adminUnfreeze','adminJail','adminUnjail']],['Player recovery',['adminHeal','adminFeed','adminRevive','adminSmite','adminSendBack','adminAllowCharSelOnce']],['Staff records',['adminAddNote','adminCopyPlayer']]];\n for(const [label,ids] of definitions){const field=document.createElement('fieldset'),legend=document.createElement('legend'),row=document.createElement('div');field.className='uiActionGroup';row.className='quickActions';legend.textContent=label;field.append(legend,row);ids.forEach(id=>{if($(id))row.append($(id));});groups.append(field);}actions.replaceWith(groups);\n const select=selectAdminPlayer;selectAdminPlayer=async(...args)=>{await select(...args);uiMarkSelectedPlayer();};\n const render=renderAdminPlayerList;renderAdminPlayerList=(...args)=>{render(...args);uiMarkSelectedPlayer();};\n}\nfunction uiInitRoleGroups(){\n const form=$('roleEditor'),grid=form.querySelector('.grid2'),minima=$('roleClaimX').closest('.row');\n function fieldGroup(label){const box=document.createElement('fieldset'),legend=document.createElement('legend');box.className='uiFieldGroup';legend.textContent=label;box.append(legend);form.insertBefore(box,grid);return box;}\n const identity=fieldGroup('Identity & appearance'),identityGrid=document.createElement('div');identityGrid.className='grid2';identity.append(identityGrid);\n ['roleCode','roleName','roleDescription','roleRank','roleColor','roleNameColor','roleGameMode'].forEach(id=>identityGrid.append($(id).closest('.field')));\n identity.append($('roleUseColors').closest('.toggleLine'));\n const limits=fieldGroup('Homes & land claims'),limitsGrid=document.createElement('div');limitsGrid.className='grid2';limits.append(limitsGrid);['roleHomeLimit','roleClaimAllowance','roleClaimAreas'].forEach(id=>limitsGrid.append($(id).closest('.field')));limits.append(minima);\n const permissions=fieldGroup('Permissions'),tools=document.createElement('div');tools.className='uiPermissionTools';\n const category=document.createElement('select');category.id='uiPrivilegeCategory';category.setAttribute('aria-label','Privilege category');category.innerHTML='<option value=\"all\">All permissions</option><option value=\"selected\">Granted permissions</option><option value=\"administration\">Administration</option><option value=\"world\">World & building</option><option value=\"other\">Other / mod permissions</option>';\n const count=document.createElement('span');count.id='uiPrivilegeCount';count.className='small';count.setAttribute('role','status');\n const heading=$('rolePrivilegeSearch').previousElementSibling;if(heading?.classList.contains('small'))permissions.append(heading);\n tools.append($('rolePrivilegeSearch'),category,count);permissions.append(tools,$('roleAutoGrant').closest('.toggleLine'),$('rolePrivilegeList'),$('roleExtraPrivileges').closest('.field'),$('roleRuntimePrivileges'));\n const travel=fieldGroup('Teleport access & cooldowns');travel.append($('rolePolicyNote'),$('rolePolicies'));\n grid.remove();form.querySelectorAll(':scope > h3').forEach(h=>h.remove());$('roleSave').closest('.toolbar').classList.add('uiRoleFooter');\n const changes=document.createElement('details');changes.id='uiRoleChanges';changes.className='uiDraftChanges';changes.hidden=true;form.insertBefore(changes,$('roleSave').closest('.toolbar'));\n const rail=$('roleList').closest('.card');rail.classList.add('uiRoleRail');const railTools=document.createElement('div');railTools.className='toolbar';railTools.append($('roleSearch'),$('rolesReload'));rail.prepend(railTools);\n [identity,limits,permissions,travel].forEach((box,index)=>{const legend=box.querySelector('legend'),label=legend.textContent,content=document.createElement('div');content.id='uiRoleGroupBody'+index;[...box.children].filter(n=>n!==legend).forEach(n=>content.append(n));box.append(content);const toggle=document.createElement('button');toggle.type='button';toggle.className='uiGroupToggle';toggle.dataset.uiFold=String(index);toggle.textContent=label;toggle.setAttribute('aria-controls',content.id);legend.replaceChildren(toggle);let folded=false;try{folded=localStorage.getItem('nsu.ui1.roleGroup.'+index)==='closed';}catch{}function setFold(value){folded=value;content.hidden=value;toggle.setAttribute('aria-expanded',String(!value));}setFold(folded);toggle.onclick=()=>{setFold(!folded);try{localStorage.setItem('nsu.ui1.roleGroup.'+index,folded?'closed':'open');}catch{}};});\n form.addEventListener('invalid',event=>{const toggle=event.target.closest('.uiFieldGroup')?.querySelector('[data-ui-fold]');if(toggle?.getAttribute('aria-expanded')==='false')toggle.click();},true);\n const originalSync=roleSync;roleSync=(...args)=>{originalSync(...args);$('rolePrivilegeSearch').disabled=false;category.disabled=false;form.querySelectorAll('[data-ui-fold]').forEach(b=>b.disabled=false);};\n const originalFilter=filterRolePrivileges;filterRolePrivileges=()=>{originalFilter();let visible=0,selected=0;document.querySelectorAll('[data-role-privilege-label]').forEach(label=>{const code=label.dataset.rolePrivilegeLabel,checked=label.querySelector('input').checked;selected+=Number(checked);const group=/control|admin|ban|kick|whitelist|commandplayer|server|root/i.test(code)?'administration':/build|break|place|claim|gamemode|world|creative|give|teleport/i.test(code)?'world':'other';label.hidden=label.hidden||(category.value==='selected'?!checked:category.value!=='all'&&category.value!==group);visible+=Number(!label.hidden);});count.textContent=visible+' shown · '+selected+' granted';};category.onchange=filterRolePrivileges;\n const render=renderRoleEditor;renderRoleEditor=(...args)=>{render(...args);$('rolePrivilegeSearch').disabled=false;category.disabled=false;uiRoleChanges();uiRolePolicyHints();};\n const capture=roleCapture;roleCapture=(...args)=>{capture(...args);uiRoleChanges();filterRolePrivileges();uiRolePolicyHints();};\n const list=renderRoleList;renderRoleList=(...args)=>{list(...args);uiRoleSwatches();document.querySelectorAll('[data-role-select]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.roleSelect===roleSelected)));};\n}\nfunction uiRoleChanges(){\n const box=$('uiRoleChanges'),draft=roleDrafts.get(roleSelected),saved=rolesData?.roles.find(r=>r.code===roleSelected);box.hidden=!draft;if(!draft)return;\n const changes=[];for(const [key,id] of Object.entries(roleFields)){const comparable=value=>/color/i.test(key)?String(value??'').toUpperCase():String(value??'');if(comparable(draft.row[key])===comparable(saved?.[key]))continue;const label=$(id).closest('.field')?.firstChild?.textContent.trim()||key;changes.push(label+': '+(saved?.[key]??'Inherit')+' → '+(draft.row[key]??'Inherit'));}\n const before=new Set(saved?.privileges||[]),after=new Set(draft.row.privileges||[]);const added=[...after].filter(p=>!before.has(p)),removed=[...before].filter(p=>!after.has(p));if(added.length)changes.push('Grant: '+added.join(', '));if(removed.length)changes.push('Remove grants: '+removed.join(', '));\n for(const cmd of ROLE_COMMANDS)if(JSON.stringify(saved?.policies?.[cmd]??null)!==JSON.stringify(draft.row.policies?.[cmd]??null)){const p=draft.row.policies?.[cmd];changes.push('/'+cmd+': '+(p?(p.allowed?'Allow':'Deny')+' · '+(p.cooldownSeconds<0?'command default':p.cooldownSeconds+'s'):'Inherit access & cooldown'));}\n if(!!saved?.autoGrant!==!!draft.row.autoGrant)changes.push('Automatic privileges: '+(draft.row.autoGrant?'On':'Off'));if(draft.useColors!==rolesData?.useRoleNameColors)changes.push('Global role name colors: '+(draft.useColors?'On':'Off'));\n box.innerHTML='<summary>'+changes.length+' pending change'+(changes.length===1?'':'s')+'</summary><ul>'+changes.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>';box.open=true;\n}\nfunction uiRolePolicyHints(){\n if(!rolesData||$('roleEditor').hidden)return;const row=roleRead().row,admin=row.autoGrant||row.privileges.some(p=>['root','controlserver','*'].includes(p.toLowerCase()));\n for(const cmd of ROLE_COMMANDS){const mode=$('rolePolicy_'+cmd),input=$('roleCooldown_'+cmd),wild=rolesData.wildcardPolicies?.[cmd],fallback=Number(rolesData.defaultCooldowns?.[cmd]||0),inherited=wild?.cooldownSeconds>=0?wild.cooldownSeconds:fallback,access=wild?wild.allowed:!['t2p','t2m'].includes(cmd)||admin;\n  mode.options[0].textContent='Inherit ('+(access?'allowed':'denied')+')';const note=mode.closest('div').querySelector('small');if(note)note.textContent=mode.value==='inherit'?'Inherited cooldown: '+inherited+'s':Number(input.value)<0?'Command default: '+fallback+'s':'Configured cooldown: '+Number(input.value)+'s';\n }\n}\nfunction uiInitProfilerViews(){\n const host=$('profiler'),mods=$('profMods').closest('.grid');mods.classList.add('uiAttributionGrid');const groups=$('incidentGroups').closest('.card'),samples=$('profIncidents').closest('.card');\n const keep=[...host.children].filter(node=>!node.classList.contains('pageTitle')&&!node.classList.contains('toolbar')&&![mods,groups,samples].includes(node));\n const strip=document.createElement('div');strip.id='uiProfileStrip';strip.className='uiProfileStrip';strip.setAttribute('role','status');strip.textContent='Run a profile to collect attribution; diagnostics show recorded lag.';\n const first=keep[0]||mods;host.insertBefore(strip,first);uiInstallTabs(host,[{key:'overview',label:'Charts & diagnosis',nodes:keep},{key:'attribution',label:'Mods & slow ticks',nodes:[mods]},{key:'lag',label:'Lag events',nodes:[groups,samples]}],'profiler',strip,value=>{if(value==='overview'&&lastProfilerPayload)requestAnimationFrame(redrawProfilerCharts);});\n const load=loadProfiler;loadProfiler=async(...args)=>{await load(...args);const p=lastProfilerPayload;if(p)strip.innerHTML='<span><b>'+Number((p.modHotspots||[]).length)+'</b> attributed mods</span><span><b>'+Number((p.profileSlowTicks||[]).length)+'</b> slow profiled ticks</span><span><b>'+Number((p.diagnosticIncidents||[]).length)+'</b> lag samples in range</span><span>'+(p.profileRunning?'Profile running':'Last loaded snapshot')+'</span>';['profMods','profTicks','incidentGroups','profIncidents'].forEach(uiRefreshTable);};\n}\n\nfunction uiRoleSwatches(){\n document.querySelectorAll('#roleList [data-role-select]').forEach(button=>{\n  const role=rolesData?.roles?.find(r=>r.code===button.dataset.roleSelect),color=role?.nameColorHex||role?.colorHex;\n  if(!/^#[0-9a-f]{6}$/i.test(color||''))return;\n  const chip=document.createElement('span');chip.className='uiRoleColor';chip.style.backgroundColor=color;chip.title='Role color '+color;chip.setAttribute('aria-hidden','true');\n  button.querySelector('b')?.prepend(chip);\n });\n}\nfunction uiInitModuleIcons(){\n const shapes={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',admin:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4',roles:'M12 3l9 4v5c0 5-9 9-9 9s-9-4-9-9V7z M8 12l3 3 5-6',profiler:'M3 18h18 M4 12l4-5 4 8 4-11 4 7',databaseStorage:'M3 6c0-4 18-4 18 0s-18 4-18 0v12c0 4 18 4 18 0V6 M3 12c0 4 18 4 18 0',chatDisplay:'M4 3h16v13H9l-5 5z M8 7h8 M8 11h5',customization:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',webmap:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',console:'M4 5l6 6-6 6 M13 18h7',mods:'M3 6l9-4 9 4v12l-9 4-9-4z M3 6l9 4 9-4 M12 10v12',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5 M12 17v.1'};\n shapes.anticheat=shapes.roles;shapes.chatguard=shapes.roles;shapes.playerlist=shapes.admin;shapes.discord=shapes.chatDisplay;shapes.communityMotd=shapes.chatDisplay;shapes.memory=shapes.profiler;\n document.querySelectorAll('#nav .navGroupBody>button[data-section]').forEach(button=>{\n  if(button.querySelector('.uiModuleIcon'))return;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','uiModuleIcon');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',shapes[button.dataset.section]||'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h4');svg.append(path);button.prepend(svg);\n });\n}\nuiInitModuleIcons();\n\nuiInitPlayerViews();uiInitRoleGroups();uiInitProfilerViews();")
		.Replace("__NSS_RETENTION_HTML__", "<div class=\"card perfSection\"><div class=\"cardHeader\"><h3>Module Retention &amp; Queues</h3></div>\n<p class=\"small\">Compare Suite-owned queues and caches alongside heap readings. Refresh and export are manual; no heap walk or forced collection runs.</p>\n<div class=\"toolbar\"><button id=\"retentionRefresh\">Refresh Counters</button><button id=\"retentionExport\" disabled>Download Diagnostics</button><span id=\"retentionState\" role=\"status\" aria-live=\"polite\">Not captured</span></div>\n<div id=\"retentionCounters\" class=\"grid\"></div><div id=\"retentionComparison\" class=\"small\"></div><details><summary>WebPanel cache lifetimes</summary><div id=\"retentionKeys\" class=\"tableWrap\"></div></details></div>")
		.Replace("__NSS_INVESTIGATION_HTML__", "<div class=\"card perfSection\"><div class=\"cardHeader\"><h3>Investigation Overview</h3></div>\n<p class=\"small\">Combine restrictions, anti-cheat evidence, effective role policies and snapshot headers. Inventory contents and block history load on demand.</p>\n<div class=\"toolbar\"><button id=\"investigationLoad\">Load Investigation</button><button id=\"investigationBlocks\">Load Block History</button><button id=\"investigationExport\" disabled>Download Investigation</button><span id=\"investigationState\" role=\"status\" aria-live=\"polite\">Choose a player</span></div>\n<div id=\"investigationBody\"></div><div id=\"investigationBlockRows\" class=\"tableWrap\"></div></div>")
		.Replace("__NSS_ROLE_HTML__", "<section id=\"roles\">\n<div class=\"pageTitle\"><div><h2>Role Config</h2><div class=\"subtitle\">Game roles, permissions, name colors and shared Suite limits in one place.</div></div></div>\n<div class=\"toolbar\"><input id=\"roleSearch\" type=\"search\" placeholder=\"Search roles…\" aria-label=\"Search roles\"><button id=\"rolesReload\">Reload</button><button id=\"roleNew\">Add Role</button><span id=\"rolesState\" class=\"small\" role=\"status\"></span></div>\n<div class=\"infoBox\">These are Vintage Story player roles. WebPanel account access is managed under Web Dashboard. Home limits, teleport policies and chat name colors share the same settings as their original pages.</div>\n<div class=\"roleWorkspace perfSection\"><div class=\"card\"><p id=\"roleListCount\" class=\"small\" role=\"status\"></p><div id=\"roleList\" class=\"roleList\"></div></div><form id=\"roleEditor\" class=\"card\" hidden>\n<div class=\"cardHeader\"><h3 id=\"roleHeading\">Role</h3><span id=\"roleDraftState\" class=\"small\" role=\"status\" aria-live=\"polite\"></span></div>\n<div class=\"grid2\">\n<label class=\"field\">Role code<input id=\"roleCode\" required maxlength=\"64\"></label><label class=\"field\">Display name<input id=\"roleName\" required maxlength=\"80\"></label>\n<label class=\"field\">Description<textarea id=\"roleDescription\" maxlength=\"500\"></textarea></label>\n<label class=\"field\">Rank / privilege level<input id=\"roleRank\" type=\"number\" min=\"0\" max=\"100000\" required></label>\n<label class=\"field\">Game role color<input id=\"roleColor\" type=\"color\"></label>\n<label class=\"field\">Chat / roster color override (role code)<input id=\"roleNameColor\" placeholder=\"Empty = inherit chat color\" pattern=\"#[0-9a-fA-F]{6}\"></label>\n<label class=\"field\">Default game mode<select id=\"roleGameMode\"></select></label>\n<label class=\"field\">Home limit<input id=\"roleHomeLimit\" type=\"number\" min=\"0\" max=\"100\" placeholder=\"Inherit global limit\"></label>\n<label class=\"field\">Claim block allowance<input id=\"roleClaimAllowance\" type=\"number\" min=\"0\" max=\"2147483647\" required></label><label class=\"field\">Maximum claim areas<input id=\"roleClaimAreas\" type=\"number\" min=\"0\" max=\"10000\" required></label>\n</div>\n<div class=\"row\"><label class=\"field\">Minimum claim X<input id=\"roleClaimX\" type=\"number\" min=\"1\" max=\"10000\" required></label><label class=\"field\">Y<input id=\"roleClaimY\" type=\"number\" min=\"1\" max=\"10000\" required></label><label class=\"field\">Z<input id=\"roleClaimZ\" type=\"number\" min=\"1\" max=\"10000\" required></label></div>\n<label class=\"toggleLine\"><input id=\"roleAutoGrant\" type=\"checkbox\"> <span>Automatically grant every registered game privilege</span></label>\n<label class=\"toggleLine\"><input id=\"roleUseColors\" type=\"checkbox\"> <span>Enable role name colors globally</span></label>\n<h3>Permissions</h3><p class=\"small\">Persistent privilege codes, including mod privileges. Runtime grants remain controlled by their originating mods.</p><input id=\"rolePrivilegeSearch\" type=\"search\" placeholder=\"Find a privilege…\" aria-label=\"Find a privilege\"><div id=\"rolePrivilegeList\" class=\"rolePrivileges\"></div><label class=\"field\">Additional privilege codes (one per line)<textarea id=\"roleExtraPrivileges\" rows=\"3\"></textarea></label><div id=\"roleRuntimePrivileges\" class=\"small\"></div>\n<h3>Teleport access &amp; cooldowns</h3><p id=\"rolePolicyNote\" class=\"small\"></p><div id=\"rolePolicies\" class=\"rolePolicies\"></div>\n<div class=\"toolbar\"><button id=\"rolePreview\" type=\"button\">Preview Changes</button><button id=\"roleSave\" class=\"primary\" type=\"submit\">Save Role</button><button id=\"roleDiscard\" type=\"button\">Discard Draft</button><div class=\"spacer\"></div><button id=\"roleDelete\" class=\"danger\" type=\"button\">Remove Role</button></div>\n<div id=\"rolePreviewResult\" class=\"compactNote\" role=\"status\" hidden></div>\n</form></div>\n<div class=\"card perfSection\"><div class=\"cardHeader\"><h3>Player Role Assignments</h3></div><div class=\"toolbar\"><input id=\"rolePlayerSearch\" type=\"search\" placeholder=\"Player name, UID or role…\" aria-label=\"Find players\"><button id=\"rolePlayerFind\">Find Players</button><span id=\"rolePlayerCount\" class=\"small\"></span></div><div class=\"toolbar\"><input id=\"rolePlayerTargetSearch\" type=\"search\" placeholder=\"Find target role…\" aria-label=\"Find target role\"><select id=\"rolePlayerTarget\" aria-label=\"Target role for assignment\"></select></div><p class=\"small\">Choose a target role above, then assign it to a player. Search saved players, including offline accounts. Direct privilege grants and denials are preserved. Discord role sync may reassign linked players later; review its mappings before removing a role.</p><div class=\"toolbar\"><button id=\"roleBatchPreview\">Preview Selected</button><button id=\"roleBatchApply\" class=\"primary\" disabled>Apply Previewed Assignments</button><span id=\"roleBatchState\" class=\"small\" role=\"status\"></span></div><div id=\"roleEffectiveResult\" class=\"compactNote\" hidden></div><div id=\"rolePlayers\" class=\"rolePlayers\"></div></div>\n</section>")
		.Replace("__NSS_ROLE_SCRIPT__", "let rolesData=null,roleSelected='',roleDrafts=new Map(),roleBusy=false,rolePlayersData=[];\nlet rolePlayersLoading=false,rolePlayersReload=false;\nconst roleAssignmentsPending=new Set();\nconst ROLE_COMMANDS=['spawn','home','back','warp','t2p','t2m','rtp'];\nconst roleFields={code:'roleCode',name:'roleName',description:'roleDescription',privilegeLevel:'roleRank',colorHex:'roleColor',nameColorHex:'roleNameColor',defaultGameMode:'roleGameMode',homeLimit:'roleHomeLimit',landClaimAllowance:'roleClaimAllowance',landClaimMaxAreas:'roleClaimAreas',claimMinX:'roleClaimX',claimMinY:'roleClaimY',claimMinZ:'roleClaimZ'};\nfunction roleCanWrite(){return rolesData?.available===true&&currentSessionRole!=='ReadOnly'&&!roleBusy;}\nfunction roleRead(){\n const row={};for(const [key,id] of Object.entries(roleFields)){const el=$(id);row[key]=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;}\n row.autoGrant=$('roleAutoGrant').checked;row.privileges=[...document.querySelectorAll('[data-role-privilege]:checked')].map(e=>e.value).concat($('roleExtraPrivileges').value.split(/[\\s,]+/).filter(Boolean));row.policies={};\n for(const cmd of ROLE_COMMANDS){const mode=$(`rolePolicy_${cmd}`).value;row.policies[cmd]=mode==='inherit'?null:{allowed:mode==='allow',cooldownSeconds:Number($(`roleCooldown_${cmd}`).value)};}\n return {row,useColors:$('roleUseColors').checked,revision:roleDrafts.get(roleSelected)?.revision||rolesData.revision};\n}\nfunction roleDefinitionSignature(draft){\n const row=draft.row,numberKeys=new Set(['privilegeLevel','homeLimit','landClaimAllowance','landClaimMaxAreas','claimMinX','claimMinY','claimMinZ']);\n return JSON.stringify([\n  Object.keys(roleFields).map(key=>[key,numberKeys.has(key)?(row[key]===''||row[key]==null?null:Number(row[key])):key==='colorHex'||key==='nameColorHex'?String(row[key]??'').toUpperCase():String(row[key]??'')]),\n  !!row.autoGrant,[...new Set(row.privileges||[])].sort(),\n  ROLE_COMMANDS.map(cmd=>{const p=row.policies?.[cmd];return[cmd,p?{allowed:p.allowed!==false,cooldownSeconds:Number(p.cooldownSeconds??-1)}:null];}),!!draft.useColors\n ]);\n}\nfunction roleCapture(){\n if(!roleSelected||$('roleEditor').hidden||!roleCanWrite())return;\n const draft=roleRead(),saved=rolesData.roles.find(r=>r.code===roleSelected),hadDraft=roleDrafts.has(roleSelected);\n if(saved&&roleDefinitionSignature(draft)===roleDefinitionSignature({row:saved,useColors:rolesData.useRoleNameColors}))roleDrafts.delete(roleSelected);\n else roleDrafts.set(roleSelected,draft);\n $('roleDraftState').textContent=roleDrafts.has(roleSelected)?'Unsaved draft':'Saved definition';\n if(hadDraft!==roleDrafts.has(roleSelected))renderRoleList();\n roleSync();\n}\nfunction roleSync(){document.querySelectorAll('[data-role-select]').forEach(e=>e.disabled=roleBusy);$('roleSearch').disabled=roleBusy;const blocked=!roleCanWrite();document.querySelectorAll('#roleEditor input,#roleEditor textarea,#roleEditor select,#roleEditor button').forEach(e=>e.disabled=blocked);$('roleCode').disabled=blocked||roleSelected!=='__new';$('roleDelete').disabled=blocked||roleSelected==='__new'||!!rolesData?.roles.find(r=>r.code===roleSelected)?.isDefault;$('roleSave').disabled=blocked||!roleDrafts.has(roleSelected);$('roleDiscard').disabled=roleBusy||!roleDrafts.has(roleSelected);$('roleNew').disabled=blocked;$('rolesReload').disabled=roleBusy;for(const cmd of ROLE_COMMANDS){$(`roleCooldown_${cmd}`).disabled=blocked||!rolesData.policiesAvailable||$(`rolePolicy_${cmd}`).value==='inherit';$(`rolePolicy_${cmd}`).disabled=blocked||!rolesData.policiesAvailable;}$('roleHomeLimit').disabled=blocked||!rolesData.policiesAvailable;$('roleNameColor').disabled=blocked||!rolesData.colorsAvailable;$('roleUseColors').disabled=blocked||!rolesData.colorsAvailable;}\nfunction renderRoleList(){const q=$('roleSearch').value.toLowerCase().trim();const all=rolesData?.roles||[],rows=all.filter(r=>[r.code,r.name,r.description].join(' ').toLowerCase().includes(q));$('roleListCount').textContent=`${rows.length} of ${all.length} roles${roleDrafts.size?` · ${roleDrafts.size} unsaved draft${roleDrafts.size===1?'':'s'}`:''}`;$('roleList').innerHTML=(roleDrafts.has('__new')?`<button type=\"button\" data-role-select=\"__new\" class=\"${roleSelected==='__new'?'primary':''}\" ${roleBusy?'disabled':''}><b>New Role</b><span>Unsaved draft</span></button>`:'')+rows.map(r=>`<button type=\"button\" data-role-select=\"${esc(r.code)}\" class=\"${roleSelected===r.code?'primary':''}\" ${roleBusy?'disabled':''}><b>${esc(r.name)}</b><span>${esc(r.code)} · ${r.assignedPlayers} players${r.isDefault?' · Default':''}${roleDrafts.has(r.code)?' · Unsaved draft':''}</span></button>`).join('');if(!$('roleList').innerHTML)$('roleList').innerHTML='<p class=\"small\">No matching roles.</p>';document.querySelectorAll('[data-role-select]').forEach(b=>b.onclick=()=>{if(roleBusy)return;roleSelected=b.dataset.roleSelect;renderRoleEditor();renderRoleList();});}\nfunction renderRoleEditor(){\n $('rolePreviewResult').hidden=true;\n const saved=rolesData?.roles.find(r=>r.code===roleSelected);const draft=roleDrafts.get(roleSelected);const row=draft?.row||saved;\n $('roleEditor').hidden=!row;if(!row)return;\n $('roleHeading').textContent=roleSelected==='__new'?'New Role':row.name;$('roleDraftState').textContent=draft?'Unsaved draft':'Saved definition';\n for(const [key,id] of Object.entries(roleFields))$(id).value=row[key]??'';\n $('roleGameMode').innerHTML=rolesData.gameModes.map(mode=>`<option>${esc(mode)}</option>`).join('');$('roleGameMode').value=row.defaultGameMode;\n $('roleAutoGrant').checked=!!row.autoGrant;$('roleUseColors').checked=draft?draft.useColors:rolesData.useRoleNameColors;\n const known=rolesData.knownPrivileges||[];$('rolePrivilegeList').innerHTML=known.map(code=>`<label class=\"toggleLine\" data-role-privilege-label=\"${esc(code)}\"><input type=\"checkbox\" data-role-privilege value=\"${esc(code)}\" ${row.privileges?.includes(code)?'checked':''}> <span>${esc(code)}</span></label>`).join('');$('roleExtraPrivileges').value=(row.privileges||[]).filter(code=>!known.includes(code)).join('\\n');$('roleRuntimePrivileges').textContent=`Runtime grants: ${(saved?.runtimePrivileges||[]).join(', ')||'none'}`;\n $('rolePolicyNote').textContent=`Home inheritance: global limit ${rolesData.globalHomeLimit}. Inherited teleport policies use wildcard overrides where present, then the command default. −1 keeps the inherited cooldown. Warmups remain in Player Commands.`;\n $('rolePolicies').innerHTML=ROLE_COMMANDS.map(cmd=>{const p=row.policies?.[cmd],wild=rolesData.wildcardPolicies?.[cmd],fallback=wild?.cooldownSeconds>=0?wild.cooldownSeconds:rolesData.defaultCooldowns?.[cmd];const access=wild?wild.allowed:(cmd==='t2p'||cmd==='t2m')?!!(row.autoGrant||row.privileges?.some(c=>c==='controlserver'||c==='root'||c==='*')):true;return `<div><b>/${cmd}</b><label class=\"field\">Access<select id=\"rolePolicy_${cmd}\"><option value=\"inherit\">Inherit (${access?'allowed':'denied'})</option><option value=\"allow\">Allow</option><option value=\"deny\">Deny</option></select></label><label class=\"field\">Cooldown (seconds)<input id=\"roleCooldown_${cmd}\" type=\"number\" min=\"-1\" max=\"604800\" value=\"${p?.cooldownSeconds??-1}\" required></label><small>Inherited: ${fallback??0}s</small></div>`;}).join('');for(const cmd of ROLE_COMMANDS)$(`rolePolicy_${cmd}`).value=row.policies?.[cmd]?(row.policies[cmd].allowed?'allow':'deny'):'inherit';\n roleSync();filterRolePrivileges();\n}\nfunction filterRolePrivileges(){const q=$('rolePrivilegeSearch').value.toLowerCase().trim();document.querySelectorAll('[data-role-privilege-label]').forEach(e=>e.hidden=!e.dataset.rolePrivilegeLabel.toLowerCase().includes(q));}\nasync function loadRoles(force=false){if(roleBusy)return;if(roleDrafts.size&&!force){$('rolesState').textContent='Drafts kept; reload to fetch newer definitions.';return;}if(force&&roleDrafts.size&&!confirm('Discard role drafts and reload?'))return;roleBusy=true;$('rolesState').textContent='Loading…';try{rolesData=await api('/api/roles');roleDrafts.clear();if(!rolesData.roles.some(r=>r.code===roleSelected))roleSelected=rolesData.roles[0]?.code||'';$('rolesState').textContent=rolesData.available?`${rolesData.roles.length} roles`:'Role definitions unavailable';}catch(e){toast(e.message,'error');$('rolesState').textContent=e.message;}finally{roleBusy=false;renderRoleList();renderRoleEditor();renderRoleTargets();}}\nasync function saveRole(action){if(!roleCanWrite())return;if(action!=='delete'&&!$('roleEditor').reportValidity())return;if(action==='delete'&&!confirm(`Remove ${roleSelected}? Roles assigned to players cannot be removed.`))return;roleCapture();if(action==='save'&&!roleDrafts.has(roleSelected))return;const draft=roleDrafts.get(roleSelected)||roleRead();roleBusy=true;roleSync();try{const d=await api('/api/roles',{method:'POST',body:JSON.stringify({action:action==='save'&&roleSelected==='__new'?'create':action,revision:draft.revision,role:draft.row,useRoleNameColors:draft.useColors})});if(!d.success)throw new Error(d.message);roleDrafts.delete(roleSelected);roleSelected=action==='delete'?'':draft.row.code.toLowerCase();rolesData=d.snapshot;if(!roleSelected)roleSelected=rolesData.roles[0]?.code||'';$('rolesState').textContent=`${rolesData.roles.length} roles`;toast(d.message,'success');}catch(e){toast(e.message,'error');$('rolesState').textContent=e.message;}finally{roleBusy=false;renderRoleList();renderRoleEditor();renderRoleTargets();renderRolePlayers();}}\nfunction renderRoleTargets(){const el=$('rolePlayerTarget'),selected=el.value,q=$('rolePlayerTargetSearch').value.toLowerCase().trim();const rows=(rolesData?.roles||[]).filter(r=>[r.code,r.name].join(' ').toLowerCase().includes(q));el.innerHTML=rows.map(r=>`<option value=\"${esc(r.code)}\">${esc(r.name)} (${esc(r.code)})</option>`).join('');if(rows.some(r=>r.code===selected))el.value=selected;el.disabled=!roleCanWrite();if(selected!==el.value)invalidateRoleBatch();}\nfunction renderRolePlayers(){\n $('rolePlayers').innerHTML=rolePlayersData.map((p,i)=>`<div><input type=\"checkbox\" data-role-batch-uid=\"${esc(p.playerUid)}\" aria-label=\"Select ${esc(p.playerName||p.playerUid)}\" ${currentSessionRole==='ReadOnly'?'disabled':''}><span><b>${esc(p.playerName||p.playerUid)}</b><small>${p.online?'Online':'Offline'} · ${esc(p.roleCode)}</small></span><button data-role-effective=\"${i}\">Effective Policy</button><button data-role-assign=\"${i}\" ${roleCanWrite()&&!roleAssignmentsPending.has(p.playerUid)?'':'disabled'}>${roleAssignmentsPending.has(p.playerUid)?'Assigning…':'Assign'}</button></div>`).join('')||'<p class=\"small\">No matching saved players.</p>';\n bindRolePolish();\n document.querySelectorAll('[data-role-assign]').forEach(b=>b.onclick=async()=>{\n  const p=rolePlayersData[Number(b.dataset.roleAssign)],roleCode=$('rolePlayerTarget').value;\n  if(!roleCanWrite()||!roleCode||!p||roleAssignmentsPending.has(p.playerUid))return;\n  roleAssignmentsPending.add(p.playerUid);renderRolePlayers();\n  try{const d=await api('/api/roles/player',{method:'POST',body:JSON.stringify({playerUid:p.playerUid,roleCode,expectedRoleCode:p.roleCode})});if(!d.success)throw new Error(d.message);toast(d.message,'success');await findRolePlayers();}\n  catch(e){toast(e.message,'error');}\n  finally{roleAssignmentsPending.delete(p.playerUid);renderRolePlayers();}\n });\n}\nasync function findRolePlayers(){\n if(rolePlayersLoading){rolePlayersReload=true;return;}\n rolePlayersLoading=true;rolePlayersReload=false;$('rolePlayerCount').textContent='Searching players…';\n const search=$('rolePlayerSearch').value.trim();\n try{\n  renderRoleTargets();const d=await api('/api/roles/players?search='+encodeURIComponent(search));\n  if(search!==$('rolePlayerSearch').value.trim()){rolePlayersReload=true;return;}\n  rolePlayersData=d.players||[];$('rolePlayerCount').textContent=`Showing ${rolePlayersData.length} of ${d.total}`;renderRolePlayers();\n }catch(e){$('rolePlayerCount').textContent='Search failed';toast(e.message,'error');}\n finally{rolePlayersLoading=false;if(rolePlayersReload){rolePlayersReload=false;await findRolePlayers();}}\n}\n$('roleSearch').oninput=renderRoleList;$('rolesReload').onclick=()=>loadRoles(true);$('roleNew').onclick=()=>{if(!roleCanWrite())return;roleSelected='__new';roleDrafts.set(roleSelected,{revision:rolesData.revision,useColors:rolesData.useRoleNameColors,row:{code:'',name:'',description:'',privilegeLevel:0,colorHex:'#FFFFFF',nameColorHex:'',defaultGameMode:'Survival',homeLimit:null,landClaimAllowance:0,landClaimMaxAreas:0,claimMinX:5,claimMinY:5,claimMinZ:5,privileges:[],policies:{}}});renderRoleEditor();renderRoleList();};\n$('roleEditor').onsubmit=e=>{e.preventDefault();saveRole('save');};$('roleDelete').onclick=()=>saveRole('delete');$('roleDiscard').onclick=()=>{if(roleBusy||!confirm('Discard this role draft?'))return;roleDrafts.delete(roleSelected);if(roleSelected==='__new')roleSelected=rolesData.roles[0]?.code||'';renderRoleEditor();renderRoleList();};\n$('roleEditor').addEventListener('input',e=>{if(e.target.id==='rolePrivilegeSearch')return;roleCapture();});$('roleEditor').addEventListener('change',e=>{if(e.target.id==='rolePrivilegeSearch')return;roleCapture();roleSync();});$('rolePrivilegeSearch').oninput=filterRolePrivileges;$('rolePlayerFind').onclick=findRolePlayers;$('rolePlayerTargetSearch').oninput=renderRoleTargets;$('rolePlayerSearch').onkeydown=e=>{if(e.key==='Enter')findRolePlayers();};\nwindow.addEventListener('beforeunload',e=>{if(roleDrafts.size){e.preventDefault();e.returnValue='';}});\n")
		.Replace("__NSS_PLAYER_COMMANDS_SCRIPT__", "let playerCommandsState=null;\nlet playerCommandsBaseline='',playerCommandsDirty=false,playerCommandsBusy=false,playerCommandsLoading=false;\nlet playerCommandsActiveTab='commands',playerPermissionBusy=false;\nconst PLAYER_COMMAND_DRAFT_SELECTOR='#playercommands input[id^=\"playerCmd\"],#playercommands select[id^=\"playerCmd\"],#playercommands textarea[id^=\"playerCmd\"],#playercommands [data-role-policy-mode],#playercommands [data-role-policy-access],#playercommands [data-role-policy-cooldown]';\nfunction playerCommandDraftFields(){return [...document.querySelectorAll(PLAYER_COMMAND_DRAFT_SELECTOR)].filter(e=>e.id!=='playerCmdRoleCommand');}\nfunction playerCommandDraftSignature(){return JSON.stringify(playerCommandDraftFields().map(e=>[e.id||`${e.dataset.role}:${e.dataset.rolePolicyMode||e.dataset.rolePolicyAccess||e.dataset.rolePolicyCooldown}:${e.type}`,e.type==='checkbox'?e.checked:e.value]));}\nfunction finishPlayerCommandsRender(){\n  playerCommandsBaseline=playerCommandDraftSignature();playerCommandsDirty=false;\n  syncPlayerCommandsDraftControls();\n}\nfunction updatePlayerCommandsDirty(){\n  if(!playerCommandsState?.available||playerCommandsBusy||playerCommandsLoading)return;\n  playerCommandsDirty=playerCommandDraftSignature()!==playerCommandsBaseline;\n  syncPlayerCommandsDraftControls();\n}\nfunction syncPlayerCommandsDraftControls(){\n  const pending=playerCommandsBusy||playerCommandsLoading;\n  const ro=currentSessionRole==='ReadOnly',available=playerCommandsState?.available===true;\n  const blocked=ro||!available||pending;\n  playerCommandDraftFields().forEach(el=>el.disabled=blocked);\n  if(!blocked){$('playerCmdReplyEnabled').disabled=!$('playerCmdMsgEnabled').checked;$('playerCmdWarpEnabled').disabled=!$('playerCmdWarpsEnabled').checked;}\n  syncPlayerCommandRoleControls();\n  $('playerCommandsSave').disabled=blocked||!playerCommandsDirty;\n  $('playerCommandsSave').textContent=playerCommandsBusy?'Applying…':'Save Settings';\n  $('playerCommandsDiscard').disabled=pending||!playerCommandsDirty;\n  $('playerCommandsRefresh').disabled=pending;\n  ['playerCommandsEnableAll','playerCommandsDisableAll','playerCmdRolePolicyReset'].forEach(id=>$(id).disabled=blocked);\n  document.querySelectorAll('[data-player-command-toggle]').forEach(el=>el.disabled=blocked||playerCommandsDirty);\n  $('playerCommandsDraftStatus').textContent=playerCommandsBusy?'Applying changes…':playerCommandsLoading?'Loading settings…':!available?'Settings unavailable':ro?'Read-only account':playerCommandsDirty?'Unsaved settings — save to apply':'All settings saved';\n  $('playerCommandsDraftStatus').className=playerCommandsDirty?'warn':'small';\n  $('playerCommandsDraftStatus').closest('.playerCommandSaveBar').classList.toggle('hasEdits',playerCommandsDirty);\n}\nfunction discardPlayerCommandsDraft(){\n  if(playerCommandsBusy||playerCommandsLoading||!playerCommandsDirty)return;\n  if(!confirm('Discard unsaved Player Commands settings?'))return;\n  renderPlayerCommands(playerCommandsState);\n}\nasync function reloadPlayerCommandsDraft(){\n  if(playerCommandsBusy||playerCommandsLoading)return;\n  if(playerCommandsDirty){\n    if(!confirm('Discard unsaved Player Commands settings and reload from the server?'))return;\n    renderPlayerCommands(playerCommandsState);\n  }\n  await loadPlayerCommands(true);\n}\nfunction setPlayerCommandTab(tab){\n  const tabs=[...document.querySelectorAll('[data-player-command-tab]')];\n  if(!tabs.some(b=>b.dataset.playerCommandTab===tab))return;\n  playerCommandsActiveTab=tab;\n  tabs.forEach(b=>{const selected=b.dataset.playerCommandTab===tab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;$(b.getAttribute('aria-controls')).hidden=!selected;});\n  if(tab==='permissions'&&!playerPermissionState)loadPlayerPermissions(false);\n  if(currentSection==='playercommands')setTimeout(syncWorkspacePage,0);\n}\nfunction renderPlayerCommandDirectory(){\n  const commands=Array.isArray(playerCommandsState?.commands)?playerCommandsState.commands:[];\n  const query=$('playerCommandSearch').value.trim().toLowerCase(),filter=$('playerCommandFilter').value;\n  const shown=commands.filter(c=>{\n    const external=!c.rootOwnedBySuite&&c.rootProvider&&c.rootProvider!=='Unregistered';\n    return (!query||[c.command,c.fallbackCommand,c.description,c.requiredPrivilege,c.rootProvider].join(' ').toLowerCase().includes(query))&&(filter==='all'||filter==='enabled'&&c.enabled||filter==='disabled'&&!c.enabled||filter==='external'&&external);\n  });\n  $('playerCommandResultCount').textContent=`${shown.length} of ${commands.length} commands`;\n  $('playerCommandsRows').innerHTML=shown.map(c=>{\n    const individual=c.individuallyEnabled!==false,provider=String(c.rootProvider||'Unknown');\n    const external=!c.rootOwnedBySuite&&provider!=='Unregistered';\n    const label=c.enabled?'Suite enabled':individual?'Feature or provider off':'Suite disabled';\n    return `<article class=\"playerCommandEntry\"><div class=\"playerCommandEntryHead\"><code>${esc(c.command||'')}</code><span class=\"badge ${c.enabled?'low':'medium'}\">${label}</span></div><p>${esc(c.description||'')}</p><dl class=\"playerCommandFacts\"><dt>Root alias</dt><dd class=\"${playerCommandProviderTone(provider)}\">${esc(provider)}</dd><dt>Fallback</dt><dd><code>${esc(c.fallbackCommand||'—')}</code></dd><dt>Privilege</dt><dd><code>${esc(c.requiredPrivilege||'chat')}</code></dd></dl><div class=\"playerCommandEntryFoot\"><span class=\"small\">${external?'Changes affect the Suite fallback.':'Individual switch applies now.'}</span><button data-player-command-toggle=\"${esc(c.key||'')}\" data-command-enabled=\"${individual}\" aria-label=\"${individual?'Disable':'Enable'} Suite ${esc(c.command||'')}\"${individual?'':' class=\"primary\"'}>${individual?'Disable Suite':'Enable Suite'}</button></div></article>`;\n  }).join('')||'<div class=\"empty\">No commands match these filters.</div>';\n  document.querySelectorAll('[data-player-command-toggle]').forEach(b=>b.onclick=()=>togglePlayerCommand(b.dataset.playerCommandToggle,b.dataset.commandEnabled!=='true'));\n  syncPlayerCommandsDraftControls();\n}\nfunction revealPlayerCommandField(el){\n  const panel=el.closest('.playerCommandPanel');if(panel)setPlayerCommandTab(panel.id.replace('playerCommandPanel-',''));\n  const roleCmd=el.dataset.rolePolicyCooldown||el.dataset.rolePolicyMode||el.dataset.rolePolicyAccess;\n  if(roleCmd){$('playerCmdRoleCommand').value=roleCmd;filterPlayerCommandRoleColumns();}\n  const card=el.closest('.workspaceCard');if(card)setWorkspaceCardCollapsed(card,false);\n  el.focus();el.scrollIntoView({block:'center',behavior:'smooth'});\n}\nfunction validatePlayerCommandsDraft(){\n  for(const el of playerCommandDraftFields().filter(e=>e.type==='number'&&!e.disabled)){\n    if(el.value.trim()===''||!Number.isInteger(Number(el.value))||!el.checkValidity()){\n      revealPlayerCommandField(el);el.reportValidity();throw new Error('Enter a whole number within the displayed limits.');\n    }\n  }\n  for(const id of ['playerCmdHomeRoleLimits','playerCmdHomePlayerLimits']){\n    try{playerCommandLimitTextToMap($(id).value);}catch(e){revealPlayerCommandField($(id));throw e;}\n  }\n  if(Number($('playerCmdRtpMaxRadius').value)<Number($('playerCmdRtpMinRadius').value)){\n    revealPlayerCommandField($('playerCmdRtpMaxRadius'));throw new Error('RTP maximum radius must be at least the minimum radius.');\n  }\n  if($('playerCmdRtpCostEnabled').checked&&!$('playerCmdRtpCostItem').value.trim()){\n    revealPlayerCommandField($('playerCmdRtpCostItem'));throw new Error('Set an item code before enabling an RTP cost.');\n  }\n}\nfunction filterPlayerPermissionRows(){\n  const query=($('playerPermissionSearch')?.value||'').trim().toLowerCase();\n  const rows=[...document.querySelectorAll('#playerPermPlayerRows tr[data-player-permission-search]')];\n  rows.forEach(row=>row.hidden=!!query&&!row.dataset.playerPermissionSearch.includes(query));\n  if($('playerPermissionSearchCount'))$('playerPermissionSearchCount').textContent=`${rows.filter(r=>!r.hidden).length} of ${rows.length} online players`;\n}\n\n\nfunction playerCommandProviderTone(provider){\n  const p=String(provider||'').toLowerCase();\n  if(p.includes(\"newfie's server essentials\"))return 'good';\n  if(p.includes('th3essentials'))return 'warn';\n  if(p.includes('another'))return 'warn';\n  return 'neutral';\n}\n\nfunction playerCommandLimitMapToText(obj){\n  return Object.entries(obj||{}).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))).map(([k,v])=>`${k}=${Number(v||0)}`).join('\\n');\n}\nfunction playerCommandLimitTextToMap(text){\n  const out={};\n  String(text||'').split(/\\r?\\n|,/).forEach((raw,index)=>{\n    const line=raw.trim();if(!line||line.startsWith('#'))return;\n    const match=line.match(/^([^=]+)=\\s*(\\d+)\\s*$/);\n    if(!match||Number(match[2])>100)throw new Error(`Home limit line ${index+1}: use name=limit with a whole number from 0 to 100.`);\n    const key=match[1].trim();\n    if(Object.keys(out).some(k=>k.toLowerCase()===key.toLowerCase()))throw new Error(`Duplicate home limit for ${key}.`);\n    Object.defineProperty(out,key,{value:Number(match[2]),enumerable:true,configurable:true,writable:true});\n  });\n  return out;\n}\n\nconst TELEPORT_ROLE_COMMANDS=['spawn','home','back','warp','t2p','t2m','rtp'];\nfunction rolePolicyFor(d,command,role){\n  const map=d?.teleportRolePolicies?.[command]||{};\n  return map[role]||map[String(role||'').toLowerCase()]||null;\n}\nfunction defaultTeleportRoleAccess(role,command){\n  if(command!=='t2p'&&command!=='t2m')return true;\n  const privs=Array.isArray(role?.privileges)?role.privileges.map(x=>String(x||'').toLowerCase()):[];\n  return privs.includes('root')||privs.includes('controlserver');\n}\nfunction renderTeleportRolePolicies(d){\n  const host=$('playerCmdRolePolicyRows');if(!host)return;\n  const roles=(Array.isArray(d?.availableRoles)?d.availableRoles:[]).map(r=>({...r,code:String(r.code||'').toLowerCase()}));\n  const seen=new Set(roles.map(r=>r.code));\n  for(const map of Object.values(d?.teleportRolePolicies||{}))for(const code of Object.keys(map||{})){\n    if(!seen.has(code.toLowerCase())){roles.push({code:code.toLowerCase(),name:code==='*'?'All roles (*)':`${code} (saved policy)`,privileges:[]});seen.add(code.toLowerCase());}\n  }\n  if(!roles.length){host.innerHTML='<tr><td colspan=\"4\" class=\"muted\">No server roles were returned.</td></tr>';return;}\n  host.innerHTML=roles.map(r=>{\n    const code=r.code;\n    const cells=TELEPORT_ROLE_COMMANDS.map(cmd=>{\n      const pol=rolePolicyFor(d,cmd,code);\n      const fallback=code!=='*'?rolePolicyFor(d,cmd,'*'):null;\n      const defaultAllowed=fallback?fallback.allowed!==false:defaultTeleportRoleAccess(r,cmd);\n      const defaultCooldown=fallback?Number(fallback.cooldownSeconds??-1):-1;\n      return `<td data-role-command-cell=\"${cmd}\"><select aria-label=\"/${cmd} policy for ${esc(code)}\" data-role-policy-mode=\"${cmd}\" data-role=\"${esc(code)}\"><option value=\"inherit\"${!pol?' selected':''}>Inherited</option><option value=\"override\"${pol?' selected':''}>Override</option></select></td><td data-role-command-cell=\"${cmd}\"><input type=\"checkbox\" aria-label=\"Allow /${cmd} for ${esc(code)}\" data-role-policy-access=\"${cmd}\" data-role=\"${esc(code)}\" data-default-allowed=\"${defaultTeleportRoleAccess(r,cmd)?'true':'false'}\"${(pol?pol.allowed!==false:defaultAllowed)?' checked':''}></td><td data-role-command-cell=\"${cmd}\"><input type=\"number\" min=\"-1\" max=\"604800\" step=\"1\" required value=\"${Number(pol?.cooldownSeconds??defaultCooldown)}\" aria-label=\"/${cmd} cooldown for ${esc(code)}\" data-role-policy-cooldown=\"${cmd}\" data-role=\"${esc(code)}\"></td>`;\n    }).join('');\n    return `<tr><td><b>${esc(r.name||code)}</b><br><code>${esc(code)}</code></td>${cells}</tr>`;\n  }).join('');\n  syncPlayerCommandRoleControls();\n  filterPlayerCommandRoleColumns();\n}\nfunction syncPlayerCommandRoleControls(){\n  const blocked=currentSessionRole==='ReadOnly'||!playerCommandsState?.available||playerCommandsBusy||playerCommandsLoading;\n  const modes=[...document.querySelectorAll('[data-role-policy-mode]')];\n  modes.forEach(mode=>{\n    const cmd=mode.dataset.rolePolicyMode,role=mode.dataset.role;\n    const access=[...document.querySelectorAll(`[data-role-policy-access=\"${cmd}\"]`)].find(x=>x.dataset.role===role);\n    const cool=[...document.querySelectorAll(`[data-role-policy-cooldown=\"${cmd}\"]`)].find(x=>x.dataset.role===role);\n    mode.disabled=blocked;access.disabled=cool.disabled=blocked||mode.value==='inherit';\n    if(mode.value==='inherit'){\n      const wildcard=modes.find(x=>x.dataset.rolePolicyMode===cmd&&x.dataset.role==='*'&&x.value==='override');\n      const wildcardRow=wildcard?.closest('tr');\n      access.checked=wildcard&&role!=='*'?wildcardRow.querySelector(`[data-role-policy-access=\"${cmd}\"]`).checked:access.dataset.defaultAllowed==='true';\n      cool.value=wildcard&&role!=='*'?wildcardRow.querySelector(`[data-role-policy-cooldown=\"${cmd}\"]`).value:'-1';\n    }\n  });\n}\nfunction filterPlayerCommandRoleColumns(){\n  const cmd=$('playerCmdRoleCommand').value;\n  document.querySelectorAll('[data-role-command-cell]').forEach(cell=>cell.hidden=cell.dataset.roleCommandCell!==cmd);\n}\nfunction collectTeleportRolePolicies(){\n  // Keep saved policies for roles absent from the current role list; inheritance\n  // must stay inheritance rather than being saved as a new explicit override.\n  const out=JSON.parse(JSON.stringify(playerCommandsState?.teleportRolePolicies||{}));\n  document.querySelectorAll('[data-role-policy-mode]').forEach(mode=>{\n    const cmd=mode.dataset.rolePolicyMode,role=mode.dataset.role;\n    out[cmd]??={};\n    if(mode.value==='inherit'){delete out[cmd][role];return;}\n    const row=mode.closest('tr');\n    const access=row.querySelector(`[data-role-policy-access=\"${cmd}\"]`);\n    const cool=row.querySelector(`[data-role-policy-cooldown=\"${cmd}\"]`);\n    Object.defineProperty(out[cmd],role,{value:{allowed:access.checked,cooldownSeconds:Number(cool.value)},enumerable:true,configurable:true,writable:true});\n  });\n  Object.keys(out).forEach(cmd=>{if(!Object.keys(out[cmd]).length)delete out[cmd];});\n  return out;\n}\nfunction resetTeleportRolePolicies(){\n  if(currentSessionRole==='ReadOnly'||playerCommandsBusy||!playerCommandsState?.available)return;\n  document.querySelectorAll('[data-role-policy-mode]').forEach(e=>e.value='inherit');\n  syncPlayerCommandRoleControls();updatePlayerCommandsDirty();\n  toast('Role overrides cleared in the draft. Save Settings to apply.','success');\n}\n\nfunction renderPlayerCommands(d){\n  playerCommandsState=d||null;\n  const available=!!d?.available;\n  const th3=!!d?.th3EssentialsDetected;\n  const ro=currentSessionRole==='ReadOnly';\n  if(!available){\n    $('playerCommandsNotice').className='warning';\n    $('playerCommandsNotice').innerHTML='<b>Player Commands feature is not running.</b> Enable the <code>playercommands</code> feature gate under Web Server → Suite Feature Gates, then restart the server.';\n    $('playerCommandsMetrics').innerHTML=metric('Module','Not running','warn')+metric('Live settings','Unavailable','warn');\n    $('playerCommandsRows').innerHTML='<div class=\"empty\">Player Commands service is unavailable.</div>';\n    ['playerCmdSpawnEnabled','playerCmdSpawnCooldown','playerCmdSpawnWarmup','playerCmdSpawnCancelMove','playerCmdMsgEnabled','playerCmdReplyEnabled','playerCmdRespectMutes','playerCmdMaxLength','playerCmdStarterEnabled','playerCmdStarterProvider','playerCmdWarpsEnabled','playerCmdWarpEnabled','playerCmdBackEnabled','playerCmdBackDeaths','playerCmdBackTeleports','playerCmdBackCancelMove','playerCmdBackCooldown','playerCmdBackWarmup','playerCmdHomesEnabled','playerCmdHomeCancelMove','playerCmdHomeGlobalLimit','playerCmdHomeCooldown','playerCmdHomeWarmup','playerCmdHomeRoleLimits','playerCmdHomePlayerLimits','playerCmdT2pEnabled','playerCmdT2pCooldown','playerCmdT2mEnabled','playerCmdT2mCooldown','playerCmdRtpEnabled','playerCmdRtpCancelMove','playerCmdRtpAvoidLiquids','playerCmdRtpCenterPlayer','playerCmdRtpCostEnabled','playerCmdRtpMinRadius','playerCmdRtpMaxRadius','playerCmdRtpCooldown','playerCmdRtpWarmup','playerCmdRtpCostItem','playerCmdRtpCostQty','playerCmdRtpAttempts','playerCommandsEnableAll','playerCommandsDisableAll','playerCmdRolePolicyReset','playerCommandsSave'].forEach(id=>{const e=$(id);if(e)e.disabled=true;});\n    renderTeleportRolePolicies(d);\n    finishPlayerCommandsRender();\n    setNavStatus('playercommands','warn','Player Commands feature is not running');\n    return;\n  }\n\n  const commands=Array.isArray(d.commands)?d.commands:[];\n  $('playerCommandsNotice').className=th3?'warning':'infoBox';\n  $('playerCommandsNotice').innerHTML=th3\n    ? '<b>Th3Essentials compatibility mode is active.</b> NSE deliberately leaves the root <code>/spawn</code>, <code>/msg</code>, <code>/r</code>, <code>/starterkit</code>, and starter-kit administration aliases to Th3Essentials. The Starter Kit Provider setting below controls NSE starter-kit fallback behavior and never disables Th3Essentials commands.'\n    : '<b>NSE player commands are active.</b> Free root aliases are registered once at startup; enable/disable changes below are enforced live without a restart.';\n\n  $('playerCommandsMetrics').innerHTML=\n    metric('Suite commands',`${commands.filter(c=>c.enabled).length} / ${commands.length} enabled`,'good')+\n    metric('Other providers',commands.filter(c=>!c.rootOwnedBySuite&&c.rootProvider!=='Unregistered').length,th3?'warn':'neutral')+\n    metric('Teleport policies',Object.values(d.teleportRolePolicies||{}).reduce((sum,map)=>sum+Object.keys(map||{}).length,0),'neutral')+\n    metric('Warps',d.warpsEnabled?`${Number(d.warpCount||0)} destinations`:'Disabled',d.warpsEnabled?'good':'neutral');\n\n  $('playerCmdSpawnEnabled').checked=!!d.spawnEnabled;\n  $('playerCmdSpawnCooldown').value=Number(d.spawnCooldownSeconds??60);\n  $('playerCmdSpawnWarmup').value=Number(d.spawnWarmupSeconds??5);\n  $('playerCmdSpawnCancelMove').checked=d.spawnCancelOnMove!==false;\n  $('playerCmdMsgEnabled').checked=!!d.privateMessagesEnabled;\n  $('playerCmdReplyEnabled').checked=!!d.replyEnabled;\n  $('playerCmdRespectMutes').checked=!!d.respectSuiteMutes;\n  $('playerCmdMaxLength').value=Number(d.maxPrivateMessageLength??500);\n  $('playerCmdStarterEnabled').checked=!!d.starterKitEnabled;\n  $('playerCmdStarterProvider').value=String(d.starterKitProvider||'Auto');\n  $('playerCmdWarpsEnabled').checked=d.warpsEnabled!==false;\n  $('playerCmdWarpEnabled').checked=d.warpCommandEnabled!==false;\n  $('playerCmdBackEnabled').checked=d.backEnabled!==false;\n  $('playerCmdBackDeaths').checked=d.backTrackDeaths!==false;\n  $('playerCmdBackTeleports').checked=d.backTrackTeleports!==false;\n  $('playerCmdBackCancelMove').checked=d.backCancelOnMove!==false;\n  $('playerCmdBackCooldown').value=Number(d.backCooldownSeconds??30);\n  $('playerCmdBackWarmup').value=Number(d.backWarmupSeconds??5);\n  $('playerCmdHomesEnabled').checked=d.homesEnabled!==false;\n  $('playerCmdHomeCancelMove').checked=d.homeCancelOnMove!==false;\n  $('playerCmdHomeGlobalLimit').value=Number(d.homeGlobalLimit??2);\n  $('playerCmdHomeCooldown').value=Number(d.homeCooldownSeconds??60);\n  $('playerCmdHomeWarmup').value=Number(d.homeWarmupSeconds??5);\n  $('playerCmdHomeRoleLimits').value=playerCommandLimitMapToText(d.homeRoleLimits);\n  $('playerCmdHomePlayerLimits').value=playerCommandLimitMapToText(d.homePlayerLimits);\n  $('playerCmdT2pEnabled').checked=d.t2pEnabled!==false;\n  $('playerCmdT2pCooldown').value=Number(d.t2pCooldownSeconds??30);\n  $('playerCmdT2mEnabled').checked=d.t2mEnabled!==false;\n  $('playerCmdT2mCooldown').value=Number(d.t2mCooldownSeconds??30);\n  $('playerCmdRtpEnabled').checked=d.rtpEnabled!==false;\n  $('playerCmdRtpCancelMove').checked=d.rtpCancelOnMove!==false;\n  $('playerCmdRtpAvoidLiquids').checked=d.rtpAvoidWaterAndLava!==false;\n  $('playerCmdRtpCenterPlayer').checked=!!d.rtpCenterOnPlayerPosition;\n  $('playerCmdRtpCostEnabled').checked=!!d.rtpCostEnabled;\n  $('playerCmdRtpMinRadius').value=Number(d.rtpMinRadius??1000);\n  $('playerCmdRtpMaxRadius').value=Number(d.rtpMaxRadius??10000);\n  $('playerCmdRtpCooldown').value=Number(d.rtpCooldownSeconds??1800);\n  $('playerCmdRtpWarmup').value=Number(d.rtpWarmupSeconds??10);\n  $('playerCmdRtpCostItem').value=String(d.rtpCostItemCode||'game:gear-rusty');\n  $('playerCmdRtpCostQty').value=Number(d.rtpCostQuantity??1);\n  $('playerCmdRtpAttempts').value=Number(d.rtpMaxSearchAttempts??20);\n  renderTeleportRolePolicies(d);\n  $('playerCmdStarterStatus').textContent=`Effective: ${d.starterKitEffectiveProvider||'NSE'} · ${d.starterKitItemCount||0} item stack(s) · ${d.starterKitClaimedCount||0} claim(s)`;\n\n  renderPlayerCommandDirectory();\n\n  ['playerCmdSpawnEnabled','playerCmdSpawnCooldown','playerCmdSpawnWarmup','playerCmdSpawnCancelMove','playerCmdMsgEnabled','playerCmdReplyEnabled','playerCmdRespectMutes','playerCmdMaxLength','playerCmdStarterEnabled','playerCmdStarterProvider','playerCmdWarpsEnabled','playerCmdWarpEnabled','playerCmdBackEnabled','playerCmdBackDeaths','playerCmdBackTeleports','playerCmdBackCancelMove','playerCmdBackCooldown','playerCmdBackWarmup','playerCmdHomesEnabled','playerCmdHomeCancelMove','playerCmdHomeGlobalLimit','playerCmdHomeCooldown','playerCmdHomeWarmup','playerCmdHomeRoleLimits','playerCmdHomePlayerLimits','playerCmdT2pEnabled','playerCmdT2pCooldown','playerCmdT2mEnabled','playerCmdT2mCooldown','playerCmdRtpEnabled','playerCmdRtpCancelMove','playerCmdRtpAvoidLiquids','playerCmdRtpCenterPlayer','playerCmdRtpCostEnabled','playerCmdRtpMinRadius','playerCmdRtpMaxRadius','playerCmdRtpCooldown','playerCmdRtpWarmup','playerCmdRtpCostItem','playerCmdRtpCostQty','playerCmdRtpAttempts','playerCommandsEnableAll','playerCommandsDisableAll','playerCmdRolePolicyReset','playerCommandsSave'].forEach(id=>{const e=$(id);if(e)e.disabled=ro;});\n  $('playerCmdReplyEnabled').disabled=ro||!$('playerCmdMsgEnabled').checked;\n  $('playerCmdWarpEnabled').disabled=ro||!$('playerCmdWarpsEnabled').checked;\n  finishPlayerCommandsRender();\n  setNavStatus('playercommands',th3?'warn':'good',th3?'NSE yielded root player-command aliases for Th3Essentials compatibility':'NSE player commands are available');\n}\n\nasync function loadPlayerCommands(showLoading=true){\n  if(playerCommandsDirty||playerCommandsBusy||playerCommandsLoading)return;\n  playerCommandsLoading=true;syncPlayerCommandsDraftControls();\n  if(showLoading&&$('playerCommandsNotice'))$('playerCommandsNotice').textContent='Loading player command status…';\n  try{\n    const d=await api('/api/playercommands');\n    renderPlayerCommands(d);\n    if(playerCommandsActiveTab==='permissions')await loadPlayerPermissions(false);\n  }catch(e){\n    $('playerCommandsNotice').className='warning';\n    $('playerCommandsNotice').textContent=e.message;\n    setNavStatus('playercommands','bad',e.message);\n  }finally{playerCommandsLoading=false;syncPlayerCommandsDraftControls();}\n}\n\nlet playerPermissionState=null;\nfunction renderPlayerPermissions(d){\n  playerPermissionState=d||{}; const ro=currentSessionRole==='ReadOnly';\n  const roles=Array.isArray(d?.roles)?d.roles:[], players=Array.isArray(d?.onlinePlayers)?d.onlinePlayers:[], known=Array.isArray(d?.knownPrivileges)?d.knownPrivileges:[];\n  if($('playerPermRoleRows'))$('playerPermRoleRows').innerHTML=roles.map(r=>`<tr><td><b>${esc(r.name||r.code)}</b><div class=\"small\"><code>${esc(r.code)}</code>${r.description?` · ${esc(r.description)}`:''}</div></td><td>${Number(r.privilegeLevel||0)}</td><td><div class=\"small\"><details><summary>${(r.privileges||[]).length} privileges</summary>${(r.privileges||[]).map(p=>`<code>${esc(p)}</code>`).join(' ')||'<span class=\"muted\">None</span>'}</details></div></td></tr>`).join('')||'<tr><td colspan=\"3\" class=\"muted\">No configured roles returned.</td></tr>';\n  if($('playerPermPlayerRows'))$('playerPermPlayerRows').innerHTML=players.map(p=>{\n    const roleOpts=roles.map(r=>`<option value=\"${esc(r.code)}\" ${String(r.code)===String(p.roleCode)?'selected':''}>${esc(r.name||r.code)} (${esc(r.code)})</option>`).join('');\n  \n    return `<tr data-player-permission-search=\"${esc([p.playerName,p.playerUid,p.roleCode,p.roleName].join(' ').toLowerCase())}\"><td>${playerIdentityHtml(p,'playerName',true)}</td><td><select data-perm-role=\"${esc(p.playerUid)}\" ${ro?'disabled':''}>${roleOpts}</select></td><td><div class=\"small\">${(p.permanentPrivileges||[]).map(v=>`<code>${esc(v)}</code>`).join(' ')||'<span class=\"muted\">None</span>'}</div></td><td><div class=\"small\">${(p.deniedPrivileges||[]).map(v=>`<code>${esc(v)}</code>`).join(' ')||'<span class=\"muted\">None</span>'}</div></td><td><input list=\"playerPermissionPrivilegeOptions\" data-perm-value=\"${esc(p.playerUid)}\" placeholder=\"Privilege code\" aria-label=\"Privilege for ${esc(p.playerName||p.playerUid)}\" ${ro?'disabled':''}><div class=\"quickActions\" style=\"margin-top:5px\"><button data-perm-act=\"grant\" data-uid=\"${esc(p.playerUid)}\" ${ro?'disabled':''}>Grant</button><button data-perm-act=\"revoke\" data-uid=\"${esc(p.playerUid)}\" ${ro?'disabled':''}>Revoke</button><button data-perm-act=\"deny\" data-uid=\"${esc(p.playerUid)}\" ${ro?'disabled':''}>Deny</button><button data-perm-act=\"undeny\" data-uid=\"${esc(p.playerUid)}\" ${ro?'disabled':''}>Un-deny</button></div></td></tr>`;\n  }).join('')||'<tr><td colspan=\"5\" class=\"muted\">No online players.</td></tr>';\n  $('playerPermissionPrivilegeOptions').innerHTML=known.map(v=>`<option value=\"${esc(v)}\"></option>`).join('');\n  filterPlayerPermissionRows();\n  document.querySelectorAll('[data-perm-role]').forEach(e=>e.onchange=()=>changePlayerPermission(e.dataset.permRole,'set-role',e.value));\n  document.querySelectorAll('[data-perm-act]').forEach(b=>b.onclick=()=>{const uid=b.dataset.uid, sel=document.querySelector(`[data-perm-value=\"${CSS.escape(uid)}\"]`); changePlayerPermission(uid,b.dataset.permAct,sel?.value||'');});\n}\nasync function loadPlayerPermissions(showLoading=true){\n  if(showLoading&&$('playerPermRoleRows'))$('playerPermRoleRows').innerHTML='<tr><td colspan=\"3\" class=\"muted\">Loading roles and privileges…</td></tr>';\n  try{renderPlayerPermissions(await api('/api/playercommands/permissions'));}catch(e){if($('playerPermRoleRows'))$('playerPermRoleRows').innerHTML=`<tr><td colspan=\"3\" class=\"bad\">${esc(e.message)}</td></tr>`;}\n}\nasync function changePlayerPermission(uid,action,value){\n  value=String(value||'').trim();\n  if(currentSessionRole==='ReadOnly'||!uid||playerPermissionBusy)return;\n  if(!value){toast('Choose a privilege code first.','error');return;}\n  if(action==='set-role'&&!confirm(`Change this player's role to ${value}? This can alter many permissions at once.`)){await loadPlayerPermissions(false);return;}\n  playerPermissionBusy=true;\n  document.querySelectorAll('[data-perm-role],[data-perm-value],[data-perm-act]').forEach(el=>el.disabled=true);\n  try{const d=await api('/api/playercommands/permissions',{method:'POST',body:JSON.stringify({playerUid:uid,action,value})});toast(d.message||'Permission updated.','success');renderPlayerPermissions(d.permissions||await api('/api/playercommands/permissions'));if(!playerCommandsDirty)await loadPlayerCommands(false);}catch(e){toast(e.message,'error');await loadPlayerPermissions(false);}\n  finally{playerPermissionBusy=false;document.querySelectorAll('[data-perm-role],[data-perm-value],[data-perm-act]').forEach(el=>el.disabled=currentSessionRole==='ReadOnly');}\n}\n\nasync function togglePlayerCommand(key,enabled){\n  if(currentSessionRole==='ReadOnly'||!key||playerCommandsBusy||!playerCommandsState?.available)return;\n  if(playerCommandsDirty){toast('Save or discard your policy edits before applying an individual command switch.','error');return;}\n  playerCommandsBusy=true;syncPlayerCommandsDraftControls();\n  try{\n    const d=await api('/api/playercommands/command',{method:'POST',body:JSON.stringify({key,enabled})});\n    renderPlayerCommands(d.playerCommands||await api('/api/playercommands'));\n    toast(d.message||`Command ${enabled?'enabled':'disabled'}.`,'success');\n  }catch(e){toast(e.message,'error');}\n  finally{playerCommandsBusy=false;syncPlayerCommandsDraftControls();}\n}\n\nasync function savePlayerCommands(){\n  if(currentSessionRole==='ReadOnly'||!playerCommandsState?.available||playerCommandsBusy||playerCommandsLoading)return;\n  try{\n    validatePlayerCommandsDraft();\n    const payload={\n    spawnEnabled:!!$('playerCmdSpawnEnabled').checked,\n    spawnCooldownSeconds:Math.round(Number($('playerCmdSpawnCooldown').value||0)),\n    spawnWarmupSeconds:Math.round(Number($('playerCmdSpawnWarmup').value||0)),\n    spawnCancelOnMove:!!$('playerCmdSpawnCancelMove').checked,\n    privateMessagesEnabled:!!$('playerCmdMsgEnabled').checked,\n    replyEnabled:!!$('playerCmdReplyEnabled').checked,\n    respectSuiteMutes:!!$('playerCmdRespectMutes').checked,\n    maxPrivateMessageLength:Math.round(Number($('playerCmdMaxLength').value||500)),\n    starterKitEnabled:!!$('playerCmdStarterEnabled').checked,\n    starterKitProvider:$('playerCmdStarterProvider').value||'Auto',\n    warpsEnabled:!!$('playerCmdWarpsEnabled').checked,\n    warpCommandEnabled:!!$('playerCmdWarpEnabled').checked,\n    backEnabled:!!$('playerCmdBackEnabled').checked,\n    backCooldownSeconds:Math.round(Number($('playerCmdBackCooldown').value||0)),\n    backWarmupSeconds:Math.round(Number($('playerCmdBackWarmup').value||0)),\n    backCancelOnMove:!!$('playerCmdBackCancelMove').checked,\n    backTrackDeaths:!!$('playerCmdBackDeaths').checked,\n    backTrackTeleports:!!$('playerCmdBackTeleports').checked,\n    homesEnabled:!!$('playerCmdHomesEnabled').checked,\n    homeGlobalLimit:Math.round(Number($('playerCmdHomeGlobalLimit').value||0)),\n    homeRoleLimits:playerCommandLimitTextToMap($('playerCmdHomeRoleLimits').value),\n    homePlayerLimits:playerCommandLimitTextToMap($('playerCmdHomePlayerLimits').value),\n    homeCooldownSeconds:Math.round(Number($('playerCmdHomeCooldown').value||0)),\n    homeWarmupSeconds:Math.round(Number($('playerCmdHomeWarmup').value||0)),\n    homeCancelOnMove:!!$('playerCmdHomeCancelMove').checked,\n    t2pEnabled:!!$('playerCmdT2pEnabled').checked,\n    t2pCooldownSeconds:Math.round(Number($('playerCmdT2pCooldown').value||0)),\n    t2mEnabled:!!$('playerCmdT2mEnabled').checked,\n    t2mCooldownSeconds:Math.round(Number($('playerCmdT2mCooldown').value||0)),\n    rtpEnabled:!!$('playerCmdRtpEnabled').checked,\n    rtpMinRadius:Math.round(Number($('playerCmdRtpMinRadius').value||0)),\n    rtpMaxRadius:Math.round(Number($('playerCmdRtpMaxRadius').value||0)),\n    rtpCooldownSeconds:Math.round(Number($('playerCmdRtpCooldown').value||0)),\n    rtpWarmupSeconds:Math.round(Number($('playerCmdRtpWarmup').value||0)),\n    rtpCancelOnMove:!!$('playerCmdRtpCancelMove').checked,\n    rtpCostEnabled:!!$('playerCmdRtpCostEnabled').checked,\n    rtpCostItemCode:$('playerCmdRtpCostItem').value.trim(),\n    rtpCostQuantity:Math.round(Number($('playerCmdRtpCostQty').value||1)),\n    rtpMaxSearchAttempts:Math.round(Number($('playerCmdRtpAttempts').value||20)),\n    rtpAvoidWaterAndLava:!!$('playerCmdRtpAvoidLiquids').checked,\n    rtpCenterOnPlayerPosition:!!$('playerCmdRtpCenterPlayer').checked,\n    teleportRolePolicies:collectTeleportRolePolicies(),\n    rolePolicyRevision:playerCommandsState?.rolePolicyRevision\n  };\n    playerCommandsBusy=true;syncPlayerCommandsDraftControls();\n    const d=await api('/api/playercommands/settings',{method:'POST',body:JSON.stringify(payload)});\n    toast(d.message||'Player command settings saved.','success');\n    renderPlayerCommands(d.playerCommands||await api('/api/playercommands'));\n  }catch(e){toast(e.message,'error');}\n  finally{playerCommandsBusy=false;syncPlayerCommandsDraftControls();}\n}\n\nfunction setAllPlayerCommands(enabled){\n  if(currentSessionRole==='ReadOnly'||playerCommandsBusy||!playerCommandsState?.available)return;\n  $('playerCmdSpawnEnabled').checked=enabled;\n  $('playerCmdMsgEnabled').checked=enabled;\n  $('playerCmdReplyEnabled').checked=enabled;\n  $('playerCmdStarterEnabled').checked=enabled;\n  $('playerCmdWarpsEnabled').checked=enabled;\n  $('playerCmdWarpEnabled').checked=enabled;\n  $('playerCmdBackEnabled').checked=enabled;\n  $('playerCmdHomesEnabled').checked=enabled;\n  $('playerCmdT2pEnabled').checked=enabled;\n  $('playerCmdT2mEnabled').checked=enabled;\n  $('playerCmdRtpEnabled').checked=enabled;\n  $('playerCmdReplyEnabled').disabled=currentSessionRole==='ReadOnly'||!enabled;\n  $('playerCmdWarpEnabled').disabled=currentSessionRole==='ReadOnly'||!enabled;\n  updatePlayerCommandsDirty();\n}\n\n$('playerCommandsRefresh').onclick=()=>reloadPlayerCommandsDraft();\n$('playerCommandsDiscard').onclick=()=>discardPlayerCommandsDraft();\nif($('playerPermRefresh'))$('playerPermRefresh').onclick=()=>loadPlayerPermissions(true);\nif($('playerCmdRolePolicyReset'))$('playerCmdRolePolicyReset').onclick=resetTeleportRolePolicies;\n$('playerCommandsSave').onclick=savePlayerCommands;\n$('playerCommandsEnableAll').onclick=()=>setAllPlayerCommands(true);\n$('playerCommandsDisableAll').onclick=()=>setAllPlayerCommands(false);\n$('playerCommandSearch').oninput=renderPlayerCommandDirectory;\n$('playerCommandFilter').onchange=renderPlayerCommandDirectory;\n$('playerCmdRoleCommand').onchange=filterPlayerCommandRoleColumns;\n$('playerCmdMsgEnabled').addEventListener('change',()=>{$('playerCmdReplyEnabled').disabled=currentSessionRole==='ReadOnly'||!$('playerCmdMsgEnabled').checked;});\n$('playerCmdWarpsEnabled').addEventListener('change',()=>{$('playerCmdWarpEnabled').disabled=currentSessionRole==='ReadOnly'||!$('playerCmdWarpsEnabled').checked;});\n\n// Draft inputs are scoped to this feature; searching and switching tabs is not an edit.\nplayerCommandDraftFields().filter(el=>el.type==='number').forEach(el=>{el.required=true;el.step='1';});\n$('playercommands').addEventListener('input',event=>{\n  if(!event.target.matches(PLAYER_COMMAND_DRAFT_SELECTOR)||event.target.id==='playerCmdRoleCommand')return;\n  if(event.target.matches('[data-role-policy-mode],[data-role-policy-access],[data-role-policy-cooldown]'))syncPlayerCommandRoleControls();\n  updatePlayerCommandsDirty();\n});\n$('playercommands').addEventListener('change',event=>{\n  if(event.target.matches(PLAYER_COMMAND_DRAFT_SELECTOR)&&event.target.id!=='playerCmdRoleCommand'){\n    if(event.target.matches('[data-role-policy-mode],[data-role-policy-access],[data-role-policy-cooldown]'))syncPlayerCommandRoleControls();\n    updatePlayerCommandsDirty();\n  }\n});\n$('playerPermissionSearch').oninput=filterPlayerPermissionRows;\ndocument.querySelectorAll('[data-player-command-tab]').forEach(button=>{\n  button.onclick=()=>setPlayerCommandTab(button.dataset.playerCommandTab);\n  button.onkeydown=event=>{\n    if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;\n    event.preventDefault();const tabs=[...document.querySelectorAll('[data-player-command-tab]')],i=tabs.indexOf(button);\n    const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;\n    setPlayerCommandTab(tabs[next].dataset.playerCommandTab);tabs[next].focus();\n  };\n});\ndocument.querySelectorAll('[data-player-command-warps]').forEach(b=>b.onclick=()=>setSection('warps'));\nwindow.addEventListener('beforeunload',event=>{if(playerCommandsDirty||playerCommandsBusy){event.preventDefault();event.returnValue='';}});\nsetPlayerCommandTab('commands');\nsyncPlayerCommandsDraftControls();\n");
}
